// ---- extracted script block ----
// BroadcastChannel früh registrieren, damit goto.html diesen Tab sofort erreichen kann
var _obsidianPendingQ = null;
var _obsidianPendingGA = null;
var _obsidianBC = new BroadcastChannel('steiner-obsidian-nav');
_obsidianBC.onmessage = function(e) {
  if (e.data && e.data.action === 'navigate' && e.data.hash) {
    var params = {};
    e.data.hash.split('&').forEach(function(part) {
      var idx = part.indexOf('=');
      if (idx > 0) params[part.substring(0, idx)] = decodeURIComponent(part.substring(idx + 1));
    });
    
    if (params.ga && params.date) {
      // GA+Datum+Seite Navigation
      if (typeof navigateToGAPage === 'function') {
        navigateToGAPage(params.ga, params.date, params.page, params.text, params.vault, params.file);
      } else {
        _obsidianPendingGA = params;
      }
    } else if (params.q) {
      // Textsuche
      if (typeof runObsidianSearch === 'function') {
        runObsidianSearch(params.q);
      } else {
        _obsidianPendingQ = params.q;
      }
    }
    
    _obsidianBC.postMessage({ action: 'ack' });
    try { window.focus(); } catch(ex) {}
  }
};

