    // Hilfsfunktion: Formatiere Lecture ID mit Kleinbuchstaben-Suffix
    // GA157A -> GA157a, GA077B/3 -> GA077b/3, GA001/001B -> GA001/001b
    function formatLectureId(lectureId) {
      if (!lectureId) return lectureId;
      
      // Regex: Finde Buchstaben-Suffix
      // Format 1: GA123A (Suffix am Ende)
      // Format 2: GA123A/4 (Suffix vor dem Slash)
      // Format 3: GA001/001A (Suffix am Ende nach Slash)
      
      // Prüfe zuerst auf Format mit Slash: GA123A/4 oder GA001/001A
      const slashMatch = lectureId.match(/^(GA\d{3})([A-Za-z])(\/\d+.*)$/i);
      if (slashMatch) {
        // GA-Band-Teil mit Suffix vor dem Slash
        const gaPart = slashMatch[1].toUpperCase();  // GA077
        const suffix = slashMatch[2].toLowerCase();   // a, b, c
        const rest = slashMatch[3];                   // /3 oder /001B
        
        // Prüfe ob es nach dem Slash auch einen Suffix gibt
        const afterSlashMatch = rest.match(/^(\/\d+)([A-Za-z])$/i);
        if (afterSlashMatch) {
          const numberPart = afterSlashMatch[1];     // /001
          const afterSuffix = afterSlashMatch[2].toLowerCase(); // a, b
          return gaPart + suffix + numberPart + afterSuffix;
        }
        
        return gaPart + suffix + rest;
      }
      
      // Prüfe auf Suffix am Ende (ohne vorangehenden Suffix): GA157A oder GA001/001A
      const endMatch = lectureId.match(/^(.+?)([A-Za-z])$/);
      if (endMatch) {
        const mainPart = endMatch[1].toUpperCase();  // GA157 oder GA001/001
        const suffix = endMatch[2].toLowerCase();     // a, b, c
        return mainPart + suffix;
      }
      
      // Kein Suffix - einfach uppercase
      return lectureId.toUpperCase();
    }

