    function buildSteinerImagesApiUrl(apiBase, lectureId) {
      const b = String(apiBase || '').replace(/\/$/, '');
      const id = String(lectureId || '').trim();
      const ix = id.indexOf('/');
      if (ix === -1) {
        return `${b}/api/steiner-images/${encodeURIComponent(id)}`;
      }
      return `${b}/api/steiner-images/${encodeURIComponent(id.slice(0, ix))}/${encodeURIComponent(id.slice(ix + 1))}`;
    }

    function steinerImageBinaryApiUrl(lectureId, imagePath) {
      const api = (typeof window !== 'undefined' && window.API_BASE) ? String(window.API_BASE).replace(/\/$/, '') : String(API_BASE || '').replace(/\/$/, '');
      if (!api || !lectureId || !imagePath) return '';
      const q = new URLSearchParams({ lectureId, path: imagePath });
      return `${api}/api/steiner-image-binary?${q.toString()}`;
    }

    // Lade Bilder für einen bestimmten Vortrag bei Bedarf
    async function loadSteinerImagesForLecture(lectureId) {
      try {
        // Prüfe ob bereits geladen
        if (steinerImages[lectureId]) {
          return steinerImages[lectureId];
        }
        
        const response = await fetch(buildSteinerImagesApiUrl(API_BASE, lectureId));
        
        if (!response.ok) {
          console.warn(`[IMAGES] Keine Bilder für ${lectureId} verfügbar`);
          steinerImages[lectureId] = [];
          return [];
        }
        
        const images = await response.json();
        steinerImages[lectureId] = Array.isArray(images) ? images : [];
        return steinerImages[lectureId];
      } catch (error) {
        console.error(`[IMAGES] Fehler beim Laden für ${lectureId}:`, error);
        steinerImages[lectureId] = [];
        return [];
      }
    }

    // ============================================================================
    // CHALKBOARDS (Wandtafelzeichnungen) - Laden und Anzeigen
    // ============================================================================
    
    let chalkboardsData = []; // Globale Variable für alle Tafeln
    let chalkboardsDataPromise = null; // Promise für einmaliges Laden
    
    // Cache löschen: In Browser-Konsole eingeben: clearChalkboardsCache()
    function clearChalkboardsCache() {
      chalkboardsData = [];
      chalkboardsDataPromise = null;
      console.log('[CHALKBOARDS] Cache gelöscht. Beim nächsten Aufruf werden Daten neu geladen.');
    }
    
    // Lade chalkboards.json beim Start (mit Promise für Synchronisation)
    async function loadChalkboardsData() {
      // Wenn bereits geladen, sofort zurückkehren
      if (chalkboardsData && chalkboardsData.length > 0) {
        return Promise.resolve();
      }
      
      // Wenn bereits ein Ladevorgang läuft, warte darauf
      if (chalkboardsDataPromise) {
        return chalkboardsDataPromise;
      }
      
      // Starte neuen Ladevorgang
      chalkboardsDataPromise = (async () => {
        try {
          const response = await fetch(`${API_BASE}/chalkboards.json`);
          if (!response.ok) {
            console.warn('[CHALKBOARDS] chalkboards.json nicht gefunden');
            chalkboardsDataPromise = null; // Reset bei Fehler
            return;
          }
          const data = await response.json();
          chalkboardsData = data.chalkboards || [];
          console.log(`[CHALKBOARDS] ${chalkboardsData.length} Tafeln geladen`);
          // Aktualisiere GA-Tab-Statistik falls bereits angezeigt (Wandtafeln-Zahl nachtragen)
          const countEl = document.getElementById('ga-volumes-count');
          if (countEl && chalkboardsData.length > 0 && !countEl.textContent.includes('Wandtafeln')) {
            countEl.textContent += ` · ${chalkboardsData.length} Wandtafeln`;
          }
        } catch (error) {
          console.error('[CHALKBOARDS] Fehler beim Laden:', error);
          chalkboardsDataPromise = null; // Reset bei Fehler für erneuten Versuch
        }
      })();
      
      return chalkboardsDataPromise;
    }
    
    // Finde Tafeln für einen bestimmten Vortrag (GA + Datum)
    function getChalkboardsForLecture(gaNumber, dateStr) {
      if (!chalkboardsData.length || !gaNumber || !dateStr) {
        return [];
      }
      
      // Normalisiere GA-Nummer (z.B. "GA199" -> "199", "GA073A" -> "073A")
      const normalizedGA = gaNumber.replace(/^GA/i, '').toUpperCase();
      
      // Normalisiere Datum (verschiedene Formate möglich)
      let normalizedDate = dateStr;
      
      // Prüfe ob bereits ISO-Format (YYYY-MM-DD)
      if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        normalizedDate = dateStr;
      } else if (dateStr.includes('.')) {
        // Format: "6. August 1920" oder "06.08.1920"
        const parts = dateStr.match(/(\d{1,2})\.?\s*(\d{1,2}|\w+)\.?\s*(\d{4})/);
        if (parts) {
          const day = parts[1].padStart(2, '0');
          let month = parts[2];
          const year = parts[3];
          
          // Wenn Monat als Wort
          const monthNames = {
            'januar': '01', 'februar': '02', 'märz': '03', 'april': '04',
            'mai': '05', 'juni': '06', 'juli': '07', 'august': '08',
            'september': '09', 'oktober': '10', 'november': '11', 'dezember': '12'
          };
          if (isNaN(month)) {
            month = monthNames[month.toLowerCase()] || '01';
          } else {
            month = month.padStart(2, '0');
          }
          normalizedDate = `${year}-${month}-${day}`;
        }
      }
      
      // Finde passende Tafeln
      return chalkboardsData.filter(cb => {
        const cbGA = cb.ga.toUpperCase();
        return cbGA === normalizedGA && cb.date === normalizedDate;
      });
    }
    
    // Async-Version: Finde Tafeln für einen bestimmten Vortrag (wartet auf Datenladen)
    async function getChalkboardsForLectureAsync(gaNumber, dateStr) {
      await loadChalkboardsData();
      return getChalkboardsForLecture(gaNumber, dateStr);
    }
    
    // Füge Tafeln am Ende des Viewers hinzu
    async function appendChalkboardsToViewer(gaNumber, dateStr) {
      const viewer = document.getElementById('viewer');
      if (!viewer) return;
      
      // WICHTIG: Versuche zuerst viewer-content zu finden, sonst viewer verwenden
      const viewerContent = document.getElementById('viewer-content');
      const targetElement = viewerContent || viewer;
      
      // WICHTIG: Entferne alte WZ-Sektion, bevor neue hinzugefügt werden
      const existingSection = targetElement.querySelector('.lecture-chalkboards-section');
      if (existingSection) {
        existingSection.remove();
      }
      
      // Suche alle WZ für diesen Vortrag (GA + Datum)
      const chalkboards = await getChalkboardsForLectureAsync(gaNumber, dateStr);
      
      if (chalkboards.length === 0) return;
      
      // Erstelle HTML für Tafeln (ohne Überschrift)
      let html = `
        <div class="lecture-chalkboards-section" style="margin-top: 1.5rem; padding-top: 0.5rem; border-top: 2px solid var(--border-color);">
          <div class="chalkboards-grid">
      `;
      
      chalkboards.forEach(cb => {
        const imageUrl = `${API_BASE}/ga-k-images/${cb.path}`;
        const relativeUrl = `/ga-k-images/${cb.path}`;
        html += `
          <div class="chalkboard-item">
            <img src="${imageUrl}" 
                 alt="Tafel ${cb.tafel}" 
                 data-image-popup-handler="true"
                 onclick="openChalkboardLightbox('${relativeUrl}', 'GA${cb.ga}', '${cb.date}')"
                 loading="lazy">
          </div>
        `;
      });
      
      html += '</div></div>';
      
      // Füge am Ende des Ziel-Elements hinzu (viewer-content wenn vorhanden, sonst viewer)
      targetElement.insertAdjacentHTML('beforeend', html);
      console.log(`[CHALKBOARDS] ${chalkboards.length} Tafeln zu Vortrag hinzugefügt (in ${viewerContent ? 'viewer-content' : 'viewer'})`);
    }

    let totalLecturesCount = 0;
    let totalBooksCount = 0;
    let totalEssaysCount = 0;
    let totalLettersCount = 0;
    
    // Generiert den Statistik-Text für Schriften, Aufsätze, Briefe und Vorträge
    function getDefaultStatsText() {
      const parts = [];
      if (totalBooksCount > 0) parts.push(`${totalBooksCount} Schriften`);
      if (totalEssaysCount > 0) parts.push(`${totalEssaysCount} Aufsätze`);
      if (totalLettersCount > 0) parts.push(`${totalLettersCount} Briefe`);
      if (totalLecturesCount > 0) parts.push(`${totalLecturesCount} Vorträge`);
      return parts.join(' · ') || '';
    }
    
    async function checkServerConnection() {
      try {
        const response = await fetch(`${API_BASE}/debug/status`);
        if (response.ok) {
          const data = await response.json();
          // Setze Werte aus Server-Response (Vorträge, Aufsätze, Briefe, Schriften)
          if (data.lecturesLoaded) totalLecturesCount = data.lecturesLoaded;
          if (data.booksLoaded) totalBooksCount = data.booksLoaded;
          if (data.essaysLoaded) totalEssaysCount = data.essaysLoaded;
          if (data.lettersLoaded) totalLettersCount = data.lettersLoaded;
          
          // NUR Statistik anzeigen wenn ALLE drei Werte vorhanden sind (inkl. Aufsätze)
          // Ansonsten zeige "Lade..." - die vollständige Statistik kommt von loadGAVolumesInSidebar()
          if (data.essaysLoaded || totalEssaysCount > 0) {
            const infoText = getDefaultStatsText();
            document.getElementById('serverInfo').textContent = infoText;
            document.getElementById('thematicServerInfo').textContent = infoText;
            updateTexteServerInfo(); // Respektiert GA-Band-Auswahl
          } else {
            // Zeige Platzhalter bis GA-Volumes geladen sind
            const loadingText = 'Lade Statistik...';
            document.getElementById('serverInfo').textContent = loadingText;
            document.getElementById('thematicServerInfo').textContent = loadingText;
            updateTexteServerInfo(); // Respektiert GA-Band-Auswahl
          }
        }
      } catch (error) {
        const errorText = `<span style="color: #c53030;">Server nicht erreichbar</span>`;
        document.getElementById('serverInfo').innerHTML = errorText;
        document.getElementById('thematicServerInfo').innerHTML = errorText;
        document.getElementById('texteServerInfo').innerHTML = errorText;
      }
    }
    
    // Update texteServerInfo: Zeige Statistik passend zum ausgewählten GA-Band
    function updateTexteServerInfo() {
      const texteServerInfo = document.getElementById('texteServerInfo');
      if (!texteServerInfo) return;
      
      // Prüfe ob ein GA-Band ausgewählt ist
      const texteGAFilter = document.getElementById('texteGAFilter');
      const selectedGA = texteGAFilter ? texteGAFilter.value : '';
      
      // gaLectureCounts-Keys sind lowercase (z.B. "ga153"), Dropdown-Werte uppercase (z.B. "GA153")
      const gaKey = selectedGA ? selectedGA.toLowerCase() : '';
      const lectureCount = gaKey ? gaLectureCounts[gaKey] : null;
      
      if (selectedGA && lectureCount) {
        // Ein GA-Band ist ausgewählt
        const gaNorm = (selectedGA || '').toUpperCase();
        if (gaNorm === 'GA028' && typeof GA028_USE_CHAPTERS_UI !== 'undefined' && GA028_USE_CHAPTERS_UI) {
          const nCh = typeof GA028_BOOK_CHAPTER_COUNT === 'number' ? GA028_BOOK_CHAPTER_COUNT : 40;
          texteServerInfo.textContent = `${nCh} Kapitel`;
        } else {
          const gaType = getGAType(selectedGA);
          if (gaType === 'book') {
            texteServerInfo.textContent = '';
          } else {
            const typeName = getGATypeName(selectedGA, true);
            texteServerInfo.textContent = `${lectureCount} ${typeName}`;
          }
        }
      } else {
        // Kein GA-Band ausgewählt: Gesamtstatistik
        texteServerInfo.textContent = getDefaultStatsText();
      }
    }
    
