    function updateServerInfo() {
      const serverInfo = document.getElementById('serverInfo');
      
      if (!serverInfo) return;
      
      // Zeige immer die Gesamtstatistik (Schriften, Aufsätze, Vorträge)
      serverInfo.textContent = getDefaultStatsText();
    }
    
    // Update thematicServerInfo basierend auf GA-Filter Auswahl
    function updateThematicServerInfo() {
      const thematicGAFilter = document.getElementById('thematicGAFilter');
      const thematicServerInfo = document.getElementById('thematicServerInfo');
      
      if (!thematicGAFilter || !thematicServerInfo) return;
      
      const selectedGA = thematicGAFilter.value;
      
      if (selectedGA && gaLectureCounts[selectedGA]) {
        const typeName = getGATypeName(selectedGA, true); // Plural
        thematicServerInfo.textContent = `${gaLectureCounts[selectedGA]} ${typeName} in ${selectedGA}`;
      } else {
        thematicServerInfo.textContent = getDefaultStatsText();
      }
    }
    
    const IMAGES_R2_BASE = 'https://ga.rudolf-steiner-online.de/images/';

    async function replaceImageSrcWithBase64(htmlContent, lectureId) {
      if (!htmlContent) return htmlContent;

      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = htmlContent;
      const imgTags = tempDiv.querySelectorAll('img');
      if (imgTags.length === 0) return htmlContent;

      const gaNumber = (lectureId || '').split('/')[0] || lectureId || '';
      if (!gaNumber) return htmlContent;

      imgTags.forEach(imgTag => {
        const src = imgTag.getAttribute('src');
        if (!src || src.startsWith('data:') || src.startsWith('http://') || src.startsWith('https://')) return;

        let decodedSrc;
        try { decodedSrc = decodeURIComponent(src); } catch { decodedSrc = src; }
        const cleanSrc = decodedSrc.replace(/^[<"']|[>"']$/g, '').trim();

        if (!/\.(png|jpe?g|webp|gif)$/i.test(cleanSrc)) return;

        // Dateiname: immer letzter Pfadteil (z.B. Steiner, Rudolf GA 076..._img-0.png oder img-0.png)
        const parts = cleanSrc.split('/');
        const filename = parts[parts.length - 1];

        // Tafelzeichnung? (NNN-TNN.webp Pattern)
        const isChalkboard = /\d{3}-T\d+\./i.test(filename);
        const isWebP = /\.webp$/i.test(filename);

        const r2Url = `${IMAGES_R2_BASE}${encodeURIComponent(gaNumber)}/${encodeURIComponent(filename)}`;
        imgTag.setAttribute('src', r2Url);
        imgTag.setAttribute('data-local-src', `/assets/${encodeURIComponent(filename)}?ga=${encodeURIComponent(gaNumber)}`);

        // onerror: erst alternative Dateiendungen auf R2, dann lokaler Fallback via Backend
        // (Backend übernimmt selbst den Extension-Fallback, daher reicht ein Versuch lokal)
        imgTag.setAttribute('onerror',
          "var c=this.src,t=(this.dataset.triedExts||'').split(',').filter(Boolean)," +
          "x=(c.match(/\\.\\w+$/)||[''])[0].toLowerCase();t.push(x);" +
          "var a=['.png','.jpeg','.jpg','.webp'].filter(function(e){return t.indexOf(e)<0});" +
          "if(c.indexOf('rudolf-steiner-online.de')>=0&&a.length){this.dataset.triedExts=t.join(',');this.src=c.replace(/\\.\\w+$/,a[0])}" +
          "else if(!this.dataset.triedLocal&&this.dataset.localSrc){this.dataset.triedLocal='1';this.src=this.dataset.localSrc}" +
          "else{this.onerror=null}"
        );

        imgTag.className = 'lecture-image';
        imgTag.style.cursor = 'pointer';

        if (isChalkboard) {
          imgTag.classList.add('blackboard-drawing');
        } else {
          imgTag.classList.add('lecture-image');
        }

        if (isWebP) imgTag.setAttribute('data-format', 'webp');

        imgTag.setAttribute('onclick',
          "event.preventDefault();event.stopPropagation();" +
          "window.openImagePopup(this.src,this.getAttribute('alt')||'',this.getAttribute('data-format'))"
        );
      });

      return tempDiv.innerHTML;
    }

