    // Event-Delegation für Bild-Klicks (funktioniert auch für dynamisch hinzugefügte Bilder)
    // Unterstützt sowohl lecture-image als auch alle anderen Bilder im Text
    document.addEventListener('click', function(e) {
      if (e.target.tagName === 'IMG') {
        // Überspringe wenn Bild bereits ein Link ist (z.B. in einem <a> Tag)
        if (e.target.closest('a')) return;

        // Überspringe wenn Bild bereits einen spezifischen Handler hat
        if (e.target.hasAttribute('data-image-popup-handler')) return;

        const imageSrc = e.target.src;
        const altText = e.target.getAttribute('alt') || '';
        const dataFormat = e.target.getAttribute('data-format');

        // Setze Cursor-Style wenn noch nicht gesetzt
        if (!e.target.style.cursor) {
          e.target.style.cursor = 'pointer';
        }
        
        // Füge lecture-image Klasse hinzu, wenn noch nicht vorhanden (für korrekte Styles)
        if (!e.target.classList.contains('lecture-image') && !e.target.closest('.logo-container') && !e.target.closest('.portrait-container')) {
          const imgSrc = e.target.getAttribute('src') || '';
          const isBlackboardDrawing = /T\d+\./.test(imgSrc) || /\d{3}-T\d+/.test(imgSrc);
          const isWebP = imgSrc.toLowerCase().includes('.webp');
          
          e.target.classList.add('lecture-image');
          
          if (isBlackboardDrawing) {
            e.target.classList.add('blackboard-drawing');
          }
          
          if (isWebP) {
            e.target.setAttribute('data-format', 'webp');
          }
        }

        openImagePopup(imageSrc, altText, dataFormat);
      }
    }, true); // useCapture: true, damit der Handler früher ausgeführt wird

