    function getAdvancedGAFilterValue() {
      return advancedGAFilterDropdown ? advancedGAFilterDropdown.getSelectedValues() : [];
    }
    
    async function populateGADropdowns() {
      try {
        const [gaListResponse, volumesResponse] = await Promise.all([
          fetch(`${API_BASE}/api/ga-list`),
          fetch(`${API_BASE}/api/keywords/available-ga-volumes`)
        ]);
        if (!gaListResponse.ok) throw new Error('GA-Liste konnte nicht geladen werden');
        const gaList = (await gaListResponse.json())
          .filter(ga => ga.number.toUpperCase() !== 'GA014')
          .sort(compareGANumbers);
        if (volumesResponse.ok) {
          const volumeData = await volumesResponse.json();
          volumeData.volumes.forEach(vol => {
            gaLectureCounts[vol.volume] = vol.lectureCount;
          });
        }
        
        // Befülle Custom Dropdown für GA-Bände im Suche-Tab
        if (gaFilterDropdown) {
          const gaItems = gaList.map(ga => ({
            value: ga.number,
            label: ga.title && ga.title !== ga.number ? `${ga.number} - ${ga.title}` : ga.number
          }));
          gaFilterDropdown.setItems(gaItems);
          }
        
        // Befülle Custom Dropdown für GA-Bände in erweiterter Suche
        if (advancedGAFilterDropdown) {
          const gaItems = gaList.map(ga => ({
            value: ga.number,
            label: ga.title && ga.title !== ga.number ? `${ga.number} - ${ga.title}` : ga.number
          }));
          advancedGAFilterDropdown.setItems(gaItems);
          }
        
        // Befülle normale Dropdowns in anderen Tabs
        const thematicGAFilter = document.getElementById('thematicGAFilter');
        const texteGAFilter = document.getElementById('texteGAFilter');
        const conceptOverviewGAFilter = document.getElementById('conceptOverviewGAFilter');
        
        if (thematicGAFilter) {
          thematicGAFilter.innerHTML = '<option value="">GA-Bände</option>';
          gaList.forEach(ga => {
            const option = document.createElement('option');
            option.value = ga.number;
            option.textContent = ga.number;
            option.className = 'available-ga';
            thematicGAFilter.appendChild(option);
          });
          
          // Event-Listener für Thematic GA-Filter hinzufügen
          thematicGAFilter.addEventListener('change', updateThematicServerInfo);
        }
        if (texteGAFilter) {
          // Speichere den aktuellen Wert, falls vorhanden
          const currentValue = texteGAFilter.value;
          
          texteGAFilter.innerHTML = '<option value="">GA-Band auswählen...</option>';
          gaList.forEach(ga => {
            const option = document.createElement('option');
            option.value = ga.number;
            // Zeige Nummer und Titel (falls verfügbar und nicht identisch)
            option.textContent = ga.title && ga.title !== ga.number ? `${ga.number} - ${ga.title}` : ga.number;
            option.className = 'available-ga';
            texteGAFilter.appendChild(option);
          });
          
          // Stelle den vorherigen Wert wieder her, falls vorhanden
          if (currentValue) {
            texteGAFilter.value = currentValue;
          }
          
          // Entferne alle alten Event-Listener durch Klonen des Elements
          const newTexteGAFilter = texteGAFilter.cloneNode(true);
          newTexteGAFilter.value = texteGAFilter.value;
          texteGAFilter.parentNode.replaceChild(newTexteGAFilter, texteGAFilter);
          // Listener wird ausschließlich über initGAFilter() registriert
          
          }
        
        // Befülle Concept Overview GA-Filter
        if (conceptOverviewGAFilter) {
          conceptOverviewGAFilter.innerHTML = '<option value="">GA-Bände</option>';
          gaList.forEach(ga => {
            const option = document.createElement('option');
            option.value = ga.number;
            option.textContent = ga.number;
            option.className = 'available-ga';
            conceptOverviewGAFilter.appendChild(option);
          });
        }
        
        // Lade und befülle Jahre
        await populateYearFilter();
      } catch (error) {
        console.error('Fehler beim Laden der GA-Liste:', error);
      }
    }
    
    async function populateYearFilter() {
      try {
        // Extrahiere Jahre aus den verfügbaren Vorträgen
        const response = await fetch(`${API_BASE}/api/available-years`);
        if (!response.ok) {
          console.warn('Konnte Jahre nicht vom Server laden, versuche Fallback');
          // Fallback: Generiere Jahre von 1900 bis heute
          const currentYear = new Date().getFullYear();
          const years = [];
          for (let year = 1900; year <= currentYear; year++) {
            years.push(year.toString());
          }
          populateYearFilterWithData(years);
          return;
        }
        
        const data = await response.json();
        const years = data.years || [];
        populateYearFilterWithData(years);
      } catch (error) {
        console.warn('Fehler beim Laden der Jahre:', error);
        // Fallback: Generiere Jahre von 1900 bis 1925 (Steiners aktive Jahre)
        const years = [];
        for (let year = 1900; year <= 1925; year++) {
          years.push(year.toString());
        }
        populateYearFilterWithData(years);
      }
    }
    
    function populateYearFilterWithData(years) {
      if (yearFilterDropdown) {
        const yearItems = years.map(year => ({
          value: year,
          label: year
        }));
        yearFilterDropdown.setItems(yearItems);
        }
    }

    function initGAFilter() {
      const texteGAFilter = document.getElementById('texteGAFilter');

      // Texte-Tab: Direkt GA-Übersicht öffnen bei Auswahl
      if (texteGAFilter && !texteGAFilter._gaFilterInitialized) {
        texteGAFilter._gaFilterInitialized = true;
        texteGAFilter.addEventListener('change', (e) => {
          const selectedGA = e.target.value;
          if (selectedGA) {
            // Setze Auswahl zurück beim Wechsel des GA-Bands
            selectedLectureIds.clear();
            updateSelectionInfo();
            openGAOverview(selectedGA);
            // Aktualisiere Statistik-Anzeige für ausgewählten Band
            updateTexteServerInfo();
          } else {
            // Filter zurückgesetzt: Zeige Gesamtstatistik
            updateTexteServerInfo();
          }
          // Aktualisiere Button-Status (für Keywords-Regeneration)
          updateButtonStates();
        });
      }
    }

    async function openGAOverview(gaNumber) {
      if (!gaNumber) return;
      try {
        // PDF-Panel schließen beim Öffnen eines neuen GA-Bandes
        const pdfPanel = document.getElementById('pdf-viewer-panel');
        if (pdfPanel && pdfPanel.classList.contains('visible') && typeof window.closePdfPanel === 'function') {
          window.closePdfPanel();
        }

        // Prüfe ob es ein Book ist (aber nicht ein Aufsatzband)
        if (isBookGANumber(gaNumber) && !isEssayGANumber(gaNumber)) {
          // Für Books: Panel NICHT schließen, da displayBook es sofort wieder öffnet
          // (verhindert Flackern/Blitzen des Inhaltsverzeichnisses durch close?reopen Transition)
          await showLecture(gaNumber);
          return;
        }
        
        // Close summary panel when opening GA overview (Vortrags-Übersicht, nicht Bücher)
        try {
          const summaryPanel = document.getElementById('summary-panel');
          if (summaryPanel && summaryPanel.classList.contains('visible')) {
            summaryPanel.classList.remove('visible');
            summaryPanel.style.width = '0';
            summaryPanel.style.minWidth = '0';
            summaryPanel.style.marginRight = '0px';

            // WICHTIG: Verwende zentrale Funktionen für Main-Container und RH
            if (typeof syncMainContainerWithPanel === 'function') {
              syncMainContainerWithPanel();
            }
            if (typeof updateResizeHandle === 'function') {
              updateResizeHandle();
            }
          }
        } catch (e) { /* silent */ }
        
        // Lade GA-Übersicht (Vorträge oder Aufsätze)
        const t0 = performance.now();
        const response = await fetch(`${API_BASE}/api/ga-overview/${gaNumber}`);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const data = await response.json();
        const t1 = performance.now();
        
        await displayGAOverview(data);
        console.log(`[PERF] ${gaNumber}: API ${Math.round(t1-t0)}ms, Render ${Math.round(performance.now()-t1)}ms, Gesamt ${Math.round(performance.now()-t0)}ms`);
      } catch (error) {
        console.error('Fehler beim Laden der GA-Übersicht:', error);
        document.getElementById('viewer').innerHTML = `
          <div class="error-message">
            <strong>Fehler beim Laden der GA-Übersicht:</strong><br>${error.message}
          </div>
        `;
      }
    }

    // Lade GA-Übersicht nur im linken Side Panel, ohne den Hauptviewer zu überschreiben
    async function loadGAOverviewInSidePanelOnly(gaNumber) {
      if (!gaNumber) return;
      
      try {
        // Lade GA-Übersicht Daten vom Server
        const response = await fetch(`${API_BASE}/api/ga-overview/${gaNumber}`);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const data = await response.json();
        
        // Normalisiere Summary-Daten
        data.lectures.forEach(lecture => {
          if (lecture.summary) {
            lecture.summary = getSummaryText(lecture.summary);
          }
        });
        
        // Fülle NUR das linke Panel (results container)
        const resultsContainer = document.getElementById('results');
        if (!resultsContainer) {
          console.error('[NAVIGATION] Results Container nicht gefunden');
          return;
        }
        
        // Setze Titel im Header (aber nicht currentLectureData - das bleibt vom Vortrag)
        const titleElement = document.getElementById('document-title');
        if (titleElement && currentLectureData) {
          // Behalte den Vortragstitel, füge nur GA-Info hinzu falls noch nicht vorhanden
          if (!titleElement.textContent.includes(data.gaNumber)) {
            // Bevorzuge fileName (vollständiger Titel)
            titleElement.textContent = currentLectureData.fileName || `${currentLectureData.ID} - ${currentLectureData.title || ''}`;
          }
        }
        
        // Erstelle HTML für linkes Panel
        // GA-Band-Name für Anzeige oberhalb der Vortragsliste (Suffix immer klein)
        const gaBandName = `${formatLectureId(data.gaNumber)} - ${data.gaTitle}`;
        
        let html = `<div id="ga-lecture-list">
          <div class="ga-band-header">
            <h3 onclick="showGABibliographyInfo()" title="Bibliographische Angaben anzeigen">${gaBandName}</h3>
          </div>`;
        
        data.lectures.forEach((lecture, idx) => {
          let titleText;
          if (lecture.fileName) {
            titleText = lecture.fileName;
          } else {
            titleText = `${formatLectureId(lecture.ID)} - ${lecture.title}`;
            const locationParts = [];
            if (lecture.location) locationParts.push(lecture.location);
            if (lecture.date) locationParts.push(lecture.date);
            if (locationParts.length > 0) {
              titleText += `, ${locationParts.join(', ')}`;
            }
          }
          
          const lectureKeywords = lecture.lectureKeywords || [];
          const hasShortSummary = lecture.shortSummary && lecture.shortSummary.trim().length > 0;
          const isSelected = selectedLectureIds.has(lecture.ID);
          
          html += `
            <div class="ga-overview-lecture" style="margin-bottom: 0.5rem; padding-bottom: 0rem; border-bottom: none; display: flex; align-items: flex-start; gap: 8px;">
              ${isLocal ? `
                <input type="checkbox" 
                       id="chk-${lecture.ID}" 
                       class="lecture-checkbox" 
                       ${isSelected ? 'checked' : ''} 
                       onchange="toggleLectureSelection('${lecture.ID}')"
                       style="margin-top: 4px; cursor: pointer; flex-shrink: 0;">
              ` : ''}
              <div style="flex: 1;">
                <h3 style="margin: 0 0 0rem 0;">
                  <a href="#" onclick="showLectureFromOverview('${lecture.ID}'); return false;" style="text-decoration: none;">
                    ${titleText}
                  </a>
                </h3>
              
              ${lecture.shortSummary ? `
                <div class="ga-summary-text" style="margin-top: 0.5rem; display: ${gaOverviewShowSummaries ? 'block' : 'none'};">
                  <p style="margin: 0; line-height: var(--line-height); font-size: var(--text-size); color: #666; font-style: italic;">
                    ${lecture.shortSummary}
                  </p>
                </div>
              ` : ''}
              </div>
            </div>
          `;
        });
        
        html += `</div>`;
        resultsContainer.innerHTML = html;
        
        // Speichere aktuelle GA-Nummer für spätere Prüfung
        window._currentGAInSidePanel = gaNumber;
        
        // Scroll nur bei erstem Laden nach oben (wenn andere GA geladen wurde)
        // Bei Klick auf Vortrag innerhalb derselben GA: Scroll-Position beibehalten
        // (wird durch die Prüfung in showLecture() gesteuert - hier immer scrollen,
        // da diese Funktion nur bei GA-Wechsel aufgerufen wird)
        const sidebarContent = document.getElementById('sidebar-content');
        if (sidebarContent) {
          sidebarContent.scrollTop = 0;
        }
        
        // Aktualisiere Auswahl-Info
        updateSelectionInfo();
        
        } catch (error) {
        console.error('[NAVIGATION] Fehler beim Laden der GA-Übersicht:', error);
        const resultsContainer = document.getElementById('results');
        if (resultsContainer) {
          resultsContainer.innerHTML = `
            <div class="error-message">
              <strong>Fehler beim Laden der GA-Übersicht:</strong><br>${error.message}
            </div>
          `;
        }
      }
    }

    // Hilfsfunktion: Lade Summaries aus zentraler Datenbank
    async function loadSummariesForOverview(data) {
      // Erstmal die Übersicht ohne Summaries anzeigen
      await displayGAOverview(data);
      
      try {
        // Nur lokal: Lade statische summary-database.json
        if (isLocal) {
          const centralResponse = await fetch(`${API_BASE}/summary-database.json`);
          if (centralResponse.ok) {
            const centralData = await centralResponse.json();
            return await applySummariesToOverview(data, centralData);
          }
        }
        
        // Online: Immer API-Endpunkt verwenden (dynamische Daten vom Render Backend)
        return await loadSummariesViaAPI(data);
        
      } catch (error) {
        console.error('Fehler beim Laden der Summaries:', error);
        // Fallback zu API-Methode
        await loadSummariesViaAPI(data);
      }
    }
    
    // Hilfsfunktion: Wende Summary-Daten auf GA-Übersicht an
    async function applySummariesToOverview(data, summaryData) {
      
      let foundSummaries = 0;
      
      // Durchlaufe alle Vorträge und suche passende Summaries
      data.lectures.forEach(lecture => {
        const lectureId = lecture.ID;
        
        // Verschiedene Formate testen
        const possibleKeys = [
          lectureId,                    // z.B. "GA001/001"
          lectureId.replace('/', '_'),  // z.B. "GA001_001"
          lectureId.replace('/', '-'),  // z.B. "GA001-001"
          lectureId.toLowerCase(),      // kleingeschrieben
          formatLectureId(lectureId),   // mit lowercase-Suffix
        ];
        
        for (const key of possibleKeys) {
          if (summaryData[key] && summaryData[key].summary) {
            lecture.summary = summaryData[key].summary;
            // Markiere Quelle der Summary
            lecture.summarySource = summaryData[key].source || 'unknown';
            lecture.summaryGeneratedAt = summaryData[key].generatedAt || null;
            foundSummaries++;
            break;
          }
        }
      });
      
      // Anzeige aktualisieren
      await displayGAOverview(data);
    }
    
    // Fallback: Lade Summaries über API-Endpunkt
    async function loadSummariesViaAPI(data) {
      const maxToCheck = Math.min(5, data.lectures.length);
      let foundSummaries = 0;
      
      for (let i = 0; i < maxToCheck; i++) {
        const lecture = data.lectures[i];
        try {
          const parts = lecture.ID.split('/');
          if (parts.length === 2) {
            // GA046: Keine Summaries (Sonderbehandlung)
            if (isGA046(parts[0])) {
              continue;
            }
            const response = await fetch(`${API_BASE}/api/check-summary/${encodeURIComponent(parts[0])}/${encodeURIComponent(parts[1])}`);
            if (response.ok) {
              const summaryData = await response.json();
              if (summaryData.exists && summaryData.summary) {
                lecture.summary = summaryData.summary;
                foundSummaries++;
                }
            }
          }
        } catch (error) {
          console.warn(`Fehler beim Laden der Summary für ${lecture.ID}:`, error);
        }
      }
      
      if (foundSummaries > 0) {
        await displayGAOverview(data);
      }
    }

// Funktion: Speichere Summary in zentrale Datenbank
async function saveSummaryToCentral(lectureId, summaryData) {
  try {
    const response = await fetch(`${API_BASE}/api/save-summary`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        lectureId: lectureId,
        summary: summaryData
      })
    });
    
    if (response.ok) {
      const result = await response.json();
      return result;
    } else {
      console.warn(`Fehler beim Speichern der Summary für ${lectureId}:`, response.status);
      return null;
    }
  } catch (error) {
    console.error(`Fehler beim Speichern der Summary für ${lectureId}:`, error);
    return null;
  }
}

// Funktion: Synchronisiere GitHub-Summaries mit zentraler Datenbank


// Globale Variable für den Toggle-Zustand
let gaOverviewShowSummaries = true;

// Globale Variable für ausgewählte Vorträge
let selectedLectureIds = new Set();

// Funktion: Toggle Vortrag-Auswahl (nur lokal)
function toggleLectureSelection(lectureId) {
  if (!isLocal) return;
  
  if (selectedLectureIds.has(lectureId)) {
    selectedLectureIds.delete(lectureId);
  } else {
    selectedLectureIds.add(lectureId);
  }
  updateSelectionInfo();
}

// Funktion: Auswahl-Info aktualisieren (nur lokal)
function updateSelectionInfo() {
  if (!isLocal) return; // Nur lokal anzeigen
  
  const count = selectedLectureIds.size;
  const infoElement = document.getElementById('texteSelectionInfo');
  if (infoElement) {
    if (count > 0) {
      infoElement.textContent = `${count} Vortrag${count > 1 ? 'e' : ''} ausgewählt`;
      infoElement.style.display = 'inline';
    } else {
      infoElement.style.display = 'none';
    }
  }
}

// Hilfsfunktion zum Extrahieren des Summary-Texts
function getSummaryText(summary) {
  if (typeof summary === 'string') return summary;
  if (typeof summary === 'object' && summary) {
    if (summary.summary) return getSummaryText(summary.summary);
    return '';
  }
  return summary || '';
}

// Hilfsfunktion: Lade Keywords-Database für Themen
let keywordsDatabaseCache = null;
async function loadKeywordsDatabaseForThemes() {
  if (keywordsDatabaseCache) return keywordsDatabaseCache;
  
  try {
    const response = await fetch(`${API_BASE}/api/keywords-database`);
    if (response.ok) {
      keywordsDatabaseCache = await response.json();
      return keywordsDatabaseCache;
    }
  } catch (error) {
    console.warn('[THEMES] Fehler beim Laden der Keywords-Database:', error.message);
  }
  return {};
}

