// Globale Variable für GA-Bände-Daten
let gaVolumesData = [];
let summaryDatabaseCache = null;
let currentGANumber = null; // Speichert aktuell angezeigten GA-Band
let gaVolumesLoading = false; // Verhindert doppeltes Laden
let gaVolumesRetryCount = 0; // Zählt Retry-Versuche
let selectedGABandFilter = null; // Filter für GA-Band-Auswahl im GA-Tab
let selectedYearFilter = null; // Filter für Jahr-Auswahl im GA-Tab
let selectedChalkboardsYearFilter = null; // Filter für Jahr-Auswahl bei Wandtafelzeichnungen
let allChronologicalLectures = null; // Speichert alle geladenen chronologischen Vorträge

// Funktion: Lade GA-Bände im Sidebar
async function loadGAVolumesInSidebar(retryAttempt = 0) {
  // Verhindere doppeltes Laden
  if (gaVolumesLoading && retryAttempt === 0) {
    return;
  }
  
  // Wenn Daten bereits geladen sind, zeige sie nur an
  if (gaVolumesData.length > 0 && retryAttempt === 0) {
    // Warte kurz, damit das DOM bereit ist
    await new Promise(resolve => setTimeout(resolve, 10));
    
    // Prüfe ob results-div existiert, bevor wir anzeigen
    const resultsDiv = document.getElementById('results');
    if (!resultsDiv) {
      console.warn('[GA-TAB] Results-DIV noch nicht bereit, warte...');
      await new Promise(resolve => setTimeout(resolve, 100));
    }
    
    // Befülle Dropdown mit GA-Bänden
    populateGABandFilterDropdown();
    
    displayGAVolumesInSidebar();
    
    // Aktualisiere Info-Element auch beim erneuten Anzeigen
    // Schriften: GA001-GA028 und GA045 – jeweils als 1 Band gezählt, Inhalte nicht einzeln
    // Briefbände (GA262, GA263a): separat als Briefe zählen, nicht als Vorträge
    const totalBooks = gaVolumesData.filter(ga => isSchriftForStats(ga.number)).length;
    const totalEssays = gaVolumesData.filter(ga => isEssayGANumber(ga.number) && !isSchriftForStats(ga.number)).reduce((sum, ga) => sum + ga.lectureCount, 0);
    const totalLetters = gaVolumesData.filter(ga => isLetterGANumber(ga.number)).reduce((sum, ga) => sum + ga.lectureCount, 0);
    const totalLectures = gaVolumesData.filter(ga => !isSchriftForStats(ga.number) && !isEssayGANumber(ga.number) && !isLetterGANumber(ga.number)).reduce((sum, ga) => sum + ga.lectureCount, 0);
    
    // Aktualisiere globale Statistik-Variablen
    totalLecturesCount = totalLectures;
    totalBooksCount = totalBooks;
    totalEssaysCount = totalEssays;
    totalLettersCount = totalLetters;
    
    const countElement = document.getElementById('ga-volumes-count');
    if (countElement) {
      const booksText = totalBooks > 0 ? `${totalBooks} Schriften · ` : '';
      const essaysText = totalEssays > 0 ? `${totalEssays} Aufsätze · ` : '';
      const lettersText = totalLetters > 0 ? `${totalLetters} Briefe · ` : '';
      const chalkboardsText = (chalkboardsData && chalkboardsData.length > 0) ? ` · ${chalkboardsData.length} Wandtafeln` : '';
      countElement.textContent = `${gaVolumesData.length} Bände · ${booksText}${essaysText}${lettersText}${totalLectures} Vorträge${chalkboardsText}`;
      countElement.style.fontStyle = 'normal';
    }
    
    // Aktualisiere auch die Statistik-Elemente in den Tabs Texte und Themen
    const statsText = getDefaultStatsText();
    const thematicServerInfo = document.getElementById('thematicServerInfo');
    const serverInfo = document.getElementById('serverInfo');
    if (thematicServerInfo) thematicServerInfo.textContent = statsText;
    if (serverInfo) serverInfo.textContent = statsText;
    updateTexteServerInfo(); // Respektiert GA-Band-Auswahl
    
    return;
  }
  
  gaVolumesLoading = true;
  
  try {
    // WICHTIG: Verwende window.API_BASE falls API_BASE nicht im Scope verfügbar ist
    // Verwende NUR window.API_BASE, um TDZ-Fehler zu vermeiden
    let apiBase = '';
    try {
      apiBase = window.API_BASE || '';
    } catch (e) {
      // Ignoriere Fehler
    }
    if (!apiBase) {
      apiBase = 'https://ga-suche.onrender.com'; // Fallback für Online-Version
    }
    
    // Lade GA-Liste und Vortrags-Count parallel
    let gaList, volumesData;
    try {
      const [gaListResponse, volumesResponse] = await Promise.all([
        fetch(`${apiBase}/api/ga-list`),
        fetch(`${apiBase}/api/keywords/available-ga-volumes`)
      ]);
      if (!gaListResponse.ok) {
        const errorText = await gaListResponse.text().catch(() => 'Unbekannter Fehler');
        throw new Error(`GA-Liste: HTTP ${gaListResponse.status} - ${errorText.substring(0, 100)}`);
      }
      if (!volumesResponse.ok) {
        const errorText = await volumesResponse.text().catch(() => 'Unbekannter Fehler');
        throw new Error(`GA-Volumes: HTTP ${volumesResponse.status} - ${errorText.substring(0, 100)}`);
      }
      gaList = (await gaListResponse.json()).sort(compareGANumbers);
      volumesData = await volumesResponse.json();
    } catch (fetchError) {
      console.error('[GA-TAB] Fetch-Fehler:', fetchError);
      throw new Error(`Verbindungsfehler: ${fetchError.message}. Server erreichbar? (${apiBase})`);
    }
    
    gaVolumesData = gaList
      .filter(ga => ga.number.toUpperCase() !== 'GA014') // GA014 wird nicht angezeigt
      .map(ga => {
        const volumeInfo = volumesData.volumes.find(v => v.volume.toLowerCase() === ga.number.toLowerCase());
        return {
          number: ga.number,
          title: ga.title,
          lectureCount: volumeInfo ? volumeInfo.lectureCount : 0
        };
      });
    
    // Befülle Dropdown mit GA-Bänden
    populateGABandFilterDropdown();
    
    // Zeige GA-Bände im Sidebar (im #results Bereich)
    displayGAVolumesInSidebar();
    
    // Berechne Gesamtanzahl der Vorträge, Schriften, Aufsätze und Briefe
    // Schriften: GA001-GA028 und GA045 – jeweils als 1 Band gezählt, Inhalte nicht einzeln
    // Briefbände (GA262, GA263a): Briefe (H2-Überschriften) separat zählen, nicht als Vorträge
    const totalBooks = gaVolumesData.filter(ga => isSchriftForStats(ga.number)).length;
    const totalEssays = gaVolumesData.filter(ga => isEssayGANumber(ga.number) && !isSchriftForStats(ga.number)).reduce((sum, ga) => sum + ga.lectureCount, 0);
    const totalLetters = gaVolumesData.filter(ga => isLetterGANumber(ga.number)).reduce((sum, ga) => sum + ga.lectureCount, 0);
    const totalLectures = gaVolumesData.filter(ga => !isSchriftForStats(ga.number) && !isEssayGANumber(ga.number) && !isLetterGANumber(ga.number)).reduce((sum, ga) => sum + ga.lectureCount, 0);
    
    // Aktualisiere globale Statistik-Variablen aus GA-Volumes (zuverlässigste Quelle)
    totalLecturesCount = totalLectures;
    totalBooksCount = totalBooks;
    totalEssaysCount = totalEssays;
    totalLettersCount = totalLetters;
    
    // Aktualisiere Info
    const countElement = document.getElementById('ga-volumes-count');
    if (countElement) {
      const booksText = totalBooks > 0 ? `${totalBooks} Schriften · ` : '';
      const essaysText = totalEssays > 0 ? `${totalEssays} Aufsätze · ` : '';
      const lettersText = totalLetters > 0 ? `${totalLetters} Briefe · ` : '';
      const chalkboardsText = (chalkboardsData && chalkboardsData.length > 0) ? ` · ${chalkboardsData.length} Wandtafeln` : '';
      countElement.textContent = `${gaVolumesData.length} Bände · ${booksText}${essaysText}${lettersText}${totalLectures} Vorträge${chalkboardsText}`;
      countElement.style.fontStyle = 'normal'; // Entferne Kursivschrift nach dem Laden
    }
    
    // Aktualisiere auch die Statistik-Elemente in den Tabs Texte und Themen
    const statsText = getDefaultStatsText();
    const thematicServerInfo = document.getElementById('thematicServerInfo');
    const serverInfo = document.getElementById('serverInfo');
    if (thematicServerInfo) thematicServerInfo.textContent = statsText;
    if (serverInfo) serverInfo.textContent = statsText;
    updateTexteServerInfo(); // Respektiert GA-Band-Auswahl
    
    gaVolumesLoading = false; // Erfolgreich geladen
    
  } catch (error) {
    console.error('[GA-TAB] Fehler beim Laden der GA-Bände:', error);
    gaVolumesLoading = false; // Reset bei Fehler
    
    // Retry-Mechanismus: Versuche es bis zu 3 Mal
    if (retryAttempt < 2) {
      setTimeout(() => {
        loadGAVolumesInSidebar(retryAttempt + 1);
      }, (retryAttempt + 1) * 1000); // 1s, 2s delays
      
      // Zeige Retry-Nachricht
      const resultsDiv = document.getElementById('results');
      if (resultsDiv) {
        resultsDiv.innerHTML = `<div style="padding: 1rem; color: var(--secondary-text); font-style: italic;">Lade GA-Bände... (Versuch ${retryAttempt + 2}/3)</div>`;
      }
      return;
    }
    
    // Nach 3 Versuchen: Zeige Fehler
    const errorHtml = `
      <div style="padding: 1rem; color: var(--text-color);">
        <strong>Fehler beim Laden der GA-Bände:</strong><br>
        ${error.message}<br><br>
        <button onclick="gaVolumesData = []; loadGAVolumesInSidebar()" class="depth-btn" style="padding: 8px 12px;">
          Erneut versuchen
        </button>
      </div>
    `;
    
    const resultsDiv = document.getElementById('results');
    if (resultsDiv) {
      resultsDiv.innerHTML = errorHtml;
    }
    
    const countElement = document.getElementById('ga-volumes-count');
    if (countElement) {
      countElement.textContent = `Fehler: ${error.message}`;
      countElement.style.fontStyle = 'normal'; // Entferne Kursivschrift bei Fehler
    }
  }
}

// Funktion: Zeige GA-Bände im Sidebar
function displayGAVolumesInSidebar() {
  const resultsDiv = document.getElementById('results');
  if (!resultsDiv) {
    console.warn('[GA-TAB] results div nicht gefunden');
    return;
  }
  
  // Filtere nach ausgewähltem GA-Band falls Filter aktiv
  // GA014 wird nicht angezeigt
  let filteredData = gaVolumesData.filter(ga => ga.number.toUpperCase() !== 'GA014');
  if (selectedGABandFilter) {
    filteredData = filteredData.filter(ga => {
      return ga.number.toLowerCase() === selectedGABandFilter.toLowerCase();
    });
  }
  
  // Prüfe ob alle Bände wieder angezeigt werden (kein Filter aktiv)
  const isShowingAllVolumes = !selectedGABandFilter;
  
  // Wenn alle Bände wieder angezeigt werden, setze Viewer zurück
  if (isShowingAllVolumes) {
    const gaTab = document.getElementById('ga-tab');
    const isInGATab = gaTab && gaTab.classList.contains('active');
    
    if (isInGATab) {
      // Setze Viewer auf Standard-Nachricht zurück
      const viewer = document.getElementById('viewer');
      if (viewer) {
        viewer.innerHTML = '<div id="viewer-content"><div style="color: var(--secondary-text); text-align: left; font-style: italic; font-size: 0.9rem;">Wählen Sie einen GA-Band aus der linken Liste aus.</div></div>';
      }
      
      // Setze Titel zurück
      const documentTitle = document.getElementById('document-title');
      if (documentTitle) {
        documentTitle.textContent = 'GA-Bände Übersicht';
      }
      
      // Setze currentGANumber zurück, damit Info-Button ausgeblendet wird
      currentGANumber = null;
      
      // Aktualisiere Button-Status, damit Info-Button ausgeblendet wird
      updateButtonStates();
    }
  }
  
  let html = '';
  
  if (filteredData.length === 0 && gaVolumesData.length > 0) {
    html = '<div style="padding: 1rem; color: var(--secondary-text); font-style: italic;">Keine GA-Bände für die Auswahl gefunden</div>';
  } else {
    filteredData.forEach(ga => {
      html += `
        <div style="margin-bottom: 0.4rem;">
          <a href="#" 
             class="ga-volume-link"
             onclick="showGALectures('${ga.number}'); return false;"
             style="
               font-weight: bold; 
               text-decoration: none;
               font-size: 0.9rem;
               display: block;
               padding: 0.1rem 0;
             "
             onmouseover="this.style.textDecoration='underline'"
             onmouseout="this.style.textDecoration='none'">
            ${formatLectureId(ga.number)} - ${ga.title}
          </a>
        </div>
      `;
    });
  }
  
  resultsDiv.innerHTML = html;
  }

// Funktion: Extrahiere alle GA-Nummern, für die Tafeln vorhanden sind
function getGAsWithChalkboards() {
  if (!chalkboardsData || chalkboardsData.length === 0) return [];
  
  // Sammle alle einzigartigen GA-Nummern aus chalkboardsData
  const gasWithChalkboards = new Set();
  chalkboardsData.forEach(cb => {
    if (cb.ga) {
      gasWithChalkboards.add(cb.ga.toUpperCase());
    }
  });
  
  return Array.from(gasWithChalkboards);
}

// Funktion: Befülle GA-Band-Filter-Dropdown
// Bei chalkboardsOnly=true werden nur GAs mit Tafeln angezeigt
function populateGABandFilterDropdown(chalkboardsOnly = false) {
  const dropdown = document.getElementById('ga-band-filter-dropdown');
  if (!dropdown) {
    console.warn('[GA-TAB] Dropdown nicht gefunden');
    return;
  }
  
  // Speichere aktuellen Wert
  const currentValue = dropdown.value;
  
  // Hole GAs mit Tafeln (falls benötigt)
  const gasWithChalkboards = chalkboardsOnly ? getGAsWithChalkboards() : [];
  
  // Leere Dropdown
  if (chalkboardsOnly) {
    dropdown.innerHTML = '<option value="">Alle Tafeln</option>';
  } else {
    dropdown.innerHTML = '<option value="">GA-Bände</option>';
  }
  
  // Sortiere GA-Bände nach Nummer (GA014 wird nicht angezeigt)
  let sortedGAs = [...gaVolumesData]
    .filter(ga => ga.number.toUpperCase() !== 'GA014')
    .sort((a, b) => {
      const numA = parseInt(a.number.replace(/^GA/i, '').replace(/[a-z]/i, '')) || 0;
      const numB = parseInt(b.number.replace(/^GA/i, '').replace(/[a-z]/i, '')) || 0;
      if (numA !== numB) return numA - numB;
      // Bei gleicher Nummer: alphabetisch nach Suffix
      return a.number.localeCompare(b.number);
    });
  
  // Wenn chalkboardsOnly, filtere nur GAs mit Tafeln
  if (chalkboardsOnly && gasWithChalkboards.length > 0) {
    sortedGAs = sortedGAs.filter(ga => {
      const gaNorm = ga.number.replace(/^GA/i, '').toUpperCase();
      return gasWithChalkboards.includes(gaNorm);
    });
    console.log(`[GA-DROPDOWN] Gefiltert auf ${sortedGAs.length} GAs mit Tafeln`);
  }
  
  // Füge GA-Bände hinzu
  sortedGAs.forEach(ga => {
    const option = document.createElement('option');
    option.value = ga.number;
    option.textContent = `${ga.number} - ${ga.title}`;
    dropdown.appendChild(option);
  });
  
  // Stelle vorherigen Wert wieder her falls vorhanden und gültig
  if (currentValue) {
    // Prüfe ob der Wert noch in der Liste ist
    const valueExists = Array.from(dropdown.options).some(opt => opt.value === currentValue);
    if (valueExists) {
      dropdown.value = currentValue;
    } else {
      // Wert existiert nicht mehr (z.B. weil GA keine Tafeln hat) - reset
      dropdown.value = '';
      selectedGABandFilter = null;
    }
  }
}

// Funktion: Toggle zwischen "Chronologisch" (alle Bände) und gefilterter Ansicht
function toggleChronologicalView() {
  const gaBandDropdown = document.getElementById('ga-band-filter-dropdown');
  const yearDropdown = document.getElementById('ga-year-filter-dropdown');
  const btn = document.getElementById('ga-chronological-view-btn');
  const chalkboardsBtn = document.getElementById('ga-chalkboards-btn');
  
  // Deaktiviere Wandtafeln-Ansicht wenn aktiv
  if (isChalkboardsViewActive) {
    isChalkboardsViewActive = false;
    selectedChalkboardsYearFilter = null; // Reset Jahresfilter
    if (chalkboardsBtn) {
      chalkboardsBtn.style.background = 'transparent';
      chalkboardsBtn.style.color = 'var(--accent-color)';
      chalkboardsBtn.classList.remove('active');
    }
    removeChalkboardsYearButtons();
    hideChalkboardsButtons(); // Buttons verstecken
    // Dropdown wieder auf "GA-Bände" zurücksetzen
    populateGABandFilterDropdown(false);
  }
  
  // Prüfe ob irgendein Filter aktiv ist
  if (selectedGABandFilter || selectedYearFilter) {
    // Filter sind aktiv -> Zurücksetzen auf "Alle Bände"
    console.log('[GA-TOGGLE] Setze alle Filter zurück');
    
    // GA-Band Dropdown auf Default zurücksetzen
    if (gaBandDropdown) {
      gaBandDropdown.value = '';
    }
    selectedGABandFilter = null;
    
    // Jahr Dropdown auf Default zurücksetzen
    if (yearDropdown) {
      yearDropdown.value = '';
    }
    selectedYearFilter = null;
    
    // Button-Text zurücksetzen
    if (btn) {
      btn.textContent = 'Chronologisch';
    }
    
    // Alle Bände im Sidebar anzeigen
    displayGAVolumesInSidebar();
    
    // Alle Vorträge chronologisch anzeigen (ohne Filter)
    if (allChronologicalLectures && allChronologicalLectures.length > 0) {
      displayGAChronological(allChronologicalLectures);
    } else {
      showGAChronologicalView(true);
    }
  } else {
    // Keine Filter aktiv -> Chronologische Ansicht anzeigen
    console.log('[GA-TOGGLE] Zeige chronologische Ansicht');
    showGAChronologicalView();
  }
}

// Funktion: Aktualisiere Button-Text basierend auf Dropdown-Auswahl
function updateChronologicalButtonText() {
  const btn = document.getElementById('ga-chronological-view-btn');
  if (btn) {
    btn.textContent = (selectedGABandFilter || selectedYearFilter) ? 'Alle Bände' : 'Chronologisch';
  }
}

// ============================================================================
// WANDTAFELZEICHNUNGEN (CHALKBOARDS) - Galerie-Ansicht
// ============================================================================

let chalkboardsCache = null;
let isChalkboardsViewActive = false;
let chalkboardsSortOrder = 'ga'; // 'ga' oder 'date'

// Funktion: Extrahiere verfügbare Jahre aus Wandtafelzeichnungen
function getChalkboardsYears() {
  if (!chalkboardsData || chalkboardsData.length === 0) {
    return [];
  }
  
  const yearsSet = new Set();
  chalkboardsData.forEach(cb => {
    if (cb.date) {
      const year = parseInt(cb.date.split('-')[0]);
      if (!isNaN(year)) {
        yearsSet.add(year);
      }
    }
  });
  
  return Array.from(yearsSet).sort((a, b) => a - b);
}

// Funktion: Erstelle und zeige Jahres-Buttons für Wandtafelzeichnungen
// Layout und Styling identisch zur chronologischen Ansicht
function createChalkboardsYearButtons() {
  // WICHTIG: Prüfe ob wir wirklich im GA-Tab sind
  const gaTab = document.getElementById('ga-tab');
  const isInGATab = gaTab && gaTab.classList.contains('active');
  
  // Nur anzeigen wenn Wandtafeln-Ansicht aktiv ist UND wir im GA-Tab sind
  if (!isChalkboardsViewActive || !isInGATab) {
    return;
  }
  
  const years = getChalkboardsYears();
  if (years.length === 0) {
    return;
  }
  
  // Suche das fixierte Panel für die Buttons
  const yearButtonsPanel = document.getElementById('chalkboards-year-nav');
  if (!yearButtonsPanel) {
    return;
  }
  
  // Entferne alte Buttons falls vorhanden
  const oldContainer = document.getElementById('chalkboards-year-buttons-container');
  if (oldContainer) {
    oldContainer.remove();
  }
  
  // Erstelle Container für Jahres-Buttons
  const buttonsContainer = document.createElement('div');
  buttonsContainer.id = 'chalkboards-year-buttons-container';
  buttonsContainer.style.cssText = `display: flex; flex-wrap: wrap; column-gap: 0.05rem; row-gap: 0.3rem; align-items: center; margin: 0; padding: 0;`;
  
  // Erstelle Buttons für jedes Jahr (identisches Styling zur chronologischen Ansicht)
  const buttonsHtml = years.map(year => {
    const isActive = selectedChalkboardsYearFilter === year;
    return `<button 
      class="year-nav-btn ${isActive ? 'active-year-btn' : ''}" 
      onclick="filterChalkboardsByYear(${year})"
      data-year="${year}"
      style="padding: 0.4rem 0.8rem; margin: 0 0.2rem; border: 1px solid var(--accent-color); background: ${isActive ? 'var(--accent-color)' : 'var(--background-color)'}; color: ${isActive ? 'white' : 'var(--text-color)'}; cursor: pointer; border-radius: 4px; font-size: 0.85em; transition: all 0.2s;"
    >${year}</button>`;
  }).join('');
  
  // "Alle" Button am Ende
  const isAllActive = selectedChalkboardsYearFilter === null;
  const allButton = `<button 
    class="year-nav-btn ${isAllActive ? 'active-year-btn' : ''}" 
    onclick="filterChalkboardsByYear(null)"
    style="padding: 0.4rem 0.8rem; margin: 0 0.2rem; border: 1px solid var(--accent-color); background: ${isAllActive ? 'var(--accent-color)' : 'var(--background-color)'}; color: ${isAllActive ? 'white' : 'var(--text-color)'}; cursor: pointer; border-radius: 4px; font-size: 0.85em; transition: all 0.2s;"
  >Alle</button>`;
  
  buttonsContainer.innerHTML = buttonsHtml + allButton;
  
  // Füge Buttons in das fixierte Panel ein
  yearButtonsPanel.appendChild(buttonsContainer);
}

// Funktion: Filtere Wandtafelzeichnungen nach Jahr
function filterChalkboardsByYear(year) {
  selectedChalkboardsYearFilter = year;
  console.log('[CHALKBOARDS] Jahr-Filter geändert zu:', year);
  
  // Aktualisiere die Anzeige
  if (isChalkboardsViewActive) {
    loadAndDisplayChalkboards();
  }
}

// Funktion: Entferne Jahres-Buttons für Wandtafelzeichnungen
function removeChalkboardsYearButtons() {
  const container = document.getElementById('chalkboards-year-buttons-container');
  if (container) {
    container.remove();
  }
}

// EINFACHE Hilfsfunktion: Verstecke BEIDE Wandtafeln-Buttons (Info und Sort)
