// Stelle sicher, dass Buttons beim ersten Laden ausgeblendet sind
function initChalkboardsSortToggleButton() {
  const sortToggleBtn = document.getElementById('chalkboardsSortToggleBtn');
  if (sortToggleBtn) {
    sortToggleBtn.style.display = 'none';
  }
  const infoBtn = document.getElementById('chalkboardsInfoBtn');
  if (infoBtn) {
    infoBtn.style.display = 'none';
  }
}

// Funktion: Toggle Wandtafeln-Ansicht
async function toggleChalkboardsView() {
  // WICHTIG: Prüfe ob wir wirklich im GA-Tab sind
  const gaTab = document.getElementById('ga-tab');
  const isInGATab = gaTab && gaTab.classList.contains('active');
  
  if (!isInGATab) {
    console.log('[CHALKBOARDS] Nicht im GA-Tab - überspringe Toggle');
    return;
  }
  
  const btn = document.getElementById('ga-chalkboards-btn');
  const chronoBtn = document.getElementById('ga-chronological-view-btn');
  
  // Prüfe Button-Status anstatt nur Variable (für Robustheit nach anderen Aktionen)
  const buttonIsActive = btn && btn.classList.contains('active');
  
  if (isChalkboardsViewActive && buttonIsActive) {
    // Wandtafeln-Ansicht deaktivieren (nur wenn wirklich aktiv)
    isChalkboardsViewActive = false;
    selectedChalkboardsYearFilter = null; // Reset Jahresfilter
    if (btn) {
      btn.style.background = 'transparent';
      btn.style.color = 'var(--accent-color)';
      btn.classList.remove('active');
    }
    removeChalkboardsYearButtons();
    hideChalkboardsButtons(); // Buttons verstecken
    // Dropdown wieder auf alle GAs zurücksetzen
    populateGABandFilterDropdown(false);
    
    // WICHTIG: Stelle Scroll-Verhalten von #main wieder her und stelle Padding-Werte sicher
    const mainElement = document.getElementById('main');
    if (mainElement) {
      mainElement.style.overflow = '';
      mainElement.style.height = '';
      
      // WICHTIG: Setze Padding explizit mit !important, damit es garantiert angewendet wird
      mainElement.style.setProperty('padding-top', '0.5rem', 'important');
      mainElement.style.setProperty('padding-right', '0', 'important');
      mainElement.style.setProperty('padding-bottom', '2rem', 'important');
      mainElement.style.setProperty('padding-left', '0', 'important');
    }
    
    // Stelle sicher, dass Padding-Werte nicht durch inline-styles überschrieben wurden
    if (typeof ensureMainPaddingPreserved === 'function') {
      ensureMainPaddingPreserved();
    }
    
    // Zurück zur normalen Ansicht
    showGAChronologicalView();
  } else {
    // Wandtafeln-Ansicht aktivieren
    isChalkboardsViewActive = true;
    
    // Deaktiviere chronologische Ansicht falls aktiv
    if (typeof currentGAView !== 'undefined') {
      currentGAView = 'chalkboards';
    }
    
    // Entferne Jahres-Buttons der chronologischen Ansicht
    if (typeof removeChronologicalYearButtons === 'function') {
      removeChronologicalYearButtons();
    }
    if (typeof forceRemoveYearButtons === 'function') {
      forceRemoveYearButtons();
    }
    
    // Button-Styles aktualisieren
    if (btn) {
      btn.style.background = 'var(--accent-color)';
      btn.style.color = 'white';
      btn.classList.add('active');
    }
    if (chronoBtn) {
      chronoBtn.style.background = 'transparent';
      chronoBtn.style.color = 'var(--accent-color)';
      chronoBtn.classList.remove('active');
    }
    
    // Stelle sicher, dass chalkboardsData geladen ist, bevor Dropdown gefiltert wird
    if (!chalkboardsData || chalkboardsData.length === 0) {
      await loadChalkboardsData();
    }
    
    // Dropdown auf nur GAs mit Tafeln filtern
    populateGABandFilterDropdown(true);
    
    // Buttons anzeigen (Info und Sort)
    showChalkboardsButtons();
    
    await loadAndDisplayChalkboards();
  }
}

// Funktion: Toggle Sortierung der Wandtafelzeichnungen
function toggleChalkboardsSort() {
  // WICHTIG: Prüfe ob wir wirklich im GA-Tab sind
  const gaTab = document.getElementById('ga-tab');
  const isInGATab = gaTab && gaTab.classList.contains('active');
  
  if (!isInGATab || !isChalkboardsViewActive) {
    console.log('[CHALKBOARDS] Nicht im GA-Tab oder Wandtafeln-Ansicht nicht aktiv - überspringe Sortierung');
    return;
  }
  
  // Wechsle zwischen 'ga' und 'date'
  chalkboardsSortOrder = chalkboardsSortOrder === 'ga' ? 'date' : 'ga';
  
  // Aktualisiere Icon
  updateChalkboardsSortIcon();
  
  // Lade Wandtafeln neu mit neuer Sortierung
  loadAndDisplayChalkboards();
}

// Funktion: Aktualisiere Sort-Icon basierend auf aktueller Sortierung
function updateChalkboardsSortIcon() {
  const btn = document.getElementById('chalkboardsSortToggleBtn');
  if (!btn) return;
  
  if (chalkboardsSortOrder === 'ga') {
    btn.textContent = '\u25BC';
  } else {
    btn.textContent = '\u25B2';
  }
}

// Funktion: Lade und zeige Wandtafelzeichnungen aus chalkboards.json
async function loadAndDisplayChalkboards() {
  // WICHTIG: Prüfe ob wir wirklich im GA-Tab sind
  const gaTab = document.getElementById('ga-tab');
  const isInGATab = gaTab && gaTab.classList.contains('active');
  
  if (!isInGATab) {
    console.log('[CHALKBOARDS] Nicht im GA-Tab - überspringe Anzeige');
    return;
  }
  
  // WICHTIG: Prüfe ob Wandtafeln-Ansicht wirklich aktiv ist
  if (!isChalkboardsViewActive) {
    console.log('[CHALKBOARDS] Wandtafeln-Ansicht nicht aktiv - überspringe Anzeige');
    return;
  }
  
  const viewer = document.getElementById('viewer');
  if (!viewer) {
    console.error('[CHALKBOARDS] Viewer-Element nicht gefunden');
    return;
  }
  
  // Zeige Ladeindikator
  viewer.innerHTML = `
    <div id="viewer-content">
      <p style="color: var(--secondary-text); font-style: italic;">Lade Wandtafelzeichnungen...</p>
    </div>
  `;
  
  // Stelle sicher, dass chalkboardsData geladen ist
  if (!chalkboardsData || chalkboardsData.length === 0) {
    await loadChalkboardsData();
  }
  
  // Lade chronologische Vorträge für die Links (falls noch nicht geladen)
  await ensureChronologicalLecturesLoaded();
  
  if (!chalkboardsData || chalkboardsData.length === 0) {
    viewer.innerHTML = `
      <div id="viewer-content">
        <p style="color: var(--secondary-text); font-style: italic;">Keine Wandtafelzeichnungen gefunden.</p>
      </div>
    `;
    return;
  }
  
  // Filtere nach GA-Band wenn ausgewählt
  let filteredChalkboards = [...chalkboardsData];
  const gaFilter = selectedGABandFilter ? selectedGABandFilter.replace(/^GA/i, '').toUpperCase() : '';
  
  if (gaFilter) {
    filteredChalkboards = chalkboardsData.filter(cb => 
      cb.ga.toUpperCase() === gaFilter
    );
  }
  
  // Filtere nach Jahr wenn ausgewählt
  if (selectedChalkboardsYearFilter !== null) {
    filteredChalkboards = filteredChalkboards.filter(cb => {
      if (!cb.date) return false;
      const year = parseInt(cb.date.split('-')[0]);
      return year === selectedChalkboardsYearFilter;
    });
  }
  
  // Sortiere nach aktueller Sortierreihenfolge
  if (chalkboardsSortOrder === 'date') {
    // Sortiere nach Datum (Jahr), dann nach GA-Nummer, dann nach Tafelnummer
    filteredChalkboards.sort((a, b) => {
      if (a.date && b.date) {
        const dateCompare = a.date.localeCompare(b.date);
        if (dateCompare !== 0) return dateCompare;
      } else if (a.date) return -1;
      else if (b.date) return 1;
      
      const gaCompare = a.ga.localeCompare(b.ga);
      if (gaCompare !== 0) return gaCompare;
      
      return (a.tafel || 0) - (b.tafel || 0);
    });
  } else {
    // Sortiere nach GA-Nummer, dann nach Datum, dann nach Tafelnummer (Standard)
    filteredChalkboards.sort((a, b) => {
      const gaCompare = a.ga.localeCompare(b.ga);
      if (gaCompare !== 0) return gaCompare;
      
      if (a.date && b.date) {
        const dateCompare = a.date.localeCompare(b.date);
        if (dateCompare !== 0) return dateCompare;
      } else if (a.date) return -1;
      else if (b.date) return 1;
      
      return (a.tafel || 0) - (b.tafel || 0);
    });
  }
  
  const yearFilterText = selectedChalkboardsYearFilter ? ` Jahr ${selectedChalkboardsYearFilter}` : '';
  console.log('[CHALKBOARDS] Zeige:', filteredChalkboards.length, 'Bilder' + (gaFilter ? ' (gefiltert nach GA' + gaFilter + ')' : '') + (yearFilterText ? ' (gefiltert nach' + yearFilterText + ')' : '') + ' (sortiert nach ' + (chalkboardsSortOrder === 'date' ? 'Datum' : 'GA-Nummer') + ')');
  
  // Erst Galerie anzeigen, dann Jahres-Buttons hinzufügen (damit sie nicht überschrieben werden)
  displayChalkboardsGallery(filteredChalkboards);
  createChalkboardsYearButtons();
}

// Funktion: Zeige Wandtafelzeichnungen in Galerie (5 pro Zeile)
function displayChalkboardsGallery(chalkboards) {
  // WICHTIG: Prüfe ob wir wirklich im GA-Tab sind
  const gaTab = document.getElementById('ga-tab');
  const isInGATab = gaTab && gaTab.classList.contains('active');
  
  if (!isInGATab) {
    console.log('[CHALKBOARDS] Nicht im GA-Tab - überspringe Galerie-Anzeige');
    return;
  }
  
  // WICHTIG: Prüfe ob Wandtafeln-Ansicht wirklich aktiv ist
  if (!isChalkboardsViewActive) {
    console.log('[CHALKBOARDS] Wandtafeln-Ansicht nicht aktiv - überspringe Galerie-Anzeige');
    return;
  }
  
  const viewer = document.getElementById('viewer');
  if (!viewer) return;
  
  // Blacklist: Bestimmte WZ ausschließen (GA + Datum)
  const blacklist = [
    { ga: '354', date: '1924-09-24' },
    { ga: '383', date: '1924-03-08' },
    { ga: '383', date: '1924-05-17' }
  ];
  
  // Filtere Blacklist-Einträge heraus
  chalkboards = chalkboards.filter(cb => {
    const isBlacklisted = blacklist.some(bl => 
      cb.ga === bl.ga && cb.date === bl.date
    );
    return !isBlacklisted;
  });
  
  // Setze Titel im Header (wie bei "Vorträge chronologisch")
  const documentTitle = document.getElementById('document-title');
  if (documentTitle) {
    const filterInfo = selectedGABandFilter ? ' aus ' + selectedGABandFilter : '';
    documentTitle.innerHTML = `<span style="font-size: 1em;">Wandtafelzeichnungen</span> <span style="font-size: 0.85em; font-weight: normal; color: var(--secondary-text);">(${chalkboards.length} Bilder${filterInfo})</span>`;
  }
  
  if (!chalkboards || chalkboards.length === 0) {
    viewer.innerHTML = `
      <div id="viewer-content">
        <p style="color: var(--secondary-text); font-style: italic;">Keine Wandtafelzeichnungen gefunden.</p>
        ${selectedGABandFilter ? '<p style="font-size: 0.9em; margin-top: 0.5rem; color: var(--secondary-text);">Versuchen Sie "GA-Bände" im Dropdown.</p>' : ''}
      </div>
    `;
    return;
  }
  
  // Galerie Grid (ohne Header, da Titel oben im document-title)
  let html = '';
  
  // Galerie Grid
  html += '<div class="chalkboards-grid">';
  
  for (const cb of chalkboards) {
    const dateStr = cb.date ? formatChalkboardDate(cb.date) : '';
    const gaNumber = `GA${cb.ga}`;
    const imageUrl = `/ga-k-images/${cb.path}`;
    
    // Finde passenden Vortrag für Link (mit Fehlerbehandlung)
    let lectureId = null;
    try {
      const lecture = findLectureByGAAndDate(cb.ga, cb.date);
      lectureId = lecture ? lecture.ID : null;
    } catch (e) {
      console.warn('[CHALKBOARDS] Fehler bei Vortrag-Suche:', e);
    }
    
    // Escape für onclick
    const escapedImageUrl = imageUrl.replace(/'/g, "\\'");
    const escapedGaNumber = gaNumber.replace(/'/g, "\\'");
    const escapedDateStr = dateStr.replace(/'/g, "\\'");
    const escapedLectureId = lectureId ? lectureId.replace(/'/g, "\\'") : '';
    
    // Info-Text mit oder ohne Link
    // Übergebe GA-Nummer und Datum an openLectureFromChalkboard
    const escapedGaNumberForFunc = cb.ga.replace(/'/g, "\\'");
    const escapedDateForFunc = cb.date ? cb.date.replace(/'/g, "\\'") : '';
    const infoContent = lectureId 
      ? `<a href="#texte&lecture=${encodeURIComponent(lectureId)}" 
            onclick="event.preventDefault(); openLectureFromChalkboard('${escapedLectureId}', '${escapedGaNumberForFunc}', '${escapedDateForFunc}');"
            style="color: var(--link-color); text-decoration: none; cursor: pointer;"
            title="Vortrag öffnen">${gaNumber}${dateStr ? ', ' + dateStr : ''}</a>`
      : `<span>${gaNumber}${dateStr ? ', ' + dateStr : ''}</span>`;
    
    html += `
      <div class="chalkboard-item">
        <img src="${API_BASE}${imageUrl}" 
             alt="${gaNumber} - ${dateStr}" 
             loading="lazy"
             data-image-popup-handler="true"
             onclick="openChalkboardLightbox('${escapedImageUrl}', '${escapedGaNumber}', '${escapedDateStr}')">
        <div class="chalkboard-info">
          ${infoContent}
        </div>
      </div>
    `;
  }
  
  html += '</div>';
  
  // Lightbox ist jetzt global im HTML, muss nicht mehr dynamisch hinzugefügt werden
  
  // Erstelle zweigeteiltes Layout (wie bei chronologischer Ansicht)
  // Entferne vorhandenes Wrapper-Element falls vorhanden
  const existingWrapper = document.getElementById('chalkboards-year-nav-wrapper');
  if (existingWrapper) {
    existingWrapper.remove();
  }
  
  // Berechne die Höhe bis zum unteren Bildschirmrand
  const mainEl = document.getElementById('main');
  const mainRect = mainEl ? mainEl.getBoundingClientRect() : null;
  const availableHeight = mainRect ? (window.innerHeight - mainRect.top - 20) : (window.innerHeight - 220);
  
  // Erstelle Wrapper für zweigeteiltes Layout
  const wrapper = document.createElement('div');
  wrapper.id = 'chalkboards-year-nav-wrapper';
  wrapper.style.cssText = `
    display: flex;
    flex-direction: column;
    height: ${availableHeight}px;
    width: 100%;
    position: relative;
    overflow: hidden;
  `;
  
  // Erstelle oberen Bereich für Jahres-Buttons (FIXIERT, scrollt nicht)
  const yearButtonsPanel = document.createElement('div');
  yearButtonsPanel.id = 'chalkboards-year-nav';
  const bgColor = document.body.classList.contains('dark-mode') ? 'var(--dark-background-color)' : 'var(--background-color)';
  yearButtonsPanel.style.cssText = `
    flex-shrink: 0;
    background: ${bgColor} !important;
    padding: 0rem 1.5rem 1rem 2em;
    border-bottom: none !important;
    box-shadow: none !important;
    z-index: 1003;
    position: relative;
    width: 100%;
  `;
  
  // Erstelle unteren Bereich für Galerie-Inhalt (scrollbar)
  const galleryContentPanel = document.createElement('div');
  galleryContentPanel.id = 'chalkboards-gallery-content';
  galleryContentPanel.style.cssText = `
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    width: 100%;
    box-sizing: border-box;
    padding-bottom: 3rem;
  `;
  
  // Füge Galerie-Inhalt ein
  galleryContentPanel.innerHTML = html;
  
  // Füge beide Panels zum Wrapper hinzu
  wrapper.appendChild(yearButtonsPanel);
  wrapper.appendChild(galleryContentPanel);
  
  // Ersetze den viewer-Inhalt durch den Wrapper
  viewer.innerHTML = '';
  viewer.appendChild(wrapper);
  
  // Deaktiviere das Scrollen von #main
  const mainElementForChalkboards = document.getElementById('main');
  if (mainElementForChalkboards) {
    // Setze overflow: hidden für Scroll-Verhalten
    mainElementForChalkboards.style.overflow = 'hidden';
    mainElementForChalkboards.style.position = 'relative';
    
    // WICHTIG: Setze Padding explizit mit !important, damit es garantiert angewendet wird
    // CSS definiert: padding: 0.5rem 0 2rem 0 !important
    mainElementForChalkboards.style.setProperty('padding-top', '0.5rem', 'important');
    mainElementForChalkboards.style.setProperty('padding-right', '0', 'important');
    mainElementForChalkboards.style.setProperty('padding-bottom', '2rem', 'important');
    mainElementForChalkboards.style.setProperty('padding-left', '0', 'important');
  }
  
  // Stelle sicher, dass Padding-Werte korrekt gesetzt sind
  // WICHTIG: Rufe diese Funktion NACH dem Setzen von overflow auf
  // Verwende mehrere setTimeout-Aufrufe, um sicherzustellen, dass das Padding gesetzt wird
  setTimeout(() => {
    if (typeof ensureMainPaddingPreserved === 'function') {
      ensureMainPaddingPreserved();
    }
    // Starte Padding-Schutz neu, falls verfügbar
    if (typeof startPaddingProtection === 'function') {
      startPaddingProtection();
    }
  }, 10);
  
  setTimeout(() => {
    if (typeof ensureMainPaddingPreserved === 'function') {
      ensureMainPaddingPreserved();
    }
  }, 100);
  
  setTimeout(() => {
    if (typeof ensureMainPaddingPreserved === 'function') {
      ensureMainPaddingPreserved();
    }
  }, 500);
}

// Funktion: Öffne Vortrag aus Wandtafel-Link
// Globale Variable: Speichere WZ-Informationen wenn Vortrag von WZ geöffnet wurde
let openedFromChalkboard = null;

function openLectureFromChalkboard(lectureId, gaNumber = null, dateStr = null) {
  if (!lectureId) return;
  
  console.log(`[CHALKBOARDS] openLectureFromChalkboard: lectureId=${lectureId}, gaNumber=${gaNumber}, dateStr=${dateStr}`);
  
  // Speichere WZ-Informationen für späteren Aufruf von displayLecture
  if (gaNumber && dateStr) {
    // Normalisiere GA-Nummer: entferne "GA"-Präfix falls vorhanden
    const normalizedGA = gaNumber.replace(/^GA/i, '');
    openedFromChalkboard = { gaNumber: normalizedGA, dateStr };
  } else {
    // Versuche GA-Nummer und Datum aus lectureId zu extrahieren
    // Finde den Vortrag in allChronologicalLectures
    if (allChronologicalLectures && allChronologicalLectures.length > 0) {
      const lecture = allChronologicalLectures.find(l => l.ID === lectureId);
      if (lecture) {
        const gaNum = lecture.ID.split('/')[0];
        // Normalisiere GA-Nummer: entferne "GA"-Präfix falls vorhanden
        const normalizedGA = gaNum.replace(/^GA/i, '');
        openedFromChalkboard = { gaNumber: normalizedGA, dateStr: lecture.date };
      }
    }
  }
  
  // Deaktiviere Wandtafeln-Ansicht
  isChalkboardsViewActive = false;
  selectedChalkboardsYearFilter = null; // Reset Jahresfilter
  const btn = document.getElementById('ga-chalkboards-btn');
  if (btn) {
    btn.style.background = 'transparent';
    btn.style.color = 'var(--accent-color)';
    btn.classList.remove('active');
  }
  removeChalkboardsYearButtons();
  hideChalkboardsButtons(); // Buttons verstecken
  
  // WICHTIG: Entferne den Chalkboards-Galerie-Wrapper aus dem Viewer
  const chalkboardsWrapper = document.getElementById('chalkboards-year-nav-wrapper');
  if (chalkboardsWrapper) {
    chalkboardsWrapper.remove();
  }
  
  // Leere den Viewer-Inhalt komplett, bevor der Vortrag geladen wird
  const viewer = document.getElementById('viewer');
  if (viewer) {
    viewer.innerHTML = '<div id="viewer-content"><div style="color: var(--secondary-text); text-align: left; font-style: italic; font-size: 0.9rem;">Lade Vortrag...</div></div>';
  }
  
  // Stelle main overflow wieder her (wurde bei Chalkboards-Galerie auf hidden gesetzt)
  const mainEl = document.getElementById('main');
  if (mainEl) {
    mainEl.style.overflow = '';
  }
  
  // Wechsle zu Tab "Texte" und lade den Vortrag
  switchTab('texte');
  
  // Lade den Vortrag mit showLecture
  setTimeout(() => {
    if (typeof showLecture === 'function') {
      showLecture(lectureId, '');
    } else {
      // Fallback: Setze Hash
      window.location.hash = `texte&lecture=${encodeURIComponent(lectureId)}`;
    }
  }, 100);
}

// Funktion: Finde Vortrag anhand von GA-Nummer und Datum
function findLectureByGAAndDate(gaNumber, dateStr) {
  // Verwende allChronologicalLectures (globale Variable)
  if (!allChronologicalLectures || !allChronologicalLectures.length || !gaNumber || !dateStr) return null;
  
  // Normalisiere GA-Nummer mit normalizeGANumber (behandelt Suffixe korrekt)
  // z.B. "073A" -> "GA073a", "GA073A" -> "GA073a"
  const normalizedGA = normalizeGANumber(gaNumber.startsWith('GA') ? gaNumber : `GA${gaNumber}`);
  
  // Suche Vortrag mit passendem GA und Datum
  return allChronologicalLectures.find(lecture => {
    if (!lecture.ID || !lecture.date) return false;
    
    // Lecture.ID ist z.B. "GA191/2", wir brauchen "GA191" oder "GA073a/2" -> "GA073a"
    const lectureGA = normalizeGANumber(lecture.ID.split('/')[0]);
    if (lectureGA !== normalizedGA) return false;
    
    // Vergleiche Datum (lecture.date kann verschiedene Formate haben)
    // dateStr ist im Format "YYYY-MM-DD"
    const lectureDate = parseLectureDateToISO(lecture.date);
    return lectureDate === dateStr;
  });
}

// Funktion: Lade chronologische Vorträge für Wandtafel-Links (falls noch nicht geladen)
async function ensureChronologicalLecturesLoaded() {
  if (allChronologicalLectures && allChronologicalLectures.length > 0) return true;
  
  try {
    const response = await fetch(`${API_BASE}/api/lectures/chronological`);
    if (!response.ok) return false;
    
    const data = await response.json();
    allChronologicalLectures = data.lectures || [];
    console.log(`[CHALKBOARDS] ${allChronologicalLectures.length} Vorträge für Links geladen`);
    return true;
  } catch (error) {
    console.warn('[CHALKBOARDS] Konnte Vorträge nicht laden:', error);
    return false;
  }
}

// Hilfsfunktion: Konvertiere Lecture-Datum zu ISO-Format
function parseLectureDateToISO(dateStr) {
  if (!dateStr) return null;
  
  // Falls bereits im ISO-Format
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return dateStr;
  
  // Format: "6. August 1920" oder "06.08.1920"
  const monthNames = {
    'januar': '01', 'februar': '02', 'märz': '03', 'april': '04',
    'mai': '05', 'juni': '06', 'juli': '07', 'august': '08',
    'september': '09', 'oktober': '10', 'november': '11', 'dezember': '12'
  };
  
  // Format: "6. August 1920"
  const match1 = dateStr.match(/(\d{1,2})\.?\s*(\w+)\s*(\d{4})/);
  if (match1) {
    const day = match1[1].padStart(2, '0');
    const monthName = match1[2].toLowerCase();
    const year = match1[3];
    const month = monthNames[monthName];
    if (month) return `${year}-${month}-${day}`;
  }
  
  // Format: "06.08.1920"
  const match2 = dateStr.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  if (match2) {
    const day = match2[1].padStart(2, '0');
    const month = match2[2].padStart(2, '0');
    const year = match2[3];
    return `${year}-${month}-${day}`;
  }
  
  return null;
}

// Funktion: Formatiere Datum für Wandtafeln
function formatChalkboardDate(dateStr) {
  if (!dateStr) return '';
  try {
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return dateStr;
    return date.toLocaleDateString('de-DE', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
  } catch (e) {
    return dateStr;
  }
}

// Funktion: Öffne Lightbox für Wandtafelbild (gedreht)
function openChalkboardLightbox(imageUrl, gaNumber, dateStr) {
  const lightbox = document.getElementById('chalkboard-lightbox');
  const img = document.getElementById('chalkboard-lightbox-img');
  const info = document.getElementById('chalkboard-lightbox-info');
  
  if (!lightbox || !img || !info) return;
  
  img.src = `${API_BASE}${imageUrl}`;
  info.innerHTML = `<strong>${gaNumber}</strong>${dateStr ? ' – ' + dateStr : ''}`;
  
  lightbox.classList.add('active');
  document.body.style.overflow = 'hidden';
}

// Funktion: Schließe Lightbox
function closeChalkboardLightbox(event) {
  // Schließe bei Klick auf Hintergrund oder X-Button, aber nicht auf Bild
  if (event && event.target.tagName === 'IMG') return;
  
  const lightbox = document.getElementById('chalkboard-lightbox');
  if (lightbox) {
    lightbox.classList.remove('active');
    document.body.style.overflow = '';
  }
}

// ESC-Taste schließt Wandtafel-Lightbox
document.addEventListener('keydown', function(event) {
  if (event.key === 'Escape') {
    const lightbox = document.getElementById('chalkboard-lightbox');
    if (lightbox && lightbox.classList.contains('active')) {
      closeChalkboardLightbox(event);
    }
  }
});

