    // - Texte-Tab: TOC im Sidebar, Sidebar öffnen
    const summaryPanel = document.getElementById('summary-panel');
    const summaryContent = document.getElementById('summary-content');
    const verticalResizeHandleWrapper = document.getElementById('verticalResizeHandleWrapper');
    const mainContainer = document.getElementById('main-container');
    
    // Prüfe nochmal welcher Tab aktiv ist (kann sich geändert haben)
    const gaTabCheck = document.getElementById('ga-tab');
    const texteTabCheck = document.getElementById('texte-tab');
    const keywordTabCheck = document.getElementById('keyword-tab');
    const isInGATabNow = gaTabCheck && gaTabCheck.classList.contains('active');
    const isInTexteTabNow = texteTabCheck && texteTabCheck.classList.contains('active');
    const isInKeywordTabNow = keywordTabCheck && keywordTabCheck.classList.contains('active');
    
    // WICHTIG: Prüfe ob Navigation aus Members Panel kommt
    const isMembersNavigating = window.membersNavigating === true;
    const isMembersPanelOpen = typeof isMembersPanelActive === 'function' && isMembersPanelActive();
    
