// Zeige chronologische Ansicht
async function showGAChronologicalView(skipHistory = false) {
  currentGAView = 'chronological';
  
  // Chalkboards-Ansicht deaktivieren und Buttons ausblenden
  if (isChalkboardsViewActive) {
    isChalkboardsViewActive = false;
    selectedChalkboardsYearFilter = null; // Reset Jahresfilter
    const chalkboardsBtn = document.getElementById('ga-chalkboards-btn');
    if (chalkboardsBtn) {
      chalkboardsBtn.style.background = 'transparent';
      chalkboardsBtn.style.color = 'var(--accent-color)';
      chalkboardsBtn.classList.remove('active');
    }
    removeChalkboardsYearButtons();
    hideChalkboardsButtons(); // Buttons verstecken
  }
  
  // WICHTIG: Prüfe ob wir im GA-Tab sind - wenn nicht, wechsle zuerst zum GA-Tab
  const gaTab = document.getElementById('ga-tab');
  const isInGATab = gaTab && gaTab.classList.contains('active');
  if (!isInGATab) {
    switchTab('ga');
    // Warte kurz, dann rufe diese Funktion nochmal auf
    setTimeout(() => showGAChronologicalView(skipHistory), 100);
    return;
  }
  
  // Entferne alte Jahres-Buttons aus anderen Ansichten
  const oldButtonsContainer = document.querySelector('.ga-year-buttons-container');
  if (oldButtonsContainer) {
    oldButtonsContainer.remove();
  }
  
  // Browser History Eintrag hinzufügen
  if (!skipHistory) {
    const url = `${window.location.pathname}#ga?view=chronological`;
    history.pushState({ 
      tab: 'ga', 
      gaView: 'chronological' 
    }, '', url);
    }
  
  // Update Button Styling
  const chronBtn = document.getElementById('ga-chronological-view-btn');
  if (chronBtn) {
    chronBtn.style.background = 'var(--accent-color)';
    chronBtn.style.color = 'white';
  }
  
  // Lade alle Vorträge chronologisch
  try {
    // Prüfe ob chronologische Ansicht bereits existiert (Wrapper ersetzt viewer)
    const viewer = document.getElementById('viewer');
    const chronologicalViewerContent = document.getElementById('chronological-viewer-content');
    const targetElement = chronologicalViewerContent || viewer;
    
    if (targetElement) {
      targetElement.innerHTML = '<p style="color: #666; font-style: italic;">Lade chronologische Übersicht...</p>';
    }
    
    const titleElement = document.getElementById('document-title');
    let titleHtml = '<span style="font-size: 1em;">Vorträge chronologisch</span>';
    if (selectedGABandFilter) {
      titleHtml += ` <span style="font-size: 1em;">– ${selectedGABandFilter}</span>`;
    }
    titleElement.innerHTML = titleHtml;
    
    
    const response = await fetch(`${API_BASE}/api/lectures/chronological`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    
    const data = await response.json();
    
    // Entferne GA031 aus der Liste und speichere alle Vorträge für spätere Filterung
    allChronologicalLectures = data.lectures.filter(lecture => {
      if (!lecture.gaNumber) return true;
      const normalizedGA = normalizeGANumber(lecture.gaNumber);
      return normalizedGA !== 'GA031';
    });
    
    // Befülle das Jahr-Filter-Dropdown
    populateYearFilterDropdown();
    
    // Filtere nach ausgewähltem GA-Band und/oder Jahr
    // Hinweis: GA031 wird automatisch in displayGAChronological herausgefiltert
    let filteredLectures = allChronologicalLectures;
    
    // Filter nach GA-Band
    if (selectedGABandFilter) {
      const normalizedFilter = normalizeGANumber(selectedGABandFilter);
      filteredLectures = filteredLectures.filter(lecture => {
        if (!lecture.gaNumber) return false;
        const normalizedLectureGA = normalizeGANumber(lecture.gaNumber);
        return normalizedLectureGA === normalizedFilter;
      });
      console.log('[GA-FILTER] Nach GA-Band gefiltert:', filteredLectures.length, 'Vorträge für', normalizedFilter);
    }
    
    // Filter nach Jahr
    if (selectedYearFilter) {
      filteredLectures = filteredLectures.filter(lecture => {
        if (!lecture.date) return false;
        const year = new Date(lecture.date).getFullYear();
        return year === selectedYearFilter;
      });
      console.log('[GA-FILTER] Nach Jahr gefiltert:', filteredLectures.length, 'Vorträge für Jahr', selectedYearFilter);
    }
    
    displayGAChronological(filteredLectures);
    
  } catch (error) {
    console.error('Fehler beim Laden der chronologischen Ansicht:', error);
    const viewer = document.getElementById('viewer');
    const chronologicalViewerContent = document.getElementById('chronological-viewer-content');
    const errorTarget = chronologicalViewerContent || viewer;
    if (errorTarget) {
      errorTarget.innerHTML = `
        <div class="error-message">
          <strong>Fehler beim Laden der chronologischen Ansicht:</strong><br>${error.message}
        </div>
      `;
    }
  }
}

// Zeige chronologisches Grid
function displayGAChronological(lectures) {
  // Entferne GA031 aus der chronologischen Liste
  if (lectures && lectures.length > 0) {
    lectures = lectures.filter(lecture => {
      if (!lecture.gaNumber) return true;
      const normalizedGA = normalizeGANumber(lecture.gaNumber);
      return normalizedGA !== 'GA031';
    });
  }
  
  // Prüfe ob chronologische Ansicht bereits existiert (Wrapper ersetzt viewer)
  let viewer = document.getElementById('viewer');
  let chronologicalViewerContent = document.getElementById('chronological-viewer-content');
  
  // Wenn chronological-viewer-content existiert, verwende dieses statt viewer
  // Das passiert, wenn die chronologische Ansicht bereits angezeigt wurde und das viewer-Element ersetzt wurde
  let targetElement = chronologicalViewerContent || viewer;
  
  const titleElement = document.getElementById('document-title');
  
  // Sicherheitsprüfung: Prüfe ob target element existiert
  if (!targetElement) {
    console.error('[GA-FILTER] Weder Viewer noch chronological-viewer-content Element gefunden!');
    return;
  }
  
  if (!titleElement) {
    console.error('[GA-FILTER] Title-Element nicht gefunden!');
    return;
  }
  
  // Entferne alle alten Jahres-Buttons aus anderen Ansichten
  const oldButtonsContainer = document.querySelector('.ga-year-buttons-container');
  if (oldButtonsContainer) {
    oldButtonsContainer.remove();
  }
  
  if (!lectures || lectures.length === 0) {
    targetElement.innerHTML = '<p style="color: #666; font-style: italic;">Keine Vorträge gefunden.</p>';
    titleElement.innerHTML = '<span style="font-size: 1em;">Vorträge chronologisch</span>';
    return;
  }
  
  // Setze Titel im Header (mit Filter-Info falls aktiv)
  let titleHtml = `<span style="font-size: 1em;">Vorträge chronologisch</span>`;
  if (selectedGABandFilter) {
    titleHtml += ` <span style="font-size: 1em;">– ${selectedGABandFilter}</span>`;
  }
  titleHtml += ` <span style="font-size: 0.85em; font-weight: normal; color: var(--secondary-text);">(${lectures.length} Vorträge)</span>`;
  titleElement.innerHTML = titleHtml;
  
  // Sortiere Vorträge chronologisch (sollten schon sortiert sein vom Server)
  const sortedLectures = lectures.sort((a, b) => {
    if (a.date && b.date) {
      return new Date(a.date) - new Date(b.date);
    }
    return 0;
  });
  
  // Gruppiere nach Jahr
  const lecturesByYear = {};
  sortedLectures.forEach(lecture => {
    if (lecture.date) {
      const year = new Date(lecture.date).getFullYear();
      if (!lecturesByYear[year]) {
        lecturesByYear[year] = [];
      }
      lecturesByYear[year].push(lecture);
    }
  });
  
  // Sortiere Jahre aufsteigend (nur für Anzeige der gefilterten Vorträge)
  const displayYears = Object.keys(lecturesByYear).sort((a, b) => parseInt(a) - parseInt(b));
  
  // Für die Jahres-Buttons: Verwende ALLE Jahre aus allChronologicalLectures (nicht nur gefilterte)
  const allYearsSet = new Set();
  if (allChronologicalLectures && allChronologicalLectures.length > 0) {
    allChronologicalLectures.forEach(lecture => {
      if (lecture.date) {
        allYearsSet.add(lecture.date.substring(0, 4));
      }
    });
  }
  const years = Array.from(allYearsSet).sort((a, b) => parseInt(a) - parseInt(b));
  
  // Erstelle sticky Jahres-Header mit ALLEN Jahren
  const yearButtonsHtml = years.map(year => {
    const isActive = selectedYearFilter === year;
    return `<button class="year-nav-btn ${isActive ? 'active-year-btn' : ''}" onclick="scrollToChronologicalYear('${year}')" data-year="${year}" style="padding: 0.4rem 0.8rem; margin: 0 0.2rem; border: 1px solid var(--accent-color); background: ${isActive ? 'var(--accent-color)' : 'var(--background-color)'}; color: ${isActive ? 'white' : 'var(--text-color)'}; cursor: pointer; border-radius: 4px; font-size: 0.85em; transition: all 0.2s;">${year}</button>`;
  }).join('');
  
  // "Alle" Button am Ende
  const isAllActive = selectedYearFilter === null;
  const allButton = `<button class="year-nav-btn ${isAllActive ? 'active-year-btn' : ''}" onclick="scrollToChronologicalYear(null)" data-year="all" style="padding: 0.4rem 0.8rem; margin: 0 0.2rem; border: 1px solid var(--accent-color); background: ${isAllActive ? 'var(--accent-color)' : 'var(--background-color)'}; color: ${isAllActive ? 'white' : 'var(--text-color)'}; cursor: pointer; border-radius: 4px; font-size: 0.85em; transition: all 0.2s;">Alle</button>`;
  
  const allYearButtonsHtml = yearButtonsHtml + allButton;
  
  // Speichere die Jahre für späteren Zugriff
  window.chronologicalYears = years;
  
  // Erstelle Grid HTML (sticky Header wird separat eingefügt)
  let html = `
    <div>
      <table style="width: 100%; border-collapse: collapse; margin-top: 0; table-layout: fixed;">
        <thead>
          <tr style="background: var(--sidebar-bg); border-bottom: 2px solid var(--border-color);">
            <th style="padding: 0.4rem; text-align: left; width: 3%; font-size: 0.9em; white-space: nowrap;">Jahr</th>
            <th style="padding: 0.4rem; padding-right: 1rem; text-align: right; width: 17%; font-size: 0.9em;">Datum</th>
            <th style="padding: 0.4rem; padding-right: 0.5rem; text-align: left; width: 8%; font-size: 0.9em;">Ort</th>
            <th style="padding: 0.4rem; padding-left: 0.5rem; text-align: left; width: 72%; font-size: 0.9em;">Vortrag</th>
          </tr>
        </thead>
        <tbody>
  `;
  
  // Hilfsfunktion: Extrahiere nur den Ortsnamen mit intelligenter Erkennung
  const cleanLocation = (loc, fullTitle = '') => {
    // Liste bekannter Vortragsorte (häufigste zuerst)
    const knownCities = [
      'Dornach', 'Berlin', 'Stuttgart', 'München', 'Basel', 'Wien', 'Zürich',
      'Karlsruhe', 'Hamburg', 'Köln', 'Frankfurt', 'Leipzig', 'Dresden', 'Hannover',
      'Nürnberg', 'Breslau', 'Düsseldorf', 'Bremen', 'Mannheim', 'Heidelberg',
      'Bern', 'Genf', 'Luzern', 'St. Gallen', 'Winterthur',
      'Prag', 'Budapest', 'Kristiania', 'Oslo', 'Stockholm', 'Kopenhagen',
      'London', 'Paris', 'Amsterdam', 'Den Haag', 'Haag',
      'Barmen', 'Elberfeld', 'Kassel', 'Weimar', 'Jena', 'Erfurt',
      'Darmstadt', 'Straßburg', 'Freiburg', 'Ulm', 'Augsburg',
      'Bochum', 'Essen', 'Dortmund', 'Münster', 'Wuppertal',
      'Braunschweig', 'Magdeburg', 'Halle', 'Chemnitz',
      'Danzig', 'Stettin', 'Königsberg',
      'Arlesheim', 'Neuchâtel', 'La Chaux-de-Fonds',
      'Torquay', 'Oxford', 'Manchester', 'Penmaenmawr',
      'Helsingfors', 'Helsinki', 'Christiania',
      'Hermannstadt', 'Stratford-on-Avon', 'Stratford'
    ];
    
    // Funktion: Normalisiere Ortsnamen (Capitalize)
    const normalizeCity = (city) => {
      // Spezialfälle mit mehreren Teilen
      const specialCases = {
        'st. gallen': 'St. Gallen',
        'den haag': 'Den Haag',
        'la chaux-de-fonds': 'La Chaux-de-Fonds',
        'stratford-on-avon': 'Stratford-on-Avon',
        'stratford-en-avon': 'Stratford-on-Avon'
      };
      
      const lowerCity = city.toLowerCase();
      if (specialCases[lowerCity]) {
        return specialCases[lowerCity];
      }
      
      // Für Städte mit Bindestrichen: jeden Teil kapitalisieren
      if (city.includes('-')) {
        return city.split('-').map(part => 
          part.charAt(0).toUpperCase() + part.slice(1).toLowerCase()
        ).join('-');
      }
      
      // Standard: Erster Buchstabe groß, Rest klein
      return city.charAt(0).toUpperCase() + city.slice(1).toLowerCase();
    };
    
    // Liste von ungültigen Mustern/Texten
    const invalidPatterns = [
      /^(Erster|Zweiter|Dritter|Vierter|Fünfter|Sechster|Siebter|Achter|Neunter|Zehnter|Elfter|Zwölfter|Dreizehnter|Vierzehnter|Fünfzehnter|Sechzehnter|Siebzehnter|Achtzehnter|Neunzehnter|Zwanzigster|Einundzwanzigster|Zweiundzwanzigster|Dreiundzwanzigster|Vierundzwanzigster|Fünfundzwanzigster|Sechsundzwanzigster|Siebenundzwanzigster|Achtundzwanzigster|Neunundzwanzigster|Dreißigster)\s+Vortrag$/i,
      /^(Erste|Zweite|Dritte|Vierte|Fünfte|Sechste|Siebte|Achte|Neunte|Zehnte|Elfte|Zwölfte|Dreizehnte|Vierzehnte|Fünfzehnte|Sechzehnte|Siebzehnte|Achtzehnte|Neunzehnte|Zwanzigste)\s+Stunde$/i,
      /^(öffentlicher|nicht\s+öffentlicher|Mitglieder)\s*Vortrag$/i,
      /^(Montag|Dienstag|Mittwoch|Donnerstag|Freitag|Samstag|Sonntag|Pfingstmontag|Pfingstsonntag|Karfreitag|Ostermontag|Ostersamstag|Ostersonntag|Gründonnerstag|Himmelfahrt|Dreikönigstag)$/i,
      /^(Notizen|Mündliche\s+Mitteilung|Beilage|Aus\s+einem\s+Brief|Zu\s+einem\s+Brief)/i,
      /^(Ansprache|Schlusswort|Eröffnungsansprache|Fragenbeantwortung|Diskussion|Anmerkung)$/i,
      /^[A-ZÄÖÜ\s]{10,}$/,  // Nur Großbuchstaben (wahrscheinlich Titel)
      /die\s+(größte|klassische)/i,  // Textfragmente
      /^GOETHE|^DIE\s+ENTWICKLUNG|^SCHULUNG/i,  // Bekannte Vortragstitel
      /johannesbau|broschüre|nachrichtenblatt/i,  // Spezielle Begriffe
      /^(Der|Die|Das|Den|Dem|Des)\s+[a-zäöü]/i  // Artikel + Kleinbuchstabe
    ];
    
    // Hilfsfunktion: Suche nach bekanntem Ort in Text
    const findCityInText = (text) => {
      if (!text) return null;
      
      // Spezialfall: Suche nach "Vortrag in [Stadt]" oder "Vortrag, [Stadt]"
      const inMatch = text.match(/Vortrag\s+in\s+([A-ZÄÖÜ][a-zäöüß]+)/);
      if (inMatch) {
        const cityCandidate = inMatch[1];
        const cityLower = cityCandidate.toLowerCase();
        // Prüfe ob es eine bekannte Stadt ist
        for (const city of knownCities) {
          if (city.toLowerCase() === cityLower) {
            return normalizeCity(city);
          }
        }
        // Auch wenn nicht in knownCities, nehme es wenn es plausibel aussieht
        if (cityCandidate.length >= 4 && !invalidPatterns.some(p => p.test(cityCandidate))) {
          return normalizeCity(cityCandidate);
        }
      }
      
      const textLower = text.toLowerCase();
      for (const city of knownCities) {
        const cityLower = city.toLowerCase();
        if (textLower.includes(cityLower)) {
          // Normalisiere Schreibweise
          return normalizeCity(city);
        }
      }
      return null;
    };
    
    // Entferne Klammern und deren Inhalt (z.B. "(Siebenbürgen)")
    let cleanedLoc = loc ? loc.replace(/\s*\([^)]*\)/g, '').trim() : loc;
    
    // Entferne "In " oder "in " am Anfang
    if (cleanedLoc && /^(In|in)\s+/.test(cleanedLoc)) {
      cleanedLoc = cleanedLoc.replace(/^(In|in)\s+/, '');
    }
    
    // 1. Wenn loc ungültig ist, suche im Titel
    if (!cleanedLoc || cleanedLoc === '-' || cleanedLoc.length > 100 || invalidPatterns.some(p => p.test(cleanedLoc.trim()))) {
      const cityFromTitle = findCityInText(fullTitle);
      return cityFromTitle || '-';
    }
    
    // 2. Suche nach bekannten Ortsnamen in loc
    const cityFromLoc = findCityInText(cleanedLoc);
    if (cityFromLoc) {
      return cityFromLoc;
    }
    
    // 3. Versuche Text zu bereinigen
    let cleaned = cleanedLoc
      .replace(/^(Erster|Zweiter|Dritter|Vierter|Fünfter|Sechster|Siebter|Achter|Neunter|Zehnter|Elfter|Zwölfter|Dreizehnter|Vierzehnter|Fünfzehnter|Sechzehnter|Siebzehnter|Achtzehnter|Neunzehnter|Zwanzigster|Einundzwanzigster)\s+Vortrag[,\s]*/i, '')
      .replace(/^(Erste|Zweite|Dritte|Vierte|Fünfte|Sechste|Siebte|Achte|Neunte|Zehnte|Elfte|Zwölfte)\s+Stunde[,\s]*/i, '')
      .replace(/^(öffentlicher|nicht\s+öffentlicher|Mitglieder)\s*Vortrag[,\s]*/i, '')
      .replace(/^Vortrag[,\s]*/i, '')
      .replace(/^\s*[,;]\s*/, '')
      .trim();
    
    // Wenn nach Komma getrennt, nimm den ersten sinnvollen Teil
    if (cleaned.includes(',')) {
      const parts = cleaned.split(',').map(p => p.trim());
      for (const part of parts) {
        if (part.length >= 3 && !invalidPatterns.some(p => p.test(part))) {
          // Suche auch hier nach bekannten Städten
          const cityInPart = findCityInText(part);
          if (cityInPart) return cityInPart;
          return normalizeCity(part);
        }
      }
    }
    
    // Prüfe ob cleaned ein gültiger Ort ist
    if (cleaned.length < 3 || invalidPatterns.some(p => p.test(cleaned))) {
      // Als letztes Resort: Suche im Titel
      const cityFromTitle = findCityInText(fullTitle);
      return cityFromTitle || '-';
    }
    
    // Normalisiere Schreibweise
    return normalizeCity(cleaned);
  };
  
  // Funktion: Füge Bindestriche für Zeilenumbruch bei bestimmten Ortsnamen hinzu
  const addHyphenation = (city) => {
    if (!city) return city;
    // Spezielle Ortsnamen mit Bindestrichen für Zeilenumbruch
    const hyphenationMap = {
      'Hermannstadt': 'Hermann-stadt',
      'Schlachtensee': 'Schlachten-see'
    };
    return hyphenationMap[city] || city;
  };
  
  displayYears.forEach((year, yearIndex) => {
    const yearLectures = lecturesByYear[year];
    
    yearLectures.forEach((lecture, idx) => {
      const date = lecture.date ? formatDate(lecture.date) : '-';
      const title = lecture.fileName || `${formatLectureId(lecture.ID)} - ${lecture.title}`;
      const location = addHyphenation(cleanLocation(lecture.location, title));
      
      // Erste Zeile eines Jahres zeigt das Jahr, danach leer
      const yearCell = idx === 0 ? year : '';
      
      // Linie nur nach dem letzten Vortrag eines Jahres (außer beim letzten Jahr)
      const isLastLectureOfYear = idx === yearLectures.length - 1;
      const isLastYear = yearIndex === years.length - 1;
      const borderStyle = (isLastLectureOfYear && !isLastYear) ? '2px solid var(--border-color)' : 'none';
      
      html += `
        <tr id="year-${year}" style="border-bottom: ${borderStyle}; scroll-margin-top: 80px;" ${idx === 0 ? `data-year-start="${year}"` : ''}>
          <td style="padding: 0.3rem; vertical-align: top; font-weight: ${idx === 0 ? 'bold' : 'normal'}; font-size: 0.85em; white-space: nowrap;">${yearCell}</td>
          <td style="padding: 0.3rem; padding-right: 0.9rem; vertical-align: top; text-align: right; font-size: 0.85em;">${date}</td>
          <td style="padding: 0.3rem; padding-right: 0.1rem; vertical-align: top; font-size: 0.85em; overflow-wrap: break-word; word-break: break-word;">${location}</td>
          <td style="padding: 0.3rem; padding-left: 0.1rem; font-size: 0.85em;">
            <a href="#" onclick="navigateToLectureInTexteTab('${lecture.ID}'); return false;" 
               class="chronological-lecture-link"
               style="text-decoration: none;">
              ${title}
            </a>
          </td>
        </tr>
      `;
    });
  });
  
  html += `
        </tbody>
      </table>
    </div>
  `;
  
  // Prüfe ob wir wirklich im GA-Tab sind (nicht im Texte-Tab oder anderen Tabs)
  const gaTab = document.getElementById('ga-tab');
  const isInGATab = gaTab && gaTab.classList.contains('active');
  
  // Prüfe ob die chronologische Ansicht aktiv ist
  const isChronologicalView = currentGAView === 'chronological';
  
  // WICHTIG: Entferne Jahres-Buttons IMMER zuerst, bevor wir prüfen ob sie erstellt werden sollen
  // Dies verhindert, dass sie in anderen Tabs sichtbar bleiben
  const gaTabCheck = document.getElementById('ga-tab');
  const isInGATabCheck = gaTabCheck && gaTabCheck.classList.contains('active');
  const isChronologicalViewCheck = currentGAView === 'chronological';
  
  // Nur behalten wenn wir wirklich im GA-Tab mit chronologischer Ansicht sind
  if (!isInGATabCheck || !isChronologicalViewCheck) {
    // Verwende globale Funktion falls verfügbar
    if (typeof removeChronologicalYearButtons === 'function') {
      removeChronologicalYearButtons();
      } else {
      const chronologicalNavBeforeCheck = document.getElementById('chronological-year-nav');
      if (chronologicalNavBeforeCheck) {
        chronologicalNavBeforeCheck.remove();
        }
    }
  } else {
    }
  
  // Wenn chronological-viewer-content bereits existiert (Layout wurde bereits erstellt),
  // müssen wir das Layout komplett neu aufbauen, damit die Jahr-Buttons korrekt angezeigt werden
  if (chronologicalViewerContent) {
    console.log('[GA-FILTER] Layout existiert bereits - baue komplett neu auf');
    
    // Entferne das alte Layout
    const wrapper = document.getElementById('chronological-year-nav-wrapper');
    if (wrapper && wrapper.parentNode) {
      // Erstelle einen neuen viewer mit korrektem Padding
      const newViewer = createViewerElement();
      newViewer.innerHTML = html;
      
      // Ersetze den Wrapper durch den neuen Viewer
      wrapper.parentNode.replaceChild(newViewer, wrapper);
      
      // Stelle das Scroll-Verhalten von #main wieder her
      const mainElement = document.getElementById('main');
      if (mainElement) {
        mainElement.style.overflow = '';
        mainElement.style.height = '';
      }
      
      // Aktualisiere die Referenzen für den nachfolgenden Code
      viewer = newViewer;
      targetElement = newViewer;
      chronologicalViewerContent = null; // Erzwinge Neuaufbau des Layouts
      
      console.log('[GA-FILTER] Layout entfernt, viewer wiederhergestellt');
    } else {
      // Fallback: Aktualisiere nur den Inhalt
      chronologicalViewerContent.innerHTML = html;
      
      // Versuche auch die Buttons zu aktualisieren
      const yearNavPanel = document.getElementById('chronological-year-nav');
      let buttonsContainer = document.getElementById('chronological-year-buttons-container');
      
      if (!buttonsContainer && yearNavPanel) {
        buttonsContainer = yearNavPanel.querySelector('div');
      }
      
      if (buttonsContainer) {
        console.log('[GA-FILTER] Aktualisiere Jahr-Buttons im Fallback, Jahre:', years.join(', '));
        buttonsContainer.innerHTML = allYearButtonsHtml;
      }
    }
  } else {
    // Füge HTML in viewer ein (viewer existiert, da chronological-viewer-content nicht existiert)
    targetElement.innerHTML = html;
  }
  
  // WICHTIG: Erstelle zweigeteiltes Layout NUR wenn wir im GA-Tab sind UND die chronologische Ansicht aktiv ist
  // UND wenn das Layout noch nicht existiert (viewer existiert noch)
  // Doppelte Prüfung für maximale Sicherheit
  if (isInGATab && isChronologicalView && isInGATabCheck && isChronologicalViewCheck && !chronologicalViewerContent) {
    // Erstelle ein zweigeteiltes Layout: oberer Bereich für Jahres-Buttons, unterer für Inhalt
    const mainContainer = document.getElementById('main');
    if (mainContainer && viewer) {
      // Entferne vorhandenes sticky Element falls vorhanden
      const existingNav = document.getElementById('chronological-year-nav');
      if (existingNav) {
        existingNav.remove();
      }
      
      // Entferne vorhandenes Wrapper-Element falls vorhanden
      const existingWrapper = document.getElementById('chronological-year-nav-wrapper');
      if (existingWrapper) {
        existingWrapper.remove();
      }
      
      // Prüfe ob bereits ein Wrapper existiert
      let wrapper = document.getElementById('chronological-year-nav-wrapper');
      let yearButtonsPanel = document.getElementById('chronological-year-nav');
      
      if (!wrapper) {
        // Berechne die Höhe bis zum unteren Bildschirmrand
        const mainEl = document.getElementById('main');
        const mainRect = mainEl ? mainEl.getBoundingClientRect() : null;
        const availableHeight = mainRect ? (window.innerHeight - mainRect.top - 20) : (window.innerHeight - 220);
        
        // Erstelle Wrapper für zweigeteiltes Layout
        wrapper = document.createElement('div');
        wrapper.id = 'chronological-year-nav-wrapper';
        wrapper.style.cssText = `
          display: flex;
          flex-direction: column;
          height: ${availableHeight}px;
          width: 100%;
          position: relative;
          overflow: hidden;
        `;
        
        // Erstelle oberen Bereich für Jahres-Buttons (FIXIERT, scrollt nicht)
        yearButtonsPanel = document.createElement('div');
        yearButtonsPanel.id = 'chronological-year-nav';
        const bgColor = document.body.classList.contains('dark-mode') ? 'var(--dark-background-color)' : 'var(--background-color)';
        yearButtonsPanel.style.cssText = `
          flex-shrink: 0;
          background: ${bgColor} !important;
          padding: 0rem 1.5rem 1rem 2em;
          border-bottom: none !important;
          box-shadow: none !important;
          z-index: 1003;
          position: relative;
          width: 100%;
        `;

        // Erstelle Container für Buttons
        const buttonsContainer = document.createElement('div');
        buttonsContainer.id = 'chronological-year-buttons-container';
        buttonsContainer.style.cssText = `display: flex; flex-wrap: wrap; column-gap: 0.05rem; row-gap: 0.3rem; align-items: center; margin: 0; padding: 0;`;
        buttonsContainer.innerHTML = allYearButtonsHtml;
        yearButtonsPanel.appendChild(buttonsContainer);
        
        // Erstelle unteren Bereich für Viewer-Inhalt (scrollbar)
        const viewerContentPanel = document.createElement('div');
        viewerContentPanel.id = 'chronological-viewer-content';
        viewerContentPanel.style.cssText = `
          flex: 1;
          overflow-y: auto;
          overflow-x: hidden;
          width: 100%;
          box-sizing: border-box;
          padding: 0 0 3rem 2em;
        `;
        
        // Verschiebe den viewer-Inhalt in den neuen Container
        const viewerContent = viewer.innerHTML;
        viewerContentPanel.innerHTML = viewerContent;
        viewer.innerHTML = '';
        
        // Füge beide Panels zum Wrapper hinzu
        wrapper.appendChild(yearButtonsPanel);
        wrapper.appendChild(viewerContentPanel);
        
        // Ersetze den viewer durch den Wrapper
        viewer.parentNode.replaceChild(wrapper, viewer);
        
        // Setze den viewer als ID auf den neuen Content-Panel für Kompatibilität
        viewerContentPanel.setAttribute('data-viewer-content', 'true');
        
        // Deaktiviere das Scrollen von #main
        if (mainEl) {
          mainEl.style.overflow = 'hidden';
        }
        
        } else {
        // Wrapper existiert bereits, aktualisiere nur die Buttons
        const buttonsContainer = yearButtonsPanel ? yearButtonsPanel.querySelector('#chronological-year-buttons-container') : null;
        if (buttonsContainer) {
          buttonsContainer.innerHTML = allYearButtonsHtml;
        }
        }
    }
    } else {
    // Wenn nicht im GA-Tab ODER nicht in chronologischer Ansicht, entferne Jahres-Buttons falls vorhanden
    const existingNav = document.getElementById('chronological-year-nav');
    if (existingNav) {
      existingNav.remove();
    } else {
      }
  }
  
  // Event-Listener für Hover-Effekt auf Jahres-Buttons
  document.querySelectorAll('.year-nav-btn').forEach(btn => {
    btn.addEventListener('mouseenter', function() {
      // Nur Hover-Effekt, wenn Button nicht aktiv ist
      if (!this.classList.contains('active-year-btn')) {
        this.style.background = 'var(--accent-color)';
        this.style.color = 'white';
        this.style.borderColor = 'var(--accent-color)';
      }
    });
    btn.addEventListener('mouseleave', function() {
      // Nur zurücksetzen, wenn Button nicht aktiv ist
      if (!this.classList.contains('active-year-btn')) {
        if (document.body.classList.contains('dark-mode')) {
          this.style.background = 'var(--dark-background-color)';
          this.style.color = 'var(--dark-text-color)';
        } else {
          this.style.background = 'var(--background-color)';
          this.style.color = 'var(--text-color)';
        }
        this.style.borderColor = 'var(--accent-color)';
      }
    });
  });
  
  // Aktualisiere Hintergrund des sticky-Elements im Dark Mode und stelle sicher, dass es sticky bleibt
  const navElement = document.getElementById('chronological-year-nav');
  if (navElement) {
    const updateNavBackground = () => {
      const viewerHeader = document.getElementById('viewer-header');
      const headerHeight = viewerHeader ? viewerHeader.offsetHeight : 80;
      
      // Setze padding-top und margin-top für Spalt-Abdeckung + gewünschter Abstand
      const desiredTopSpacing = 0; // HIER ÄNDERN SIE DEN WERT FÜR DEN ABSTAND NACH OBEN! (0 = minimal)
      const negativeMarginTop = -(headerHeight + desiredTopSpacing);
      const paddingTopValue = headerHeight + desiredTopSpacing;
      
      // Setze mehrfach mit verschiedenen Methoden für maximale Robustheit
      navElement.style.paddingTop = `${paddingTopValue}px`;
      navElement.style.marginTop = `${negativeMarginTop}px`;
      navElement.style.setProperty('padding-top', `${paddingTopValue}px`, 'important');
      navElement.style.setProperty('margin-top', `${negativeMarginTop}px`, 'important');
      navElement.style.cssText += ` padding-top: ${paddingTopValue}px !important; margin-top: ${negativeMarginTop}px !important;`;
      document.documentElement.style.setProperty('--chronological-nav-padding-top', `${paddingTopValue}px`);
      
      // buttonsContainer braucht keinen margin-top, da der Abstand über das padding-top des Parent-Elements gesteuert wird
      const buttonsContainer = document.getElementById('chronological-year-buttons-container') || navElement.querySelector('div');
      if (buttonsContainer) {
        // Stelle sicher, dass buttonsContainer keine margin/padding hat
        buttonsContainer.style.setProperty('margin', '0', 'important');
        buttonsContainer.style.setProperty('padding', '0', 'important');
        } else {
        console.error('[CHRONOLOGICAL] buttonsContainer nicht gefunden in updateNavBackground!');
      }
      
      if (document.body.classList.contains('dark-mode')) {
        const bgColor = 'var(--dark-background-color)';
        navElement.style.setProperty('background', bgColor, 'important');
        navElement.style.setProperty('border-bottom', 'none', 'important');
        navElement.style.setProperty('box-shadow', 'none', 'important');
      } else {
        const bgColor = 'var(--background-color)';
        navElement.style.setProperty('background', bgColor, 'important');
        navElement.style.setProperty('border-bottom', 'none', 'important');
        navElement.style.setProperty('box-shadow', 'none', 'important');
      }
    };
    
    // Initiales Update
    updateNavBackground();
    
    // Beobachte Änderungen am body-Element für Dark Mode Wechsel
    const observer = new MutationObserver(updateNavBackground);
    observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
    
  }
}

// Filtert die chronologische Ansicht nach Jahr (oder zeigt alle wenn year=null)
function scrollToChronologicalYear(year) {
  // Speichere den Jahr-Filter
  selectedYearFilter = year;
  
  // Entferne aktive Markierung von allen Buttons
  document.querySelectorAll('.year-nav-btn').forEach(btn => {
    btn.classList.remove('active-year-btn');
    if (document.body.classList.contains('dark-mode')) {
      btn.style.background = 'var(--dark-background-color)';
      btn.style.color = 'var(--dark-text-color)';
    } else {
      btn.style.background = 'var(--background-color)';
      btn.style.color = 'var(--text-color)';
    }
    btn.style.borderColor = 'var(--accent-color)';
    btn.style.fontWeight = 'normal';
  });
  
  // Markiere den angeklickten Button als aktiv
  const clickedButton = year 
    ? document.querySelector(`.year-nav-btn[data-year="${year}"]`)
    : document.querySelector(`.year-nav-btn[data-year="all"]`);
  if (clickedButton) {
    clickedButton.classList.add('active-year-btn');
    clickedButton.style.background = 'var(--accent-color)';
    clickedButton.style.color = 'white';
    clickedButton.style.borderColor = 'var(--accent-color)';
    clickedButton.style.fontWeight = 'bold';
  }
  
  // Filtere und zeige die Vorträge
  if (allChronologicalLectures && allChronologicalLectures.length > 0) {
    let filteredLectures = allChronologicalLectures;
    
    if (year) {
      // Filtere nach Jahr
      filteredLectures = allChronologicalLectures.filter(lecture => {
        if (!lecture.date) return false;
        const lectureYear = lecture.date.substring(0, 4);
        return lectureYear === String(year);
      });
    }
    
    // Zeige gefilterte Vorträge
    displayGAChronological(filteredLectures);
    
    // Aktualisiere Button-Text
    updateChronologicalButtonText();
  }
}

