    // Navigiere zu einer spezifischen Überschrift in einem Vortrag (für GA001/GA018 Inhaltsverzeichnis)
    // Verwendet exakt den gleichen Code wie die TOC-Links im Side Panel
    async function navigateToLectureHeading(lectureId, headingText) {
      try {
        if (!lectureId || !headingText) {
          console.error('[NAVIGATION] Keine Lecture-ID oder Überschrift angegeben');
          return;
        }
        
        console.log('[NAV-HEADING] Navigiere zu Überschrift:', headingText, 'in', lectureId);
        
        // Speichere Ziel-Überschrift global für späteres Scrollen
        window._pendingHeadingScroll = headingText;
        window.skipParagraphHighlight = true;
        
        // Wechsle zum Texte-Tab
        switchTab('texte', true);
        
        // Extrahiere GA-Nummer
        const gaNumber = lectureId.split('/')[0];
        
        // Setze den GA-Filter
        const texteGAFilter = document.getElementById('texteGAFilter');
        if (texteGAFilter && gaNumber) {
          texteGAFilter.value = gaNumber;
        }
        
        // Lade den Vortrag
        await showLecture(lectureId, null, []);
        
        // Scrolle zur Überschrift - exakt wie activateTOCLinks
        const scrollToTargetHeading = () => {
          const targetText = window._pendingHeadingScroll;
          if (!targetText) return false;
          
          const viewer = document.getElementById('viewer');
          const mainContainer = document.getElementById('main');
          if (!viewer || !mainContainer) return false;
          
          // Find the H2, H3 or H4 heading that matches (exakt wie TOC-Links)
          const headings = viewer.querySelectorAll('h2, h3, h4');
          let foundHeading = null;
          const searchText = targetText.trim();
          
          for (const heading of headings) {
            const headingTextContent = heading.textContent.trim();
            
            // Try exact match first
            if (headingTextContent === searchText) {
              foundHeading = heading;
              break;
            }
            
            // Try case-insensitive match
            if (headingTextContent.toLowerCase() === searchText.toLowerCase()) {
              foundHeading = heading;
              break;
            }
            
            // Try partial match (contains)
            if (headingTextContent.includes(searchText) || searchText.includes(headingTextContent)) {
              foundHeading = heading;
              break;
            }
          }
          
          if (foundHeading) {
            scrollViewerHeadingBelowViewportHeader(foundHeading, 'auto');
            window._pendingHeadingScroll = null;
            return true;
          }
          return false;
        };
        
        // Versuche mehrmals mit kurzen Intervallen (50ms für schnellere Reaktion)
        let attempts = 0;
        const tryScroll = setInterval(() => {
          attempts++;
          if (scrollToTargetHeading() || attempts > 30) {
            clearInterval(tryScroll);
            window._pendingHeadingScroll = null;
            window.skipParagraphHighlight = false;
          }
        }, 50);
        
      } catch (error) {
        console.error('[NAVIGATION] Fehler beim Navigieren zur Überschrift:', error);
        window._pendingHeadingScroll = null;
        window.skipParagraphHighlight = false;
      }
    }
    
    // Stelle Funktionen im globalen Scope verfügbar für onclick-Attribute
    window.navigateToLectureInTexteTab = navigateToLectureInTexteTab;
    window.navigateToLectureHeading = navigateToLectureHeading;
    window.resolveGA028ChapterId = resolveGA028ChapterId;
    window.showBookChapter = showBookChapter;

