    // Extrahiere GA-Nummer aus Lecture-Objekt
    function extractGANumber(lecture) {
      if (!lecture) return null;
      
      // Versuche aus ID (z.B. "GA100/8" -> "GA100")
      if (lecture.ID) {
        const match = lecture.ID.match(/^(GA\d{3}[a-z]?)/i);
        if (match) return match[1];
      }
      
      // Versuche aus fileName (z.B. "GA100/8 - TITLE" -> "GA100")
      if (lecture.fileName) {
        const match = lecture.fileName.match(/^(GA\d{3}[a-z]?)/i);
        if (match) return match[1];
      }
      
      return null;
    }

