    // Viewer-Inhalt als Datei herunterladen
    window.downloadViewerContent = async function(format, tabName) {
      const viewer = document.getElementById('viewer');
      if (!viewer) return;
      
      closeDownloadModal();
      
      // Extrahiere Text aus dem Viewer
      const clone = viewer.cloneNode(true);
      
      // Entferne Buttons und interaktive Elemente
      clone.querySelectorAll('button, .download-btn, .copy-btn').forEach(el => el.remove());
      
      // Entferne alle Inline-Styles für sauberes PDF
      clone.querySelectorAll('*').forEach(el => {
        el.removeAttribute('style');
      });
      
      // Hole den Textinhalt
      let textContent = '';
      
      // Verarbeite den Inhalt je nach Format
      if (format === 'md') {
        // Markdown: Konvertiere HTML zu Markdown-ähnlichem Text
        textContent = `# ${tabName}\n\n`;
        
        // Durchlaufe die Hauptelemente
        clone.querySelectorAll('h1, h2, h3, h4, p, div, li').forEach(el => {
          const text = el.innerText.trim();
          if (!text) return;
          
          if (el.tagName === 'H1') textContent += `# ${text}\n\n`;
          else if (el.tagName === 'H2') textContent += `## ${text}\n\n`;
          else if (el.tagName === 'H3') textContent += `### ${text}\n\n`;
          else if (el.tagName === 'H4') textContent += `#### ${text}\n\n`;
          else if (el.tagName === 'LI') textContent += `- ${text}\n`;
          else if (el.tagName === 'P' || el.tagName === 'DIV') {
            // Nur wenn es keinen verschachtelten Block-Inhalt hat
            if (!el.querySelector('h1, h2, h3, h4, p, div')) {
              textContent += `${text}\n\n`;
            }
          }
        });
      } else {
        // TXT: Einfacher Text
        textContent = `${tabName}\n${'='.repeat(tabName.length)}\n\n`;
        textContent += clone.innerText;
      }
      
      // Bereinige mehrfache Leerzeilen
      textContent = textContent.replace(/\n{3,}/g, '\n\n').trim();
      
      // Erstelle Dateinamen
      const timestamp = new Date().toISOString().slice(0, 10);
      const fileName = `${tabName} - ${timestamp}`;
      
      if (format === 'pdf') {
        // PDF-Download mit Browser-Print
        const printWindow = window.open('', '_blank');
        if (!printWindow) {
          alert('Popup-Blocker verhindert den PDF-Download. Bitte erlauben Sie Popups für diese Seite.');
          return;
        }
        
        printWindow.document.write(`
          <!DOCTYPE html>
          <html>
          <head>
            <title>${tabName}</title>
            <style>
              * {
                margin: 0 !important;
                padding: 0 !important;
                box-sizing: border-box;
              }
              body { 
                font-family: Georgia, 'Times New Roman', serif !important; 
                line-height: 1.3 !important; 
                padding: 1.5rem !important;
                max-width: 800px;
                margin: 0 auto !important;
                font-size: 11pt !important;
              }
              h1 { 
                color: #467886 !important; 
                margin-top: 0 !important; 
                margin-bottom: 0.4em !important;
                font-size: 1.3em !important;
                padding-bottom: 0.2em !important;
              }
              h2 { 
                color: #467886 !important; 
                margin-top: 0.5em !important; 
                margin-bottom: 0.2em !important;
                font-size: 1.15em !important;
              }
              h3 { 
                color: #467886 !important; 
                margin-top: 0.4em !important; 
                margin-bottom: 0.15em !important;
                font-size: 1.05em !important;
              }
              h4 { 
                color: #467886 !important; 
                margin-top: 0.3em !important; 
                margin-bottom: 0.1em !important;
                font-size: 1em !important;
              }
              p { 
                margin: 0.15em 0 !important; 
                padding: 0 !important;
              }
              ul, ol {
                margin: 0.15em 0 !important;
                padding-left: 1.2em !important;
              }
              li {
                margin: 0.05em 0 !important;
                padding: 0 !important;
              }
              a { 
                color: #467886 !important; 
                text-decoration: none !important;
              }
              div {
                margin: 0 !important;
                padding: 0 !important;
              }
              .semantic-answer, .answer-content, .timeline-item, .concept-content {
                margin: 0 !important;
                padding: 0 !important;
              }
              mark {
                background: #fff3cd !important;
                padding: 0 !important;
              }
            </style>
          </head>
          <body>
            <h1>${tabName}</h1>
            ${clone.innerHTML}
          </body>
          </html>
        `);
        printWindow.document.close();
        
        setTimeout(() => {
          printWindow.print();
        }, 500);
      } else {
        // TXT oder MD Download
        const extension = format === 'md' ? 'md' : 'txt';
        const blob = new Blob([textContent], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${fileName} - ${extension}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }
    };
    
    // Text als verschiedene Formate herunterladen
    window.downloadAsText = async function(format) {
      // Prüfe ob Text markiert ist
      const selection = window.getSelection();
      const selectedText = selection.toString().trim();
      const hasSelection = selectedText.length > 0;
      
      // Hole Viewer-Content Element
      const viewerContent = document.getElementById('viewer-content') || document.getElementById('viewer');
      if (!viewerContent && !currentLectureData) {
        alert('Kein Text zum Herunterladen vorhanden.');
        return;
      }
      
      try {
        // Schließe Modal
        closeDownloadModal();
        
        // Hole Header aus document-title
        const documentTitleEl = document.getElementById('document-title');
        let headerLine = '';
        if (documentTitleEl) {
          // Entferne Links und extrahiere Text
          const titleClone = documentTitleEl.cloneNode(true);
          titleClone.querySelectorAll('a').forEach(a => {
            a.replaceWith(document.createTextNode(a.textContent));
          });
          headerLine = titleClone.textContent.trim();
        }
        
        // Erstelle Textinhalt
        let textContent = '';
        let bodyContent = '';
        
        if (hasSelection) {
          // Nur markierten Text verwenden
          bodyContent = selectedText;
        } else if (viewerContent) {
          // Gesamten Viewer-Content verwenden
          const clone = viewerContent.cloneNode(true);
          
          // Entferne Buttons und interaktive Elemente
          clone.querySelectorAll('button, .download-btn, .copy-btn, script, style').forEach(el => el.remove());
          
          // Entferne alle Inline-Styles für sauberen Text
          clone.querySelectorAll('*').forEach(el => {
            el.removeAttribute('style');
          });
          
          // Konvertiere HTML zu Text
          if (format === 'md') {
            // Markdown-ähnliche Konvertierung
            clone.querySelectorAll('h1, h2, h3, h4, h5, h6, p, div, li').forEach(el => {
              const text = el.innerText.trim();
              if (!text) return;
              
              const tagName = el.tagName;
              if (tagName === 'H1') bodyContent += `# ${text}\n\n`;
              else if (tagName === 'H2') bodyContent += `## ${text}\n\n`;
              else if (tagName === 'H3') bodyContent += `### ${text}\n\n`;
              else if (tagName === 'H4') bodyContent += `#### ${text}\n\n`;
              else if (tagName === 'H5') bodyContent += `##### ${text}\n\n`;
              else if (tagName === 'H6') bodyContent += `###### ${text}\n\n`;
              else if (tagName === 'LI') bodyContent += `- ${text}\n`;
              else if (tagName === 'P' || tagName === 'DIV') {
                // Nur wenn es keinen verschachtelten Block-Inhalt hat
                if (!el.querySelector('h1, h2, h3, h4, h5, h6, p, div')) {
                  bodyContent += `${text}\n\n`;
                }
              }
            });
          } else {
            // Einfacher Text
            bodyContent = clone.innerText || clone.textContent || '';
          }
        } else if (currentLectureData) {
          // Fallback: Verwende currentLectureData (alte Logik)
          const lecture = currentLectureData;
          const lectureId = lecture.ID || lecture.id || 'text';
          const title = lecture.title || '';
          const location = lecture.location || '';
          const date = lecture.date ? formatDate(lecture.date) : '';
          const paragraphs = lecture.paragraphs || [];
          
          // Hole Überschriften falls vorhanden
          const headings = currentLectureSummary?.headings || [];
          const summary = currentLectureSummary?.summary || '';
          
          let headerParts = [lectureId];
          if (title) headerParts.push(title);
          headerLine = headerParts.join(' - ');
          
          let subHeaderParts = [];
          if (location) subHeaderParts.push(location);
          if (date) subHeaderParts.push(date);
          const subHeader = subHeaderParts.join(', ');
          
          // Format-spezifische Formatierung
          if (format === 'md') {
            bodyContent = `# ${headerLine}\n\n`;
            if (subHeader) bodyContent += `*${subHeader}*\n\n`;
            if (summary) bodyContent += `**Zusammenfassung:** ${summary}\n\n---\n\n`;
            
            paragraphs.forEach((para, idx) => {
              if (para._deleted) return;
              const paraIndex = para.index ? para.index.replace(/^\^/, '') : `para_${idx}`;
              const matchingHeadings = headings.filter(h => {
                const hIndex = (h.index || '').replace(/^\^/, '');
                return hIndex === paraIndex;
              });
              matchingHeadings.forEach(heading => {
                const level = heading.level === 'h3' ? '##' : '###';
                bodyContent += `\n${level} ${heading.text || heading.title}\n\n`;
              });
              let content = para.content || para.text || '';
              content = content.replace(/<[^>]+>/g, '');
              content = content.replace(/&nbsp;/g, ' ');
              content = content.replace(/&amp;/g, '&');
              content = content.replace(/&lt;/g, '<');
              content = content.replace(/&gt;/g, '>');
              content = content.replace(/&quot;/g, '"');
              if (content.trim()) {
                bodyContent += content.trim() + '\n\n';
              }
            });
          } else {
            bodyContent = headerLine + '\n';
            bodyContent += '='.repeat(headerLine.length) + '\n\n';
            if (subHeader) bodyContent += subHeader + '\n\n';
            if (summary) bodyContent += 'Zusammenfassung:\n' + summary + '\n\n' + '-'.repeat(40) + '\n\n';
            
            paragraphs.forEach((para, idx) => {
              if (para._deleted) return;
              const paraIndex = para.index ? para.index.replace(/^\^/, '') : `para_${idx}`;
              const matchingHeadings = headings.filter(h => {
                const hIndex = (h.index || '').replace(/^\^/, '');
                return hIndex === paraIndex;
              });
              matchingHeadings.forEach(heading => {
                const headingText = heading.text || heading.title || '';
                bodyContent += '\n' + headingText.toUpperCase() + '\n\n';
              });
              let content = para.content || para.text || '';
              content = content.replace(/<[^>]+>/g, '');
              content = content.replace(/&nbsp;/g, ' ');
              content = content.replace(/&amp;/g, '&');
              content = content.replace(/&lt;/g, '<');
              content = content.replace(/&gt;/g, '>');
              content = content.replace(/&quot;/g, '"');
              if (content.trim()) {
                bodyContent += content.trim() + '\n\n';
              }
            });
          }
        }
        
        // Bereinige mehrfache Leerzeilen
        bodyContent = bodyContent.replace(/\n{3,}/g, '\n\n').trim();
        
        // Kombiniere Header und Body
        if (format === 'md') {
          if (headerLine) {
            textContent = `# ${headerLine}\n\n${bodyContent}`;
          } else {
            textContent = bodyContent;
          }
        } else {
          if (headerLine) {
            textContent = headerLine + '\n' + '='.repeat(headerLine.length) + '\n\n' + bodyContent;
          } else {
            textContent = bodyContent;
          }
        }
        
        // Dateiname erstellen
        let safeFilename = 'text';
        if (headerLine) {
          safeFilename = headerLine.replace(/[^a-zA-Z0-9äöüÄÖÜß]/g, '_').substring(0, 50);
        } else if (currentLectureData) {
          const lectureId = currentLectureData.ID || currentLectureData.id || 'text';
          safeFilename = lectureId.replace(/[^a-zA-Z0-9äöüÄÖÜß]/g, '_');
        }
        
        if (hasSelection) {
          safeFilename += '_Auszug';
        }
        
        if (format === 'pdf') {
          // PDF mit jsPDF erstellen
          await generatePdfFromText(textContent, headerLine || 'Text', safeFilename);
        } else {
          // TXT oder MD als Download
          const blob = new Blob([textContent], { type: 'text/plain;charset=utf-8' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `${safeFilename} - ${format}`;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          URL.revokeObjectURL(url);
        }
        
      } catch (error) {
        console.error('[DOWNLOAD] Fehler:', error);
        alert('Fehler beim Erstellen des Downloads:\n\n' + error.message);
      }
    };
    
    // PDF aus Text generieren
    async function generatePdfFromText(textContent, title, filename) {
      try {
        const { jsPDF } = window.jspdf;
        
        // Erstelle neues PDF
        const pdf = new jsPDF({
          orientation: 'portrait',
          unit: 'mm',
          format: 'a4'
        });
        
        // Schriftart und Größe
        const pageWidth = pdf.internal.pageSize.getWidth();
        const pageHeight = pdf.internal.pageSize.getHeight();
        const margin = 20;
        const textWidth = pageWidth - 2 * margin;
        
        // Titel
        pdf.setFontSize(14);
        pdf.setFont(undefined, 'bold');
        const titleLines = pdf.splitTextToSize(title, textWidth);
        pdf.text(titleLines, margin, margin + 5);
        
        // Berechne Startposition für Text
        let yPosition = margin + 5 + (titleLines.length * 6) + 10;
        
        // Haupttext
        pdf.setFontSize(11);
        pdf.setFont(undefined, 'normal');
        
        // Text in Zeilen aufteilen
        const lines = textContent.split('\n');
        
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          
          // Prüfe ob Überschrift (Zeile mit === oder nur Großbuchstaben)
          const isHeader = line.match(/^={3,}$/) || (line.trim() === line.toUpperCase() && line.length > 3 && line.length < 100);
          
          if (isHeader && !line.match(/^={3,}$/)) {
            pdf.setFont(undefined, 'bold');
            yPosition += 4; // Extra Abstand vor Überschrift
          }
          
          // Zeile umbrechen wenn nötig
          const wrappedLines = pdf.splitTextToSize(line || ' ', textWidth);
          
          for (const wrappedLine of wrappedLines) {
            // Prüfe ob neue Seite nötig
            if (yPosition > pageHeight - margin) {
              pdf.addPage();
              yPosition = margin;
            }
            
            pdf.text(wrappedLine, margin, yPosition);
            yPosition += 5; // Zeilenabstand
          }
          
          // Reset nach Überschrift
          if (isHeader && !line.match(/^={3,}$/)) {
            pdf.setFont(undefined, 'normal');
          }
          
          // Extra Leerzeile nach Absatzumbruch
          if (line === '') {
            yPosition += 2;
          }
        }
        
        // PDF speichern
        pdf.save(`${filename}.pdf`);
        
      } catch (error) {
        console.error('[PDF-GENERATE] Fehler:', error);
        throw error;
      }
    }

    // Einfache, erweiterbare Rechtschreib-Autokorrektur für deutsche Begriffe/GA-Kontexte
    function autocorrectQuery(q) {
      if (!q) return q;
      let s = String(q);
      // Beispielhafte, häufige Korrekturen (erweiterbar)
      const corrections = [
        ['bewußtsein', 'Bewusstsein'],
        ['bewußtseins', 'Bewusstseins'],
        ['anthroposophie', 'Anthroposophie'],
        ['rudolf steiner', 'Rudolf Steiner'],
        ['goethe', 'Goethe'],
        ['kants', 'Kants'],
        ['ich organisation', 'Ich-Organisation'],
        ['aetherleib', 'Ätherleib'],
        ['astral leib', 'Astralleib'],
        ['geist selbst', 'Geist-Selbst']
      ];
      corrections.forEach(([from, to]) => {
        const re = new RegExp(`\\b${from}\\b`, 'gi');
        s = s.replace(re, to);
      });
      // Erstes Zeichen groß, wenn sinnvoll
      s = s.trim();
      if (s.length > 0) {
        s = s.charAt(0).toUpperCase() + s.slice(1);
      }
      return s;
    }


