/**
 * Button 3: Alles neu für aktuellen Vortrag
 */
async function generateCurrentAll() {
  if (!currentLectureData || !currentLectureData.ID) {
    alert('Kein Vortrag geladen.');
    return;
  }
  
  if (!confirm('WARNUNG: Alle Daten (S+H+TOC+KW) werden komplett neu generiert und überschrieben. Fortfahren?')) {
    return;
  }
  
  // Button Status auf "aktiv..." setzen
  const btn = document.getElementById('viewerRegenerateBtn');
  const originalText = btn.innerHTML;
  btn.innerHTML = '<em>aktiv...</em>';
  btn.disabled = true;
  
  const lectureId = currentLectureData.ID;
  const providerSelect = document.getElementById('batch-provider-select');
  const selectedProvider = providerSelect?.value || null;
  
  setUILocked(true);
  try {
    const resp = await fetch(`${API_BASE}/api/batch-regenerate-all`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        lectureIds: [lectureId],
        preferredProvider: selectedProvider
      })
    });
    
    if (!resp.ok) throw new Error(`Server-Fehler: ${resp.status}`);
    
    const result = await resp.json();
    
    if (result.processed > 0) {
      alert(`? Alles neu generiert:\nSummary, Headings, TOC und Keywords komplett neu erstellt`);
      
      // Lade aktualisierte Summary-Daten vom Server
      const summaryResp = await fetch(`${API_BASE}/api/check-summary/${encodeURIComponent(lectureId.split('/')[0])}/${encodeURIComponent(lectureId.split('/')[1])}`);
      if (summaryResp.ok) {
        const summaryData = await summaryResp.json();
        
        // Aktualisiere lokale Daten - normalisiere Struktur falls nötig
        currentLectureSummary = {
          summary: summaryData.summary,
          headings: summaryData.headings || [],
          tableOfContents: summaryData.tableOfContents || [],
          lectureKeywords: summaryData.lectureKeywords || [],
          version: summaryData.version || 'v2'
        };
        
        // Weise Summary-Daten auch an currentLectureData zu
        currentLectureData.summary = summaryData.summary;
        currentLectureData.headings = summaryData.headings || [];
        currentLectureData.tableOfContents = summaryData.tableOfContents || [];
        currentLectureData.lectureKeywords = summaryData.lectureKeywords || [];
        
        // Zeige aktualisierte Ansicht im Viewer
        displaySummaryWithHeadings(currentLectureData, currentLectureSummary);
        
        // Aktualisiere GA-Übersicht im linken Panel (zeigt neue Keywords!)
        const gaNumber = lectureId.split('/')[0];
        externalSummaryDBCache = null; // Cache löschen
        openGAOverview(gaNumber);
      }
    } else if (result.failed > 0) {
      alert(`? Fehler bei der Generierung`);
    }
  } catch (err) {
    alert('Fehler: ' + err.message);
  } finally {
    setUILocked(false);
    
    // Button-Text wiederherstellen
    btn.innerHTML = originalText;
    btn.disabled = false;
  }
}

