// ENTFERNT: updateKeywordsButtonText() und regenerateLectureKeywords()
// Keywords werden jetzt über "Summary neu" Button generiert (zusammen mit TOC)

// Startet die Batch-Zusammenfassungs-Generation für den aktuell im Tab Texte ausgewählten GA-Band
function startBatchSummaries() {
  const gaNumber = document.getElementById('texteGAFilter')?.value;
  if (!gaNumber) {
    alert('Bitte wählen Sie zuerst einen GA-Band im Tab Texte (Dropdown) aus.');
    return;
  }

  // Starte direkt Batch-Verarbeitung (detaillierte Prüfung erfolgt in batchSummarizeGA)
  batchSummarizeGA(gaNumber);
}

// Führt die Summarizer-Requests sequentiell aus und zeigt Fortschritt an
async function batchSummarizeGA(gaNumber) {
  const resultsContainer = document.getElementById('results');
  resultsContainer.innerHTML = `
    <div class="batch-progress" id="batch-progress-ui">
      <div id="batch-status">Vorbereiten...</div>
      <div style="margin-top:8px; background:#e9eef0; border-radius:4px; overflow:hidden;">
        <div class="bar" id="batch-progress-bar"></div>
      </div>
    </div>
  `;

  try {
    // Hole ausgewählten Provider aus Keywords-Tab (wie bei "Summary neu")
    const selectedProviderRadio = document.querySelector('input[name="llmProvider"]:checked');
    const selectedProvider = selectedProviderRadio ? selectedProviderRadio.value : null;
    // Sperre UI während des Batch-Laufs
    setUILocked(true);
    
    // Lade lokale summary-database (nur lokal verfügbar)
    let summaryDB = {};
    try {
      const sresp = await fetch(`${API_BASE}/summary-database.json`, { cache: 'no-store' });
      if (sresp.ok) summaryDB = await sresp.json();
    } catch (e) {
      console.warn('Konnte summary-database.json nicht laden:', e.message);
    }
    
    const resp = await fetch(`${API_BASE}/api/ga-overview/${encodeURIComponent(gaNumber)}`);
    if (!resp.ok) throw new Error(`GA-Overview konnte nicht geladen werden: ${resp.status}`);
    const data = await resp.json();
    let lectures = data.lectures || [];
    if (lectures.length === 0) {
      resultsContainer.innerHTML = '<p>Keine Vorträge in dieser GA gefunden.</p>';
      return;
    }

    // Nur Vorträge ohne Summary/TOC/Keywords verarbeiten (prüfe gegen summary-database.json)
    const missing = lectures.filter(l => {
      const lectureId = l.ID;
      const entry = summaryDB[lectureId];
      // Vortrag braucht Verarbeitung wenn:
      // 1. Kein Eintrag in der DB ODER
      // 2. Summary fehlt/leer ODER
      // 3. TOC fehlt/leer ODER
      // 4. Keywords fehlen/leer
      return !entry || 
             !entry.summary || (typeof entry.summary === 'string' && entry.summary.trim() === '') ||
             !entry.tableOfContents || entry.tableOfContents.length === 0 ||
             !entry.lectureKeywords || entry.lectureKeywords.length === 0;
    });
    
    
    if (missing.length === 0) {
      alert(`Alle Vorträge in ${gaNumber} haben bereits vollständige Daten (Summary, TOC, Keywords).`);
      return;
    }
    lectures = missing;

    const total = lectures.length;
    let completed = 0;
    let failed = 0;

    for (const lecture of lectures) {
      const lectureId = lecture.ID;
      const statusEl = document.getElementById('batch-status');
      const barEl = document.getElementById('batch-progress-bar');
      if (statusEl) statusEl.textContent = `Verarbeite ${lectureId} - ${completed + 1} - ${total})`;

      try {
        const sResp = await fetch(`${API_BASE}/api/summarize-lecture`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            lectureId: lectureId, 
            forceRegenerate: false,  // Batch: Nur fehlende Daten ergänzen
            preferredProvider: selectedProvider
          })
        });

        if (!sResp.ok) {
          const errorData = await sResp.json();
          console.warn('Fehler bei Zusammenfassung', lectureId, sResp.status, errorData.error);
          failed += 1;
        } else {
          const sData = await sResp.json();
          }
      } catch (err) {
        console.warn('Exception beim Erzeugen der Summary für', lectureId, err);
        failed += 1;
      }

      completed += 1;
      const pct = Math.round((completed / total) * 100);
      if (barEl) barEl.style.width = pct + '%';
    }

  const doneMsg = `Batch fertig. ${completed - failed} erfolgreich, ${failed} fehlgeschlagen.`;
    const statusEl = document.getElementById('batch-status');
    if (statusEl) statusEl.textContent = doneMsg;

  // UI wieder freigeben
  setUILocked(false);

    // Aktualisiere die GA-Übersicht, damit neue Summaries sichtbar werden
    setTimeout(() => {
      openGAOverview(gaNumber);
    }, 800);

  } catch (err) {
    console.error('Batch-Fehler:', err);
    resultsContainer.innerHTML = `<div class="error-message"><strong>Batch-Fehler:</strong><br>${err.message}</div>`;
  }
}

// Startet die Batch-Zusammenfassungs-Generation für alle GA-Bände in der Dropdown-Liste im Tab Texte
async function startBatchAllSummaries() {
  try {
    // Hole ausgewählten Provider aus Keywords-Tab (wie bei "Summary neu")
    const selectedProviderRadio = document.querySelector('input[name="llmProvider"]:checked');
    const selectedProvider = selectedProviderRadio ? selectedProviderRadio.value : null;
    // Hole alle GA-Bände aus dem Dropdown im Tab Texte
    const texteGAFilter = document.getElementById('texteGAFilter');
    if (!texteGAFilter) {
      alert('Dropdown im Tab Texte nicht gefunden.');
      return;
    }
    
    // Sammle alle GA-Nummern aus dem Dropdown (außer dem ersten leeren Eintrag)
    const gaBands = [];
    for (let i = 1; i < texteGAFilter.options.length; i++) {
      const value = texteGAFilter.options[i].value;
      if (value) gaBands.push(value);
    }
    
    if (gaBands.length === 0) {
      alert('Keine GA-Bände im Dropdown gefunden.');
      return;
    }
    
    // Lade lokale summary-database VORHER (nur lokal verfügbar)
    let summaryDB = {};
    try {
      const sresp = await fetch(`${API_BASE}/summary-database.json`, { cache: 'no-store' });
      if (sresp.ok) summaryDB = await sresp.json();
    } catch (e) {
      console.warn('Konnte summary-database.json nicht laden:', e.message);
    }
    
    // Sammle alle Vorträge ohne Summary aus allen GA-Bänden
    const lectureIdsToProcess = [];
    
    for (const gaNumber of gaBands) {
      try {
        const resp = await fetch(`${API_BASE}/api/ga-overview/${encodeURIComponent(gaNumber)}`);
        if (!resp.ok) continue; // Überspringe GA-Bände, die nicht geladen werden können
        const data = await resp.json();
        const lectures = data.lectures || [];
        
        // Filter: nur Vorträge ohne Summary/TOC/Keywords (prüfe gegen summary-database.json)
        for (const lecture of lectures) {
          const lectureId = lecture.ID;
          const entry = summaryDB[lectureId];
          // Vortrag braucht Verarbeitung wenn:
          // 1. Kein Eintrag in der DB ODER
          // 2. Summary fehlt/leer ODER
          // 3. TOC fehlt/leer ODER
          // 4. Keywords fehlen/leer
          const needsProcessing = !entry || 
                                  !entry.summary || (typeof entry.summary === 'string' && entry.summary.trim() === '') ||
                                  !entry.tableOfContents || entry.tableOfContents.length === 0 ||
                                  !entry.lectureKeywords || entry.lectureKeywords.length === 0;
          if (needsProcessing) {
            lectureIdsToProcess.push(lectureId);
          }
        }
      } catch (err) {
        console.warn(`Fehler beim Laden von ${gaNumber}:`, err.message);
      }
    }


    if (lectureIdsToProcess.length === 0) {
      alert('Alle Vorträge in den verfügbaren GA-Bänden haben bereits vollständige Daten (Summary, TOC, Keywords).');
      return;
    }
    
    // Bestätigung mit korrekter Anzahl
    if (!confirm(`Batch All: Es werden ${lectureIdsToProcess.length} Vorträge in ${gaBands.length} GA-Bänden verarbeitet (fehlende Summary/TOC/Keywords werden ergänzt). Fortfahren?`)) {
      return;
    }

    // Sperre UI während des Batch-All Prozesses
    setUILocked(true);

    // Teile in 10 Portionen auf
    const portions = 10;
    const chunkSize = Math.ceil(lectureIdsToProcess.length / portions);
    const chunks = [];
    for (let i = 0; i < lectureIdsToProcess.length; i += chunkSize) {
      chunks.push(lectureIdsToProcess.slice(i, i + chunkSize));
    }

    // UI vorbereiten
    const resultsContainer = document.getElementById('results');
    resultsContainer.innerHTML = `
      <div class="batch-progress" id="batch-progress-ui">
        <div id="batch-status">Vorbereiten Batch All...</div>
        <div style="margin-top:8px; background:#e9eef0; border-radius:4px; overflow:hidden;">
          <div class="bar" id="batch-progress-bar"></div>
        </div>
        <div style="margin-top:8px;"><button id="batch-cancel-btn" class="depth-btn" style="padding:4px 8px; font-size:0.85em;">Abbrechen</button></div>
      </div>
    `;

    const abortController = new AbortController();
    document.getElementById('batch-cancel-btn').addEventListener('click', () => {
      abortController.abort();
    });

    let totalProcessed = 0;
    let totalFailed = 0;

    // Verarbeite die Chunks parallel (alle Portionen gleichzeitig)
    const total = lectureIdsToProcess.length;
    let processedTotal = 0;
    let failedTotal = 0;

    const statusEl = document.getElementById('batch-status');
    const barEl = document.getElementById('batch-progress-bar');
    if (statusEl) statusEl.textContent = `Starte ${chunks.length} Portionen parallel (${total} Vorträge aus ${gaBands.length} GA-Bänden)...`;

    // Shared onProgress callback
    const onProgress = ({ success }) => {
      processedTotal += 1;
      if (!success) failedTotal += 1;
      try {
        if (barEl) barEl.style.width = Math.round((processedTotal / total) * 100) + '%';
        if (statusEl) statusEl.textContent = `Verarbeitet ${processedTotal} - ${total} - ${failedTotal} fehlgeschlagen)`;
      } catch (e) {}
    };

    const promises = chunks.map((chunk, idx) => {
      if (!chunk || chunk.length === 0) return Promise.resolve({ processed: 0, failed: 0 });
      return batchSummarizeLectures(chunk, { concurrency: 10, signal: abortController.signal, onProgress, preferredProvider: selectedProvider });
    });

    const settled = await Promise.allSettled(promises);
    // Aggregate results
    for (const res of settled) {
      if (res.status === 'fulfilled') {
        totalProcessed += res.value.processed || 0;
        totalFailed += res.value.failed || 0;
      } else {
        // rejected (possibly aborted)
        console.warn('Portion failed or aborted:', res.reason);
      }
    }

    // Ensure progress bar full
    if (barEl) barEl.style.width = '100%';

    const statusElFin = document.getElementById('batch-status');
    if (statusElFin) statusElFin.textContent = `Batch All fertig. ${totalProcessed - totalFailed} erfolgreich, ${totalFailed} fehlgeschlagen.`;
    // Aktualisiere Ansicht
    setTimeout(() => { try { if (typeof refreshLectureList === 'function') refreshLectureList(); } catch(e){} }, 800);

  // UI wieder freigeben
  setUILocked(false);

  } catch (err) {
    alert('Fehler beim Starten von Batch All: ' + err.message);
    setUILocked(false);
  }
}

// ============================================================================
// PAGES CORRECTION - Seitenzahlen überprüfen und korrigieren
// ============================================================================

/**
 * Exportiert den aktuell ausgewählten GA-Band oder einzelnen Vortrag neu.
 * Wenn ein Vortrag im Side Panel angeklickt ist, wird nur dieser exportiert.
 * Erkennt automatisch den Typ (Bücher, Vorträge, Briefe) und ruft das passende Export-Skript auf.
 */
async function exportCurrentGA() {
  // Prüfe ob wir lokal sind
  if (!isLocal) {
    alert('Diese Funktion ist nur lokal verfügbar.');
    return;
  }
  
  // Hole den aktuell ausgewählten GA-Band
  const gaNumber = document.getElementById('texteGAFilter')?.value;
  if (!gaNumber) {
    alert('Bitte wählen Sie zuerst einen GA-Band aus.');
    return;
  }
  
  // Prüfe ob ein einzelner Vortrag angeklickt ist
  const lectureId = window.currentOpenLectureId;
  const isLectureExport = lectureId && lectureId.startsWith('GA');
  
  // Zeige Bestätigungsdialog
  let confirmMsg;
  let exportTarget;
  
  if (isLectureExport) {
    confirmMsg = `Einzelnen Vortrag "${lectureId}" exportieren?\n\nDies wird:\n |  Die Markdown-Quelle für diesen Vortrag lesen\n |  Die JSON-Daten für diesen Vortrag aktualisieren\n\nDer Export kann einige Sekunden dauern.`;
    exportTarget = lectureId;
  } else {
    confirmMsg = `GA-Band ${gaNumber} neu exportieren?\n\nDies wird:\n |  Die Markdown-Quellen aus Steiner_GA/ lesen\n |  Die JSON-Dateien neu generieren\n |  Bestehende Pagebreaks für diesen Band löschen\n\nDer Export kann einige Sekunden dauern.`;
    exportTarget = gaNumber;
  }
  
  if (!confirm(confirmMsg)) {
    return;
  }
  
  // Zeige Fortschrittsanzeige im Viewer
  const viewer = document.getElementById('viewer');
  const exportLabel = isLectureExport ? `Vortrag: ${lectureId}` : `GA-Band: ${gaNumber}`;
  viewer.innerHTML = `
    <div style="padding: 2rem; text-align: center;">
      <h3 style="margin-bottom: 1rem;">📤 Export: ${exportLabel}</h3>
      <div id="export-progress" style="margin-bottom: 1rem;">
        <p style="color: #17a2b8;">? Export wird gestartet...</p>
      </div>
      <p style="color: #666; font-size: 0.9em;">
        Bitte warten Sie, bis der Export abgeschlossen ist.
      </p>
    </div>
  `;
  
  // Scrolle zum Viewer und stelle sicher, dass er sichtbar ist
  viewer.scrollTop = 0;
  viewer.scrollIntoView({ behavior: 'auto', block: 'start' });
  
  try {
    // Rufe Backend-API für Export auf
    const requestBody = isLectureExport 
      ? { gaNumber, lectureId } 
      : { gaNumber };
    
    const resp = await fetch(`${API_BASE}/api/export/ga`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(requestBody)
    });
    
    const result = await resp.json();
    const progressDiv = document.getElementById('export-progress');
    
    if (resp.ok && result.success) {
      // Erfolg
      const lectureInfo = result.lectureId 
        ? `<p><strong>Vortrag:</strong> ${result.lectureId}</p>` 
        : '';
      progressDiv.innerHTML = `
        <p style="color: #5cb85c; font-size: 1.2em;">\u2713 Export erfolgreich!</p>
        <div style="background: var(--code-bg); padding: 1rem; border-radius: 8px; margin-top: 1rem; text-align: left;">
          <p><strong>GA-Band:</strong> ${result.gaNumber}</p>
          ${lectureInfo}
          <p><strong>Typ:</strong> ${result.type}</p>
          <p><strong>Exportierte Dateien:</strong> ${result.files?.length || 1}</p>
          ${result.lectureCount ? `<p><strong>Vorträge:</strong> ${result.lectureCount}</p>` : ''}
          ${result.message ? `<p style="margin-top: 0.5rem; color: #666;">${result.message}</p>` : ''}
        </div>
      `;
      
      // Füge Buttons hinzu
      progressDiv.insertAdjacentHTML('afterend', `
        <div style="margin-top: 1.5rem; display: flex; gap: 1rem; justify-content: center;">
          <button class="depth-btn" onclick="location.reload()" style="padding: 8px 16px; background: #17a2b8; color: white; border: none;">
            🔄 Seite neu laden
          </button>
          <button class="depth-btn" onclick="openPagesCorrectionDialog()" style="padding: 8px 16px;">
            📄 Seitenmarker einfügen
          </button>
        </div>
      `);
      
    } else {
      // Fehler
      progressDiv.innerHTML = `
        <p style="color: #d9534f; font-size: 1.2em;">\u2717 Export fehlgeschlagen</p>
        <div style="background: #f8d7da; padding: 1rem; border-radius: 8px; margin-top: 1rem; text-align: left; color: #721c24;">
          <p><strong>Fehler:</strong> ${result.error || 'Unbekannter Fehler'}</p>
          ${result.details ? `<pre style="margin-top: 0.5rem; white-space: pre-wrap; font-size: 0.85em;">${result.details}</pre>` : ''}
        </div>
      `;
      
      progressDiv.insertAdjacentHTML('afterend', `
        <div style="margin-top: 1.5rem;">
          <button class="depth-btn" onclick="location.reload()" style="padding: 8px 16px;">
            Schließen
          </button>
        </div>
      `);
    }
    
  } catch (err) {
    console.error('[EXPORT] Fehler:', err);
    const progressDiv = document.getElementById('export-progress');
    if (progressDiv) {
      progressDiv.innerHTML = `
        <p style="color: #d9534f; font-size: 1.2em;">\u2717 Verbindungsfehler</p>
        <p style="margin-top: 0.5rem;">${err.message}</p>
      `;
    }
  }
}

/**
 * Führt process_pagebreaks.py für den aktuell ausgewählten GA-Band aus.
 * Fügt Seitenmarker in JSON und MD-Dateien ein.
 */
async function openPagesCorrectionDialog() {
  // Prüfe ob wir lokal sind
  if (!isLocal) {
    alert('Diese Funktion ist nur lokal verfügbar.');
    return;
  }
  
  // Hole den aktuell ausgewählten GA-Band
  const gaNumber = document.getElementById('texteGAFilter')?.value;
  if (!gaNumber) {
    alert('Bitte wählen Sie zuerst einen GA-Band aus.');
    return;
  }
  
  // Prüfe ob ein einzelner Vortrag angeklickt ist
  const lectureId = window.currentOpenLectureId;
  // Prüfe ob lectureId ein gültiges Format hat (GA201/1, GA201 (1.), etc.)
  const isLectureProcess = lectureId && (
    lectureId.match(/^GA\d{3}[a-z]?\s*\(\d+\.\)/i) ||  // GA201 (1.)
    lectureId.match(/^GA\d{3}[a-z]?\/\d+/i)           // GA201/1
  );
  
  // Debug-Ausgabe
  if (lectureId) {
    console.log('[PAGES] Lecture ID gefunden:', lectureId, 'isLectureProcess:', isLectureProcess);
  }
  
  // Bestätigungsdialog
  let confirmMsg;
  let processTarget;
  
  if (isLectureProcess) {
    confirmMsg = `Seitenmarker für einzelnen Vortrag "${lectureId}" generieren?\n\nDies führt process_pagebreaks.py aus:\n |  PDF aus Steiner_GA_pdf/ kopieren\n |  Seitenmarker nur für diesen Vortrag in JSON einfügen\n |  Seitenmarker in MD-Dateien einfügen\n |  Alte Override-Dateien inaktivieren\n\nDer Prozess kann einige Sekunden dauern.`;
    processTarget = lectureId;
  } else {
    confirmMsg = `Seitenmarker für ${gaNumber} generieren?\n\nDies führt process_pagebreaks.py aus:\n |  PDF aus Steiner_GA_pdf/ kopieren\n |  Seitenmarker in JSON einfügen\n |  Seitenmarker in MD-Dateien einfügen\n |  Alte Override-Dateien inaktivieren\n\nDer Prozess kann einige Sekunden dauern.`;
    processTarget = gaNumber;
  }
  
  if (!confirm(confirmMsg)) {
    return;
  }
  
  // Zeige Fortschrittsanzeige im Viewer
  const viewer = document.getElementById('viewer');
  const processLabel = isLectureProcess ? `Vortrag: ${lectureId}` : `GA-Band: ${gaNumber}`;
  viewer.innerHTML = `
    <div style="padding: 2rem; text-align: center;">
      <h3 style="margin-bottom: 1rem;">📄 Seitenmarker generieren: ${processLabel}</h3>
      <div id="pages-progress" style="margin-bottom: 1rem;">
        <p style="color: #17a2b8;">? Führe process_pagebreaks.py aus...</p>
      </div>
      <p style="color: #666; font-size: 0.9em;">
        Bitte warten Sie, bis der Prozess abgeschlossen ist.
      </p>
    </div>
  `;
  
  try {
    // Rufe Backend-API auf
    const requestBody = isLectureProcess 
      ? { gaNumber, lectureId } 
      : { gaNumber };
    
    const resp = await fetch(`${API_BASE}/api/pages/process`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(requestBody)
    });
    
    const result = await resp.json();
    const progressDiv = document.getElementById('pages-progress');
    
    if (resp.ok && result.success) {
      // Erfolg
      const lectureInfo = result.lectureId 
        ? `<p><strong>Vortrag:</strong> ${result.lectureId}</p>` 
        : '';
      progressDiv.innerHTML = `
        <p style="color: #5cb85c; font-size: 1.2em;">\u2713 Seitenmarker erfolgreich eingef\u00FCgt!</p>
        <div style="background: var(--code-bg); padding: 1rem; border-radius: 8px; margin-top: 1rem; text-align: left;">
          <p><strong>GA-Band:</strong> ${result.gaNumber}</p>
          ${lectureInfo}
          <p><strong>JSON-Marker:</strong> ${result.jsonMarkers || 0}</p>
          <p><strong>MD-Marker:</strong> ${result.mdMarkers || 0}</p>
          <p><strong>PDF kopiert:</strong> ${result.pdfCopied ? '\u2713' : '\u2014'}</p>
          <p><strong>Override deaktiviert:</strong> ${result.overrideDeactivated ? '\u2713' : '\u2014'}</p>
          ${result.message ? `<p style="margin-top: 0.5rem; color: #666;">${result.message}</p>` : ''}
        </div>
      `;
      
      // Füge Buttons hinzu
      progressDiv.insertAdjacentHTML('afterend', `
        <div style="margin-top: 1.5rem; display: flex; gap: 1rem; justify-content: center;">
          <button class="depth-btn" onclick="location.reload()" style="padding: 8px 16px; background: #17a2b8; color: white; border: none;">
            🔄 Seite neu laden
          </button>
        </div>
        <p style="margin-top: 1rem; color: #856404; background: #fff3cd; padding: 0.5rem; border-radius: 4px;">
          ⚠️ <strong>Wichtig:</strong> Server neu starten (Ctrl+C, dann nb), damit die Änderungen wirksam werden!
        </p>
      `);
      
    } else {
      // Fehler
      progressDiv.innerHTML = `
        <p style="color: #d9534f; font-size: 1.2em;">\u2717 Fehler bei der Verarbeitung</p>
        <div style="background: #f8d7da; padding: 1rem; border-radius: 8px; margin-top: 1rem; text-align: left; color: #721c24;">
          <p><strong>Fehler:</strong> ${result.error || 'Unbekannter Fehler'}</p>
          ${result.details ? `<pre style="margin-top: 0.5rem; white-space: pre-wrap; font-size: 0.85em;">${result.details}</pre>` : ''}
        </div>
      `;
      
      progressDiv.insertAdjacentHTML('afterend', `
        <div style="margin-top: 1.5rem;">
          <button class="depth-btn" onclick="location.reload()" style="padding: 8px 16px;">
            Schließen
          </button>
        </div>
      `);
    }
    
  } catch (err) {
    console.error('[PAGES] Fehler:', err);
    const progressDiv = document.getElementById('pages-progress');
    if (progressDiv) {
      progressDiv.innerHTML = `
        <p style="color: #d9534f; font-size: 1.2em;">\u2717 Verbindungsfehler</p>
        <p style="margin-top: 0.5rem;">${err.message}</p>
      `;
    }
  }
}

