/**
 * @deprecated - ersetzt durch process_pagebreaks.py
 */
async function generatePagesForLecture_LEGACY(lectureId) {
  const viewer = document.getElementById('viewer');
  
  viewer.innerHTML = `
    <div style="padding: 2rem; text-align: center;">
      <p>Generiere Seitenzahlen für ${lectureId}...</p>
    </div>
  `;
  
  try {
    // Extrahiere GA-Nummer
    const gaMatch = lectureId.match(/^(GA\d{3}[a-z]?)/i);
    if (!gaMatch) {
      throw new Error('Ungültige Lecture-ID');
    }
    const gaNumber = gaMatch[1].toUpperCase();
    
    // Prüfe ob Pagebreaks existieren
    const statusResp = await fetch(`${API_BASE}/api/pages/status/${encodeURIComponent(gaNumber)}`);
    const status = await statusResp.json();
    
    if (!status.hasPagebreaks) {
      // Pagebreaks müssen erst generiert werden
      viewer.innerHTML = `
        <div style="padding: 2rem;">
          <h3 style="color: #f0ad4e;">? Pagebreaks fehlen für ${gaNumber}</h3>
          <p>Bevor Seitenzahlen eingefügt werden können, müssen die Pagebreaks aus dem PDF extrahiert werden.</p>
          <div style="margin-top: 1rem;">
            <button class="depth-btn" onclick="generatePagebreaksForGAs('${gaNumber}')" 
                    style="padding: 8px 16px; background: #ffc107; color: #212529; border: none;">
              📑 Pagebreaks generieren
            </button>
            <button class="depth-btn" onclick="openPagesCorrectionDialog()" style="padding: 8px 16px; margin-left: 1rem;">
              Zurück
            </button>
          </div>
        </div>
      `;
      return;
    }
    
    // Generiere Pagebreaks für den gesamten GA-Band und lade dann neu
    // force=true: Auch wenn Pagebreaks existieren, neu generieren (für Vorträge ohne Seitenzahlen)
    const resp = await fetch(`${API_BASE}/api/pages/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ gaNumber, force: true })
    });
    
    const result = await resp.json();
    
    if (result.success) {
      viewer.innerHTML = `
        <div style="padding: 2rem;">
          <h3 style="color: #5cb85c;">? Seitenzahlen generiert</h3>
          <p>${result.message || 'Seitenzahlen wurden erfolgreich eingefügt.'}</p>
          <div style="margin-top: 1rem;">
            <button class="depth-btn" onclick="showLecture('${lectureId}')" style="padding: 8px 16px; background: #17a2b8; color: white; border: none;">
              Vortrag anzeigen
            </button>
            <button class="depth-btn" onclick="openPagesCorrectionDialog()" style="padding: 8px 16px; margin-left: 1rem;">
              Zurück zur Übersicht
            </button>
          </div>
        </div>
      `;
    } else {
      throw new Error(result.error || 'Unbekannter Fehler');
    }
    
  } catch (err) {
    console.error('[PAGES] Generierung Fehler:', err);
    viewer.innerHTML = `
      <div style="padding: 2rem;">
        <h3 style="color: #d9534f;">? Fehler bei der Generierung</h3>
        <p>${err.message}</p>
        <button class="depth-btn" onclick="openPagesCorrectionDialog()" style="margin-top: 1rem;">Zurück</button>
      </div>
    `;
  }
}

/**
 * Generiert Seitenzahlen für mehrere Vorträge
 */
async function generatePagesForMultiple(lectureIdsString) {
  const lectureIds = lectureIdsString.split(',').filter(Boolean);
  
  if (lectureIds.length === 0) {
    alert('Keine Vorträge zum Generieren ausgewählt.');
    return;
  }
  
  const viewer = document.getElementById('viewer');
  
  // Ermittle betroffene GA-Bände
  const gaNumbers = [...new Set(lectureIds.map(id => {
    const match = id.match(/^(GA\d{3}[a-z]?)/i);
    return match ? match[1].toUpperCase() : null;
  }).filter(Boolean))];
  
  viewer.innerHTML = `
    <div style="padding: 2rem;">
      <h3 style="margin-bottom: 1rem;">📄 Seitenzahlen werden generiert...</h3>
      <div id="gen-progress">
        ${gaNumbers.map(ga => `
          <div id="gen-${ga}" style="padding: 0.5rem; margin-bottom: 0.5rem; background: var(--code-bg); border-radius: 4px;">
            <span style="color: #17a2b8;">\u23F3</span> ${ga}: Warte...
          </div>
        `).join('')}
      </div>
      <p style="color: #666; font-size: 0.9em; margin-top: 1rem;">
        Die Seitenzahlen werden aus den Pagebreaks eingefügt...
      </p>
    </div>
  `;
  
  let successCount = 0;
  let errorCount = 0;
  
  for (const gaNumber of gaNumbers) {
    const progressDiv = document.getElementById(`gen-${gaNumber}`);
    if (progressDiv) {
      progressDiv.innerHTML = `<span style="color: #17a2b8;">\u23F3</span> ${gaNumber}: Generiere...`;
    }
    
    try {
      // Prüfe ob Pagebreaks existieren
      const statusResp = await fetch(`${API_BASE}/api/pages/status/${encodeURIComponent(gaNumber)}`);
      const status = await statusResp.json();
      
      // Generiere Pagebreaks (force=true: auch wenn bereits vorhanden, neu generieren)
      if (progressDiv) {
        progressDiv.innerHTML = `<span style="color: #17a2b8;">\u23F3</span> ${gaNumber}: Generiere Seitenzahlen...`;
      }
      
      const resp = await fetch(`${API_BASE}/api/pages/generate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ gaNumber, force: true })
      });
      
      const result = await resp.json();
      
      if (result.success) {
        if (progressDiv) {
          progressDiv.innerHTML = `<span style="color: #5cb85c;">\u2713</span> ${gaNumber}: Seitenzahlen eingef\u00FCgt`;
        }
        successCount++;
      } else {
        throw new Error(result.error);
      }
      
    } catch (err) {
      errorCount++;
      if (progressDiv) {
        progressDiv.innerHTML = `<span style="color: #d9534f;">\u2717</span> ${gaNumber}: ${err.message}`;
      }
    }
  }
  
  // Zeige Zusammenfassung
  const summaryHtml = `
    <div style="margin-top: 1.5rem; padding: 1rem; background: ${errorCount === 0 ? '#d4edda' : '#fff3cd'}; border-radius: 8px;">
      <h4>${errorCount === 0 ? '? Generierung abgeschlossen' : '? Generierung mit Warnungen'}</h4>
      <p>Erfolgreich: ${successCount} GA-Bände</p>
      ${errorCount > 0 ? `<p style="color: #856404;">Fehler: ${errorCount} GA-Bände</p>` : ''}
      <div style="margin-top: 1rem;">
        <button class="depth-btn" onclick="openPagesCorrectionDialog()" style="padding: 8px 16px; background: #17a2b8; color: white; border: none;">
          🔄 Erneut analysieren
        </button>
        <button class="depth-btn" onclick="location.reload()" style="padding: 8px 16px; margin-left: 1rem;">
          Schließen
        </button>
      </div>
    </div>
  `;
  
  const progressContainer = document.getElementById('gen-progress');
  if (progressContainer) {
    progressContainer.insertAdjacentHTML('afterend', summaryHtml);
  }
}

