// NEUE 3-BUTTON ARCHITEKTUR - UNIFIED BATCH GENERATION
// ============================================================================

/**
 * BUTTON 1: Grundstruktur generieren (S+H+TOC)
 * Überspringt Vorträge die bereits S+H+TOC haben
 */
async function batchGenerateStructure() {
  const gaNumber = document.getElementById('texteGAFilter')?.value;
  if (!gaNumber) {
    alert('Bitte wählen Sie zuerst einen GA-Band aus.');
    return;
  }
  
  // Button Status auf "aktiv..." setzen
  const btn = document.getElementById('batch-structure-btn');
  const originalText = btn.innerHTML;
  btn.innerHTML = '<em>aktiv...</em>';
  btn.disabled = true;
  
  const providerSelect = document.getElementById('batch-provider-select');
  const selectedProvider = providerSelect?.value || null;
  
  const resultsContainer = document.getElementById('results');
  resultsContainer.innerHTML = `
    <div class="batch-progress" id="batch-progress-ui">
      <div id="batch-status">Vorbereiten...</div>
      <div style="margin-top:8px; background:#e9eef0; border-radius:4px; overflow:hidden;">
        <div class="bar" id="batch-progress-bar"></div>
      </div>
    </div>
  `;
  
  try {
    setUILocked(true);
    
    let lectureIds;
    
    // Prüfe ob Vorträge ausgewählt sind
    if (selectedLectureIds.size > 0) {
      // Verwende nur ausgewählte Vorträge
      lectureIds = Array.from(selectedLectureIds);
      } else {
      // Hole alle Vorträge des GA-Bands
      const resp = await fetch(`${API_BASE}/api/ga-overview/${encodeURIComponent(gaNumber)}`);
      if (!resp.ok) throw new Error(`GA-Overview konnte nicht geladen werden: ${resp.status}`);
      const data = await resp.json();
      const lectures = data.lectures || [];
      
      if (lectures.length === 0) {
        resultsContainer.innerHTML = '<p>Keine Vorträge in dieser GA gefunden.</p>';
        return;
      }
      
      lectureIds = lectures.map(l => l.ID);
      }
    
    // Rufe Backend-API auf
    const statusEl = document.getElementById('batch-status');
    if (statusEl) statusEl.textContent = `Sende ${lectureIds.length} Vorträge an Server...`;
    
    const batchResp = await fetch(`${API_BASE}/api/batch-generate-structure`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        lectureIds: lectureIds,
        preferredProvider: selectedProvider,
        skipExisting: true
      })
    });
    
    if (!batchResp.ok) {
      const errorData = await batchResp.json();
      throw new Error(errorData.error || 'Server-Fehler');
    }
    
    const result = await batchResp.json();
    const doneMsg = `? Grundstruktur: ${result.processed} generiert, ${result.skipped} übersprungen, ${result.failed} Fehler`;
    if (statusEl) statusEl.textContent = doneMsg;
    
    const barEl = document.getElementById('batch-progress-bar');
    if (barEl) barEl.style.width = '100%';
    
    setUILocked(false);
    
    // Button-Text wiederherstellen
    btn.innerHTML = originalText;
    btn.disabled = false;
    
    // Cache löschen und GA-Übersicht aktualisieren
    externalSummaryDBCache = null;
    setTimeout(() => {
      openGAOverview(gaNumber);
    }, 800);
    
  } catch (err) {
    console.error('[BATCH-STRUCTURE] Fehler:', err);
    resultsContainer.innerHTML = `<div class="error-message"><strong>Fehler:</strong><br>${err.message}</div>`;
    setUILocked(false);
    
    // Button-Text wiederherstellen
    btn.innerHTML = originalText;
    btn.disabled = false;
  }
}

