// Aktiviere Tab basierend auf URL-Hash beim Laden
// Initialisiere Tab-Strukturen beim Laden der Seite
window.addEventListener('DOMContentLoaded', function() {
  // Speichere ursprüngliche HTML-Strukturen aller Tabs
  document.querySelectorAll('.tab-content').forEach(tab => {
    if (tab.id && !tabOriginalContent[tab.id]) {
      tabOriginalContent[tab.id] = tab.innerHTML;
      }
  });
});

window.addEventListener('DOMContentLoaded', function() {
  let hash = window.location.hash.substring(1); // Entferne das #
  
  // Parse Query-Parameter aus dem Hash
  // Unterstützt sowohl "texte&lecture=GA005" als auch "texte?lecture=GA005"
  let queryParams = {};
  
  // Zuerst ?-Parameter extrahieren (z.B. "texte?lecture=GA005&p=42")
  if (hash && hash.includes('?')) {
    const qParts = hash.split('?');
    hash = qParts[0];
    qParts.slice(1).join('?').split('&').forEach(part => {
      const [key, value] = part.split('=');
      if (key && value) {
        queryParams[key] = decodeURIComponent(value);
      }
    });
  }
  
  // Dann &-Parameter (z.B. "texte&lecture=GA052/15&p=42")
  if (hash && hash.includes('&')) {
    const parts = hash.split('&');
    hash = parts[0];
    parts.slice(1).forEach(part => {
      const [key, value] = part.split('=');
      if (key && value) {
        queryParams[key] = decodeURIComponent(value);
      }
    });
  }
  
  if (hash) {
    // Map Hash-Werte zu Tab-Namen
    const tabMap = {
      'ga': 'ga',
      'keyword': 'keyword',
      'texte': 'texte',
      'thematic': 'thematic',
      'timeline': 'timeline',
      'schlagworte': 'schlagworte',
      'maps': 'maps'
    };
    
    let tabName = tabMap[hash];
    // Maps-Tab nur lokal – online auf GA umleiten
    const _isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
    if (tabName === 'maps' && !_isLocal) tabName = 'ga';
    
    if (tabName) {
      // Warte kurz, bis alle Initialisierungen abgeschlossen sind
      setTimeout(() => {
        // Setze initialen History State ohne neuen Eintrag - Maps mit scroll= behalten
        const baseUrl = window.location.origin + window.location.pathname;
        const keepHash = (tabName === 'maps' && queryParams.scroll) ? `${tabName}&scroll=${encodeURIComponent(queryParams.scroll)}` : tabName;
        history.replaceState({ tab: tabName }, '', `${baseUrl}#${keepHash}`);
        switchTab(tabName, true); // skipHistory = true beim ersten Laden
        
        // Wenn lecture-Parameter vorhanden, öffne den Vortrag/das Buch
        if (queryParams.lecture) {
          setTimeout(() => {
            const paragraphIndex = queryParams.p || '';
            const paragraphEndIndex = queryParams.pEnd || '';
            // Speichere End-Index in temporärer Variable, die showLecture ausliest
            window._pendingHighlightEndIndex = paragraphEndIndex ? paragraphEndIndex.replace(/^\^/, '') : null;
            console.log('[HIGHLIGHT-DEBUG] URL-Parser: lecture =', queryParams.lecture, 'p =', paragraphIndex, 'pEnd =', paragraphEndIndex, '_pendingHighlightEndIndex =', window._pendingHighlightEndIndex);
            showLecture(queryParams.lecture, paragraphIndex);
          }, 200);
        }
        
        // Obsidian-Link: q-Parameter ? Suche ausführen
        if (queryParams.q) {
          runObsidianSearch(queryParams.q);
        }
        
        // Obsidian-Link: GA+Datum+Seite ? Vortrag öffnen
        if (queryParams.ga && queryParams.date) {
          navigateToGAPage(queryParams.ga, queryParams.date, queryParams.page, queryParams.text, queryParams.vault, queryParams.file);
        }
        
      }, 100);
    }
  } else {
    // Kein Hash vorhanden - setze initialen State für aktiven Tab
    const activeTabButton = document.querySelector('.tab-button.active');
    if (activeTabButton) {
      const onclick = activeTabButton.getAttribute('onclick');
      const match = onclick.match(/switchTab\('([^']+)'\)/);
      if (match) {
        const initialTab = match[1];
        setTimeout(() => {
          const baseUrl = window.location.origin + window.location.pathname;
          history.replaceState({ tab: initialTab }, '', `${baseUrl}#${initialTab}`);
          analyticsTrack('tab_view', initialTab);
        }, 100);
      }
    }
  }
});

// Obsidian-Zitat: Im Suche-Tab suchen (Textsuche)
function runObsidianSearch(rawQ) {
  const searchText = rawQ.replace(/\+/g, ' ')
    .replace(/ß/g, 'ss')
    .replace(/\[\[([^\]]*?\|)?([^\]]*?)\]\]/g, '$2');
  switchTab('keyword', true);
  setTimeout(function() {
    document.getElementById('word1').value = searchText;
    if (window.updateSearchClearButtons) window.updateSearchClearButtons();
    performKeywordSearch();
  }, 500);
}

// Obsidian-Zitat: Via GA+Datum+Seite navigieren
var _obsidianTryScrollTimeout = null;  // Verhindert mehrere parallele tryScroll-Loops (Flackern)
async function navigateToGAPage(ga, date, page, searchText, vault, file) {
  const isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
  const apiBase = isLocal ? 'http://localhost:3003' : 'https://ga-suche.onrender.com';
  
  console.log('[OBSIDIAN-GA] Navigiere zu GA', ga, 'Datum', date, 'Seite', page, searchText ? `Text: "${searchText}"` : '');
  
  // Vorherigen tryScroll-Loop abbrechen (verhindert mehrfaches Flackern)
  if (_obsidianTryScrollTimeout) {
    clearTimeout(_obsidianTryScrollTimeout);
    _obsidianTryScrollTimeout = null;
  }
  
  try {
    const resp = await fetch(`${apiBase}/api/resolve-lecture?ga=${encodeURIComponent(ga)}&date=${encodeURIComponent(date)}`);
    if (!resp.ok) {
      console.error('[OBSIDIAN-GA] Vortrag nicht gefunden:', ga, date);
      return;
    }
    
    const data = await resp.json();
    if (!data.success || !data.lectureId) {
      console.error('[OBSIDIAN-GA] Keine lectureId erhalten');
      return;
    }
    
    console.log('[OBSIDIAN-GA] Vortrag gefunden:', data.lectureId, data.title);
    switchTab('texte', true);
    await showLecture(data.lectureId);
    
    // Warte bis Vortrag geladen ist – wiederhole mehrmals, da replaceImageSrcWithBase64 den DOM später überschreibt
    var appliedCount = 0;
    var startTime = Date.now();
    var maxWaitTime = 20000;
    var lastApplyTime = 0;
    
    var tryScroll = function() {
      if (Date.now() - startTime > maxWaitTime) {
        if (appliedCount === 0) console.log('[OBSIDIAN-GA] ? Timeout erreicht');
        _obsidianTryScrollTimeout = null;
        return;
      }
      
      const viewer = document.getElementById('viewer');
      if (!viewer) {
        _obsidianTryScrollTimeout = setTimeout(tryScroll, 300);
        return;
      }
      
      const allParas = viewer.querySelectorAll('.paragraph');
      if (allParas.length === 0) {
        _obsidianTryScrollTimeout = setTimeout(tryScroll, 400);
        return;
      }
      
      var hasMarker = viewer.querySelector('.obsidian-page-marker');
      // Bereits markiert? Kein Entfernen und kein erneutes Anwenden – verhindert Flackern
      if (hasMarker) {
        if (appliedCount > 0 && Date.now() - lastApplyTime > 3000) {
          // Marker stabil seit 3s – Loop beenden
          _obsidianTryScrollTimeout = null;
          return;
        }
        _obsidianTryScrollTimeout = setTimeout(tryScroll, 1500);
        return;
      }
      
      // Nur entfernen wenn wir neu anwenden werden (Marker wurde durch replaceImageSrcWithBase64 überschrieben)
      viewer.querySelectorAll('.obsidian-page-marker').forEach(function(el) {
        el.classList.remove('obsidian-page-marker');
        el.style.borderLeft = '';
        el.style.paddingLeft = '';
        el.style.transition = '';
      });
      viewer.querySelectorAll('.obsidian-first-words').forEach(function(span) {
        var text = span.textContent;
        span.replaceWith(text);
      });
      
      var targetPara = null;
      var foundByText = false;
      var pageBreakNumForScroll = null;  // Bei Fallback: zum Seitenanfang scrollen (Seitenzahlen stehen am Anfang)
      
      const normalize = function(txt) {
        return (txt || '').toLowerCase()
          .replace(/ß/g, 'ss')
          .replace(/[,;.:!?()"'„"‚'»«›‹—–-]/g, '')
          .replace(/\s+/g, ' ')
          .trim();
      };
      
      // PRIMÄR: Suchworte finden und markieren – Absatz = der, in dem die Suchworte stehen (blauer Balken)
      // FALLBACK (nur wenn Suchworte nicht gefunden): Seitenzahl – Absatz mit Seitenmarker
      // Wichtig: Seitenzahlen in app.html stehen immer am Anfang einer Seite, nicht am Ende
      if (searchText) {
        console.log('[OBSIDIAN-GA] 🔍 Primär: Suche nach Suchworten:', searchText);
        
        const words = normalize(searchText).split(/\s+/).filter(w => w.length >= 2);
        console.log('[OBSIDIAN-GA] Durchsuche', allParas.length, '.paragraph Divs');
        
        // Versuche mit absteigender Wortanzahl (5, 4, 3, 2)
        for (let len = Math.min(words.length, 5); len >= 2 && !targetPara; len--) {
          const searchPhrase = words.slice(0, len).join(' ');
          for (let i = 0; i < allParas.length; i++) {
            const p = allParas[i];
            if (normalize(p.textContent).includes(searchPhrase)) {
              targetPara = p;
              foundByText = true;
              console.log('[OBSIDIAN-GA] ? Suchworte gefunden in Absatz', i, '(mit', len, 'Worten)');
              break;
            }
          }
        }
        
        if (!targetPara) {
          console.log('[OBSIDIAN-GA] ? Suchworte "' + searchText + '" nicht gefunden ? Fallback auf Seitenzahl');
        }
      }
      
      // Fallback: Nur wenn Suchworte fehlen oder nicht gefunden – Absatz mit Seitenmarker
      // WICHTIG: Seitenzahlen stehen am ANFANG einer Seite – der Marker steht am Ende des
      // vorherigen Absatzes. Der Absatz MIT dem Zitat ist der NÄCHSTE (nach dem Marker).
      if (!targetPara && page) {
        console.log('[OBSIDIAN-GA] 📍 Fallback: Suche Seitenmarker', page, '(Seitenzahlen am Seitenanfang)');
        const pageNums = viewer.querySelectorAll('.page-break-num');
        
        for (const numSpan of pageNums) {
          if (numSpan.textContent.trim() === String(page)) {
            var markerPara = numSpan.closest('.paragraph');
            if (!markerPara) markerPara = numSpan.closest('p');
            pageBreakNumForScroll = numSpan;
            // NÄCHSTEN Absatz verwenden – dort beginnt der Inhalt der Seite (Zitat)
            if (markerPara) {
              const parasArr = Array.from(viewer.querySelectorAll('.paragraph'));
              const idx = parasArr.indexOf(markerPara);
              if (idx >= 0 && idx + 1 < parasArr.length) {
                targetPara = parasArr[idx + 1];
                console.log('[OBSIDIAN-GA] ? Nächster Absatz nach Seitenmarker (Seitenanfang)');
              } else {
                targetPara = markerPara;
                console.log('[OBSIDIAN-GA] ? Seitenmarker gefunden (kein nächster Absatz, verwende Marker-Absatz)');
              }
            } else {
              targetPara = null;
            }
            break;
          }
        }
      }
      
      // Scrolle und markiere
      if (targetPara) {
        // Bei Fallback: zum Seitenanfang scrollen (Seitenzahlen stehen am Anfang der Seite)
        if (pageBreakNumForScroll) {
          pageBreakNumForScroll.scrollIntoView({ behavior: 'auto', block: 'start' });
        } else {
          targetPara.scrollIntoView({ behavior: 'auto', block: 'center' });
        }
        
        setTimeout(function() {
          // Markiere Absatz mit blauem Balken (wie bei selected-for-keyword)
          targetPara.classList.add('obsidian-page-marker');
          targetPara.style.borderLeft = '4px solid rgba(70, 120, 134, 0.6)';
          targetPara.style.setProperty('padding-left', '12px', 'important');
          targetPara.style.transition = 'border-left 0.3s ease, padding-left 0.3s ease';
          appliedCount++;
          lastApplyTime = Date.now();
          
          // Markiere die ersten Worte des Zitats (aus searchText Parameter)
          // WICHTIG: Suchwort kann in einem späteren <p> stehen (nach Überschriften h3/h4) –
          // durchsuche alle <p> und den Absatz selbst, nicht nur das erste <p>
          if (searchText) {
            var pTag = null;
            var originalHTML = '';
            var textContent = '';
            var textElems = targetPara.querySelectorAll('p');
            if (textElems.length === 0) textElems = [targetPara];
            for (var te = 0; te < textElems.length; te++) {
              var elem = textElems[te];
              var txt = (elem.textContent || '').trim();
              if (txt.length < 5) continue;
              var norm = (txt || '').toLowerCase().replace(/ß/g, 'ss').replace(/[,;.:!?()"'„"‚'»«›‹—–-]/g, '').replace(/\s+/g, ' ').trim();
              var searchNorm = (searchText || '').toLowerCase().replace(/ß/g, 'ss').replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
              var words = searchNorm.split(/\s+/).filter(function(w){ return w.length >= 2; });
              var phrase = words.slice(0, Math.min(5, words.length)).join(' ');
              if (phrase && norm.includes(phrase)) {
                pTag = elem;
                originalHTML = elem.innerHTML || '';
                textContent = elem.textContent || '';
                break;
              }
            }
            if (!pTag) { pTag = targetPara.querySelector('p') || targetPara; originalHTML = pTag.innerHTML || ''; textContent = pTag.textContent || ''; }
            if (pTag && (originalHTML || textContent)) {
              
              // Normalisiere den searchText (die ersten 5 Worte aus Obsidian)
              var normalizedSearchText = searchText.replace(/ß/g, 'ss')
                .replace(/\[\[([^\]]*?\|)?([^\]]*?)\]\]/g, '$2')
                .replace(/[^\w\s]/g, ' ')
                .replace(/\s+/g, ' ')
                .trim();
              
              var words = normalizedSearchText.split(/\s+/);
              var match = null;
              var actualText = null;
              
              // Versuche zuerst alle Worte (normalerweise 5)
              if (words.length >= 1) {
                var wordPattern = words.map(w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('\\s+');
                var regex = new RegExp('(' + wordPattern + ')', 'i');
                match = textContent.match(regex);
                
                if (match) {
                  actualText = match[0];
                  console.log('[OBSIDIAN-GA] ? Zitatanfang gefunden mit ' + words.length + ' Worten:', actualText);
                }
              }
              
              // Fallback: Versuche nur die ersten 3 Worte
              if (!match && words.length >= 3) {
                var firstThree = words.slice(0, 3);
                var wordPattern3 = firstThree.map(w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('\\s+');
                var regex3 = new RegExp('(' + wordPattern3 + ')', 'i');
                match = textContent.match(regex3);
                
                if (match) {
                  actualText = match[0];
                  console.log('[OBSIDIAN-GA] ? Zitatanfang gefunden mit Fallback (3 Worte):', actualText);
                }
              }
              
              // Markiere die gefundenen Worte (auch wenn page-break-num dazwischen ist)
              if (match && actualText) {
                console.log('[OBSIDIAN-GA] 🔍 Versuche zu markieren:', actualText);
                console.log('[OBSIDIAN-GA] 📄 Original HTML (erste 200 Zeichen):', originalHTML.substring(0, 200));
                
                // Extrahiere page-break-num Spans temporär
                var pageMarkers = [];
                var htmlWithPlaceholders = originalHTML.replace(/<span class="page-break-num"[^>]*>.*?<\/span>/g, function(match) {
                  var placeholder = '___PM' + pageMarkers.length + '___';
                  pageMarkers.push(match);
                  console.log('[OBSIDIAN-GA] 📌 Gefundener Seitenmarker:', match);
                  return placeholder;
                });
                
                console.log('[OBSIDIAN-GA] 📝 HTML mit Platzhaltern (erste 200 Zeichen):', htmlWithPlaceholders.substring(0, 200));
                
                // Erstelle ein flexibles Regex-Pattern
                var escapedText = actualText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var words = escapedText.split(/\s+/);
                
                console.log('[OBSIDIAN-GA] 🔤 Worte zum Suchen:', words);
                
                // Pattern: Worte können durch Platzhalter und Whitespace getrennt sein
                var patternParts = [];
                for (var i = 0; i < words.length; i++) {
                  patternParts.push(words[i]);
                  if (i < words.length - 1) {
                    // Zwischen Worten: optionale Platzhalter, Whitespace, optionale weitere Platzhalter
                    patternParts.push('(?:\\s*___PM\\d+___\\s*|\\s+)');
                  }
                }
                var flexPattern = new RegExp(patternParts.join(''), 'i');
                
                console.log('[OBSIDIAN-GA] 🔎 Regex-Pattern:', flexPattern);
                
                var matchInHTML = htmlWithPlaceholders.match(flexPattern);
                
                if (matchInHTML) {
                  console.log('[OBSIDIAN-GA] ? Match gefunden:', matchInHTML[0]);
                  
                  // Erstelle Obsidian-Link wenn vault und file vorhanden
                  var obsidianLink = '';
                  if (vault && file) {
                    obsidianLink = 'obsidian://open?vault=' + encodeURIComponent(vault) + '&file=' + encodeURIComponent(file);
                    console.log('[OBSIDIAN-GA] 🔗 Obsidian-Link erstellt:', obsidianLink);
                  }
                  
                  // Ersetze den gefundenen Text mit markierter Version (mit Link wenn vorhanden)
                  var markedHTML;
                  if (obsidianLink) {
                    markedHTML = htmlWithPlaceholders.replace(flexPattern, 
                      '<a href="' + obsidianLink + '" class="obsidian-first-words" style="text-decoration: underline dotted rgba(70, 120, 134, 0.8); text-decoration-thickness: 2px; text-underline-offset: 3px; color: inherit; cursor: pointer;" title="Zurück zu Obsidian">' + 
                      matchInHTML[0] + '</a>');
                  } else {
                    markedHTML = htmlWithPlaceholders.replace(flexPattern, 
                      '<span class="obsidian-first-words" style="text-decoration: underline dotted rgba(70, 120, 134, 0.8); text-decoration-thickness: 2px; text-underline-offset: 3px;">' + 
                      matchInHTML[0] + '</span>');
                  }
                  
                  // Setze page-break-num Spans wieder ein
                  for (var i = 0; i < pageMarkers.length; i++) {
                    markedHTML = markedHTML.replace('___PM' + i + '___', pageMarkers[i]);
                  }
                  
                  pTag.innerHTML = markedHTML;
                  console.log('[OBSIDIAN-GA] ? Suchworte markiert (gepunktete Unterstreichung):', actualText);
                  // Scrolle zu den Suchworten (Hauptziel), damit sie sichtbar sind
                  var markedEl = pTag.querySelector('.obsidian-first-words');
                  if (markedEl) markedEl.scrollIntoView({ behavior: 'auto', block: 'center' });
                } else {
                  console.log('[OBSIDIAN-GA] ? Konnte Zitatanfang nicht im HTML finden');
                  console.log('[OBSIDIAN-GA] 💡 Versuche ohne Seitenmarker-Logik...');
                  
                  // Fallback ohne Seitenmarker-Logik
                  var simpleMatch = originalHTML.match(new RegExp(escapedText, 'i'));
                  if (simpleMatch) {
                    // Erstelle Obsidian-Link wenn vault und file vorhanden
                    var obsidianLink = '';
                    if (vault && file) {
                      obsidianLink = 'obsidian://open?vault=' + encodeURIComponent(vault) + '&file=' + encodeURIComponent(file);
                    }
                    
                    var markedHTML;
                    if (obsidianLink) {
                      markedHTML = originalHTML.replace(simpleMatch[0], 
                        '<a href="' + obsidianLink + '" class="obsidian-first-words" style="text-decoration: underline dotted rgba(70, 120, 134, 0.8); text-decoration-thickness: 2px; text-underline-offset: 3px; color: inherit; cursor: pointer;" title="Zurück zu Obsidian">' + 
                        simpleMatch[0] + '</a>');
                    } else {
                      markedHTML = originalHTML.replace(simpleMatch[0], 
                        '<span class="obsidian-first-words" style="text-decoration: underline dotted rgba(70, 120, 134, 0.8); text-decoration-thickness: 2px; text-underline-offset: 3px;">' + 
                        simpleMatch[0] + '</span>');
                    }
                    pTag.innerHTML = markedHTML;
                    console.log('[OBSIDIAN-GA] ? Suchworte markiert (einfache Methode):', actualText);
                    var markedEl = pTag.querySelector('.obsidian-first-words');
                    if (markedEl) markedEl.scrollIntoView({ behavior: 'auto', block: 'center' });
                  }
                }
              } else {
                console.log('[OBSIDIAN-GA] ? Konnte Zitatanfang nicht finden:', normalizedSearchText);
              }
            }
          }
          
          // Blauer Balken und Wortmarkierung bleiben dauerhaft sichtbar
          console.log('[OBSIDIAN-GA] 🔵 Blauer Balken bleibt dauerhaft sichtbar (bis neuer Inhalt geladen wird)');
        }, 300);
        
        console.log('[OBSIDIAN-GA] ? Navigation abgeschlossen');
      } else if (appliedCount === 0) {
        console.log('[OBSIDIAN-GA] ? Kein Ziel gefunden');
      }
      
      // Weiter prüfen (replaceImageSrcWithBase64 kann DOM später überschreiben)
      if (Date.now() - startTime < maxWaitTime) {
        _obsidianTryScrollTimeout = setTimeout(tryScroll, 1200);
      } else {
        _obsidianTryScrollTimeout = null;
      }
    };
    
    _obsidianTryScrollTimeout = setTimeout(tryScroll, 500);
  } catch (err) {
    console.error('[OBSIDIAN-GA] Fehler:', err.message);
  }
}

