// Globale Schlagwort-Funktionen
async function initializeKeywordSystem() {
  const countContainer = document.getElementById('keyword-count');
  if (countContainer) countContainer.textContent = '';
  
  try {
    // Lade Schlagwort-Daten
    await loadKeywordsData();
    
    if (keywordsData.length === 0) {
      if (countContainer) countContainer.textContent = '';
      console.warn('[KEYWORDS] Keine Schlagwörter geladen!');
      return;
    }
    
    // Erstelle Alphabet-Navigation
    createAlphabetNavigation();
    
    // Initialer Aufbau der Anzeige
    displayKeywords('Alle');
    
    // Event Listener für Suche
    setupKeywordSearch();
    
    // Verlinkungsanalyse wird jetzt LAZY durchgeführt (bei Bedarf)
    // Starte Hintergrund-Analyse mit requestIdleCallback für bessere Performance
    if (typeof requestIdleCallback === 'function') {
      requestIdleCallback(() => {
        analysiereSchlagwortVerlinkungen();
      }, { timeout: 5000 }); // Max 5 Sekunden warten
    }
    // Falls requestIdleCallback nicht verfügbar, wird die Analyse bei Bedarf in getSchlagwortVerlinkungen() durchgeführt
    
    } catch (error) {
    console.error('[KEYWORDS] ? Fehler beim Initialisieren:', error);
    if (countContainer) countContainer.textContent = '';
  }
}

async function loadKeywordsData() {
  // Prüfe ob konsolidierte Dateien vorhanden sind
  await checkForConsolidatedFiles();
  
  // STRATEGIE: Lade Basis-Keywords, dann füge Obsichan-Keywords hinzu (merge)
  keywordsData = [];
  
  try {
    // Versuche zuerst eine vollständige Schlagwort-Liste zu laden
    const response = await fetch(`${API_BASE}/api/concepts-list`);
    if (response.ok) {
      const data = await response.json();
      keywordsData = data.keywords || [];
      }
  } catch (error) {
    console.warn('[KEYWORDS] API nicht verfügbar:', error.message);
    
    // Fallback: Versuche lokale Schlagwort-Dateien zu laden
    try {
      await loadLocalKeywordFiles();
      } catch (localError) {
      console.warn('[KEYWORDS] Lokale Dateien nicht verfügbar:', localError.message);
    }
  }
  
  // Hinweis: Obsichan-Exports wurden einmalig migriert in concepts-database.json
  // Alle Concepts (KI + Obsichan) sind jetzt in concepts-database.json vereint
  
  // Wenn nichts geladen wurde, zeige leere Liste
  if (keywordsData.length === 0) {
    console.warn('[KEYWORDS] ⚠️ Keine Concepts geladen!');
  }
}

