function createAlphabetNavigationInContainer() {
  const navContainer = document.getElementById('alphabet-nav-dynamic');
  if (!navContainer) return;
  
  // Leere den Container
  navContainer.innerHTML = '';
  
  // Alle verfügbaren Buchstaben aus den Daten ermitteln
  const availableLetters = [...new Set(keywordsData.map(k => k.alphabetical || k.keyword.charAt(0).toUpperCase()))].sort();
  
  // "Alle" Button
  const allBtn = document.createElement('button');
  allBtn.className = 'depth-btn active';
  allBtn.textContent = 'Alle';
  allBtn.onclick = () => selectAlphabet('Alle', allBtn);
  navContainer.appendChild(allBtn);
  
  // Alphabet-Buttons für verfügbare Buchstaben
  availableLetters.forEach(letter => {
    const btn = document.createElement('button');
    btn.className = 'depth-btn';
    btn.textContent = letter;
    btn.onclick = () => selectAlphabet(letter, btn);
    navContainer.appendChild(btn);
  });
  
  // Setze aktiven Button
  const activeButton = Array.from(navContainer.querySelectorAll('.depth-btn')).find(btn => 
    btn.textContent === currentAlphabet
  );
  if (activeButton) {
    navContainer.querySelectorAll('.depth-btn').forEach(btn => btn.classList.remove('active'));
    activeButton.classList.add('active');
  }
}

function processKeywordText(text, gaReferences = []) {
  if (!text) return '';
  
  let processedText = text;
  
  // Verarbeite Markdown-Formatierung für fette Schrift **text**
  processedText = processedText.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  
  // Verarbeite Markdown-Links im Format:
  // [[GA066/1]] oder 
  // [[GA066 (1.) TITLE|GA066/1]] (Obsichan-Format mit vollem Titel)
  processedText = processedText.replace(/\[\[([^\]]*\|)?([^|\]]+)\]\]/g, (match, titlePart, lastPart) => {
    let gaId;
    
    if (titlePart) {
      // Format: [[TITLE|GA066/1]] - lastPart ist die GA-ID
      gaId = lastPart.trim();
    } else {
      // Format: [[GA066/1]] - lastPart ist direkt die GA-ID
      gaId = lastPart.trim();
    }
    
    // Prüfe ob es eine gültige GA-ID ist (Format: GA123/4 oder GA123a/4)
    if (/^GA\d{3}[a-z]?\/\d+$/i.test(gaId)) {
      // Normalisiere GA-ID
      const normalizedGaId = gaId.replace(/^GA(\d{3}[a-z]?)\/(\d+)$/i, (m, ga, num) => 
        `GA${ga} - ${num}`
      );
      const displayId = formatLectureId(normalizedGaId);
      return `<a href="#" class="ga-keyword-link" data-ga-id="${normalizedGaId}" onclick="showLecture('${normalizedGaId}'); return false;">${displayId}</a>`;
    }
    
    return match; // Fallback: ursprünglichen Text beibehalten
  });
  
  return processedText;
}


async function openFromKeyword(gaId) {
  try {
    // Timeline schließen falls geöffnet
    hideTimelineIfOpen();
    
    // Schließe Summary Panel falls geöffnet
    const summaryPanel = document.getElementById('summary-panel');
    const resizeHandle = document.getElementById('verticalResizeHandle');
    const mainContainer = document.getElementById('main-container');
    if (summaryPanel.classList.contains('visible')) {
      summaryPanel.classList.remove('visible');
      resizeHandle.classList.remove('visible');
      summaryPanel.style.width = '0';
      summaryPanel.style.minWidth = '0';
      summaryPanel.style.marginRight = '0px';
      
      // Main-Container bis zum rechten Rand ausdehnen
      if (mainContainer) {
        mainContainer.style.marginRight = '0px';
      }
    }
    
    // Zeige Vortrag
    await showLecture(gaId, null, []);
    
  } catch (error) {
    console.error('[KEYWORDS] Fehler beim Öffnen der GA-Referenz:', error);
    alert(`Fehler beim Laden des Vortrags ${gaId} - ${error.message}`);
  }
}

