function restoreKeywordSearchCursor(savedValue, savedPosition) {
  const keywordSearchInput = document.getElementById('keywordSearch');
  if (keywordSearchInput && savedValue !== undefined) {
    // Setze den Wert
    keywordSearchInput.value = savedValue;
    
    // Stelle Cursor-Position wieder her
    if (savedPosition !== undefined && savedPosition !== null) {
      // Verwende setTimeout, um sicherzustellen, dass das DOM aktualisiert ist
      setTimeout(() => {
        keywordSearchInput.setSelectionRange(savedPosition, savedPosition);
        keywordSearchInput.focus();
      }, 0);
    }
  }
}

