// KEYWORD THEMATIC SEARCH FUNKTIONEN
// ============================================================================

async function performKeywordThematicSearch(keyword) {
  // Timeline schließen falls geöffnet
  hideTimelineIfOpen();
  
  // Prüfe ob lokale Version
  const isLocal = window.location.hostname === 'localhost' || 
                  window.location.hostname === '127.0.0.1' ||
                  window.location.hostname.startsWith('192.168.') ||
                  window.location.hostname.startsWith('172.') ||
                  window.location.hostname.startsWith('10.') ||
                  window.location.protocol === 'file:';
  
  try {
    const results = document.getElementById('results');
    const countContainer = document.getElementById('keyword-count');
    
    // WICHTIG: Prüfe zuerst ob das Keyword bereits gespeicherte Ergebnisse hat
    const existingKeyword = keywordsData.find(kw => kw.keyword === keyword);
    
    // Prüfe ob gespeicherte Ergebnisse vorhanden sind
    const hasText = existingKeyword && existingKeyword.text;
    const hasOverview = existingKeyword && existingKeyword.overview;
    
    // Wenn mindestens ein gespeichertes Ergebnis vorhanden ist, zeige es an (keine API-Anfrage)
    if (hasText || hasOverview) {
      const viewer = document.getElementById('viewer');
      
      // Zeige Themen_Übersicht im Main Viewer zuerst, falls vorhanden
      if (hasOverview) {
        if (viewer) {
          // renderConceptOverview zeigt bereits beide Methoden an (overview + text)
          renderConceptOverview(keyword, { 
            overview: existingKeyword.overview,
            text: existingKeyword.text || null
          });
        }
        // WICHTIG: Wenn hasOverview vorhanden ist, wird text bereits in renderConceptOverview angezeigt
        // Daher wird displayKeywordThematicResults NICHT mehr aufgerufen, um Doppelung zu vermeiden
      } else if (hasText) {
        // Nur wenn KEIN Overview vorhanden ist, zeige Text separat an
        const textWithoutFormatting = existingKeyword.text.replace(/\*\*/g, '').trim();
        const isOnlyKeyword = textWithoutFormatting === keyword;
        
        // Wenn Text mehr als nur das Keyword selbst ist
        if (!isOnlyKeyword && existingKeyword.text.length > 50) {
          // In Online-Version: Nur anzeigen wenn vollständige Darstellung vorhanden
          if (!isLocal) {
            if (countContainer) {
              countContainer.textContent = '';
            }
            // Keine Anzeige in Online-Version, aber nicht return hier, damit die Funktion normal endet
          } else {
            // Lokale Version: Anzeigen
            
            if (viewer) {
              viewer.innerHTML = '';
            }
            
            const data = {
              query: keyword,
              content: existingKeyword.text,
              sources: existingKeyword.sources || [],
              fromCache: false,
              fromKeywordData: true
            };
            
            displayKeywordThematicResults(keyword, data);
          }
        } else {
          }
      }
      
      // Wenn gespeicherte Ergebnisse vorhanden sind, verwende nur diese (keine neue API-Anfrage)
      if (countContainer) {
        countContainer.textContent = '';
      }
      return; // WICHTIG: Keine API-Anfrage, wenn gespeicherte Ergebnisse vorhanden sind
    }
    
    // Zeige Loading-Status
    const viewer = document.getElementById('viewer');
    if (viewer) {
      viewer.innerHTML = `
        <div id="viewer-content">
          <div style="color: var(--secondary-text); font-style: italic;">Suche...</div>
        </div>
      `;
    }
    
    if (countContainer) {
      countContainer.textContent = 'Lade...';
    }
    
    // Versuche zuerst das gespeicherte Ergebnis zu laden (mit den gleichen Parametern wie beim Hinzufügen)
    const cacheResponse = await fetch(`${API_BASE}/api/keyword-thematic-search`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        query: keyword,
        limit: 30,
        useCache: true  // Explizit Cache verwenden
      })
    });
    
    if (!cacheResponse.ok) {
      throw new Error(`Server Error: ${cacheResponse.status}`);
    }
    
    const data = await cacheResponse.json();
    
    // Prüfe ob das Ergebnis aus dem Cache kommt
    if (data.fromCache) {
      if (countContainer) {
        countContainer.textContent = '';
      }
    } else {
      if (countContainer) {
        countContainer.textContent = '';
      }
    }
    
    // Zeige die Ergebnisse an
    displayKeywordThematicResults(keyword, data);
    
  } catch (error) {
    console.error('[KEYWORD-THEMATIC] Fehler:', error);
    
    const viewer = document.getElementById('viewer');
    if (viewer) {
      viewer.innerHTML = `
        <div id="viewer-content">
          <div style="color: #c53030;">
            <div style="font-size: 1.1em; margin-bottom: 1rem;">? Fehler bei der Analyse</div>
            <div style="font-style: italic;">${error.message}</div>
            <button onclick="switchTab('schlagworte')" style="margin-top: 1rem; padding: 8px 16px; background: #467886; color: white; border: none; border-radius: 4px; cursor: pointer;">
              Zurück zur Schlagwort-Liste
            </button>
          </div>
        </div>
      `;
    }
  }
}

// Funktion: Konvertiere GA-Referenzen in klickbare Links im DOM (für Keyword-Ergebnisse)
function convertGAReferencesToLinksInKeywordResults(container) {
  // Finde alle Textknoten und ersetze (GA###/##:index) durch klickbare Links
  const walk = document.createTreeWalker(
    container,
    NodeFilter.SHOW_TEXT,
    null,
    false
  );
  
  const nodesToReplace = [];
  let node;
  
  while (node = walk.nextNode()) {
    const text = node.nodeValue;
    // Suche nach GA-Referenzen:
    // - Vorträge: (GA###/##:^index), (GA###/##) oder GA###/## (ohne Klammern)
    // - Bücher: (GA###:^index) oder GA###:^index (ohne Klammern)
    // Unterstützt auch GA157a/2 (mit Buchstaben nach der Nummer)
    // Index kann mit ^ beginnen und alphanumerisch sein
    if (/GA\d{1,3}[a-z]?\/\d+(?::\^?[a-zA-Z0-9]+)?/g.test(text) ||
        /GA\d{1,3}[a-z]?:\^?[a-zA-Z0-9]+/g.test(text)) {
      nodesToReplace.push(node);
    }
  }
  
  nodesToReplace.forEach(textNode => {
    const text = textNode.nodeValue;
    const parent = textNode.parentNode;
    
    // Überspringe wenn bereits ein Link ist
    if (parent.tagName === 'A') return;
    
    // Erstelle ein Dokumentfragment mit den ersetzten Links
    const fragment = document.createDocumentFragment();
    let lastIndex = 0;
    
    // WICHTIG: Finde ALLE Links zuerst (Vorträge UND Bücher), dann sortiere nach Position
    const allMatches = [];
    
    // 1. Finde alle Vorträge mit Slash: GA###/##:^index oder GA###/##
    const regexVortrag = /(\()?GA(\d{1,3}[a-z]?)\/(\d+)(?::(\^?[a-zA-Z0-9]+))?(\))?/g;
    let match;
    regexVortrag.lastIndex = 0;
    while ((match = regexVortrag.exec(text)) !== null) {
      allMatches.push({
        type: 'vortrag',
        match: match,
        index: match.index,
        length: match[0].length
      });
    }
    
    // 2. Finde alle Bücher MIT Index: GA###:^index (mit und ohne Klammern)
    const regexBuchMitIndex = /(\()?GA(\d{1,3}[a-z]?):(\^?[a-zA-Z0-9]+)(\))?/g;
    regexBuchMitIndex.lastIndex = 0;
    let buchMitIndexMatch;
    while ((buchMitIndexMatch = regexBuchMitIndex.exec(text)) !== null) {
      allMatches.push({
        type: 'buch',
        match: buchMitIndexMatch,
        index: buchMitIndexMatch.index,
        length: buchMitIndexMatch[0].length
      });
    }
    
    // 3. Sortiere alle Matches nach Position
    allMatches.sort((a, b) => a.index - b.index);
    
    // 4. Verarbeite alle Matches in der richtigen Reihenfolge
    allMatches.forEach(({ type, match, index, length }) => {
      if (index > lastIndex) {
        fragment.appendChild(document.createTextNode(text.substring(lastIndex, index)));
      }
      
      if (type === 'vortrag') {
        // Verarbeite Vortrag
        const hasOpeningParen = match[1] === '(';
        const hasClosingParen = match[5] === ')';
        
        if (hasOpeningParen) {
          fragment.appendChild(document.createTextNode('('));
        }
        
        const gaNumber = match[2];
        const lectureNum = match[3];
        const lectureId = `GA${gaNumber}/${lectureNum}`;
        const rawIndex = match[4] || '';
        const paragraphIndex = rawIndex ? (rawIndex.startsWith('^') ? rawIndex : `^${rawIndex}`) : null;
        const displayText = `GA${gaNumber}/${lectureNum}`;
        
        const link = document.createElement('a');
        link.href = '#';
        link.className = 'ga-keyword-link';
        link.textContent = displayText;
        
        if (paragraphIndex) {
          const escapedIndex = paragraphIndex.replace(/'/g, "\\'");
          const escapedLectureId = lectureId.replace(/'/g, "\\'");
          link.setAttribute('onclick', `showLectureFromAdvancedSearch('${escapedLectureId}', '', '${escapedIndex}'); return false;`);
        } else {
          const escapedLectureId = lectureId.replace(/'/g, "\\'");
          link.setAttribute('onclick', `showLectureFromAdvancedSearch('${escapedLectureId}', '', null); return false;`);
        }
        
        fragment.appendChild(link);
        
        if (hasClosingParen) {
          fragment.appendChild(document.createTextNode(')'));
        }
      } else if (type === 'buch') {
        // Verarbeite Buch: (GA013:^b0i0j3) -> (<a>GA013</a>)
        const hasOpeningParen = match[1] === '(';
        const hasClosingParen = match[4] === ')';
        
        if (hasOpeningParen) {
          fragment.appendChild(document.createTextNode('('));
        }
        
        const gaNumber = match[2];
        const lectureId = `GA${gaNumber}`;
        const rawIndex = match[3] || '';
        const paragraphIndex = rawIndex ? (rawIndex.startsWith('^') ? rawIndex : `^${rawIndex}`) : null;
        const displayText = `GA${gaNumber}`;
        
        const link = document.createElement('a');
        link.href = '#';
        link.className = 'ga-keyword-link';
        link.textContent = displayText;
        
        if (paragraphIndex) {
          const escapedIndex = paragraphIndex.replace(/'/g, "\\'");
          const escapedLectureId = lectureId.replace(/'/g, "\\'");
          link.setAttribute('onclick', `showLectureFromAdvancedSearch('${escapedLectureId}', '', '${escapedIndex}'); return false;`);
        } else {
          const escapedLectureId = lectureId.replace(/'/g, "\\'");
          link.setAttribute('onclick', `showLectureFromAdvancedSearch('${escapedLectureId}', '', null); return false;`);
        }
        
        fragment.appendChild(link);
        
        if (hasClosingParen) {
          fragment.appendChild(document.createTextNode(')'));
        }
      }
      
      lastIndex = index + length;
    });
    
    // Füge restlichen Text hinzu
    if (lastIndex < text.length) {
      fragment.appendChild(document.createTextNode(text.substring(lastIndex)));
    }
    
    // Ersetze den Textknoten durch das Fragment
    parent.replaceChild(fragment, textNode);
  });
}

// Nachbearbeitung: Stelle sicher, dass * * * eine Leerzeile davor und danach hat.
// Der Poem-Merger fügt bereits ein <br> vor dem <p> ein (Zeilenumbruch).
// Wir fügen ein ZWEITES <br> hinzu, damit eine Leerzeile entsteht.
// Nach dem <p> fügen wir ebenfalls ein <br> ein (Leerzeile nach * * *).
function fixAsteriskBreakSpacing(container) {
  if (!container) return;
  const asterisks = container.querySelectorAll('p.asterisk-break');
  if (asterisks.length > 0) {
    console.log('[ASTERISK-SPACING] Gefunden:', asterisks.length, '* * * Elemente in', container.id || container.className);
  }
  asterisks.forEach((el, idx) => {
    // Zähle vorhandene <br> direkt VOR dem asterisk-break
    let brCountBefore = 0;
    let node = el.previousSibling;
    while (node) {
      if (node.nodeType === Node.TEXT_NODE && !node.textContent.trim()) {
        node = node.previousSibling;
        continue;
      }
      if (node.nodeType === Node.ELEMENT_NODE && node.tagName && node.tagName.toLowerCase() === 'br') {
        brCountBefore++;
        node = node.previousSibling;
        continue;
      }
      break;
    }
    console.log(`[ASTERISK-SPACING] #${idx} - ${brCountBefore} <br> VOR dem Element gefunden, brauche 2`);
    // Brauche mindestens 2 <br> vor asterisk-break (1 = Zeilenumbruch, 2 = Leerzeile)
    for (let i = brCountBefore; i < 2; i++) {
      el.parentNode.insertBefore(document.createElement('br'), el);
    }

    // Zähle vorhandene <br> direkt NACH dem asterisk-break
    let brCountAfter = 0;
    node = el.nextSibling;
    while (node) {
      if (node.nodeType === Node.TEXT_NODE && !node.textContent.trim()) {
        node = node.nextSibling;
        continue;
      }
      if (node.nodeType === Node.ELEMENT_NODE && node.tagName && node.tagName.toLowerCase() === 'br') {
        brCountAfter++;
        node = node.nextSibling;
        continue;
      }
      break;
    }
    console.log(`[ASTERISK-SPACING] #${idx} - ${brCountAfter} <br> NACH dem Element gefunden, brauche 2`);
    // Brauche mindestens 2 <br> nach asterisk-break (1 = Zeilenumbruch, 2 = Leerzeile)
    // Füge neue <br> NACH allen bestehenden <br> ein (= vor dem nächsten Nicht-<br>-Element)
    const insertPoint = node; // node zeigt auf das erste Nicht-<br>-Element nach den <br>
    for (let i = brCountAfter; i < 2; i++) {
      if (insertPoint) {
        el.parentNode.insertBefore(document.createElement('br'), insertPoint);
      } else {
        el.parentNode.appendChild(document.createElement('br'));
      }
    }
  });
}

// Hilfsfunktion: Erkennt Gedichte und kurze Zeilen (< 75 Zeichen) und markiert sie
function detectAndFormatPoems(container) {
  const containerId = container ? (container.id || container.className || 'unbekannt') : 'null';
  console.log('[GEDICHT-ERKENNUNG] Funktion aufgerufen, Container-ID:', containerId, 'Element:', container);
  if (!container) {
    console.log('[GEDICHT-ERKENNUNG] Container ist null/undefined, breche ab');
    return;
  }
  
  // Finde alle <p> Elemente im Container (auch innerhalb von .paragraph)
  const paragraphs = Array.from(container.querySelectorAll('p'));
  
  // ZUSÄTZLICH: Prüfe auch .paragraph Divs, die direkt Text enthalten (ohne <p> Tags)
  const paragraphDivs = Array.from(container.querySelectorAll('.paragraph'));
  
  // Debug: Zähle gefundene Paragraphen
  console.log('[GEDICHT-ERKENNUNG] Gefundene .paragraph Divs:', paragraphDivs.length);
  console.log('[GEDICHT-ERKENNUNG] Gefundene <p> Elemente:', paragraphs.length);
  paragraphDivs.forEach(div => {
    // Prüfe ob die Div direkt Text enthält (nicht nur in <p> Tags)
    // WICHTIG: Berücksichtige auch HTML mit <br> Tags (nach Markdown-Konvertierung)
    let textContent = '';
    
    // Methode 1: Direkter Text-Node
    const directText = Array.from(div.childNodes)
      .filter(node => node.nodeType === Node.TEXT_NODE)
      .map(node => node.textContent.trim())
      .filter(text => text.length > 0)
      .join('\n');
    
    // Methode 2: HTML-Inhalt mit <br> Tags (nach marked() Konvertierung)
    if (!directText || directText.length < 10) {
      // Erstelle temporäres Element um HTML zu parsen
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = div.innerHTML;
      
      // Entferne versteckte Spans (mit display:none oder data-index Attribut)
      const hiddenSpans = tempDiv.querySelectorAll('[style*="display:none"], [data-index]');
      hiddenSpans.forEach(span => span.remove());
      
      // Ersetze <br> durch Zeilenumbrüche für die Analyse
      const htmlWithBreaks = tempDiv.innerHTML.replace(/<br\s*\/?>/gi, '\n');
      const tempDiv2 = document.createElement('div');
      tempDiv2.innerHTML = htmlWithBreaks;
      
      // Extrahiere Text-Inhalt (ohne HTML-Tags)
      textContent = tempDiv2.textContent || tempDiv2.innerText || '';
    } else {
      textContent = directText;
    }
    
    if (textContent) {
      // Teile Text in Zeilen auf
      const lines = textContent.split('\n').map(line => {
        // Entferne Obsichan-Index am Ende der Zeile
        return line.replace(/\s+\^[a-z0-9]+\s*$/i, '').trim();
      }).filter(line => line.length > 0);
      
      // Prüfe, ob mindestens zwei aufeinanderfolgende Zeilen weniger als 90 Zeichen haben
      let consecutiveShortLines = 0;
      for (let i = 0; i < lines.length; i++) {
        const lineLength = lines[i].length;
        if (lineLength > 0 && lineLength < 90) {
          consecutiveShortLines++;
          if (consecutiveShortLines >= 2) {
            // Markiere die Div als Gedicht
            div.classList.add('has-poem');
            // WICHTIG: Entferne alle margin-Styles aus dem inline style-Attribut
            const currentStyle = div.getAttribute('style') || '';
            const newStyle = currentStyle
              .replace(/margin[^:]*:\s*[^;]+;?\s*/gi, '')
              .replace(/margin-top[^:]*:\s*[^;]+;?\s*/gi, '')
              .replace(/margin-bottom[^:]*:\s*[^;]+;?\s*/gi, '')
              .trim();
            div.setAttribute('style', newStyle);
            // Setze explizit margin-top und margin-bottom auf 0
            div.style.marginTop = '0';
            div.style.marginBottom = '0';
            break;
          }
        } else {
          consecutiveShortLines = 0;
        }
      }
    }
  });
  
  // ZUSÄTZLICH: Prüfe aufeinanderfolgende .paragraph Divs (für Vorträge, wo jeder Paragraph eine Zeile ist)
  // WICHTIG: Markiere alle aufeinanderfolgenden kurzen Paragraphen als Gedicht
  let i = 0;
  while (i < paragraphDivs.length) {
    const div = paragraphDivs[i];
    
    // Überspringe bereits markierte Gedichte
    if (div.classList.contains('has-poem')) {
      i++;
      continue;
    }
    
    // Extrahiere Text-Inhalt
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = div.innerHTML;
    
    // Entferne versteckte Spans (mit display:none oder data-index Attribut)
    const hiddenSpans = tempDiv.querySelectorAll('[style*="display:none"], [data-index]');
    hiddenSpans.forEach(span => span.remove());
    
    // Entferne auch versteckte Spans mit data-index Attribut (für Obsichan-Indizes)
    const indexSpans = tempDiv.querySelectorAll('[data-index]');
    indexSpans.forEach(span => {
      const style = span.getAttribute('style') || '';
      if (style.includes('display:none') || style.includes('display: none')) {
        span.remove();
      }
    });
    
    // Extrahiere Text-Inhalt (ohne HTML-Tags)
    let textContent = tempDiv.textContent || tempDiv.innerText || '';
    
    // Entferne Obsichan-Index am Ende (Format: ^abc123)
    const cleanText = textContent.replace(/\s+\^[a-z0-9]+\s*$/i, '').trim();
    
    // Wenn dieser Paragraph kurz ist (< 90 Zeichen), prüfe die nächsten
    if (cleanText.length > 0 && cleanText.length < 90) {
      const poemStartIndex = i;
      let consecutiveShortParagraphs = 1;
      let nextIndex = i + 1;
      
      // Sammle alle aufeinanderfolgenden kurzen Paragraphen
      const poemParagraphs = [div];
      
      // Prüfe die nächsten Paragraphs - NUR wenn sie direkt aufeinander folgen (keine anderen Elemente dazwischen)
      while (nextIndex < paragraphDivs.length) {
        const nextDiv = paragraphDivs[nextIndex];
        
        // WICHTIG: Prüfe ob zwischen diesem und dem nächsten Paragraph ein Absatzabstand ist
        // Wenn zwischen den Paragraphen andere Elemente sind (z.B. Überschriften), ist es kein Gedicht
        let hasGap = false;
        let currentElement = div.nextElementSibling;
        while (currentElement && currentElement !== nextDiv) {
          // Wenn zwischen den Paragraphen ein Element ist, das nicht versteckt ist, gibt es einen Abstand
          const computedStyle = window.getComputedStyle(currentElement);
          if (computedStyle.display !== 'none' && 
              computedStyle.visibility !== 'hidden' &&
              currentElement.textContent.trim().length > 0) {
            hasGap = true;
            break;
          }
          currentElement = currentElement.nextElementSibling;
        }
        
        // Wenn ein Abstand gefunden wurde, stoppe die Suche
        if (hasGap) {
          break;
        }
        
        const nextTempDiv = document.createElement('div');
        nextTempDiv.innerHTML = nextDiv.innerHTML;
        const nextHiddenSpans = nextTempDiv.querySelectorAll('[style*="display:none"], [data-index]');
        nextHiddenSpans.forEach(span => span.remove());
        const nextTextContent = nextTempDiv.textContent || nextTempDiv.innerText || '';
        const nextCleanText = nextTextContent.replace(/\s+\^[a-z0-9]+\s*$/i, '').trim();
        
        if (nextCleanText.length > 0 && nextCleanText.length < 90) {
          consecutiveShortParagraphs++;
          poemParagraphs.push(nextDiv);
          nextIndex++;
        } else {
          break;
        }
      }
      
      // Wenn mindestens 2 aufeinanderfolgende kurze Paragraphen gefunden wurden, markiere alle
      if (consecutiveShortParagraphs >= 2) {
        console.log(`[GEDICHT-ERKENNUNG] Gefunden: ${consecutiveShortParagraphs} aufeinanderfolgende kurze Paragraphen (Gedicht)`);
        
        // WICHTIG: Prüfe für jeden Paragraph, ob davor eine Leerzeile war (Strophen-Trenner)
        poemParagraphs.forEach((poemDiv, idx) => {
          poemDiv.classList.add('has-poem');
          
          // Prüfe ob dieser Paragraph der erste nach einer Leerzeile ist
          // (erkennbar an einem leeren/kurzen vorherigen Element oder doppeltem <br>)
          let isAfterStanzaBreak = false;
          
          if (idx > 0) {
            // Prüfe das vorherige Element im DOM
            const prevSibling = poemDiv.previousElementSibling;
            if (prevSibling) {
              const prevText = (prevSibling.textContent || '').trim();
              // Leere Zeile (nur Whitespace) oder sehr kurzer Text = Strophen-Trenner
              if (prevText.length === 0 || prevText === '\u00A0' || prevText === '&nbsp;') {
                isAfterStanzaBreak = true;
                // Markiere die leere Zeile als Strophen-Trenner
                prevSibling.classList.add('stanza-break');
              }
            }
          }
          
          // Prüfe auch ob der Paragraph selbst einen doppelten Zeilenumbruch enthält
          const innerHTML = poemDiv.innerHTML || '';
          if (innerHTML.includes('<br><br>') || innerHTML.includes('<br /><br />') || innerHTML.includes('<br/><br/>')) {
            isAfterStanzaBreak = true;
          }
          
          // WICHTIG: Entferne alle margin-Styles aus dem inline style-Attribut
          const currentStyle = poemDiv.getAttribute('style') || '';
          const newStyle = currentStyle
            .replace(/margin[^:]*:\s*[^;]+;?\s*/gi, '')
            .replace(/margin-top[^:]*:\s*[^;]+;?\s*/gi, '')
            .replace(/margin-bottom[^:]*:\s*[^;]+;?\s*/gi, '')
            .replace(/padding[^:]*:\s*[^;]+;?\s*/gi, '')
            .trim();
          // Entferne style-Attribut komplett und setze neue Styles
          poemDiv.removeAttribute('style');
          // Setze explizit margin und padding auf 0 mit !important
          poemDiv.style.setProperty('margin', '0', 'important');
          poemDiv.style.setProperty('margin-bottom', '0', 'important');
          poemDiv.style.setProperty('padding', '0', 'important');
          poemDiv.style.setProperty('line-height', '1.5', 'important');
          
          // ABER: Wenn nach einem Strophen-Trenner, behalte margin-top für Abstand
          if (isAfterStanzaBreak && idx > 0) {
            poemDiv.style.setProperty('margin-top', '1em', 'important');
            poemDiv.classList.add('after-stanza-break');
            console.log(`[GEDICHT-ERKENNUNG] Paragraph ${idx + 1} ist nach Strophen-Trenner`);
          } else {
            poemDiv.style.setProperty('margin-top', '0', 'important');
          }
          
          console.log(`[GEDICHT-ERKENNUNG] Paragraph ${idx + 1} markiert als Gedicht, Style: ${poemDiv.getAttribute('style')}`);
        });
        
        // Überspringe alle markierten Paragraphen
        i = nextIndex;
      } else {
        i++;
      }
    } else {
      i++;
    }
  }
  
  // Prüfe jeden Paragraph einzeln UND aufeinanderfolgende Paragraphs
  paragraphs.forEach((p, index) => {
    // Überspringe bereits markierte Gedichte
    if (p.classList.contains('poem')) return;
    // Extrahiere Text-Inhalt (ohne HTML-Tags)
    const textContent = p.textContent || p.innerText || '';
    
    // Teile Text in Zeilen auf (berücksichtigt <br> und Zeilenumbrüche)
    // Erstelle temporäres Element, um HTML zu parsen
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = p.innerHTML;
    
    // Ersetze <br> durch Zeilenumbrüche für die Analyse
    const textWithBreaks = tempDiv.innerHTML.replace(/<br\s*\/?>/gi, '\n');
    const lines = textWithBreaks.split('\n').map(line => {
      // Entferne HTML-Tags für die Zeichenzählung
      const temp = document.createElement('div');
      temp.innerHTML = line;
      
      // Entferne versteckte Spans (mit display:none oder data-index Attribut)
      const hiddenSpans = temp.querySelectorAll('[style*="display:none"], [data-index]');
      hiddenSpans.forEach(span => span.remove());
      
      let text = temp.textContent || temp.innerText || '';
      // Entferne Obsichan-Index am Ende der Zeile (Format: ^xyz123 oder Leerzeichen + ^xyz123)
      text = text.replace(/\s+\^[a-z0-9]+\s*$/i, '');
      return text;
    }).filter(line => line.trim().length > 0);
    
    // Prüfe, ob mindestens zwei aufeinanderfolgende Zeilen weniger als 90 Zeichen haben
    let consecutiveShortLines = 0;
    for (let i = 0; i < lines.length; i++) {
      const lineLength = lines[i].trim().length;
      if (lineLength > 0 && lineLength < 90) {
        consecutiveShortLines++;
        if (consecutiveShortLines >= 2) {
          // Markiere als Gedicht/kurze Zeilen
          p.classList.add('poem');
          
          // Entferne margin-bottom von parent .paragraph Div (überschreibt Inline-Styles)
          const parentParagraph = p.closest('.paragraph');
          if (parentParagraph) {
            parentParagraph.classList.add('has-poem');
            // Entferne alle margin/padding Styles aus dem style-Attribut
            const currentStyle = parentParagraph.getAttribute('style') || '';
            const newStyle = currentStyle
              .replace(/margin[^:]*:\s*[^;]+;?\s*/gi, '')
              .replace(/padding[^:]*:\s*[^;]+;?\s*/gi, '')
              .trim();
            // Entferne style-Attribut und setze neue Styles
            parentParagraph.removeAttribute('style');
            parentParagraph.style.setProperty('margin', '0', 'important');
            parentParagraph.style.setProperty('margin-top', '0', 'important');
            parentParagraph.style.setProperty('margin-bottom', '0', 'important');
            parentParagraph.style.setProperty('padding', '0', 'important');
            parentParagraph.style.setProperty('line-height', '1.5', 'important');
          }
          
          break;
        }
      } else {
        // Reset wenn Zeile zu lang ist
        consecutiveShortLines = 0;
      }
    }
    
    // ZUSÄTZLICH: Prüfe aufeinanderfolgende <p> Elemente mit kurzen Zeilen
    // Wenn dieser Paragraph eine kurze Zeile hat (< 90 Zeichen), prüfe die nächsten
    // WICHTIG: Nur wenn zwischen den Paragraphen kein Absatzabstand ist (direkt aufeinander folgen)
    if (lines.length > 0 && lines[0].trim().length > 0 && lines[0].trim().length < 90) {
      let consecutiveShortParagraphs = 1;
      let nextIndex = index + 1;
      
      // Prüfe die nächsten Paragraphs - NUR wenn sie direkt aufeinander folgen (keine anderen Elemente dazwischen)
      while (nextIndex < paragraphs.length && consecutiveShortParagraphs < 2) {
        const nextP = paragraphs[nextIndex];
        
        // WICHTIG: Prüfe ob zwischen diesem und dem nächsten Paragraph ein Absatzabstand ist
        // Wenn zwischen den Paragraphen andere Elemente sind (z.B. Überschriften), ist es kein Gedicht
        let hasGap = false;
        let currentElement = p.nextElementSibling;
        while (currentElement && currentElement !== nextP) {
          // Wenn zwischen den Paragraphen ein Element ist, das nicht versteckt ist, gibt es einen Abstand
          const computedStyle = window.getComputedStyle(currentElement);
          if (computedStyle.display !== 'none' && 
              computedStyle.visibility !== 'hidden' &&
              currentElement.textContent.trim().length > 0) {
            hasGap = true;
            break;
          }
          currentElement = currentElement.nextElementSibling;
        }
        
        // Wenn ein Abstand gefunden wurde, stoppe die Suche
        if (hasGap) {
          break;
        }
        
        const nextTextContent = nextP.textContent || nextP.innerText || '';
        const nextTempDiv = document.createElement('div');
        nextTempDiv.innerHTML = nextP.innerHTML;
        const nextTextWithBreaks = nextTempDiv.innerHTML.replace(/<br\s*\/?>/gi, '\n');
        const nextLines = nextTextWithBreaks.split('\n').map(line => {
          const temp = document.createElement('div');
          temp.innerHTML = line;
          
          // Entferne versteckte Spans (mit display:none oder data-index Attribut)
          const hiddenSpans = temp.querySelectorAll('[style*="display:none"], [data-index]');
          hiddenSpans.forEach(span => span.remove());
          
          let text = temp.textContent || temp.innerText || '';
          // Entferne Obsichan-Index am Ende der Zeile (Format: ^xyz123 oder Leerzeichen + ^xyz123)
          text = text.replace(/\s+\^[a-z0-9]+\s*$/i, '');
          return text;
        }).filter(line => line.trim().length > 0);
        
        if (nextLines.length > 0 && nextLines[0].trim().length > 0 && nextLines[0].trim().length < 90) {
          consecutiveShortParagraphs++;
        if (consecutiveShortParagraphs >= 2) {
          // Markiere beide als Gedicht
          p.classList.add('poem');
          nextP.classList.add('poem');
          
          // Entferne margin-bottom von parent .paragraph Divs (überschreibt Inline-Styles)
          const parentParagraph = p.closest('.paragraph');
          if (parentParagraph) {
            parentParagraph.classList.add('has-poem');
            const currentStyle = parentParagraph.getAttribute('style') || '';
            const newStyle = currentStyle
              .replace(/margin[^:]*:\s*[^;]+;?\s*/gi, '')
              .replace(/padding[^:]*:\s*[^;]+;?\s*/gi, '')
              .trim();
            // Entferne style-Attribut und setze neue Styles
            parentParagraph.removeAttribute('style');
            parentParagraph.style.setProperty('margin', '0', 'important');
            parentParagraph.style.setProperty('margin-top', '0', 'important');
            parentParagraph.style.setProperty('margin-bottom', '0', 'important');
            parentParagraph.style.setProperty('padding', '0', 'important');
            parentParagraph.style.setProperty('line-height', '1.5', 'important');
          }
          const nextParentParagraph = nextP.closest('.paragraph');
          if (nextParentParagraph) {
            nextParentParagraph.classList.add('has-poem');
            // Entferne style-Attribut und setze neue Styles
            nextParentParagraph.removeAttribute('style');
            nextParentParagraph.style.setProperty('margin', '0', 'important');
            nextParentParagraph.style.setProperty('margin-top', '0', 'important');
            nextParentParagraph.style.setProperty('margin-bottom', '0', 'important');
            nextParentParagraph.style.setProperty('padding', '0', 'important');
            nextParentParagraph.style.setProperty('line-height', '1.5', 'important');
          }
          
          break;
        }
        } else {
          break;
        }
        nextIndex++;
      }
    }
  });
  
  // Fasse aufeinanderfolgende .paragraph.has-poem Divs zu einem Block zusammen
  // (wie in Büchern, wo ein <p class="poem"> mit <br> Tags verwendet wird)
  const foundPoemParagraphs = Array.from(container.querySelectorAll('.paragraph.has-poem'));
  if (foundPoemParagraphs.length > 0) {
    let i = 0;
    while (i < foundPoemParagraphs.length) {
      const firstPoemDiv = foundPoemParagraphs[i];
      if (!firstPoemDiv.classList.contains('has-poem')) {
        i++;
        continue;
      }
      
      // Sammle alle aufeinanderfolgenden .paragraph.has-poem Divs
      const poemBlock = [firstPoemDiv];
      let nextIndex = i + 1;
      
      while (nextIndex < foundPoemParagraphs.length) {
        const nextDiv = foundPoemParagraphs[nextIndex];
        // Prüfe ob nextDiv direkt nach dem letzten Element im Block kommt
        const lastInBlock = poemBlock[poemBlock.length - 1];
        // Prüfe ob nextDiv direkt nach lastInBlock kommt (aufeinanderfolgend im DOM)
        if (nextDiv.previousElementSibling === lastInBlock) {
          poemBlock.push(nextDiv);
          nextIndex++;
        } else {
          // Nicht aufeinanderfolgend - Block ist vollständig
          break;
        }
      }
      
      // Wenn mehr als 1 Paragraph im Block, fasse sie zusammen
      if (poemBlock.length > 1) {
        // Erstelle einen neuen Container für den Gedicht-Block
        const poemContainer = document.createElement('div');
        poemContainer.className = 'paragraph has-poem poem-block';
        poemContainer.style.margin = '0';
        poemContainer.style.padding = '0';
        poemContainer.style.lineHeight = '1.5';
        
        // Verschiebe alle Elemente aus den einzelnen Paragraphen in den Container
        // WICHTIG: Behalte nicht nur <p> Tags, sondern auch Überschriften (<h2>, <h3>, <h4>) und <hr> Tags
        poemBlock.forEach((poemDiv, idx) => {
          // Sammle alle direkten Kind-Elemente (nicht nur <p> Tags)
          const allChildren = Array.from(poemDiv.childNodes);
          
          allChildren.forEach((child, childIdx) => {
            // Überspringe Text-Knoten die nur Whitespace enthalten
            if (child.nodeType === Node.TEXT_NODE && !child.textContent.trim()) {
              return;
            }
            
            // Für Element-Knoten
            if (child.nodeType === Node.ELEMENT_NODE) {
              const tagName = child.tagName.toLowerCase();
              
              // Überschriften und horizontale Linien BEIBEHALTEN
              if (tagName === 'h2' || tagName === 'h3' || tagName === 'h4' || tagName === 'hr') {
                poemContainer.appendChild(child.cloneNode(true));
                return;
              }
              
              // Überschriften und horizontale Linien BEIBEHALTEN  
              // (asterisk-break wird als normales <p> behandelt und danach von fixAsteriskBreakSpacing korrigiert)
              
              // Für <p> Tags: Entferne Margins und füge hinzu
              if (tagName === 'p') {
                const clonedP = child.cloneNode(true);
                clonedP.style.margin = '0';
                clonedP.style.padding = '0';
                clonedP.style.lineHeight = '1.5';
                
                // Füge <br> zwischen Zeilen hinzu (außer bei der ersten)
                if (idx > 0 || childIdx > 0) {
                  poemContainer.appendChild(document.createElement('br'));
                }
                
                poemContainer.appendChild(clonedP);
                return;
              }
              
              // Andere Elemente auch beibehalten (z.B. <img>, <span>, etc.)
              poemContainer.appendChild(child.cloneNode(true));
            } else if (child.nodeType === Node.TEXT_NODE && child.textContent.trim()) {
              // Text-Knoten mit Inhalt beibehalten
              poemContainer.appendChild(child.cloneNode(true));
            }
          });
          
          // Ersetze den ursprünglichen Paragraph durch den Container (nur beim ersten)
          if (idx === 0) {
            // Bewahre alle Attribute des ersten Paragraphs
            poemContainer.id = poemDiv.id;
            poemContainer.setAttribute('data-index', poemDiv.getAttribute('data-index') || '');
            if (poemDiv.onclick) {
              poemContainer.onclick = poemDiv.onclick;
            }
            poemDiv.replaceWith(poemContainer);
          } else {
            // Entferne die anderen Paragraphen
            poemDiv.remove();
          }
        });
        
        // Überspringe alle verarbeiteten Paragraphen
        i = nextIndex;
      } else {
        i++;
      }
    }
  }
  
  // Nachbearbeitung: Korrigiere Abstände um * * * Sternchen-Trenner
  fixAsteriskBreakSpacing(container);
}

// Globale Variable für aktuellen Keyword-Text (für Markierung in Treffer-Absätzen)
let currentKeywordText = null;

function displayKeywordThematicResults(keyword, data) {
  // Speichere aktuellen Keyword-Text für Markierung
  currentKeywordText = keyword;
  const viewer = document.getElementById('viewer');
  const countContainer = document.getElementById('keyword-count');
  
  if (!viewer) return;
  
  // Hilfsfunktion: Wandle Markdown zu HTML um
  function markdownToHtml(text) {
    const processed = text
      // WICHTIG: Entferne Markdown-Links ZUERST (vor allen anderen Ersetzungen)
      // [[GA066 (1.) GEIST UND STOFF...|GA066/1]] -> GA066/1 (ohne Klammern, die werden später hinzugefügt)
      .replace(/\[\[[^\]]*\|(GA\d+[a-z]?\/\d+)\]\]/g, '$1')
      // Entfernt H1-Überschriften vollständig
      .replace(/^# (.+)$/gm, '')
      // Entfernt H3-Überschriften (### ...) vollständig
      .replace(/^### (.+)$/gm, '')
      // Wandelt H4 (#### ...) in <h4> um
      .replace(/^#### (.+)$/gm, '<h4>$1</h4>')
      // Wandelt H2 (## ...) in semantische Überschriften ohne Inline-Styles
      .replace(/^## (.+)$/gm, '<h3>$1</h3>')
      // Fett: **text** -> <strong>text</strong>
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      // Kursiv: *text* -> <em>text</em>
      .replace(/\*(.+?)\*/g, '<em>$1</em>')
      // Kursiv: _text_ -> <em>text</em> (nur wenn von Nicht-Buchstaben umgeben)
      .replace(/(?<=[^a-zA-ZäöüÄÖÜß])_([^_]+)_(?=[^a-zA-ZäöüÄÖÜß]|$)/g, '<em>$1</em>')
      // Kursiv am Zeilenanfang: _text_ -> <em>text</em>
      .replace(/^_([^_]+)_(?=[^a-zA-ZäöüÄÖÜß]|$)/gm, '<em>$1</em>')
      // Zeilenumbrüche: \n\n -> </p><p>
      .replace(/\n\n/g, '</p><p>')
      // Einzelne Zeilenumbrüche: \n -> <br>
      .replace(/\n/g, '<br>');
    
    // Wenn Paragraphen erstellt wurden, füge öffnendes <p> am Anfang und schließendes </p> am Ende hinzu
    if (processed.includes('</p><p>')) {
      return `<p>${processed}</p>`;
    }
    return processed;
  }
  
  // Hilfsfunktion: Wandle GA-Referenzen in klickbare Links um (für rechtes Side-Panel)
  // HINWEIS: Links mit Klammern werden jetzt im DOM konvertiert (convertGAReferencesToLinksInKeywordResults)
  // Diese Funktion wird nur noch für "Weitere Quellen" verwendet (ohne Klammern)
  function makeGAReferencesClickable(text) {
    let result = text;
    
    // NEU: Wandle GA-Referenzen OHNE Klammern in Links um (für "Weitere Quellen:")
    // Format: GA###/Y:index oder GA###a/Y:index (ohne Klammern drumherum)
    // Unterstützt auch GA157a/2 (mit Buchstaben nach der Nummer)
    result = result.replace(/\bGA(\d{1,3}[a-z]?)\/(\d+)(?::(\^?[a-zA-Z0-9]+))?\b/gi, (match, gaNum, lectureNum, index) => {
      const lectureId = `GA${gaNum} - ${lectureNum}`;
      
      // Index: Stelle sicher, dass ^ vorhanden ist (wie in Themen_Übersicht)
      const rawIndex = index || '';
      const paragraphIndex = rawIndex ? (rawIndex.startsWith('^') ? rawIndex : `^${rawIndex}`) : null;
      
      // Für die Anzeige: Original-Nummern ohne Padding
      const displayId = `GA${gaNum} - ${lectureNum}`;
      
      // Escape für JavaScript-String
      const escapedLectureId = lectureId.replace(/'/g, "\\'");
      
      // Verwende showLectureFromAdvancedSearch für rechtes Panel (wie bei Themen_Übersicht)
      if (paragraphIndex) {
        const escapedIndex = paragraphIndex.replace(/'/g, "\\'");
        return `<a href="#" onclick="showLectureFromAdvancedSearch('${escapedLectureId}', '', '${escapedIndex}'); return false;" class="ga-keyword-link">${displayId}</a>`;
      } else {
        return `<a href="#" onclick="showLectureFromAdvancedSearch('${escapedLectureId}', '', null); return false;" class="ga-keyword-link">${displayId}</a>`;
      }
    });
    
    return result;
  }
  
  // Hauptinhalt (KI-Analyse) mit Markdown-zu-HTML und klickbaren GA-Referenzen
  let contentHtml = '';
  if (data.content) {
    const markdownHtml = markdownToHtml(data.content);
    const contentWithLinks = makeGAReferencesClickable(markdownHtml);
    
    // Hinweis: Klammern-Entfernung ist nicht mehr nötig, da der neue Prompt 
    // "Weitere Quellen" bereits ohne Klammern generiert und die Links korrekt erstellt werden
    
    // Ersetze englische Anführungszeichen durch deutsche Anführungszeichen
    // "text" -> „text"
    // WICHTIG: Nur in Text-Inhalten, nicht in HTML-Attributen
    let contentWithGermanQuotes = contentWithLinks
      // Ersetze öffnende Anführungszeichen: " nach Leerzeichen, Zeilenumbruch oder am Anfang
      // Aber nicht wenn es Teil eines HTML-Attributs ist (nicht nach = oder <)
      .replace(/(?<!<[^>]*)(?<!=[^>]*)(^|[\s\n>])"/g, '$1„')
      // Ersetze schließende Anführungszeichen: " vor Leerzeichen, Satzzeichen oder am Ende
      // Aber nicht wenn es Teil eines HTML-Attributs ist (nicht vor = oder >)
      .replace(/"([\s\n.,;:!?)]|$)(?![^<]*=)(?![^<]*>)/g, '"$1');
    
    // Alternative einfachere Methode: Ersetze nur in Text-Inhalten (nicht in Tags)
    // Teile HTML in Tags und Text auf
    contentWithGermanQuotes = contentWithGermanQuotes.replace(/>([^<]+)</g, (match, text) => {
      // Ersetze Anführungszeichen nur im Text-Inhalt
      const replacedText = text
        .replace(/(^|[\s\n])"/g, '$1„')
        .replace(/"([\s\n.,;:!?)]|$)/g, '"$1');
      return '>' + replacedText + '<';
    });
    
    // Wrappe in <p> nur wenn noch keine Paragraphen vorhanden sind
    const hasParagraphs = contentWithGermanQuotes.includes('</p>');
    const wrappedContent = hasParagraphs ? contentWithGermanQuotes : `<p>${contentWithGermanQuotes}</p>`;
    contentHtml = `
      <div class="keyword-answer">
        ${wrappedContent}
      </div>
    `;
  }
  
  // Kombiniere alles (nur Hauptinhalt) im gleichen Layout wie Themensuche
  // Prüfe ob bereits eine Übersicht im Viewer angezeigt wird
  const existingContent = viewer.innerHTML;
  const hasOverview = existingContent.includes('concept-overview-header');
  
  // Wenn bereits eine Übersicht vorhanden ist, füge die Ergebnisse unterhalb hinzu (ohne zweite Überschrift, mit Trennlinie)
  if (hasOverview) {
    const resultsHtml = `
      <div class="concept-results-separator"></div>
      <div class="semantic-answer concept-results-content">
        <div class="answer-content" id="keywordAnswerContent">
          ${contentHtml}
        </div>
      </div>
    `;
    viewer.innerHTML += resultsHtml;
  } else {
    // Wenn keine Übersicht vorhanden ist, ersetze den gesamten Viewer-Inhalt (ohne Überschrift, da das Keyword bereits in der Übersicht steht)
    viewer.innerHTML = `
      <div class="semantic-answer">
        <div class="answer-content" id="keywordAnswerContent">
          ${contentHtml}
        </div>
      </div>
    `;
  }

  // Sicherheitshalber Inline-Styles entfernen (falls Backend-Markdown doch Styles liefert)
  removeInlineStyles(viewer);
  // Normalisiere Unicode-Zeichen für einheitliche Darstellung
  normalizeUnicode(viewer);
  
  // Erkenne und formatiere Gedichte/kurze Zeilen in concept-content (nach DOM-Rendering)
  setTimeout(() => {
    const conceptContent = viewer.querySelector('.concept-content');
    if (conceptContent) {
      detectAndFormatPoems(conceptContent);
    }
    // Prüfe auch alle anderen Bereiche im viewer
    detectAndFormatPoems(viewer);
  }, 0);
  
  // Konvertiere GA-Links im DOM (nach dem Setzen des HTML)
  // Verwende die gleiche Methode wie bei Themen_Übersicht für konsistente Verlinkung
  try {
    const answerContent = document.getElementById('keywordAnswerContent');
    if (answerContent) {
      convertGAReferencesToLinksInKeywordResults(answerContent);
      
      // Füge Click-Handler zu allen Bildern hinzu, um sie zu vergrößern
      const images = answerContent.querySelectorAll('img');
      images.forEach(img => {
        // Überspringe wenn bereits ein Handler vorhanden ist
        if (img.hasAttribute('data-image-popup-handler')) return;
        
        img.setAttribute('data-image-popup-handler', 'true');
        img.style.cursor = 'pointer';
        
        img.addEventListener('click', function(e) {
          e.preventDefault();
          e.stopPropagation();
          const imageSrc = img.src;
          const altText = img.getAttribute('alt') || '';
          const dataFormat = img.getAttribute('data-format');
          openImagePopup(imageSrc, altText, dataFormat);
        });
      });
    }
  } catch (error) {
    console.error('[KEYWORD-THEMATIC] Fehler beim Konvertieren der GA-Links:', error);
  }
  
  // Einheitliche Abstände um Klammern an GA-Quellenangaben (Keyword-Themen)
  try {
    const kc = document.getElementById('keywordAnswerContent');
    if (kc) {
      normalizeCitationSpacing(kc);
      // Deutsche Anführungszeichen „..." verwenden
      convertToGermanQuotes(kc);
    }
  } catch (_) {}
  
  // Verlinke Schlagwörter im Text, die als Index-Einträge existieren
  // DEAKTIVIERT: Schlagwort-Links wurden entfernt - nur GA-Links bleiben erhalten
  // setTimeout(() => {
  //   const answerContentForLinks = document.getElementById('keywordAnswerContent');
  //   if (answerContentForLinks) {
  //     linkifySchlagworteInElement(answerContentForLinks, keyword);
  //   }
  // }, 150);
  
  // Lucide Icons initialisieren
  initializeLucideIcons();
  
  // Aktualisiere Count-Container
  if (countContainer) {
    countContainer.textContent = '';
  }
  
  // WICHTIG: Scrolle Ergebnisfenster immer nach oben bei neuem Schlagwort
  const mainContainer = document.getElementById('main');
  if (mainContainer) {
    mainContainer.scrollTop = 0;
    }
  
  }

