// Blende "Schlagwort hinzufügen" nur lokal ein
(() => {
  try {
    const host = window.location.hostname || '';
    const protocol = window.location.protocol || '';
    const localHosts = ['localhost', '127.0.0.1', '::1', '0.0.0.0'];
    const isLocalHost = localHosts.includes(host) || host.endsWith('.local');
    const isLocalProtocol = protocol === 'file:'; // allow when opened directly from disk during local work
    const isLocal = isLocalHost || isLocalProtocol;
    
    const addSection = document.getElementById('addKeywordSection');
    const regenerateSection = document.getElementById('regenerateKeywordSection');
    const batchSection = document.getElementById('batchKeywordSection');
    const consolidateSection = document.getElementById('consolidateKeywordSection');
    
    if (addSection) {
      addSection.style.display = isLocal ? 'block' : 'none';
    }
    if (regenerateSection) {
      regenerateSection.style.display = isLocal ? 'block' : 'none';
    }
    if (batchSection) {
      batchSection.style.display = isLocal ? 'block' : 'none';
    }
    if (consolidateSection) {
      consolidateSection.style.display = isLocal ? 'block' : 'none';
    }
  } catch (_) {}
})();

// Batch-Schlagwort-Generierung
let batchProcessing = false;
let batchAbortController = null;
let batchSectionVisible = true;

function toggleBatchSection() {
  const batchContent = document.getElementById('batchContent');
  const toggleButton = document.getElementById('batchToggleButton');
  
  if (batchSectionVisible) {
    // Ausblenden
    batchContent.style.display = 'none';
    toggleButton.textContent = 'Einblenden';
    toggleButton.style.background = '#2e7d32';
    batchSectionVisible = false;
  } else {
    // Einblenden
    batchContent.style.display = 'block';
    toggleButton.textContent = 'Ausblenden';
    toggleButton.style.background = '#666';
    batchSectionVisible = true;
  }
}

// EventSource für Batch-Verarbeitung (global für Abbruch-Funktion)
let batchEventSource = null;

async function addBatchKeywords() {
  const batchInput = document.getElementById('batchKeywordsInput');
  const batchButton = document.getElementById('batchAddButton');
  const batchCancelButton = document.getElementById('batchCancelButton');
  const statusDiv = document.getElementById('batchKeywordStatus');
  const progressContainer = document.getElementById('batchProgressContainer');
  const progressText = document.getElementById('batchProgressText');
  const progressPercent = document.getElementById('batchProgressPercent');
  const progressBar = document.getElementById('batchProgressBar');
  const resultsDiv = document.getElementById('batchResults');
  const keywordsList = document.getElementById('batchKeywordsList');
  const overwriteCheckbox = document.getElementById('batchOverwriteCheckbox');
  
  if (!batchInput || !batchButton || !statusDiv) {
    console.error('[BATCH-KEYWORDS] UI-Elemente nicht gefunden');
    return;
  }
  
  const keywordsText = batchInput.value.trim();
  
  if (!keywordsText) {
    statusDiv.innerHTML = '<div style="color: #d32f2f; font-size: 0.85em;">Bitte geben Sie mindestens ein Schlagwort ein.</div>';
    statusDiv.style.display = 'block';
    return;
  }
  
  // Parse Schlagwörter aus Textarea
  const keywords = keywordsText.split('\n')
    .map(k => k.trim())
    .filter(k => k.length > 0);
  
  if (keywords.length === 0) {
    statusDiv.innerHTML = '<div style="color: #d32f2f; font-size: 0.85em;">Keine gültigen Schlagwörter gefunden.</div>';
    statusDiv.style.display = 'block';
    return;
  }
  
  if (keywords.length > 50) {
    statusDiv.innerHTML = '<div style="color: #d32f2f; font-size: 0.85em;">Maximal 50 Schlagwörter pro Batch erlaubt.</div>';
    statusDiv.style.display = 'block';
    return;
  }
  
  // UI-Status aktualisieren
  batchProcessing = true;
  
  batchButton.disabled = true;
  batchButton.style.display = 'none';
  batchCancelButton.style.display = 'inline-block';
  statusDiv.style.display = 'none';
  progressContainer.style.display = 'block';
  resultsDiv.style.display = 'none';
  
  // Fortschritt und Schlagwort-Liste zurücksetzen
  progressText.textContent = `Verarbeite 0 von ${keywords.length} Schlagwörtern (parallel)...`;
  progressPercent.textContent = '0%';
  progressBar.style.width = '0%';
  keywordsList.innerHTML = '';
  
  // Erstelle Status-Elemente für jedes Schlagwort
  const keywordStatusMap = new Map();
  keywords.forEach((kw, i) => {
    const statusEl = document.createElement('div');
    statusEl.id = `batch-kw-${i}`;
    statusEl.style.cssText = 'padding: 4px 8px; margin: 2px 0; border-radius: 4px; background: var(--input-bg); display: flex; align-items: center; gap: 8px;';
    statusEl.innerHTML = `
      <span class="batch-kw-indicator" style="width: 12px; height: 12px; border-radius: 50%; background: #888; flex-shrink: 0;"></span>
      <span class="batch-kw-name" style="flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${kw}</span>
      <span class="batch-kw-status" style="font-size: 0.9em; color: #888;">Wartend...</span>
    `;
    keywordsList.appendChild(statusEl);
    keywordStatusMap.set(i, statusEl);
  });
  
  // Hilfsfunktion zum Aktualisieren des Schlagwort-Status
  const updateKeywordStatus = (index, status, message) => {
    const statusEl = keywordStatusMap.get(index);
    if (!statusEl) return;
    
    const indicator = statusEl.querySelector('.batch-kw-indicator');
    const statusText = statusEl.querySelector('.batch-kw-status');
    
    switch (status) {
      case 'processing':
        indicator.style.background = '#f0ad4e'; // Orange - verarbeitet
        indicator.style.animation = 'pulse 1s infinite';
        statusText.textContent = 'Suche...';
        statusText.style.color = '#f0ad4e';
        break;
      case 'generating':
        indicator.style.background = '#5bc0de'; // Blau - KI generiert
        statusText.textContent = 'KI generiert...';
        statusText.style.color = '#5bc0de';
        break;
      case 'completed':
        indicator.style.background = '#5cb85c'; // Grün - erfolgreich
        indicator.style.animation = 'none';
        statusText.textContent = '? Fertig';
        statusText.style.color = '#5cb85c';
        break;
      case 'skipped':
        indicator.style.background = '#f0ad4e'; // Orange - übersprungen
        indicator.style.animation = 'none';
        statusText.textContent = message || 'Übersprungen';
        statusText.style.color = '#f0ad4e';
        break;
      case 'failed':
        indicator.style.background = '#d9534f'; // Rot - fehlgeschlagen
        indicator.style.animation = 'none';
        statusText.textContent = message || 'Fehler';
        statusText.style.color = '#d9534f';
        break;
    }
    
    // Scroll zum aktiven Element
    statusEl.scrollIntoView({ behavior: 'auto', block: 'nearest' });
  };
  
  try {
    const apiBase = window.API_BASE || 'http://localhost:3003';
    const params = new URLSearchParams({
      keywords: keywords.join(','),
      overwrite: overwriteCheckbox.checked,
      concurrency: 5, // Parallele Verarbeitung: 5 gleichzeitig
      batchId: `batch_${Date.now()}`
    });
    
    // SSE-Verbindung aufbauen
    batchEventSource = new EventSource(`${apiBase}/api/concepts-batch-add-stream?${params}`);
    
    batchEventSource.addEventListener('start', (event) => {
      const data = JSON.parse(event.data);
      console.log('[BATCH-KEYWORDS] Gestartet:', data);
      progressText.textContent = `Verarbeite 0 von ${data.totalKeywords} Schlagwörtern (${data.concurrency} parallel)...`;
    });
    
    batchEventSource.addEventListener('progress', (event) => {
      const data = JSON.parse(event.data);
      console.log('[BATCH-KEYWORDS] Progress:', data);
      updateKeywordStatus(data.index, data.status, data.message);
    });
    
    batchEventSource.addEventListener('batch-progress', (event) => {
      const data = JSON.parse(event.data);
      const percent = Math.round((data.processed / data.total) * 100);
      progressText.textContent = `Verarbeite ${data.processed} von ${data.total} Schlagwörtern...`;
      progressPercent.textContent = `${percent}%`;
      progressBar.style.width = `${percent}%`;
      
      // Live-Zähler aktualisieren
      document.getElementById('batchSuccessCount').textContent = data.successful;
      document.getElementById('batchFailedCount').textContent = data.failed;
      document.getElementById('batchSkippedCount').textContent = data.skipped;
      resultsDiv.style.display = 'block';
    });
    
    batchEventSource.addEventListener('complete', async (event) => {
      const data = JSON.parse(event.data);
      console.log('[BATCH-KEYWORDS] Abgeschlossen:', data);
      
      // Verbindung schließen
      batchEventSource.close();
      batchEventSource = null;
      
      // Erfolg anzeigen
      statusDiv.innerHTML = `<div style="color: #2e7d32; font-size: 0.85em;">? ${data.message}</div>`;
      statusDiv.style.display = 'block';
      
      // Eingabefeld leeren
      batchInput.value = '';
      
      // Fortschritt auf 100% setzen
      progressText.textContent = `Abgeschlossen: ${data.successful.length} von ${data.totalKeywords} erfolgreich`;
      progressPercent.textContent = '100%';
      progressBar.style.width = '100%';
      
      // Ergebnisse anzeigen
      document.getElementById('batchSuccessCount').textContent = data.successful.length;
      document.getElementById('batchFailedCount').textContent = data.failed.length;
      document.getElementById('batchSkippedCount').textContent = data.skipped.length;
      resultsDiv.style.display = 'block';
      
      // Schlagwort-Liste aktualisieren
      await loadKeywordsData();
      
      // Markiere erfolgreich hinzugefügte Schlagwörter als neu generiert
      if (data.successful) {
        data.successful.forEach(keywordName => {
          const existingKeyword = keywordsData.find(kw => kw.keyword === keywordName);
          if (existingKeyword) {
            existingKeyword.replaced = true;
            existingKeyword.newlyGenerated = true;
          }
        });
      }
      
      displayKeywords();
      
      // UI-Status zurücksetzen
      batchProcessing = false;
      batchButton.disabled = false;
      batchButton.style.display = 'inline-block';
      batchCancelButton.style.display = 'none';
    });
    
    batchEventSource.addEventListener('error', (event) => {
      let errorData = {};
      try {
        errorData = JSON.parse(event.data || '{}');
      } catch (e) {}
      
      console.error('[BATCH-KEYWORDS] SSE Fehler:', errorData);
      
      // Verbindung schließen
      if (batchEventSource) {
        batchEventSource.close();
        batchEventSource = null;
      }
      
      statusDiv.innerHTML = `<div style="color: #d32f2f; font-size: 0.85em;">? Fehler: ${errorData.message || 'Verbindung unterbrochen'}</div>`;
      statusDiv.style.display = 'block';
      
      // UI-Status zurücksetzen
      batchProcessing = false;
      batchButton.disabled = false;
      batchButton.style.display = 'inline-block';
      batchCancelButton.style.display = 'none';
    });
    
    batchEventSource.onerror = (event) => {
      // Connection error (nicht das custom error event)
      if (batchEventSource && batchEventSource.readyState === EventSource.CLOSED) {
        console.log('[BATCH-KEYWORDS] Verbindung geschlossen');
      }
    };
    
  } catch (error) {
    console.error('[BATCH-KEYWORDS] Fehler:', error);
    statusDiv.innerHTML = `<div style="color: #d32f2f; font-size: 0.85em;">? Fehler: ${error.message}</div>`;
    statusDiv.style.display = 'block';
    
    // UI-Status zurücksetzen
    batchProcessing = false;
    batchButton.disabled = false;
    batchButton.style.display = 'inline-block';
    batchCancelButton.style.display = 'none';
  }
}

function cancelBatchKeywords() {
  // SSE-Verbindung schließen (neue Methode)
  if (batchEventSource) {
    batchEventSource.close();
    batchEventSource = null;
    
    const statusDiv = document.getElementById('batchKeywordStatus');
    const batchButton = document.getElementById('batchAddButton');
    const batchCancelButton = document.getElementById('batchCancelButton');
    
    if (statusDiv) {
      statusDiv.innerHTML = '<div style="color: #f57c00; font-size: 0.85em;">? Batch-Verarbeitung abgebrochen</div>';
      statusDiv.style.display = 'block';
    }
    
    // UI zurücksetzen
    batchProcessing = false;
    if (batchButton) {
      batchButton.disabled = false;
      batchButton.style.display = 'inline-block';
    }
    if (batchCancelButton) {
      batchCancelButton.style.display = 'none';
    }
  }
  
  // Fallback für alte AbortController-Methode
  if (batchAbortController) {
    batchAbortController.abort();
  }
}

// === KEYWORD CONSOLIDATION ===
let consolidationFactor = 0.5;
let consolidationLastResult = null;
let lastConsolidatedFile = null;

// Prüfe beim Laden, ob konsolidierte Dateien vorhanden sind
async function checkForConsolidatedFiles() {
  try {
    const filesResponse = await fetch(`${API_BASE}/api/list-files`);
    const files = await filesResponse.json();
    const consolidatedFiles = files.filter(f => f.startsWith('keywords-database-consolidated-')).sort().reverse();
    
    if (consolidatedFiles.length > 0) {
      // Zeige Aktivieren-Button wenn konsolidierte Dateien existieren
      const activateBtn = document.getElementById('consolidateActivateBtn');
      if (activateBtn) {
        activateBtn.style.display = 'inline-block';
        }
    }
  } catch (error) {
    }
}

function updateConsolidationFactor(value) {
  consolidationFactor = parseInt(value) / 100;
  document.getElementById('consolidationFactorValue').textContent = consolidationFactor.toFixed(2);
  
  // Update description
  const desc = document.getElementById('consolidationFactorDesc');
  if (consolidationFactor < 0.3) {
    desc.innerHTML = '<strong>Sehr streng (< 0.3):</strong> Nur fast identische Keywords werden konsolidiert (z.B. "karma" + "Karma" ? "Karma")';
  } else if (consolidationFactor < 0.7) {
    desc.innerHTML = '<strong>Mittel (0.3-0.7):</strong> Wortstämme werden konsolidiert (z.B. "karma", "karmagesetz", "karmisch" ? "Karma")';
  } else {
    desc.innerHTML = '<strong>Locker (> 0.7):</strong> Semantisch ähnliche Keywords werden zusammengeführt (z.B. "reinkarnation", "wiederverkörperung" ? "Reinkarnation")';
  }
  
  // Reset wenn Faktor geändert wurde
  consolidationLastResult = null;
  document.getElementById('consolidationPreview').style.display = 'none';
  document.getElementById('consolidateActivateBtn').style.display = 'none';
}

async function executeConsolidation() {
  const executeBtn = document.getElementById('consolidateExecuteBtn');
  const previewDiv = document.getElementById('consolidationPreview');
  const statusDiv = document.getElementById('consolidationStatus');
  
  executeBtn.disabled = true;
  executeBtn.textContent = 'Konsolidiere...';
  statusDiv.style.display = 'none';
  previewDiv.style.display = 'none';
  
  try {
    const response = await fetch(`${API_BASE}/api/consolidate-keywords-execute`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ factor: consolidationFactor })
    });
    
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    
    const data = await response.json();
    consolidationLastResult = data;
    
    // Speichere konsolidierte Datei für Aktivierung
    lastConsolidatedFile = data.consolidatedFile;
    
    // Zeige Ergebnis
    let resultHTML = `
      <div style="margin-bottom: 0.5rem;">
        <strong style="color: #5cb85c;">? Konsolidierung abgeschlossen!</strong><br>
        ${data.consolidatedCount.toLocaleString()} Keywords konsolidiert<br>
        <div style="margin-top: 0.5rem; font-size: 0.9em;">
          Backup: <code style="font-size: 0.85em;">${data.backupFile}</code><br>
          Konsolidiert: <code style="font-size: 0.85em;">${data.consolidatedFile}</code>
        </div>
      </div>
    `;
    
    previewDiv.innerHTML = resultHTML;
    previewDiv.style.display = 'block';
    
    // Zeige Activate-Button
    document.getElementById('consolidateActivateBtn').style.display = 'inline-block';
    
    // Reload keywords
    await loadKeywords();
    
  } catch (error) {
    console.error('[CONSOLIDATION] Fehler:', error);
    statusDiv.innerHTML = `<div style="color: #d9534f; font-size: 0.85em;">? Fehler: ${error.message}</div>`;
    statusDiv.style.display = 'block';
  } finally {
    executeBtn.disabled = false;
    executeBtn.textContent = 'Konsolidierung ausführen';
  }
}

async function activateConsolidation() {
  // Finde neueste konsolidierte Datei, falls keine in Variable gespeichert
  if (!lastConsolidatedFile) {
    try {
      const filesResponse = await fetch(`${API_BASE}/api/list-files`);
      const files = await filesResponse.json();
      const consolidatedFiles = files.filter(f => f.startsWith('keywords-database-consolidated-')).sort().reverse();
      
      if (consolidatedFiles.length === 0) {
        alert('Keine konsolidierte Datenbank gefunden. Bitte erst "Konsolidierung ausführen" klicken.');
        return;
      }
      
      lastConsolidatedFile = consolidatedFiles[0];
      } catch (error) {
      alert('Fehler beim Suchen der konsolidierten Datenbank: ' + error.message);
      return;
    }
  }
  
  if (!confirm(`Konsolidierte Datenbank aktivieren?\n\nDatei: ${lastConsolidatedFile}\n\n1. Aktuelle keywords-database.json wird gesichert\n2. Konsolidierte DB wird aktiviert\n3. Themen werden automatisch neu generiert\n\nMöchten Sie fortfahren?`)) {
    return;
  }
  
  const activateBtn = document.getElementById('consolidateActivateBtn');
  const statusDiv = document.getElementById('consolidationStatus');
  
  activateBtn.disabled = true;
  activateBtn.textContent = 'Aktiviere...';
  statusDiv.style.display = 'none';
  
  try {
    // Schritt 1: Aktiviere konsolidierte Datenbank
    const activateResponse = await fetch(`${API_BASE}/api/consolidate-keywords-activate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ consolidatedFile: lastConsolidatedFile })
    });
    
    if (!activateResponse.ok) {
      throw new Error(`HTTP ${activateResponse.status}`);
    }
    
    const activateData = await activateResponse.json();
    statusDiv.innerHTML = `<div style="color: #5cb85c; font-size: 0.85em;">? Konsolidierte DB aktiviert!<br>Original gesichert: ${activateData.preConsolidationFile}<br><br>Starte Themen-Generierung...</div>`;
    statusDiv.style.display = 'block';
    
    // Schritt 2: Generiere Themen neu
    await new Promise(resolve => setTimeout(resolve, 1000)); // Kurze Pause
    
    const themeCount = document.getElementById('timelineThemeCount')?.value || 30;
    await generateThemes(); // Rufe bestehende Funktion auf
    
    statusDiv.innerHTML = `<div style="color: #5cb85c; font-size: 0.85em;">? Konsolidierung abgeschlossen!<br>? Datenbank aktiviert<br>? Themen neu generiert<br><br>Bitte laden Sie die Seite neu (F5).</div>`;
    
    // Reset
    lastConsolidatedFile = null;
    consolidationLastResult = null;
    document.getElementById('consolidationPreview').style.display = 'none';
    activateBtn.style.display = 'none';
    
  } catch (error) {
    console.error('[CONSOLIDATION] Aktivierungs-Fehler:', error);
    statusDiv.innerHTML = `<div style="color: #d9534f; font-size: 0.85em;">? Fehler: ${error.message}</div>`;
    statusDiv.style.display = 'block';
  } finally {
    activateBtn.disabled = false;
    activateBtn.textContent = 'Aktivieren + Themen neu generieren';
  }
}

async function addNewKeyword() {
  const keywordInput = document.getElementById('newKeywordInput');
  const addButton = document.getElementById('addKeywordButton');
  const statusDiv = document.getElementById('addKeywordStatus');
  
  if (!keywordInput || !addButton || !statusDiv) {
    console.error('[ADD-KEYWORD] UI-Elemente nicht gefunden');
    return;
  }
  
  const keyword = keywordInput.value.trim();
  
  if (!keyword) {
    statusDiv.innerHTML = '';
    return;
  }
  
  // UI-Status aktualisieren
  addButton.disabled = true;
  addButton.innerHTML = '<em>Analysiere...</em>';
  statusDiv.innerHTML = '';
  
  try {
    const response = await fetch('http://localhost:3003/api/concepts-add', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ 
        keyword: keyword,
        overwrite: true // Überschreibe vorhandene Schlagwörter beim Neu-Generieren
      })
    });
    
    const result = await response.json();
    
    if (response.ok) {
      // Erfolg
      statusDiv.innerHTML = '';
      
      // Eingabefeld leeren
      keywordInput.value = '';
      
      // Schlagwort-Liste aktualisieren
      await loadKeywordsData();
      
      // Markiere das Schlagwort als neu generiert/ersetzt, wenn es bereits existiert hat
      if (result.keyword && result.keyword.keyword) {
        const keywordName = result.keyword.keyword;
        const existingKeyword = keywordsData.find(kw => kw.keyword === keywordName);
        if (existingKeyword) {
          // Schlagwort existiert bereits - markiere als ersetzt/neu generiert
          existingKeyword.replaced = true;
          existingKeyword.newlyGenerated = true;
          }
      }
      
      // Zeige das neue Schlagwort in der Liste
      displayKeywords();
      
      // Zeige beide Ergebnisse an:
      // 1. KI-Suchergebnis im Content Fenster (results)
      if (result.analysis) {
        const results = document.getElementById('results');
        if (results) {
          // Bereite Daten vor wie bei performKeywordThematicSearch
          const data = {
            query: result.keyword.keyword,
            content: result.analysis,
            sources: result.keyword.sources || [],
            fromCache: false,
            fromKeywordData: true
          };
          displayKeywordThematicResults(result.keyword.keyword, data);
        }
      }
      
      // 2. Themen_Übersicht im Main Viewer
      if (result.overview) {
        const viewer = document.getElementById('viewer');
        if (viewer) {
          renderConceptOverview(result.keyword.keyword, { 
            overview: result.overview,
            text: result.analysis || null
          });
        }
      }
      
    } else {
      // Fehler
      if (response.status === 409) {
        statusDiv.innerHTML = '';
      } else if (response.status === 404) {
        statusDiv.innerHTML = '';
      } else {
        statusDiv.innerHTML = '';
      }
      
      console.error('[ADD-KEYWORD] Fehler beim Hinzufügen:', result);
    }
    
  } catch (error) {
    statusDiv.innerHTML = '';
    console.error('[ADD-KEYWORD] Netzwerkfehler:', error);
  } finally {
    // UI-Status zurücksetzen
    addButton.disabled = false;
    addButton.textContent = 'Schlagwort hinzufügen';
  }
}

