window.handleDeleteKeywordInputKeypress = function(event) {
  if (event.key === 'Enter') {
    window.deleteKeyword();
  }
}

window.deleteKeyword = async function() {
  const keywordInput = document.getElementById('regenerateKeywordInput');
  const regenerateButton = document.getElementById('regenerateKeywordButton');
  const statusDiv = document.getElementById('regenerateKeywordStatus');
  
  if (!keywordInput || !regenerateButton || !statusDiv) {
    console.error('[DELETE-KEYWORD] UI-Elemente nicht gefunden');
    return;
  }
  
  const keyword = keywordInput.value.trim();
  
  if (!keyword) {
    statusDiv.innerHTML = '';
    return;
  }
  
  // UI-Status aktualisieren
  regenerateButton.disabled = true;
  regenerateButton.textContent = 'Lösche...';
  regenerateButton.style.fontStyle = 'italic';
  statusDiv.innerHTML = '';
  
  try {
    const apiBase = window.API_BASE || 'http://localhost:3003';
    const response = await fetch(`${apiBase}/api/concepts-delete`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ keyword })
    });
    
    let result;
    const contentType = response.headers.get('content-type') || '';
    if (contentType.includes('application/json')) {
      result = await response.json();
    } else {
      const text = await response.text();
      throw new Error(`Unerwartete Antwort (kein JSON): ${text.slice(0, 120)}`);
    }
    
    if (response.ok && result.success) {
      statusDiv.innerHTML = '';
      keywordInput.value = '';
      await loadKeywordsData();
      displayKeywords();
      } else {
      statusDiv.innerHTML = '';
      console.error('[DELETE-KEYWORD] Fehler beim Löschen:', result);
    }
    
  } catch (error) {
    statusDiv.innerHTML = '';
    console.error('[DELETE-KEYWORD] Netzwerkfehler:', error);
  } finally {
    // UI-Status zurücksetzen
    regenerateButton.disabled = false;
    regenerateButton.textContent = 'Schlagwort löschen';
    regenerateButton.style.fontStyle = 'normal';
  }
}

// Enter-Taste für Schlagwort-Eingabe
function handleKeywordInputKeypress(event) {
  if (event.key === 'Enter') {
    addNewKeyword();
  }
}

// Enter-Taste für Schlagwort löschen
function handleDeleteKeywordInputKeypress(event) {
  if (event.key === 'Enter') {
    deleteKeyword();
  }
}

// Enter-Taste für Schlagwort-Suche
function handleKeywordSearchKeypress(event) {
  if (event.key === 'Enter') {
    event.preventDefault();
    const input = event.target;
    const value = input.value.trim().toLowerCase();
    
    // Suche exaktes Schlagwort
    if (value.length > 0) {
      const exactMatch = keywordsData.find(k => 
        k.keyword.toLowerCase() === value
      );
      if (exactMatch) {
        // Zeige alle Schlagwörter und scrolle zum Treffer
        displayKeywords('Alle');
        setTimeout(() => scrollToKeyword(exactMatch.keyword), 100);
        return;
      }
    }
    
    displayKeywords(currentAlphabet);
  }
}

// Bei Eingabe: Filtere Liste und scrolle zu erstem Treffer wenn exakt vorhanden
function handleKeywordSearchInput(event) {
  displayKeywords(currentAlphabet);
  
  const input = event.target;
  const value = input.value.trim().toLowerCase();
  
  // Wenn exaktes Schlagwort existiert, scrolle dorthin
  if (value.length >= 2) {
    const exactMatch = keywordsData.find(k => 
      k.keyword.toLowerCase() === value
    );
    if (exactMatch) {
      setTimeout(() => scrollToKeyword(exactMatch.keyword), 100);
    }
  }
}

// Scrolle zum Schlagwort in der Liste
function scrollToKeyword(keyword) {
  const keywordEntries = document.querySelectorAll('.keyword-entry h4 a');
  for (const entry of keywordEntries) {
    if (entry.textContent.trim().toLowerCase() === keyword.toLowerCase()) {
      const container = entry.closest('.keyword-entry');
      if (container) {
        container.scrollIntoView({ behavior: 'auto', block: 'center' });
        // Kurzes Highlight
        container.style.transition = 'background-color 0.3s';
        container.style.backgroundColor = 'rgba(70, 120, 134, 0.2)';
        setTimeout(() => {
          container.style.backgroundColor = '';
        }, 1500);
      }
      break;
    }
  }
}

// Ctrl+Enter für Zitate-Textfeld

// Lade vollständige Vortragsdaten für Timeline (aus steiner-full-lectures-...json)
async function loadFullLecturesForTimeline() {
  // Wenn bereits geladen, überspringe
  if (Object.keys(fullLecturesData).length > 0) {
    return fullLecturesData;
  }
  
  try {
    const response = await fetch(`${API_BASE}/api/full-lectures`);
    if (!response.ok) {
      throw new Error(`API Fehler: ${response.status}`);
    }
    
    fullLecturesData = await response.json();
    return fullLecturesData;
    
  } catch (error) {
    console.error('[LECTURES] Fehler beim Laden:', error);
    fullLecturesData = {};
    return {};
  }
}

// Hilfsfunktion: Ermittelt die Reihenfolge der Absatz-Indices für einen Vortrag
// Gibt ein Array von Indices in der Reihenfolge zurück, wie sie im Text erscheinen
function getParagraphOrderForLecture(lectureId) {
  const lecture = fullLecturesData[lectureId];
  if (!lecture || !lecture.paragraphs || !Array.isArray(lecture.paragraphs)) {
    console.warn(`[PARAGRAPH_ORDER] Keine Absätze gefunden für ${lectureId}`);
    return [];
  }
  
  // Extrahiere alle Indices in der Reihenfolge wie sie im paragraphs-Array erscheinen
  const order = lecture.paragraphs
    .map(p => (p.index || '').replace(/^\^/, '')) // Entferne ^ prefix
    .filter(idx => idx); // Nur nicht-leere Indices
  
  return order;
}

// Hilfsfunktion: Lade ein Buch von der API (mit Caching)
async function loadBookForTimeline(bookId) {
  // Prüfe ob bereits geladen
  if (fullBooksData[bookId]) {
    return fullBooksData[bookId];
  }
  
  try {
    const response = await fetch(`${API_BASE}/api/book/${bookId}`);
    if (!response.ok) {
      console.warn(`[BOOK] Buch ${bookId} nicht gefunden`);
      return null;
    }
    
    const book = await response.json();
    
    // Speichere im Cache
    fullBooksData[bookId] = book;
    
    return book;
    
  } catch (error) {
    console.error(`[BOOK] Fehler beim Laden von ${bookId}:`, error);
    return null;
  }
}

// Hilfsfunktion: Ermittelt die Reihenfolge der Absatz-Indices für ein Buch
// Gibt ein Array von Indices in der Reihenfolge zurück, wie sie im Text erscheinen
function getParagraphOrderForBook(bookId) {
  const book = fullBooksData[bookId];
  if (!book || !book.paragraphs || !Array.isArray(book.paragraphs)) {
    return [];
  }
  
  // Extrahiere alle Indices in der Reihenfolge wie sie im paragraphs-Array erscheinen
  const order = book.paragraphs
    .map(p => (p.index || '').replace(/^\^/, '')) // Entferne ^ prefix
    .filter(idx => idx); // Nur nicht-leere Indices
  
  return order;
}

// Hilfsfunktion: Normalisiere Überschriften-Text (entferne eckige Klammern für Vergleich)
// Beispiel: "86 [Anthroposophie als Geisteswissenschaft]" -> "86 Anthroposophie als Geisteswissenschaft"
// Die eckigen Klammern werden nur für den Vergleich entfernt, nicht aus der Anzeige
function normalizeHeadingText(heading) {
  if (!heading) return heading;
  // Entferne eckige Klammern und ihren Inhalt, aber behalte den Text davor und danach
  // Ersetze "[...]" durch ein Leerzeichen, falls Text davor oder danach vorhanden ist
  return heading.replace(/\s*\[[^\]]*\]\s*/g, ' ').replace(/\s+/g, ' ').trim();
}

// Fallback-Funktion für Bücher: Finde Überschrift basierend auf String-Vergleich
// Diese Funktion wird verwendet, wenn die Absatzreihenfolge-Methode nicht funktioniert
function findBestHeadingForBookFallback(paragraphIndex, headings) {
  if (!paragraphIndex || !headings || headings.length === 0) {
    return null;
  }
  
  const cleanIndex = paragraphIndex.replace(/^\^/, '');
  
  // Versuche zuerst exakte Übereinstimmung
  const exactMatch = headings.find(h => {
    const hIndex = (h.id || h.index || '').replace(/^\^/, '');
    return hIndex === cleanIndex;
  });
  
  if (exactMatch) {
    return exactMatch.text;
  }
  
  // Versuche numerischen Vergleich (falls Index eine Zahl ist)
  const indexNum = parseInt(cleanIndex);
  if (!isNaN(indexNum)) {
    // Suche nach Überschriften mit numerischem Index, der kleiner oder gleich ist
    const numericHeadings = headings
      .map(h => {
        const hIndex = (h.id || h.index || '').replace(/^\^/, '');
        const hNum = parseInt(hIndex);
        return {
          ...h,
          numericIndex: !isNaN(hNum) ? hNum : -1,
          cleanIndex: hIndex
        };
      })
      .filter(h => h.numericIndex >= 0 && h.numericIndex <= indexNum)
      .sort((a, b) => b.numericIndex - a.numericIndex); // Sortiere absteigend
    
    if (numericHeadings.length > 0) {
      // Bevorzuge höhere Überschriften (h2, h3) über niedrigere (h4)
      const bestHeading = numericHeadings.find(h => h.level === 'h2') ||
                          numericHeadings.find(h => h.level === 'h3') ||
                          numericHeadings.find(h => h.level === 'h4') ||
                          numericHeadings[0];
      
      return bestHeading.text;
    }
  }
  
  // Versuche String-Vergleich (falls Index einen Teilstring enthält)
  const indexLower = cleanIndex.toLowerCase();
  const stringMatches = headings
    .map(h => {
      const hIndex = (h.id || h.index || '').replace(/^\^/, '').toLowerCase();
      // Prüfe ob der Index einen Teilstring des Überschriften-Index enthält oder umgekehrt
      const contains = hIndex.includes(indexLower) || indexLower.includes(hIndex);
      return {
        ...h,
        cleanIndex: hIndex,
        match: contains
      };
    })
    .filter(h => h.match);
  
  if (stringMatches.length > 0) {
    // Bevorzuge höhere Überschriften (h2, h3) über niedrigere (h4)
    const bestHeading = stringMatches.find(h => h.level === 'h2') ||
                        stringMatches.find(h => h.level === 'h3') ||
                        stringMatches.find(h => h.level === 'h4') ||
                        stringMatches[0];
    
    return bestHeading.text;
  }
  
  return null;
}

// Hilfsfunktion: Finde die beste Überschrift für einen Absatz-Index
// Verwendet die tatsächliche Absatzreihenfolge aus steiner-full-lectures-...json oder Büchern
// Unterstützt sowohl Vorträge als auch Bücher
async function findBestHeadingForIndex(paragraphIndex, headings, lectureId = null) {
  if (!paragraphIndex || !headings || headings.length === 0) {
    return null;
  }
  
  // Normalisiere den Index (entferne ^)
  const cleanIndex = paragraphIndex.replace(/^\^/, '');
  
  // Suche zuerst nach H4 mit genau diesem Index (Überschrift direkt am Absatz)
  const h4Match = headings.find(h => {
    const hIndex = (h.id || h.index || '').replace(/^\^/, '');
    return h.level === 'h4' && hIndex === cleanIndex;
  });
  
  if (h4Match) {
    return h4Match.text;
  }
  
  // Suche nach H3 mit genau diesem Index (Überschrift direkt am Absatz)
  const h3Match = headings.find(h => {
    const hIndex = (h.id || h.index || '').replace(/^\^/, '');
    return h.level === 'h3' && hIndex === cleanIndex;
  });
  
  if (h3Match) {
    return h3Match.text;
  }
  
  // NEUE METHODE: Verwende tatsächliche Absatzreihenfolge aus steiner-full-lectures oder Büchern
  if (lectureId) {
    // Prüfe ob es ein Buch oder ein Vortrag ist
    const isBook = isBookGANumber(lectureId);
    let paragraphOrder = [];
    
    if (isBook) {
      // Für Bücher: Lade Buch-Daten falls noch nicht geladen
      if (!fullBooksData[lectureId]) {
        await loadBookForTimeline(lectureId);
      }
      paragraphOrder = getParagraphOrderForBook(lectureId);
    } else {
      // Für Vorträge: Verwende vorhandene Daten
      if (fullLecturesData[lectureId]) {
        paragraphOrder = getParagraphOrderForLecture(lectureId);
      }
    }
    
    if (paragraphOrder.length === 0) {
      console.warn(`[HEADING] Keine Absatzreihenfolge für ${lectureId} - ${isBook ? 'Buch' : 'Vortrag'})`);
      return null;
    }
    
    // Finde Position des gesuchten Absatzes
    const targetPosition = paragraphOrder.indexOf(cleanIndex);
    
    if (targetPosition === -1) {
      console.warn(`[HEADING] Index ${cleanIndex} nicht gefunden in ${lectureId}`);
      return null;
    }
    
    // Erstelle Mapping: Index -> Position im Text
    const indexToPosition = new Map();
    paragraphOrder.forEach((idx, pos) => {
      indexToPosition.set(idx, pos);
    });
    
    // Erweitere Überschriften mit Position-Information
    // WICHTIG: Für Bücher sind die Überschriften-Indizes auf den ersten Paragraph NACH der Überschrift gesetzt
    // Das bedeutet: Überschrift mit Index X ist VOR dem Paragraph mit Index X
    // Wir suchen also nach Überschriften, deren Index-Position <= targetPosition ist
    // Beim Vergleich ignorieren wir eckige Klammern in den Überschriften-Texten
    const headingsWithPosition = headings
      .map(h => {
        const hIndex = (h.id || h.index || '').replace(/^\^/, '');
        const position = indexToPosition.get(hIndex);
        // Normalisiere Überschriften-Text (entferne eckige Klammern für Vergleich)
        const normalizedText = normalizeHeadingText(h.text || '');
        return {
          ...h,
          cleanIndex: hIndex,
          position: position !== undefined ? position : -1,
          normalizedText: normalizedText
        };
      })
      .filter(h => h.position >= 0) // Nur Überschriften mit gültiger Position
      .filter(h => h.position <= targetPosition); // Überschriften VOR oder AM target (da Index auf ersten Paragraph NACH Überschrift zeigt)
    
    if (headingsWithPosition.length === 0) {
      return null;
    }
    
    // Sortiere nach Position (absteigend), um die nächsthöhere Überschrift zu finden
    headingsWithPosition.sort((a, b) => b.position - a.position);
    
    // Nimm die erste (= nächstgelegene vor dem target, da absteigend sortiert)
    // Für Bücher: Bevorzuge höhere Überschriften (h3, h4) über niedrigere
    // Für Vorträge: Bevorzuge H4 über H3 (spezifischer)
    const bestPosition = headingsWithPosition[0].position;
    const candidatesAtBestPosition = headingsWithPosition.filter(h => h.position === bestPosition);
    
    let bestHeading;
    if (isBook) {
      // Für Bücher: Bevorzuge H3 oder H4 (nächsthöhere Überschrift)
      // Suche nach h3, dann h4, dann h2
      bestHeading = candidatesAtBestPosition.find(h => h.level === 'h3') ||
                    candidatesAtBestPosition.find(h => h.level === 'h4') ||
                    candidatesAtBestPosition.find(h => h.level === 'h2') ||
                    candidatesAtBestPosition[0];
    } else {
      // Für Vorträge: Bevorzuge H4 über H3 (spezifischer)
      bestHeading = candidatesAtBestPosition.find(h => h.level === 'h4') || candidatesAtBestPosition[0];
    }
    
    return bestHeading.text;
  }
  
  // FALLBACK: Alte Methode (wenn keine lectureId oder Daten nicht geladen)
  console.warn(`[HEADING] Fallback-Methode für ${cleanIndex} (keine Vortragsdaten verfügbar)`);
  
  const sortedHeadings = [...headings]
    .map(h => ({
      ...h,
      cleanIndex: (h.id || h.index || '').replace(/^\^/, '')
    }))
    .filter(h => h.cleanIndex)
    .sort((a, b) => {
      const numA = parseInt(a.cleanIndex);
      const numB = parseInt(b.cleanIndex);
      
      if (!isNaN(numA) && !isNaN(numB)) {
        if (numA !== numB) return numA - numB;
        if (a.level === 'h4' && b.level === 'h3') return 1;
        if (a.level === 'h3' && b.level === 'h4') return -1;
        return 0;
      }
      
      return a.cleanIndex.localeCompare(b.cleanIndex);
    });
  
  let lastHeading = null;
  for (const heading of sortedHeadings) {
    if (heading.cleanIndex <= cleanIndex) {
      lastHeading = heading;
    } else {
      break;
    }
  }
  
  if (lastHeading) {
    return lastHeading.text;
  }
  
  return null;
}

// Zeige Timeline für ein Schlagwort
async function showTimeline(keyword, clickedButton) {
  const splitView = document.getElementById('timelineSplitView');
  // Toggle-Logik: Wenn Timeline offen und gleiches Schlagwort -> schließen
  if (splitView && splitView.style.display !== 'none' && currentTimelineKeyword === keyword) {
    closeTimeline();
    return;
  }
  const timelinePanel = document.querySelector('.timeline-panel');
  const content = document.getElementById('timelineContentArea');
  const documentTitle = document.getElementById('timelineDocumentTitle');
  const viewerContent = document.getElementById('timelineViewerContent');
  
  if (!content) {
    console.error('[TIMELINE] timelineContentArea Element nicht gefunden!');
    return;
  }
  
  // Main Viewer leeren wenn Timeline geöffnet wird
  const viewer = document.getElementById('viewer');
  if (viewer) {
    viewer.innerHTML = '';
    }
  
  // Document Title auf Timeline setzen
  const mainDocumentTitle = document.getElementById('document-title');
  if (mainDocumentTitle) {
    mainDocumentTitle.textContent = 'Timeline';
    }
  
  // Alle anderen Timeline-Buttons auf inaktiv setzen (außer dem geklickten)
  document.querySelectorAll('.timeline-btn').forEach(btn => {
    if (btn !== clickedButton) {  // Nur andere Buttons deaktivieren
      btn.classList.remove('active');
      btn.innerHTML = '<i data-lucide="calendar"></i>';
      btn.title = 'Timeline anzeigen';
      }
  });
  
  // Aktuellen Button als aktiv markieren
  if (clickedButton) {
    clickedButton.classList.add('active');
    clickedButton.innerHTML = '<i data-lucide="calendar"></i>';
    clickedButton.title = 'Timeline verstecken';
    }
  
  // Nach dem Aktualisieren der Button-Inhalte Lucide-Icons neu initialisieren
  if (typeof initializeLucideIcons === 'function') {
    initializeLucideIcons();
  }
  
  // Timeline-Schlagwort speichern
  currentTimelineKeyword = keyword;
  
  // Timeline-Panel-Titel setzen
  const timelinePanelTitle = document.getElementById('timelinePanelTitle');
  if (timelinePanelTitle) {
    timelinePanelTitle.textContent = keyword;
  }
  
  // Timeline-Panel-Such-Button anzeigen
  const timelinePanelSearchBtn = document.getElementById('timelinePanelSearchBtn');
  if (timelinePanelSearchBtn) {
    timelinePanelSearchBtn.style.display = 'inline-block';
  }
  
  // Split-View anzeigen und Haupt-Viewer verstecken
  splitView.style.display = 'flex';
  document.getElementById('viewer').style.display = 'none';
  document.getElementById('document-title').style.display = 'none';
  document.getElementById('viewer-header').style.display = 'none';
  
  // Debug: Prüfe ob Timeline-Buttons noch sichtbar sind
  setTimeout(() => {
    const timelineButtons = document.querySelectorAll('.timeline-btn');
    timelineButtons.forEach((btn, index) => {
    });
  }, 100);
  
  // Header-Gap für Timeline-Ansicht entfernen
  const mainContainerEl = document.getElementById('main-container');
  const summaryPanelEl = document.getElementById('summary-panel');
  if (mainContainerEl) mainContainerEl.style.marginTop = '0px';
  if (summaryPanelEl) summaryPanelEl.style.top = '0px';
  
  // Timeline-Panel sichtbar machen
  if (timelinePanel) {
    timelinePanel.classList.remove('hidden');
  }
  
  // Keywords neu rendern NACH dem Öffnen der Timeline - ENTFERNT (verursacht Doppelklick-Problem)
  // setTimeout(() => {
  //   displayKeywords(currentAlphabet);
  // }, 100);
  
  // title.textContent = `Timeline: ${keyword}`; // Timeline-Titel entfernt
  content.innerHTML = '<div style="text-align: center; padding: 2rem;">Lade Timeline...</div>';
  documentTitle.textContent = 'Wählen Sie einen Vortrag aus der Timeline';
  viewerContent.innerHTML = '';
  
  try {
    // Lade Vortragsdaten
    await loadFullLecturesForTimeline();
    
    // NEUE METHODE: Verwende keywords-database.json direkt (wie Admin-Tab)
    // Mit Cache für schnelleres Laden bei wiederholten Abfragen
    const cacheKey = keyword.toLowerCase();
    let groupedLectures;
    
    // Prüfe ob Daten im Cache vorhanden sind
    if (timelineCache[cacheKey]) {
      console.log(`[TIMELINE] Cache-Treffer für "${keyword}"`);
      content.innerHTML = '<div style="text-align: center; padding: 2rem; font-style: italic;">Lade aus Cache...</div>';
      groupedLectures = timelineCache[cacheKey];
    } else {
      content.innerHTML = '<div style="text-align: center; padding: 2rem; font-style: italic;">Lade Timeline...</div>';
    
    try {
      // Lade Keywords-Database
      const keywordsDBResponse = await fetch(`${API_BASE}/api/keywords-database`);
      if (!keywordsDBResponse.ok) {
        throw new Error(`Keywords-DB Fehler: ${keywordsDBResponse.status}`);
      }
      
      const keywordsDB = await keywordsDBResponse.json();
      // Lade Summary-Database für Überschriften
      const summaryDBResponse = await fetch(`${API_BASE}/summary-database.json`);
      const summaryDB = summaryDBResponse.ok ? await summaryDBResponse.json() : {};
      
      // Sammle alle Vorträge mit diesem Keyword
      const timelineEntries = [];
      
      for (const lecture of Object.values(keywordsDB)) {
        // Filtere nur neue unified/manual Keywords
        const isNewGeneration = lecture.generationMethod && 
          (lecture.generationMethod.includes('unified-batch') || 
           lecture.generationMethod.includes('unified') ||
           lecture.generationMethod.includes('manual-add') ||
           lecture.generationMethod.includes('manual') ||
           lecture.generationMethod.includes('synced-from-summary-db'));
        
        if (isNewGeneration && lecture.keywords && Array.isArray(lecture.keywords)) {
          for (const kw of lecture.keywords) {
            if (kw.term.toLowerCase() === keyword.toLowerCase()) {
              // Finde die beste Überschrift für diesen Absatz-Index
              const bestHeading = await findBestHeadingForIndex(
                kw.index, 
                summaryDB[lecture.lectureId]?.headings || [],
                lecture.lectureId  // NEU: lectureId übergeben für korrekte Positionsermittlung
              );
              
              // Hole vollständige Vortrags-/Aufsatz-Daten
              const fullLectureData = fullLectures[lecture.lectureId];
              let entryDate = lecture.date;
              let entryYear = lecture.year;
              
              // Fallback: Versuche Jahr aus Titel zu extrahieren (z.B. "(1879)")
              if (!entryYear && fullLectureData?.title) {
                const titleYearMatch = fullLectureData.title.match(/\((\d{4})\)/);
                if (titleYearMatch) {
                  entryYear = parseInt(titleYearMatch[1]);
                  // Setze auch ein pseudo-Datum mit dem Jahr
                  if (!entryDate) {
                    entryDate = titleYearMatch[1];
                  }
                }
              }
              
              // Fallback: Versuche Jahr aus fullLectureData zu extrahieren
              if (!entryYear && fullLectureData) {
                if (fullLectureData.year) {
                  entryYear = fullLectureData.year;
                } else if (fullLectureData.date) {
                  const yearMatch = fullLectureData.date.match(/\b(18|19|20)\d{2}\b/);
                  if (yearMatch) entryYear = parseInt(yearMatch[0]);
                }
              }
              
              timelineEntries.push({
                lectureId: lecture.lectureId,
                date: entryDate,
                year: entryYear,
                title: fullLectureData?.title || lecture.lectureId,
                keyword: kw,
                heading: bestHeading || kw.heading || kw.term
              });
            }
          }
        }
      }
      
      if (timelineEntries.length === 0) {
        content.innerHTML = '<div class="timeline-no-results">Keine Vorträge mit diesem Schlagwort gefunden.</div>';
        return;
      }
      
      // Sortiere chronologisch
      timelineEntries.sort((a, b) => {
        if (a.year !== b.year) return a.year - b.year;
        return (a.date || '').localeCompare(b.date || '');
      });
      
      // Gruppiere Einträge nach Vortrag (lectureId)
      const groupedByLecture = {};
      timelineEntries.forEach(entry => {
        if (!groupedByLecture[entry.lectureId]) {
          groupedByLecture[entry.lectureId] = {
            lectureId: entry.lectureId,
            date: entry.date,
            year: entry.year,
            title: entry.title,
            entries: []
          };
        }
        groupedByLecture[entry.lectureId].entries.push(entry);
      });
      
      // Konvertiere zu Array und sortiere nach Datum
      groupedLectures = Object.values(groupedByLecture).sort((a, b) => {
        if (a.year !== b.year) return a.year - b.year;
        return (a.date || '').localeCompare(b.date || '');
      });
      
      // Speichere im Cache
      timelineCache[cacheKey] = groupedLectures;
      console.log(`[TIMELINE] Daten für "${keyword}" gecacht (${groupedLectures.length} Vorträge)`);
    } catch (loadError) {
      console.error('[TIMELINE] Fehler beim Laden:', loadError);
      content.innerHTML = '<div class="timeline-no-results">Fehler beim Laden der Timeline-Daten.</div>';
      return;
    }
    } // Ende des else-Blocks (keine gecachten Daten)
      
    // Berechne Anzahl einzigartiger Vorträge
    const uniqueLecturesCount = groupedLectures.length;
      
      // Generiere Timeline HTML
      let html = `
        <div class="timeline-analysis">
          <div class="timeline-stats">
            <span>Gefunden in ${uniqueLecturesCount} Vorträgen</span>
          </div>
        </div>
      `;
      
      // Hilfsfunktion: Markiere Schlagwort im Text
      function highlightKeyword(text, keyword) {
        if (!text || !keyword) return text;
        const escapedKeyword = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const regex = new RegExp(`(${escapedKeyword})`, 'gi');
        return text.replace(regex, '<mark>$1</mark>');
      }
      
      // Hilfsfunktion: HTML-Escape
      function escapeHtml(text) {
        if (!text) return '';
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
      }
      
      let lastYear = null;
      groupedLectures.forEach(lectureGroup => {
        const showYear = lastYear !== lectureGroup.year;
        lastYear = lectureGroup.year;
        
        // Entferne ^ vom Index falls vorhanden und erstelle Links für Überschriften
        const headingLinks = lectureGroup.entries.map(entry => {
          let cleanIndex = entry.keyword.index || '';
          if (cleanIndex.startsWith('^')) {
            cleanIndex = cleanIndex.substring(1);
          }
          
          // HTML-Escape der Überschrift (ohne Markierung)
          const headingText = entry.heading || '';
          const escapedHeadingText = String(headingText)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
          
          // Erstelle Link zur Überschrift ohne eckige Klammern und ohne Markierung
          const escapedKeyword = keyword.replace(/'/g, "\\'");
          const escapedLectureId = entry.lectureId.replace(/'/g, "\\'");
          const linkHtml = `<a href="#" onclick="showLectureInTimeline('${escapedLectureId}', '${cleanIndex}', '${escapedKeyword}'); return false;" class="timeline-heading-link">${escapedHeadingText}</a>`;
          
          return linkHtml;
        });
        
        html += `
          <div class="timeline-item enhanced">
            ${showYear ? `<div class="timeline-year">${lectureGroup.year}</div>` : '<div class="timeline-year-spacer"></div>'}
            <div class="timeline-content enhanced">
              <div class="timeline-lecture-number" style="margin-bottom: 0.3rem;">
                ${formatDateToDDMMYYYY(lectureGroup.date)}${formatLectureId(lectureGroup.lectureId)}
              </div>
              <div class="timeline-headings-list">
                ${headingLinks.join('')}
              </div>
            </div>
          </div>
        `;
      });
      
      content.innerHTML = html;
      // Timeline-Panel-Titel erweitern
      const timelinePanelTitle = document.getElementById('timelinePanelTitle');
      if (timelinePanelTitle) {
        timelinePanelTitle.textContent = `${keyword} - ${uniqueLecturesCount} Vorträge)`;
      }
      
  } catch (error) {
    console.error('[TIMELINE] Fehler:', error);
    content.innerHTML = '<div class="timeline-no-results">Fehler beim Laden der Timeline.</div>';
  }
}

// Hilfsfunktion: Mache Timeline-Zitate klickbar (verwendet gleiche Logik wie Themensuche)
function makeTimelineQuotesClickable(quoteText, lectureId) {
  // Verwende die gleiche Regex wie in der Themensuche
  const gaRefRegex = /\(GA(\d{3}[a-z]?)\/(\d+):([a-z0-9^]+)\)/gi;
  
  return quoteText.replace(gaRefRegex, (match, gaNum, lectureNum, index) => {
    const cleanIndex = index.replace(/^\^/, '');
    const refLectureId = `GA${gaNum} - ${lectureNum}`;
    const displayId = formatLectureId(refLectureId);
    return ` (<a href="#" onclick="showLectureInTimeline('${lectureId}', '${cleanIndex}'); return false;" class="timeline-quote-link" title="Zu diesem Absatz springen">${displayId}</a>)`;
  });
}

// Generiere erweiterte Timeline HTML mit KI-Analyse
function generateEnhancedTimelineHTML(timelineData) {
  let html = '';
  
  // Prüfe ob Timeline-Daten vorhanden sind
  if (!timelineData || !timelineData.timelineEntries || timelineData.timelineEntries.length === 0) {
    console.warn('[TIMELINE-HTML] Keine Timeline-Einträge gefunden');
    return '<div class="timeline-no-results">Keine Vorträge mit höchster Relevanz für dieses Schlagwort gefunden.</div>';
  }
  
  // Timeline-Statistiken anzeigen (ohne Analyse)
  html += `
    <div class="timeline-analysis">
      <div class="timeline-stats">
        <span>Gefunden in ${timelineData.relevantLectures || 0} von ${timelineData.totalLectures || 0} Vorträgen</span>
      </div>
    </div>
  `;
  
  // Sortiere Timeline-Einträge chronologisch
  const sortedEntries = timelineData.timelineEntries.sort((a, b) => {
    if (a.year !== b.year) return a.year - b.year;
    return a.date.localeCompare(b.date);
  });
  
  // Erstelle Timeline mit Jahr-Gruppierung
  let lastYear = null;
  sortedEntries.forEach((entry, index) => {
    // Zeige Jahr nur wenn es sich ändert
    const showYear = lastYear !== entry.year;
    lastYear = entry.year;
    
    html += `
      <div class="timeline-item enhanced">
        ${showYear ? `<div class="timeline-year">${entry.year}</div>` : '<div class="timeline-year-spacer"></div>'}
        <div class="timeline-content enhanced" onclick="showLectureInTimeline('${entry.lectureId}')">
          <div class="timeline-lecture-number">
            ${entry.date}
          </div>
          <div class="timeline-lecture-title">${entry.title} - ${entry.lectureId})</div>
          ${entry.keyQuotes && entry.keyQuotes.length > 0 ? `
            <div class="timeline-quotes">
              ${entry.keyQuotes.map(quote => makeTimelineQuotesClickable(quote, entry.lectureId)).join('; ')}
            </div>
          ` : ''}
          ${entry.thematicFocus ? `
            <div class="timeline-focus">
              <strong>${entry.thematicFocus}</strong>
            </div>
          ` : ''}
        </div>
      </div>
    `;
  });
  
  return html;
}

// Erstelle Timeline-Einträge aus GA-Referenzen
async function createTimelineEntries(gaReferences) {
  const entries = [];
  const seenLectures = new Set(); // Verhindert Duplikate
  
  for (const gaRef of gaReferences) {
    // Parse GA-Referenz (z.B. "GA306/5")
    const match = gaRef.match(/^(GA\d{3}[a-z]?)\/(\d+)$/);
    if (!match) continue;
    
    const [, gaNumber, lectureNumber] = match;
    const lectureId = `${gaNumber} - ${lectureNumber}`;
    
    // Prüfe ob dieser Vortrag bereits hinzugefügt wurde
    if (seenLectures.has(lectureId)) {
      continue; // Überspringe Duplikate
    }
    
    // Finde Vortrag in den Daten
    const lecture = fullLecturesData[lectureId];
    if (!lecture) continue;
    
    // Markiere als gesehen
    seenLectures.add(lectureId);
    
    // Extrahiere Jahr aus dem Datum
    let year = null;
    if (lecture.date) {
      const yearMatch = lecture.date.match(/^(\d{4})/);
      if (yearMatch) {
        year = parseInt(yearMatch[1]);
      }
    }
    
    // Fallback: Jahr aus GA-Nummer ableiten (ungefähr)
    if (!year) {
      const gaNum = parseInt(gaNumber.replace('GA', ''));
      if (gaNum >= 51 && gaNum <= 100) year = 1900 + Math.floor((gaNum - 51) * 0.5);
      else if (gaNum >= 101 && gaNum <= 200) year = 1910 + Math.floor((gaNum - 101) * 0.3);
      else if (gaNum >= 201 && gaNum <= 300) year = 1920 + Math.floor((gaNum - 201) * 0.2);
      else year = 1925; // Fallback
    }
    
    entries.push({
      year: year,
      lecture: lecture,
      gaRef: gaRef,
      lectureId: lectureId
    });
  }
  
  return entries;
}

// Gruppiere Timeline-Einträge nach Jahr
function groupTimelineByYear(entries) {
  const grouped = {};
  
  entries.forEach(entry => {
    if (!grouped[entry.year]) {
      grouped[entry.year] = [];
    }
    grouped[entry.year].push(entry);
  });
  
  // Sortiere Einträge innerhalb jedes Jahres nach Datum
  Object.keys(grouped).forEach(year => {
    grouped[year].sort((a, b) => {
      const dateA = parseDateForSorting(a.lecture.date);
      const dateB = parseDateForSorting(b.lecture.date);
      return dateA - dateB;
    });
  });
  
  return grouped;
}

// Hilfsfunktion: Parse Datum für Sortierung (deutsches Format TT.MM.JJJJ)
function parseDateForSorting(dateString) {
  if (!dateString) return new Date('1900-01-01'); // Fallback für fehlende Daten
  
  try {
    // Versuche verschiedene Datumsformate zu parsen
    let date;
    
    // Deutsches Format: TT.MM.JJJJ
    if (dateString.includes('.')) {
      const parts = dateString.split('.');
      if (parts.length === 3) {
        const day = parseInt(parts[0], 10);
        const month = parseInt(parts[1], 10) - 1; // JavaScript Monate sind 0-basiert
        const year = parseInt(parts[2], 10);
        date = new Date(year, month, day);
      }
    }
    // ISO Format: JJJJ-MM-TT
    else if (dateString.includes('-')) {
      date = new Date(dateString.split(' ')[0]);
    }
    // Andere Formate
    else {
      date = new Date(dateString);
    }
    
    // Prüfe ob Datum gültig ist
    if (isNaN(date.getTime())) {
      return new Date('1900-01-01'); // Fallback
    }
    
    return date;
  } catch (error) {
    console.warn('Fehler beim Parsen des Datums:', dateString, error);
    return new Date('1900-01-01'); // Fallback
  }
}

// Hilfsfunktion: Formatiere Datum zu TT.MM.JJJJ
function formatDateToDDMMYYYY(dateString) {
  if (!dateString) return 'Datum unbekannt';
  
  try {
    // Prüfe ob es nur ein Jahr ist (z.B. "1879" oder "(1879)")
    const yearOnlyMatch = dateString.toString().match(/^\(?(\d{4})\)?$/);
    if (yearOnlyMatch) {
      return yearOnlyMatch[1]; // Nur das Jahr zurückgeben
    }
    
    // Parse verschiedene Datumsformate
    let date;
    if (dateString.includes('-')) {
      // Format: YYYY-MM-DD oder YYYY-MM-DD HH:MM:SS
      date = new Date(dateString.split(' ')[0]);
    } else if (dateString.includes('.')) {
      // Format: DD.MM.YYYY
      const parts = dateString.split('.');
      if (parts.length === 3) {
        date = new Date(parts[2], parts[1] - 1, parts[0]);
      }
    } else {
      // Prüfe ob Jahr im String extrahiert werden kann (z.B. "um 1879")
      const yearInStringMatch = dateString.toString().match(/\b(18\d{2}|19\d{2}|20\d{2})\b/);
      if (yearInStringMatch) {
        return yearInStringMatch[1]; // Nur das Jahr zurückgeben
      }
      // Fallback: Versuche direkt zu parsen
      date = new Date(dateString);
    }
    
    if (isNaN(date.getTime())) {
      // Versuche Jahr aus dem String zu extrahieren
      const fallbackYearMatch = dateString.toString().match(/\b(18\d{2}|19\d{2}|20\d{2})\b/);
      if (fallbackYearMatch) {
        return fallbackYearMatch[1];
      }
      return 'Datum unbekannt';
    }
    
    // Formatiere zu DD.MM.YYYY
    const day = date.getDate().toString().padStart(2, '0');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const year = date.getFullYear();
    
    return `${day} - ${month} - ${year}`;
  } catch (error) {
    console.warn('Fehler beim Formatieren des Datums:', dateString, error);
    return 'Datum unbekannt';
  }
}

// Generiere Timeline HTML
function generateTimelineHTML(groupedByYear) {
  let html = '';
  
  const years = Object.keys(groupedByYear).sort((a, b) => parseInt(a) - parseInt(b));
  
  years.forEach(year => {
    const entries = groupedByYear[year];
    
    entries.forEach((entry, index) => {
      const lectureDate = formatDateToDDMMYYYY(entry.lecture.date);
      
      html += `
        <div class="timeline-item">
          ${index === 0 ? `<div class="timeline-year">${year}</div>` : '<div class="timeline-year-spacer"></div>'}
          <div class="timeline-content" onclick="showLectureInTimeline('${entry.lectureId}')">
            <div class="timeline-lecture-number">
              ${lectureDate}
            </div>
          </div>
        </div>
      `;
    });
  });
  
  return html;
}

// Zeige Vortrag im Timeline-Viewer
async function showLectureInTimeline(lectureId, targetIndex = null, keyword = null) {
  const documentTitle = document.getElementById('timelineDocumentTitle');
  const viewerContent = document.getElementById('timelineViewerContent');
  
  // Verwende die gleiche Funktion wie in der GA-Übersicht
  // Übergebe Keyword für Highlighting
  const keywords = keyword ? [keyword] : [];
  
  try {
    await showLecture(lectureId, targetIndex, keywords);
    
    // Lade Lecture-Daten für Titel-Setzung (wie im Index-Tab)
    let lecture = null;
    if (currentLectureData) {
      lecture = currentLectureData;
    } else {
      // Fallback: Lade Lecture-Daten direkt
      try {
        const parts = lectureId.split('/');
        const url = parts.length === 2 
                    ? `${API_BASE}/api/full-lecture/${encodeURIComponent(parts[0])}/${encodeURIComponent(parts[1])}`
                    : `${API_BASE}/api/full-lecture/${encodeURIComponent(lectureId)}`;
        const response = await fetch(url);
        if (response.ok) {
          const data = await response.json();
          lecture = data.lecture;
        }
      } catch (e) {
        console.warn('[TIMELINE] Konnte Lecture-Daten nicht laden:', e);
      }
    }
    
    // Kopiere den Inhalt vom Haupt-Viewer in den Timeline-Viewer
    const mainViewer = document.getElementById('viewer');
    const mainTitle = document.getElementById('document-title');
    
    if (mainViewer && mainTitle) {
      // Setze Titel genau wie im Index-Tab
      if (lecture && documentTitle) {
        // Bevorzuge fileName (vollständiger Titel), wie im Seitenpanel
        let fullTitle;
        if (lecture.fileName) {
          fullTitle = lecture.fileName;
        } else {
          // Baue den Titel-String zusammen
          let titleParts = [];
          
          // GA-Nummer
          const gaNumber = lectureId || lecture.ID || '';
          if (gaNumber) {
            titleParts.push(gaNumber);
          }
          
          // Titel
          const title = lecture.title || '';
          if (title) {
            titleParts.push(title);
          }
          
          // Ort und Datum
          let locationDateParts = [];
          if (lecture.location) {
            locationDateParts.push(lecture.location);
          }
          if (lecture.date) {
            locationDateParts.push(formatDate(lecture.date));
          }
          
          // Kombiniere alles: "GA100/8 - TITEL, Ort, Datum"
          fullTitle = '';
          if (titleParts.length > 0) {
            fullTitle = titleParts.join(' - ');
          }
          if (locationDateParts.length > 0) {
            fullTitle += (fullTitle ? ', ' : '') + locationDateParts.join(', ');
          }
          
          // Fallback wenn nichts gefunden wurde
          if (!fullTitle) {
            fullTitle = lectureId;
          }
        }
        
        // Setze Titel-Text und mache ihn klickbar (wie im Index-Tab)
        documentTitle.textContent = fullTitle;
        documentTitle.style.cursor = 'pointer';
        documentTitle.style.color = 'var(--link-color)';
        documentTitle.title = 'Klicken um zum Vortrag im Texte-Tab zu navigieren';
        
        // Kein Hover-Effekt mehr - Link soll bei Hover nicht verblassen
        
        // Füge onclick-Handler hinzu
        documentTitle.onclick = () => navigateToLectureInTexteTab(lectureId);
      } else {
        // Fallback: Kopiere Titel vom Haupt-Viewer
        documentTitle.innerHTML = mainTitle.innerHTML;
      }
      
      // Kopiere Inhalt
      viewerContent.innerHTML = mainViewer.innerHTML;
      
      // Scrolle nach oben (wird von showLecture überschrieben wenn targetIndex gesetzt ist)
      if (!targetIndex) {
        viewerContent.scrollTop = 0;
      } else {
        // Wenn targetIndex gesetzt ist, scrolle zum entsprechenden Absatz im Timeline-Viewer
        setTimeout(() => {
          const cleanIndex = targetIndex.replace(/^\^/, '');
          const paraElement = viewerContent.querySelector(`#para-${cleanIndex}`);
          if (paraElement) {
            paraElement.scrollIntoView({ behavior: 'auto', block: 'start' });
            // Highlighting hinzufügen
            paraElement.style.backgroundColor = '#fff3cd';
            paraElement.style.borderLeft = '4px solid #ffc107';
            setTimeout(() => {
              paraElement.style.backgroundColor = '';
              paraElement.style.borderLeft = '';
            }, 3000);
          }
        }, 200);
      }
      
      // TOC für Timeline-Viewer erstellen
      buildTableOfContents();
    }
    
    // Zeige die Timeline-Viewer-Buttons
    const originalBtn = document.getElementById('timelineViewerOriginalBtn');
    const summaryBtn = document.getElementById('timelineViewerSummaryBtn');
    
    if (originalBtn) originalBtn.style.display = 'inline-block';
    if (summaryBtn) summaryBtn.style.display = 'inline-block';
    
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden des Vortrags:', error);
    documentTitle.textContent = 'Fehler beim Laden des Vortrags';
    viewerContent.innerHTML = '<p>Der gewählte Vortrag konnte nicht geladen werden.</p>';
    
    // Verstecke die Timeline-Viewer-Buttons bei Fehlern
    const originalBtn = document.getElementById('timelineViewerOriginalBtn');
    const summaryBtn = document.getElementById('timelineViewerSummaryBtn');
    
    if (originalBtn) originalBtn.style.display = 'none';
    if (summaryBtn) summaryBtn.style.display = 'none';
  }
}

// Reset Timeline-Viewer-Buttons
function resetTimelineViewerButtons() {
  const originalBtn = document.getElementById('timelineViewerOriginalBtn');
  const summaryBtn = document.getElementById('timelineViewerSummaryBtn');
  
  if (originalBtn) originalBtn.style.display = 'none';
  if (summaryBtn) summaryBtn.style.display = 'none';
  
  // Reset Timeline-Dokument-Titel
  const documentTitle = document.getElementById('timelineDocumentTitle');
  if (documentTitle) {
    documentTitle.textContent = 'Wählen Sie einen Vortrag aus der Timeline';
  }
}

// Schließe Timeline Split-View
function closeTimeline() {
  const splitView = document.getElementById('timelineSplitView');
  splitView.style.display = 'none';
  
  // Haupt-Viewer wieder anzeigen
  document.getElementById('viewer').style.display = 'block';
  document.getElementById('document-title').style.display = 'block';
  document.getElementById('viewer-header').style.display = 'flex';
  
  // Reset Timeline-Viewer-Buttons
  resetTimelineViewerButtons();
  
  // TOC-Links für Haupt-Viewer wiederherstellen
  setTimeout(() => {
    buildTableOfContents();
  }, 100);
}

// Timeline Panel Resize Funktionalität
function initializeTimelineResize() {
  const resizeHandle = document.getElementById('timelineResizeHandle');
  const timelinePanel = document.querySelector('.timeline-panel');
  
  if (!resizeHandle || !timelinePanel) {
    return;
  }
  
  let isResizing = false;
  let startX = 0;
  let startWidth = 0;
  
  resizeHandle.addEventListener('mousedown', (e) => {
    isResizing = true;
    startX = e.clientX;
    startWidth = timelinePanel.offsetWidth;
    
    // Prevent text selection during resize
    e.preventDefault();
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'col-resize';
  });
  
  document.addEventListener('mousemove', (e) => {
    if (!isResizing) return;
    
    const deltaX = e.clientX - startX;
    const newWidth = startWidth + deltaX;
    
    // Set min and max width constraints
    const minWidth = 400;
    const maxWidth = window.innerWidth * 0.8;
    
    if (newWidth >= minWidth && newWidth <= maxWidth) {
      timelinePanel.style.width = newWidth + 'px';
    }
  });
  
  document.addEventListener('mouseup', () => {
    if (isResizing) {
      isResizing = false;
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
    }
  });
}

// Initialize Timeline Resize on page load
document.addEventListener('DOMContentLoaded', () => {
  initializeTimelineResize();
});

// Suche das Timeline-Schlagwort im aktuellen Vortragstext
function searchKeywordInCurrentLecture() {
  if (!currentTimelineKeyword) {
    return;
  }
  
  const viewerContent = document.getElementById('timelineViewerContent');
  if (!viewerContent || !viewerContent.innerHTML.trim()) {
    alert('Bitte wählen Sie zuerst einen Vortrag aus der Timeline aus.');
    return;
  }
  
  // Entferne vorherige Markierungen
  const paragraphs = viewerContent.querySelectorAll('.paragraph');
  paragraphs.forEach(para => {
    para.innerHTML = para.innerHTML.replace(/<mark[^>]*>([^<]*)<\/mark>/gi, '$1');
  });
  
  // Suche nach dem Schlagwort und markiere es
  let foundCount = 0;
  const keyword = currentTimelineKeyword.trim();
  const regex = new RegExp(`(${keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
  
  paragraphs.forEach(para => {
    const originalContent = para.innerHTML;
    const isDarkMode = document.body.classList.contains('dark-mode');
    const backgroundColor = isDarkMode ? 'rgba(70, 120, 134, 0.5)' : 'rgba(70, 120, 134, 0.3)';
    const textColor = isDarkMode ? 'var(--dark-text-color)' : 'inherit';
    const highlightedContent = originalContent.replace(regex, `<mark style="background-color: ${backgroundColor}; color: ${textColor}; padding: 2px 4px; border-radius: 2px;">$1</mark>`);
    
    if (highlightedContent !== originalContent) {
      para.innerHTML = highlightedContent;
      foundCount += (originalContent.match(regex) || []).length;
    }
  });
  
  if (foundCount > 0) {
    // Scrolle zum ersten gefundenen Element
    const firstMark = viewerContent.querySelector('mark');
    if (firstMark) {
      firstMark.scrollIntoView({ behavior: 'auto', block: 'center' });
    }
    
    // Zeige Erfolgsmeldung
    const button = document.querySelector('.keyword-search-btn');
    if (button) {
      const originalText = button.innerHTML;
      button.innerHTML = `${foundCount}`;
      button.style.backgroundColor = 'var(--accent-color)';
      button.style.color = 'white';
      
      // Nach 3 Sekunden zurücksetzen
      setTimeout(() => {
        button.innerHTML = originalText;
        button.style.backgroundColor = '';
        button.style.color = '';
      }, 3000);
    }
    
    // Zeige Erfolgsmeldung auch im Timeline-Panel-Button
    const timelineButton = document.getElementById('timelinePanelSearchBtn');
    if (timelineButton) {
      const originalText = timelineButton.innerHTML;
      timelineButton.innerHTML = `${foundCount}`;
      timelineButton.style.backgroundColor = 'var(--accent-color)';
      timelineButton.style.color = 'white';
      
      // Nach 3 Sekunden zurücksetzen
      setTimeout(() => {
        timelineButton.innerHTML = '<i data-lucide="text-search"></i>';
        timelineButton.style.backgroundColor = '';
        timelineButton.style.color = '';
        initializeLucideIcons(); // Icons nach Content-Update neu initialisieren
      }, 3000);
    }
  } else {
    alert(`Das Schlagwort "${currentTimelineKeyword}" wurde im aktuellen Vortragstext nicht gefunden.`);
  }
}

// Globale Funktion zum Schließen der Timeline
function hideTimelineIfOpen() {
  const splitView = document.getElementById('timelineSplitView');
  if (splitView && splitView.style.display !== 'none') {
    closeTimeline();
  }
}


// Hilfsfunktion: Formatiere Datum
function formatDate(dateStr) {
  if (!dateStr) return '';
  
  try {
    // Prüfe ob es nur ein Jahr ist (z.B. "1879" oder "(1879)")
    const yearOnlyMatch = dateStr.toString().match(/^\(?(\d{4})\)?$/);
    if (yearOnlyMatch) {
      return yearOnlyMatch[1]; // Nur das Jahr zurückgeben
    }
    
    // Prüfe ob Jahr im String extrahiert werden kann (z.B. "um 1879" oder "(ca. 1879)")
    const yearInStringMatch = dateStr.toString().match(/\b(18\d{2}|19\d{2}|20\d{2})\b/);
    if (yearInStringMatch && !dateStr.includes('-') && !dateStr.includes('.')) {
      return yearInStringMatch[1]; // Nur das Jahr zurückgeben
    }
    
    const date = new Date(dateStr);
    
    // Prüfe ob Datum gültig ist
    if (isNaN(date.getTime())) {
      // Versuche Jahr aus dem String zu extrahieren
      const fallbackYearMatch = dateStr.toString().match(/\b(18\d{2}|19\d{2}|20\d{2})\b/);
      if (fallbackYearMatch) {
        return fallbackYearMatch[1];
      }
      return dateStr; // Original zurückgeben statt "Invalid Date"
    }
    
    return date.toLocaleDateString('de-DE', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  } catch (error) {
    return dateStr;
  }
}

