// Funktion zum Speichern von markierten fehlerhaften Wörtern
async function saveMarkedWord(word, gaTitle) {
  try {
    const response = await fetch(`${API_BASE}/api/save-marked-word`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        word: word,
        gaTitle: gaTitle,
        timestamp: new Date().toISOString()
      })
    });
    
    if (!response.ok) {
      const errorText = await response.text();
      console.error('[MARKED-WORD] Server Error:', errorText);
      throw new Error(`Server Error (${response.status}): ${errorText}`);
    }
    
    const result = await response.json();
    // Kurze visuelle Bestätigung
    showTemporaryMessage(`Wort "${word}" gespeichert (${result.totalEntries} Einträge)`);
    
    return result;
  } catch (error) {
    console.error('[MARKED-WORD] Fehler:', error);
    alert(`Fehler beim Speichern:\n${error.message}\n\nBitte prüfen Sie die Browser-Konsole für Details.`);
  }
}

// Event-Listener für Rechtsklick im Viewer und Summary-Panel (für Textmarkierung und Schreibfehlerkorrektur)
// DEAKTIVIERT - Wird durch Members Context Menu ersetzt
// Nur noch bei Strg+Shift+Rechtsklick aktiv (für Fehlerkorrektur)
document.addEventListener('DOMContentLoaded', function() {
  const viewer = document.getElementById('viewer');
  const summaryPanel = document.getElementById('summary-panel');
  
  // Gemeinsame Funktion für Schreibfehler-Markierung
  function handleTypoMarking(e) {
    // Hole markierten Text
    const selection = window.getSelection();
    const selectedText = selection.toString().trim();
    
    if (!selectedText || selectedText.length === 0) {
      return;
    }
    
    // Hole aktuellen Vortragstitel
    const documentTitle = document.getElementById('document-title');
    const gaTitle = documentTitle ? documentTitle.textContent : 'Unbekannt';
    
    // Zeige Bestätigungsdialog
    const confirmed = confirm(`Wort "${selectedText}" als fehlerhaft markieren?\n\nVortrag: ${gaTitle}`);
    
    if (confirmed) {
      saveMarkedWord(selectedText, gaTitle);
    }
  }
  
  // Funktion zum Hinzufügen der Event-Listener zu einem Element
  function addTypoMarkingListeners(element) {
    if (!element) return;
    
    // Rechtsklick-Handler: Nur bei Strg+Shift+Rechtsklick
    element.addEventListener('contextmenu', function(e) {
      const selection = window.getSelection();
      const selectedText = selection.toString().trim();
      
      // NUR bei Strg+Shift+Rechtsklick (für Fehlerkorrektur)
      // Normaler Rechtsklick wird vom Members Context Menu behandelt
      if (selectedText && selectedText.length > 0 && e.ctrlKey && e.shiftKey) {
        e.preventDefault(); // Verhindere Standard-Kontextmenü
        handleTypoMarking(e);
      }
    });
    
    // Klick-Handler: Bei Alt+Klick (linke Maustaste) für Rechtschreibfehler
    element.addEventListener('click', function(e) {
      // Nur wenn Alt-Taste gedrückt ist (für Fehlerkorrektur)
      if (e.altKey && !e.ctrlKey && !e.shiftKey && !e.metaKey) {
        // Prüfe ob geklicktes Element ein Link ist - dann nicht blockieren
        const target = e.target;
        const isLink = target.tagName === 'A' || target.closest('a');
        
        if (isLink) {
          return; // Link normal funktionieren lassen
        }
        
        const selection = window.getSelection();
        const selectedText = selection.toString().trim();
        
        // Nur wenn Text markiert ist
        if (selectedText && selectedText.length > 0) {
          e.preventDefault();
          e.stopPropagation();
          handleTypoMarking(e);
        }
      }
    });
  }
  
  // Event-Listener für Viewer (linkes Hauptpanel)
  addTypoMarkingListeners(viewer);
  
  // Event-Listener für Summary-Panel (rechtes Panel)
  addTypoMarkingListeners(summaryPanel);
});

// ============================================
// Auto-Scroll zu Absatz bei URL-Parameter &index=...
// Verwendet die gleiche Struktur wie Timeline-Links
// ============================================
function scrollToParagraphFromURL() {
  // Prüfe URL-Parameter (wie Timeline: ?ga=GA051&index=1a)
  const urlParams = new URLSearchParams(window.location.search);
  const targetIndex = urlParams.get('index');
  
  if (!targetIndex) return;
  
  // Funktion zum Finden und Scrollen (verwendet gleiche Logik wie scrollToIndexInViewer)
  function findAndScroll() {
    // Suche Element mit ID "para-{index}" (z.B. "para-1a", "para-42")
    const targetElement = document.getElementById(`para-${targetIndex}`);
    
    if (targetElement) {
      // Verwende die gleiche Scroll-Logik wie scrollToIndexInViewer
      const mainContainer = document.getElementById('main');
      if (mainContainer) {
        const header = document.getElementById('viewer-header');
        const headerHeight = header ? header.offsetHeight + 5 : 5;
        
        const mainRect = mainContainer.getBoundingClientRect();
        const paraRect = targetElement.getBoundingClientRect();
        const relativeTop = paraRect.top - mainRect.top + mainContainer.scrollTop - headerHeight;
        
        mainContainer.scrollTop = Math.max(0, relativeTop);
      } else {
        // Fallback: Standard scrollIntoView
        targetElement.scrollIntoView({ behavior: 'auto', block: 'center' });
      }
      
      // Highlighting (wie in scrollToIndexInViewer)
      targetElement.style.transition = 'background-color 0.5s ease, box-shadow 0.5s ease';
      targetElement.style.backgroundColor = '#fff3cd';
      targetElement.style.boxShadow = '0 0 0 0.4rem rgba(255, 193, 7, 0.3)';
      
      setTimeout(() => {
        targetElement.style.backgroundColor = '';
        targetElement.style.boxShadow = '';
        setTimeout(() => {
          targetElement.style.transition = '';
        }, 500);
      }, 2500);
      
      return true;
    } else {
      console.warn('[PARAGRAPH-SCROLL] Element nicht gefunden: para-' + targetIndex);
      return false;
    }
  }
  
  // Versuche mehrmals zu scrollen (falls Content noch lädt)
  if (!findAndScroll()) {
    setTimeout(findAndScroll, 300);
    setTimeout(findAndScroll, 800);
    setTimeout(findAndScroll, 1500);
    setTimeout(findAndScroll, 2500);
  }
}

// Beim Laden ausführen
window.addEventListener('load', scrollToParagraphFromURL);

// Verarbeite URL-Parameter beim Laden (?ga= und ?index=)
window.addEventListener('load', function() {
  const urlParams = new URLSearchParams(window.location.search);
  const gaParam = urlParams.get('ga');
  const indexParam = urlParams.get('index');
  
  if (gaParam) {
    // Wechsle zum Texte-Tab falls nötig
    const texteTab = document.getElementById('texte-tab');
    if (texteTab && !texteTab.classList.contains('active')) {
      if (typeof switchTab === 'function') {
        switchTab('texte');
      }
    }
    
    // Warte kurz, dann öffne den Vortrag
    setTimeout(() => {
      if (typeof showLecture === 'function') {
        showLecture(gaParam, indexParam || null, []);
      }
    }, 300);
  }
});

// Bei DOMContentLoaded (früher als load)
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    setTimeout(scrollToParagraphFromURL, 100);
  });
} else {
  // Falls schon geladen
  setTimeout(scrollToParagraphFromURL, 100);
}

// ---- extracted script block ----
// Quellenangabe beim Kopieren von Text anhängen
// Funktioniert in allen Tabs: Texte, Suche, Themen, Abfrage, Index
// Format: (Titel, GA XXX, Verlagsort Jahr, S. XX)
document.addEventListener('DOMContentLoaded', function() {
  // Bibliographische Daten vorladen, damit sie beim Kopieren sofort verfügbar sind
  if (typeof window.loadGABibliographyData === 'function') {
    window.loadGABibliographyData();
  }
  
  // Relevante Container-IDs, in denen Text mit Quellenangabe kopiert werden soll
  const containerIds = ['viewer', 'results', 'summary-panel'];
  
  document.addEventListener('copy', function(e) {
    try {
      const selection = window.getSelection();
    if (!selection.rangeCount) return;
    
    const selectedText = selection.toString().trim();
    if (!selectedText || selectedText.length < 3) return;
    
    const commonAncestor = selection.getRangeAt(0).commonAncestorContainer;
    
    // === ÜBERSCHRIFTEN ALS LINKS KOPIEREN ===
    // Prüfe ob die Selektion eine Überschrift ist (Dokumenttitel oder Abschnitts-Überschrift)
    const ancestorEl = commonAncestor.nodeType === 1 ? commonAncestor : commonAncestor.parentElement;
    if (ancestorEl) {
      const mainEl = document.getElementById('main');
      const viewerEl = document.getElementById('viewer');
      
      // 1. Dokumenttitel (GA-Titel im viewer-header)
      const docTitle = document.getElementById('document-title');
      if (docTitle && docTitle.contains(commonAncestor)) {
        const lectureId = window.currentOpenLectureId || null;
        if (lectureId) {
          const linkUrl = `https://rudolf-steiner-online.de/app.html#texte&lecture=${encodeURIComponent(lectureId)}`;
          e.preventDefault();
          e.clipboardData.setData('text/plain', selectedText + '\n' + linkUrl);
          const escapedText = selectedText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
          const escapedUrl = linkUrl.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
          e.clipboardData.setData('text/html', `<a href="${escapedUrl}" style="color: #467886; text-decoration: none; font-weight: bold;">${escapedText}</a>`);
          console.log('[COPY] Dokumenttitel als Link kopiert:', selectedText, linkUrl);
          return; // Fertig - keine Quellenangabe anhängen
        }
      }
      
      // 2. Abschnitts-Überschrift erkennen:
      //    a) Direkt im Viewer (h2/h3/h4 mit data-heading-index oder data-index)
      //    b) Im Side Panel TOC oder linkem Panel (Text ? Viewer-Überschrift zuordnen)
      const summaryPanelEl = document.getElementById('summary-panel');
      const resultsEl = document.getElementById('results');
      
      // Prüfe ob Selektion in einer Überschrift liegt (Viewer, Side Panel, results)
      let headingIndex = null;
      let headingLectureId = null;
      
      // a) Element mit data-heading-index oder data-index direkt gefunden
      const headingEl = ancestorEl.closest('[data-heading-index], h2[data-index], h3[data-index], h4[data-index]');
      if (headingEl) {
        headingIndex = headingEl.getAttribute('data-heading-index') || headingEl.getAttribute('data-index');
        headingLectureId = headingEl.getAttribute('data-lecture-id');
      }
      
      // b) Fallback: Selektion ist im TOC (summary-panel) oder results-Panel
      //    ? Suche die passende Überschrift im Viewer anhand des Textes
      if (!headingIndex) {
        const isInTOC = (summaryPanelEl && summaryPanelEl.contains(commonAncestor)) ||
                        (resultsEl && resultsEl.contains(commonAncestor));
        if (isInTOC && viewerEl) {
          // Prüfe ob der selektierte Text eine Überschrift im Viewer ist
          const normalizedSelected = selectedText.trim().toLowerCase();
          const viewerHeadings = viewerEl.querySelectorAll('h2[data-heading-index], h3[data-heading-index], h4[data-heading-index], h2[data-index], h3[data-index], h4[data-index]');
          for (const vh of viewerHeadings) {
            const vhText = vh.textContent.trim().toLowerCase();
            if (vhText === normalizedSelected || vhText.includes(normalizedSelected) || normalizedSelected.includes(vhText)) {
              headingIndex = vh.getAttribute('data-heading-index') || vh.getAttribute('data-index');
              if (headingIndex) {
                console.log('[COPY] TOC-Text im Viewer gefunden:', vh.textContent.trim(), '? Index:', headingIndex);
                break;
              }
            }
          }
        }
      }
      
      // Wenn ein Heading-Index gefunden wurde ? als Link kopieren
      if (headingIndex) {
        const cleanIndex = headingIndex.replace(/^\^/, '');
        const lectureId = headingLectureId || window.currentOpenLectureId || null;
        if (lectureId) {
          const linkUrl = `https://rudolf-steiner-online.de/app.html#texte&lecture=${encodeURIComponent(lectureId)}&p=${encodeURIComponent(cleanIndex)}`;
          e.preventDefault();
          e.clipboardData.setData('text/plain', selectedText + '\n' + linkUrl);
          const escapedText = selectedText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
          const escapedUrl = linkUrl.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
          e.clipboardData.setData('text/html', `<a href="${escapedUrl}" style="color: #467886; text-decoration: none; font-weight: bold;">${escapedText}</a>`);
          console.log('[COPY] Abschnitts-Überschrift als Link kopiert:', selectedText, linkUrl);
          return; // Fertig - keine Quellenangabe anhängen
        }
      }
    }
    
    // === NORMALER TEXT MIT QUELLENANGABE ===
    // Prüfe Wortanzahl: Bei <= 10 Wörtern keine Quellenangabe hinzufügen
    const wordCount = selectedText.split(/\s+/).filter(word => word.length > 0).length;
    
    if (selectedText.length < 10 || wordCount <= 10) {
      console.log(`[COPY] Kurzer Text (${wordCount} Wörter) - keine Quellenangabe`);
      return;
    }
    
    // Prüfe ob die Selektion in einem relevanten Container liegt
    let container = null;
    for (const id of containerIds) {
      const el = document.getElementById(id);
      if (el && el.contains(commonAncestor)) {
        container = el;
        break;
      }
    }
    if (!container) return;
    
    // GA-Nummer ermitteln: primär currentGANumber, alternativ aus dem DOM extrahieren
    let gaNumber = null;
    
    // 1. Verwende currentGANumber (wird beim Laden eines Vortrags/Buchs gesetzt)
    if (typeof currentGANumber !== 'undefined' && currentGANumber) {
      gaNumber = currentGANumber;
    }
    
    // 2. Fallback: GA-Nummer aus dem nächsten Ergebnis-Element extrahieren
    //    (z.B. in Suchergebnissen oder Timeline, wo jedes Ergebnis eine eigene GA hat)
    if (!gaNumber) {
      const nearestLink = commonAncestor.nodeType === 1 
        ? commonAncestor.querySelector('a[onclick*="showLecture"]') 
        : null;
      const parentWithGA = commonAncestor.nodeType === 1 
        ? commonAncestor 
        : commonAncestor.parentElement;
      if (parentWithGA) {
        // Suche nach GA-Nummer in onclick-Attributen oder data-Attributen
        const gaEl = parentWithGA.closest('[onclick*="GA"]') || 
                     parentWithGA.querySelector('[onclick*="GA"]');
        if (gaEl) {
          const onclickMatch = gaEl.getAttribute('onclick')?.match(/(GA\d{1,3}[a-z]?)/i);
          if (onclickMatch) gaNumber = onclickMatch[1];
        }
      }
      // Fallback: GA-Nummer aus Dokumenttitel extrahieren
      if (!gaNumber) {
        const docTitle = document.getElementById('document-title');
        if (docTitle) {
          const titleMatch = docTitle.textContent.match(/(GA\s*\d{1,3}[a-z]?)/i);
          if (titleMatch) gaNumber = titleMatch[1].replace(/\s+/g, '');
        }
      }
    }
    
    if (!gaNumber) return;
    
    // Verwende gecachte bibliographische Daten (synchron, da copy-Event synchron sein muss)
    // gaInfo kann null sein (z.B. wenn GA in der Bibliographie fehlt) - dann Fallback-Quellenangabe
    const hasBibData = typeof window.gaBibliographyData !== 'undefined' && window.gaBibliographyData;
    const normalizedGA = normalizeGANumber(gaNumber);
    const gaInfo = hasBibData ? (window.gaBibliographyData[normalizedGA] || null) : null;
    
    // Finde die nächste Seitenzahl VOR einem DOM-Knoten (rückwärts durch DOM laufen)
    function findNearestPageBefore(node) {
      let current = node;
      while (current && current !== container) {
        let sibling = current.previousSibling;
        while (sibling) {
          if (sibling.nodeType === 1) { // Element-Knoten
            // Direkt ein Seitenmarker?
            if (sibling.classList && sibling.classList.contains('page-break-container')) {
              const numEl = sibling.querySelector('.page-break-num');
              if (numEl) return parseInt(numEl.textContent.trim());
            }
            // Seitenmarker in Kindelementen suchen (letzten nehmen)
            const pageBreaks = sibling.querySelectorAll('.page-break-container .page-break-num');
            if (pageBreaks.length > 0) {
              return parseInt(pageBreaks[pageBreaks.length - 1].textContent.trim());
            }
          }
          sibling = sibling.previousSibling;
        }
        current = current.parentNode;
      }
      return null;
    }
    
    // Seitenzahlen am Anfang und Ende der Selektion ermitteln
    let startPage = null;
    let endPage = null;
    
    const range = selection.getRangeAt(0);
    startPage = findNearestPageBefore(range.startContainer);
    endPage = findNearestPageBefore(range.endContainer);
    
    // Seitenzahlen sortieren (falls nötig)
    if (startPage && endPage && startPage > endPage) {
      const temp = startPage;
      startPage = endPage;
      endPage = temp;
    }
    
    // Quellenangabe erstellen
    // GA-Nummer ohne führende Nullen (z.B. "GA004" -> "GA 4", "GA070a" -> "GA 70a")
    const gaMatch = normalizedGA.match(/^GA(\d+)(.*)$/i);
    const gaNum = gaMatch ? parseInt(gaMatch[1]) : normalizedGA.replace(/^GA/i, '');
    const gaSuffix = gaMatch ? gaMatch[2] : '';
    const gaLabel = `GA ${gaNum}${gaSuffix}`;
    
    // Titel aus Bibliographie oder Fallback aus dem Dokumenttitel extrahieren
    let title = '';
    let place = '';
    let year = '';
    
    if (gaInfo) {
      title = gaInfo.title || '';
      place = gaInfo.place || '';
      year = gaInfo.year || '';
    } else {
      // Fallback: Titel aus dem Dokumenttitel extrahieren (wenn GA nicht in Bibliographie)
      const docTitleEl = document.getElementById('document-title');
      if (docTitleEl) {
        const docTitleText = docTitleEl.textContent.trim();
        // Entferne GA-Nummer und Klammern am Anfang: "GA190 - Titel..." ? "Titel..."
        const titleMatch = docTitleText.match(/^(?:GA\s*\d+[a-z]?\s*[-–]\s*)?(.+?)(?:\s*\(\d{4}\)\s*)?$/i);
        title = titleMatch ? titleMatch[1].trim() : docTitleText;
      }
    }
    
    let citation = '';
    if (title) {
      citation = `(${title} - ${gaLabel}`;
    } else {
      citation = `(Rudolf Steiner, ${gaLabel}`;
    }
    if (place && year) {
      citation += `, ${place} ${year}`;
    } else if (place) {
      citation += `, ${place}`;
    } else if (year) {
      citation += `, ${year}`;
    }
    
    // Seitenangabe hinzufügen
    if (startPage && !isNaN(startPage)) {
      if (endPage && !isNaN(endPage) && endPage !== startPage) {
        citation += `, S.\u00A0${startPage}\u2013${endPage}`;
      } else {
        citation += `, S.\u00A0${startPage}`;
      }
    }
    
    citation += ')';
    
    // Link-URL für die Quellenangabe erstellen
    let linkUrl = '';
    
    // Lecture-ID ermitteln: primär currentOpenLectureId, alternativ aus DOM
    let lectureIdForLink = window.currentOpenLectureId || null;
    if (!lectureIdForLink) {
      // Fallback: Suche data-lecture-id im DOM (z.B. in Suchergebnissen)
      let linkEl = commonAncestor.nodeType === 1 ? commonAncestor : commonAncestor.parentElement;
      while (linkEl && linkEl !== container) {
        if (linkEl.getAttribute && linkEl.getAttribute('data-lecture-id')) {
          lectureIdForLink = linkEl.getAttribute('data-lecture-id');
          break;
        }
        linkEl = linkEl.parentElement;
      }
    }
    
    if (lectureIdForLink) {
      // Absatz-Index am Anfang der Selektion ermitteln
      let paragraphIndex = null;
      let paraEl = range.startContainer.nodeType === 1 ? range.startContainer : range.startContainer.parentElement;
      while (paraEl && paraEl !== container) {
        const pIdx = paraEl.getAttribute && (paraEl.getAttribute('data-paragraph-index') || paraEl.getAttribute('data-chunk-index'));
        if (pIdx) {
          paragraphIndex = pIdx.replace(/^\^/, '');
          break;
        }
        paraEl = paraEl.parentElement;
      }
      
      // Absatz-Index am Ende der Selektion ermitteln (für Bereichs-Markierung)
      let paragraphEndIndex = null;
      let endEl = range.endContainer.nodeType === 1 ? range.endContainer : range.endContainer.parentElement;
      while (endEl && endEl !== container) {
        const pIdx = endEl.getAttribute && (endEl.getAttribute('data-paragraph-index') || endEl.getAttribute('data-chunk-index'));
        if (pIdx) {
          paragraphEndIndex = pIdx.replace(/^\^/, '');
          break;
        }
        endEl = endEl.parentElement;
      }
      
      linkUrl = `https://rudolf-steiner-online.de/app.html#texte&lecture=${encodeURIComponent(lectureIdForLink)}`;
      if (paragraphIndex) {
        linkUrl += `&p=${encodeURIComponent(paragraphIndex)}`;
        // Nur pEnd anfügen wenn sich der End-Absatz vom Start-Absatz unterscheidet
        if (paragraphEndIndex && paragraphEndIndex !== paragraphIndex) {
          linkUrl += `&pEnd=${encodeURIComponent(paragraphEndIndex)}`;
        }
      }
    }
    
    // Clipboard modifizieren
    e.preventDefault();
    const plainText = linkUrl 
      ? selectedText + '\n' + citation + '\n' + linkUrl
      : selectedText + '\n' + citation;
    
    // HTML-Version: Formatierung beibehalten, Seitenmarker aus kopiertem Inhalt entfernen
    let htmlContent = '';
    const fragment = range.cloneContents();
    const div = document.createElement('div');
    div.appendChild(fragment);
    // Seitenmarker-Elemente entfernen (sind im DOM, aber nicht selektierbar)
    div.querySelectorAll('.page-break-container').forEach(el => el.remove());
    const escapedCitation = citation.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    
    if (linkUrl) {
      // Quellenangabe als klickbarer Link zur Textstelle
      const escapedUrl = linkUrl.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
      htmlContent = div.innerHTML + '<br><a href="' + escapedUrl + '" style="font-size: 0.9em; color: #666;">' + escapedCitation + '</a>';
    } else {
      htmlContent = div.innerHTML + '<br><span style="font-size: 0.9em; color: #666;">' + escapedCitation + '</span>';
    }
    
    e.clipboardData.setData('text/plain', plainText);
    if (htmlContent) {
      e.clipboardData.setData('text/html', htmlContent);
    }
    
    console.log('[COPY] Quellenangabe angehängt:', citation, linkUrl ? '(Link: ' + linkUrl + ')' : '', '(Container:', container.id, ')');
    } catch (err) {
      console.error('[COPY] Fehler im Copy-Handler:', err);
    }
  });
});

// ---- extracted script block ----
// Docs Tab - Dokumentation im Main Viewer anzeigen
function showDocsInViewer() {
  const viewer = document.getElementById('viewer');
  const docsSource = document.getElementById('docs-content-source');
  
  if (!viewer || !docsSource) return;
  
  // Hole den Inhalt aus dem versteckten Dokumentations-Container
  const docsContent = docsSource.querySelector('div');
  if (docsContent) {
    // Klone den Inhalt und zeige ihn im Viewer
    viewer.innerHTML = `
      <div style="padding: 1rem 2rem 2rem 1rem; max-width: 1200px; margin: 0 auto;">
        ${docsContent.innerHTML}
      </div>
    `;
    
    // Scroll zum Anfang
    viewer.scrollTop = 0;
    
    // Zeige TOC im Summary Panel
    showDocsTOC();
  }
}

// Maps Tab - Obsidian-Inhalt links (#results), rechte Seite: PDF via PDF.js
// COGGLE_MAPS wird dynamisch von /api/maps-list geladen
let COGGLE_MAPS = [
  { id: 'Rhythmisches_System_neu', name: 'Rhythmisches System', pdfUrl: true, contentMapId: 'Rhythmisches_System_neu', publishUrl: 'https://publish.obsidian.md/anthropologie/I.+Themen/Dreigliederung/Rhythmisches+System' }
];

async function loadMapsList() {
  try {
    const apiBase = typeof API_BASE !== 'undefined' ? API_BASE : (window.location.hostname === 'localhost' ? 'http://localhost:3003' : '');
    const res = await fetch(apiBase + '/api/maps-list');
    if (!res.ok) return;
    const data = await res.json();
    if (!data.maps || !data.maps.length) return;
    COGGLE_MAPS = data.maps.map(function(m) {
      return { id: m.id, name: m.name, pdfUrl: true, contentMapId: m.id, publishUrl: null };
    });
    // Dropdown aktualisieren falls Maps-Tab bereits aktiv
    const dropdown = document.getElementById('maps-dropdown');
    if (dropdown) {
      // Beim Laden kein Auto-Select: Dropdown nur befuellen wenn Kategorie aktiv
      const catEl = document.getElementById('maps-category-dropdown');
      const cat = catEl ? catEl.value : '';
      if (cat) filterMapsByCategory(cat, window._coggleMapId || '');
    }
  } catch(e) {
    console.warn('[MAPS] Liste konnte nicht geladen werden:', e);
  }
}
// Maps-Liste beim Start laden
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', loadMapsList);
} else {
  loadMapsList();
}
function mapsSetViewMode(mode) {
  window._mapsViewMode = mode;
  const localBtn = document.getElementById('maps-view-local');
  const publishBtn = document.getElementById('maps-view-publish');
  if (localBtn) localBtn.classList.toggle('active', mode === 'local');
  if (publishBtn) publishBtn.classList.toggle('active', mode === 'publish');
  showMapsInViewer();
}

async function showMapsInViewer() {
  var sp = document.getElementById('summary-panel');
  if (sp && sp.classList.contains('visible')) {
    if (typeof closeSummaryPanelFromHeader === 'function') closeSummaryPanelFromHeader();
  }
  const viewerSummaryBtn = document.getElementById('viewerSummaryBtn');
  if (viewerSummaryBtn) viewerSummaryBtn.style.display = 'inline-flex';
  const viewer = document.getElementById('viewer');
  const resultsDiv = document.getElementById('results');
  const dropdown = document.getElementById('maps-dropdown');
  if (!viewer) return;
  const selectedId = (window._coggleMapId || COGGLE_MAPS[0].id);
  const map = COGGLE_MAPS.find(m => m.id === selectedId) || COGGLE_MAPS[0];
  const usePublish = (window._mapsViewMode || 'local') === 'publish' && map.publishUrl;
  const titleEl = document.getElementById('document-title');
  if (titleEl) titleEl.textContent = map.name || 'Karten';
  window._currentMapsMap = map;
  updateMapsPdfDownloadBtn();
  
  if (dropdown) {
    const catEl = document.getElementById('maps-category-dropdown');
    const cat = catEl ? catEl.value : 'entwicklung';
    const reinkId = 'Reinkarnations-Metamorphose';
    const filtered = cat === 'reinkarnation'
      ? COGGLE_MAPS.filter(m => m.id === reinkId)
      : COGGLE_MAPS.filter(m => m.id !== reinkId);
    dropdown.innerHTML = '<option value="">-- Karte wählen --</option>' +
      filtered.map(m => `<option value="${m.id}"${m.id === map.id ? ' selected' : ''}>${m.name}</option>`).join('');
  }
  const localBtn = document.getElementById('maps-view-local');
  const publishBtn = document.getElementById('maps-view-publish');
  if (localBtn) localBtn.classList.toggle('active', !usePublish);
  if (publishBtn) publishBtn.classList.toggle('active', usePublish);
  
  const apiBase = typeof API_BASE !== 'undefined' ? API_BASE : (window.location.hostname === 'localhost' ? 'http://localhost:3003' : '');
  const pdfSrc = map.pdfUrl ? ((apiBase || window.location.origin) + '/api/maps-pdf?map=' + encodeURIComponent(map.id)) : '';
  if (pdfSrc && typeof pdfjsLib !== 'undefined') {
    viewer.innerHTML = `
      <div id="maps-pdf-viewer" style="display:flex;flex-direction:column;height:calc(100vh - 120px);min-height:2000px;resize:vertical;overflow:hidden;background:var(--background-color);">        
        <div style="flex:0 0 auto;display:flex;align-items:center;gap:6px;padding:6px 10px;background:var(--background-color);border-bottom:1px solid var(--border-color);">
          <button type="button" id="maps-pdf-out" class="pdf-panel-controls" style="padding:4px 8px;font-size:0.85em;border:1px solid var(--border-color);background:transparent;color:var(--text-color);cursor:pointer;border-radius:4px;">-</button>
          <button type="button" id="maps-pdf-in"  class="pdf-panel-controls" style="padding:4px 8px;font-size:0.85em;border:1px solid var(--border-color);background:transparent;color:var(--text-color);cursor:pointer;border-radius:4px;">+</button>
          <span id="maps-pdf-pct" style="font-size:0.8em;color:var(--secondary-text);min-width:3.5rem;">100%</span>
          <button type="button" id="maps-pdf-fit" class="pdf-panel-controls" style="padding:4px 8px;font-size:0.85em;border:1px solid var(--border-color);background:transparent;color:var(--text-color);cursor:pointer;border-radius:4px;">Anpassen</button>
        </div>
        <div id="maps-pdf-scroll" style="flex:1;height:calc(100vh - 150px);max-height:calc(100vh - 150px);min-height:0;overflow:auto;padding:0;background:var(--background-color);">
          <div id="maps-pdf-wrap" style="position:relative;margin:0 auto;">
            <canvas id="maps-pdf-canvas"></canvas>
            <div id="maps-pdf-links" style="position:absolute;top:0;left:0;pointer-events:none;"></div>
          </div>
        </div>
      </div>
    `;
    try {
      const pdf = await pdfjsLib.getDocument({ url: pdfSrc, withCredentials: false }).promise;
      const page = await pdf.getPage(1);
      const annotations = await page.getAnnotations();
      const scrollEl = document.getElementById('maps-pdf-scroll');
      const canvas = document.getElementById('maps-pdf-canvas');
      const updateBlendMode = function() {
        canvas.style.mixBlendMode = document.body.classList.contains('dark-mode') ? 'normal' : 'multiply';
      };
      updateBlendMode();
      const blendObserver = new MutationObserver(updateBlendMode);
      blendObserver.observe(document.body, { attributes: true, attributeFilter: ['class'] });
      const linksDiv = document.getElementById('maps-pdf-links');
      const baseVp = page.getViewport({ scale: 1 });
      const sw = scrollEl.clientWidth  || (scrollEl.offsetWidth  || 800);
      const sh = scrollEl.clientHeight || (scrollEl.offsetHeight || 600);
      const fitScale = Math.max(0.1, Math.min((sw - 24) / baseVp.width, (sh - 24) / baseVp.height, 3));
      let scale = fitScale;
      let renderTask = null;
      const render = async function() {
        if (renderTask) { try { renderTask.cancel(); } catch(e){} }
        const vp = page.getViewport({ scale });
        const dpr = window.devicePixelRatio || 1;
        canvas.width = Math.floor(vp.width * dpr);
        canvas.height = Math.floor(vp.height * dpr);
        canvas.style.width = vp.width + 'px';
        canvas.style.height = vp.height + 'px';
        const wrapEl = document.getElementById('maps-pdf-wrap');
        if (wrapEl) { wrapEl.style.width = vp.width + 'px'; wrapEl.style.height = vp.height + 'px'; }
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        renderTask = page.render({ canvasContext: ctx, viewport: vp, transform: dpr !== 1 ? [dpr,0,0,dpr,0,0] : null });
        try { await renderTask.promise; } catch(e) { if (e.name !== 'RenderingCancelledException') throw e; return; }
        renderTask = null;
        linksDiv.innerHTML = '';
        linksDiv.style.cssText = 'position:absolute;top:0;left:0;width:' + baseVp.width + 'px;height:' + baseVp.height + 'px;pointer-events:auto;transform-origin:top left;transform:scale(' + scale + ');';
        annotations.filter(a => a.subtype === 'Link').forEach(function(ann) {
          if (!ann.rect || ann.rect.length < 4) return;
          const url = ann.url || (ann.action && ann.action.uri);
          if (!url) return;
          const r = ann.rect;
          const a = document.createElement('a');
          a.href = url;
          a.style.cssText = 'position:absolute;left:' + r[0] + 'px;top:' + (baseVp.height - r[3]) + 'px;width:' + (r[2]-r[0]) + 'px;height:' + (r[3]-r[1]) + 'px;display:block;cursor:pointer;';
          a.addEventListener('click', function(e) {
            e.preventDefault();
            const scrollMatch = url.match(/[?#&]scroll=([^&]*)/);
            if (scrollMatch) {
              const heading = decodeURIComponent(scrollMatch[1]).replace(/\+/g, ' ');
              const el = document.getElementById(heading);
              if (el) {
                const sidebar = document.getElementById('sidebar');
                if (sidebar && sidebar.classList.contains('collapsed')) {
                  if (typeof toggleSidebar === 'function') toggleSidebar();
                  setTimeout(function() { el.scrollIntoView({ behavior: 'instant', block: 'start' }); }, 150);
                } else {
                  el.scrollIntoView({ behavior: 'instant', block: 'start' });
                }
                return;
              }
                return;
            }
            // Obsidian Publish Links: Fragment als Ueberschriften-ID im linken Panel suchen
            if (url.includes('publish.obsidian.md')) {
              const hashIdx = url.indexOf('#');
              if (hashIdx >= 0) {
                const fragment = url.substring(hashIdx + 1);
                const heading = decodeURIComponent(fragment.replace(/\+/g, ' '));
                const scrollToEl = function(el) {
                  const sidebar = document.getElementById('sidebar');
                  if (sidebar && sidebar.classList.contains('collapsed')) {
                    if (typeof toggleSidebar === 'function') toggleSidebar();
                    setTimeout(function() { el.scrollIntoView({ behavior: 'instant', block: 'start' }); }, 150);
                  } else {
                    el.scrollIntoView({ behavior: 'instant', block: 'start' });
                  }
                };
                // Obsidian Publish entfernt Klammern aus Ankern: normalize fuer Vergleich
                const normAnchor = function(s) {
                  return s
                    .replace(/\u00a0/g, ' ')   // geschuetztes Leerzeichen -> normales
                    .replace(/[()]/g, '')     // Klammern entfernen
                    .replace(/\s*:\s*/g, ':') // Leerzeichen um Doppelpunkt
                    .replace(/\s+/g, ' ')     // mehrfache Leerzeichen
                    .trim();
                };
                const normHeading = normAnchor(heading);
                const directEl = document.getElementById(heading);
                if (directEl) { scrollToEl(directEl); return; }
                // Fallback: Ueberschriften im Panel nach normalisiertem Text durchsuchen
                const obsidianContent = document.getElementById('maps-obsidian-content');
                if (obsidianContent) {
                  const allHeadings = obsidianContent.querySelectorAll('h1,h2,h3,h4,h5,h6');
                  for (let i = 0; i < allHeadings.length; i++) {
                    const h = allHeadings[i];
                    const hText = (h.textContent || '').trim();
                    if (hText === heading || normAnchor(hText) === normHeading) {
                      scrollToEl(h); return;
                    }
                  }
                }
              }
              return;
            }
            window.open(url, '_blank', 'noopener');
          });
          linksDiv.appendChild(a);
        });
        document.getElementById('maps-pdf-pct').textContent = Math.round(scale * 100) + '%';
        updateCursor();
      };
      // Drag-to-Pan mit Grab-Hand
      const setCursor = function(c) {
        scrollEl.style.cursor = c;
        canvas.style.cursor = c;
        linksDiv.style.cursor = c;
      };
      const isZoomed = function() {
        // Canvas-Größe direkt mit Scroll-Container vergleichen (robust gegen min-height)
        const canvasEl = document.getElementById('maps-pdf-canvas');
        if (!canvasEl) return false;
        return canvasEl.offsetWidth  > scrollEl.clientWidth  + 2 ||
               canvasEl.offsetHeight > scrollEl.clientHeight + 2;
      };
      const updateCursor = function() {
        // Grab-Cursor immer anzeigen wenn PDF geladen (erlaubt Drag in beide Richtungen)
        setCursor('grab');
      };
      await render();
      let isFitMode = true;
      const recalcFitScale = function() {
        const sw = scrollEl.clientWidth || scrollEl.offsetWidth || 800;
        const sh = scrollEl.clientHeight || scrollEl.offsetHeight || 600;
        return Math.max(0.1, Math.min((sw - 24) / baseVp.width, (sh - 24) / baseVp.height, 3));
      };
      document.getElementById('maps-pdf-in').onclick  = function() { isFitMode = false; scale = Math.min(scale * 1.2, 6); render(); };
      document.getElementById('maps-pdf-out').onclick = function() { isFitMode = false; scale = Math.max(scale / 1.2, 0.2); render(); };
      document.getElementById('maps-pdf-fit').onclick = function() { isFitMode = true; scale = recalcFitScale(); render(); };
      let resizeTimer = null;
      const resizeObs = new ResizeObserver(function() {
        if (!isFitMode) return;
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(function() { scale = recalcFitScale(); render(); }, 150);
      });
      resizeObs.observe(scrollEl);
      scrollEl.addEventListener('wheel', function(e) {
        if (e.ctrlKey || e.metaKey || e.shiftKey) {
          e.preventDefault();
          isFitMode = false;
          scale = e.deltaY < 0 ? Math.min(scale * 1.1, 6) : Math.max(scale / 1.1, 0.2);
          render();
        }
      }, { passive: false });
      let dragStart = null;
      scrollEl.addEventListener('mousedown', function(e) {
        if (e.button !== 0) return;
        dragStart = { x: e.clientX + scrollEl.scrollLeft, y: e.clientY + scrollEl.scrollTop };
        setCursor('grabbing');
        document.body.style.userSelect = 'none';
        e.preventDefault();
      });
      canvas.addEventListener('mousedown', function(e) {
        if (e.button !== 0) return;
        dragStart = { x: e.clientX + scrollEl.scrollLeft, y: e.clientY + scrollEl.scrollTop };
        setCursor('grabbing');
        document.body.style.userSelect = 'none';
        e.preventDefault();
      });
      window.addEventListener('mousemove', function(e) {
        if (!dragStart) return;
        e.preventDefault();
        scrollEl.scrollLeft = dragStart.x - e.clientX;
        scrollEl.scrollTop  = dragStart.y - e.clientY;
      }, { passive: false });
      window.addEventListener('mouseup', function() {
        if (dragStart) { dragStart = null; updateCursor(); document.body.style.userSelect = ''; }
      });
    } catch(e) {
      console.error('[PDF-Viewer] Fehler:', e);
      const v = document.getElementById('maps-pdf-viewer');
      if (v) v.innerHTML = '<div style="padding:2rem;color:var(--secondary-text);text-align:center;"><p>PDF konnte nicht geladen werden.</p><p style="font-size:0.8em;">' + (e && e.message ? e.message : 'Pfad in backend.js prüfen: MAPS_PDF_PATHS') + '</p></div>';
    }
  } else {
    viewer.innerHTML = '<div style="padding: 2rem; color: var(--secondary-text);">Keine Karte verfügbar.</div>';
  }
  
  if (resultsDiv) {
    resultsDiv.style.display = 'block';
    const sidebarContent = document.getElementById('sidebar-content');
    if (sidebarContent) sidebarContent.style.display = 'block';
    if (usePublish && map.publishUrl) {
      resultsDiv.innerHTML = `<div style="min-height: 500px;"><iframe src="${map.publishUrl}" style="width: 100%; height: calc(100vh - 200px); min-height: 500px; border: none; display: block;" title="Obsidian Publish"></iframe></div>`;
    } else if (map.contentMapId) {
      resultsDiv.innerHTML = '<div style="padding: 1rem; color: var(--secondary-text);">Lade Inhalt</div>';
      try {
      const apiBase = typeof API_BASE !== 'undefined' ? API_BASE : (window.location.hostname === 'localhost' ? 'http://localhost:3003' : '');
      const res = await fetch(apiBase + '/api/maps-content?map=' + encodeURIComponent(map.contentMapId));
      if (!res.ok) throw new Error('Datei nicht gefunden');
      const data = await res.json();
      let md = data.markdown.replace(/\[\[#([^\]]+)\]\]/g, (_, h) => `[${h}](#${encodeURIComponent(h)})`);
      md = md.replace(/\[GA\s+\d+[a-z]?,[^\]]+\]\s*(?=\^[a-z0-9]+)/g, '');
      // Block-IDs als unsichtbare Spans einbetten (für Navigation, nicht sichtbar)
      md = md.replace(/ \^([a-z0-9]+)(?=[ \[;\s]|$)/g, ' <span class="blkref" data-bid="$1"></span>');
      let html = (typeof marked !== 'undefined' ? marked.parse(md, { breaks: true, gfm: true }) : md.replace(/\n/g, '<br>'));
      const wrap = document.createElement('div');
      wrap.innerHTML = html;
      const appBaseUrl = (window.location.origin || '') + (window.location.pathname || '/app.html');
      const coggleLinkBase = appBaseUrl.replace(/app\.html\/?$/i, 'coggle-link.html');
      wrap.querySelectorAll('h1,h2,h3,h4,h5,h6').forEach(h => {
        const txt = (h.textContent || '').trim();
        if (txt) {
          h.id = txt;
        }
      });
      wrap.querySelectorAll('p').forEach(p => {
        p.classList.add('paragraph');
      });
      resultsDiv.innerHTML = '<div id="maps-obsidian-content" class="maps-sidepanel-content">' + wrap.innerHTML + '</div>';
      resultsDiv.querySelectorAll('#maps-obsidian-content a[href^="#"]').forEach(a => {
        a.addEventListener('click', function(e) {
          const h = this.getAttribute('href').slice(1);
          const id = h ? decodeURIComponent(h).replace(/\+/g, ' ') : '';
          const el = id ? document.getElementById(id) : null;
          if (el) {
            e.preventDefault();
            el.scrollIntoView({ behavior: 'auto', block: 'start' });
          }
        });
      });
      // blkref-Spans in klickbare GA-Links umwandeln
      (function() {
        var apiBase = typeof API_BASE !== 'undefined' ? API_BASE : (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' ? 'http://localhost:3003' : '');
        resultsDiv.querySelectorAll('#maps-obsidian-content .blkref[data-bid]').forEach(function(span) {
          var blockId = span.dataset.bid;
          if (!blockId) return;
          var captured = blockId;
          fetch(apiBase + '/api/resolve-block-id?id=' + encodeURIComponent(blockId))
            .then(function(r) { return r.ok ? r.json() : null; })
            .then(function(data) {
              if (!data || !data.success || !data.lectureId) return;
              var lid = data.lectureId;
              var a = document.createElement('a');
              a.href = '#';
              a.textContent = '(' + (lid || '') + ')'; a.style.fontWeight = 'bold';
              a.addEventListener('click', function(e) {
                e.preventDefault();
                if (typeof window.showLectureFromAdvancedSearch === 'function') {
                  window.showLectureFromAdvancedSearch(lid, '', '^' + captured);
                }
              });
              if (span.parentNode) span.parentNode.replaceChild(a, span);
            })
            .catch(function() {});
        });
      })();
      const hash = (window.location.hash || '').replace(/^#/, '');
      let frag = '';
      if (hash.includes('&scroll=')) {
        const m = hash.match(/&scroll=([^&]*)/);
        frag = m ? decodeURIComponent(m[1]).replace(/\+/g, ' ') : '';
      } else if (hash && hash !== 'maps') {
        frag = decodeURIComponent(hash).replace(/\+/g, ' ');
      }
      const scrollEl = frag ? document.getElementById(frag) : null;
      if (scrollEl) scrollEl.scrollIntoView({ behavior: 'auto', block: 'start' });
    } catch (e) {
      resultsDiv.innerHTML = '<div style="padding: 1rem; color: var(--secondary-text);">Inhalt konnte nicht geladen werden. Pfad in backend.js prüfen.</div>';
    }
    } else {
      resultsDiv.innerHTML = '';
    }
  }
}


// Sub-Navigation im Themen-Tab: Schwerpunkte | Timeline | Karten
function switchThemenView(view) {
  window._themenView = view;
  analyticsTrack('tab_view', 'thematic2_' + view);
  const views = ['schwerpunkte', 'timeline', 'karten', 'sammlungen'];

  // Rechtes Side Panel schliessen
  if (typeof closeSummaryPanelFromHeader === 'function') closeSummaryPanelFromHeader();

  // Titel im Main Viewer setzen
  const docTitle = document.getElementById('document-title');
  if (docTitle) {
    if (view === 'schwerpunkte') docTitle.textContent = 'Themenschwerpunkte im Gesamtwerk (1879-1925)';
    else if (view === 'timeline') docTitle.textContent = 'Timeline';
    else if (view === 'karten')   docTitle.textContent = 'Karten';
    else if (view === 'sammlungen') docTitle.textContent = 'Sammlungen';
  }

  // Viewer und Side Panel leeren
  const viewer = document.getElementById('viewer');
  if (viewer) viewer.innerHTML = '';
  const results = document.getElementById('results');
  if (results) {
    if (view === 'schwerpunkte') {
      results.innerHTML = '<div style="color: var(--secondary-text); text-align: left; font-style: italic; font-size: 0.9rem;">Für eine Zusammenfassung klicken Sie auf einen Themenschwerpunkt in der Graphik</div>';
    } else {
      results.innerHTML = '';
    }
  }

  // Vorherige Lecture-Daten zurücksetzen (kein Text geladen in neuer Sub-View)
  currentLectureData = null;

  // Alle text-bezogenen Header-Buttons verstecken (werden erst bei Text-Anzeige wieder eingeblendet)
  var _gaInfoBtn = document.getElementById('gaInfoBtn');
  if (_gaInfoBtn) _gaInfoBtn.style.display = 'none';
  var _pdfToggleBtn = document.getElementById('pdfToggleBtn');
  if (_pdfToggleBtn) _pdfToggleBtn.style.display = 'none';
  var _viewerDownloadBtn = document.getElementById('viewerDownloadBtn');
  if (_viewerDownloadBtn) _viewerDownloadBtn.style.display = 'none';
  var _h4ToggleBtn = document.getElementById('h4ToggleBtn');
  if (_h4ToggleBtn) _h4ToggleBtn.style.display = 'none';
  var _viewerOriginalBtn = document.getElementById('viewerOriginalBtn');
  if (_viewerOriginalBtn) _viewerOriginalBtn.style.display = 'none';

  // Buttons aktualisieren
  views.forEach(function(v) {
    const btn = document.getElementById('themen-btn-' + v);
    if (!btn) return;
    if (v === view) {
      btn.style.borderBottomColor = 'var(--accent-color)';
      btn.style.color = 'var(--accent-color)';
      btn.style.fontWeight = '600';
    } else {
      btn.style.borderBottomColor = 'transparent';
      btn.style.color = 'var(--secondary-text)';
      btn.style.fontWeight = '';
    }
  });

  const mapsDiv = document.getElementById('maps-in-themen');
  const timelineDiv = document.getElementById('timelineFilterSection');

  document.body.classList.toggle('karten-view', view === 'karten');
  if (view !== 'karten') { window._currentMapsMap = null; }
  document.body.classList.toggle('sammlungen-view', view === 'sammlungen');
      var sammlDlBtn = document.getElementById('sammlungenPdfDownloadBtn'); if (sammlDlBtn) sammlDlBtn.style.display = view === 'sammlungen' ? 'inline-flex' : 'none';
  if (typeof updateMapsPdfDownloadBtn === 'function') updateMapsPdfDownloadBtn();

  // Side-Panel Toggle: IMMER verstecken beim Sub-View-Wechsel (wird erst bei Text-Anzeige eingeblendet)
  const viewerSummaryBtn = document.getElementById('viewerSummaryBtn');
  if (viewerSummaryBtn) {
    viewerSummaryBtn.style.display = 'none';
  }

  if (view === 'schwerpunkte') {
    if (mapsDiv) mapsDiv.style.display = 'none';
    if (timelineDiv) timelineDiv.style.display = 'none';
    if (typeof initThematicVisualization === 'function') {
      initThematicVisualization();
    }

  } else if (view === 'timeline') {
    if (mapsDiv) mapsDiv.style.display = 'none';
    if (timelineDiv) timelineDiv.style.display = 'block';
    // Dropdowns zurücksetzen
    const themeDropdown = document.getElementById('timelineThemeFilterAdmin');
    const keywordDropdown = document.getElementById('timelineKeywordFilterAdmin');
    if (themeDropdown) themeDropdown.value = '';
    if (keywordDropdown) keywordDropdown.value = '';
    const keywordSearch = document.getElementById('timelineKeywordSearch');
    if (keywordSearch) keywordSearch.value = '';

  } else if (view === 'karten') {
    if (mapsDiv) mapsDiv.style.display = 'flex';
    if (timelineDiv) timelineDiv.style.display = 'none';
    // Maps-State zurücksetzen damit beim nächsten Wechsel zu Karten neu geladen wird
    window._coggleMapId = null;
    // Dropdown befüllen und erste Karte laden
    if (typeof COGGLE_MAPS !== 'undefined' && COGGLE_MAPS.length > 0) {
      const catEl = document.getElementById('maps-category-dropdown');
      const cat = (catEl && catEl.value) ? catEl.value : 'entwicklung';
      if (catEl && !catEl.value) catEl.value = 'entwicklung';
      filterMapsByCategory(cat, '');
      const reinkId = 'Reinkarnations-Metamorphose';
      const firstMap = cat === 'reinkarnation'
        ? COGGLE_MAPS.find(function(m) { return m.id === reinkId; })
        : COGGLE_MAPS.find(function(m) { return m.id !== reinkId; });
      if (firstMap) {
        const dd = document.getElementById('maps-dropdown');
        if (dd) dd.value = firstMap.id;
        switchCoggleMap(firstMap.id);
      }
    }

  } else if (view === 'sammlungen') {
    if (mapsDiv) mapsDiv.style.display = 'none';
    if (timelineDiv) timelineDiv.style.display = 'none';
    loadSammlungenList();
  }
}

function filterMapsByCategory(cat, selectedId) {
  const reinkId = 'Reinkarnations-Metamorphose';
  const dropdown = document.getElementById('maps-dropdown');
  if (!dropdown) return;
  // Leere Kategorie: Dropdown zuruecksetzen, nichts laden
  if (!cat) {
    dropdown.innerHTML = '<option value="">-- Karte wählen --</option>';
    return;
  }
  const filtered = cat === 'reinkarnation'
    ? COGGLE_MAPS.filter(function(m) { return m.id === reinkId; })
    : COGGLE_MAPS.filter(function(m) { return m.id !== reinkId; });
  const sel = selectedId || '';
  const validSel = filtered.find(function(m) { return m.id === sel; }) ? sel : '';
  dropdown.innerHTML = '<option value="">-- Karte wählen --</option>' + filtered.map(function(m) {
    return '<option value="' + m.id + '"' + (m.id === validSel ? ' selected' : '') + '>' + m.name + '</option>';
  }).join('');
  // Nicht automatisch laden – Nutzer muss explizit auswaehlen
}
function switchCoggleMap(mapId) {
  if (!mapId) return; // Placeholder: nichts laden
  window._coggleMapId = mapId;
  showMapsInViewer();
}

function updateMapsPdfDownloadBtn() {
  var btn = document.getElementById('mapsPdfDownloadBtn');
  if (!btn) return;
  var isKarten = document.body.classList.contains('karten-view') || window._themenView === 'karten';
  var hasMap = window._currentMapsMap && window._currentMapsMap.pdfUrl;
  btn.style.display = (isKarten && hasMap) ? 'inline-flex' : 'none';
}

window.downloadMapsPdf = function() {
  var map = window._currentMapsMap;
  if (!map) return;
  showMapsDownloadOptions();
};

function showMapsDownloadOptions() {
  var map = window._currentMapsMap;
  if (!map) return;
  var existing = document.getElementById('mapsDownloadModal');
  if (existing) existing.remove();

  var apiBase = typeof API_BASE !== 'undefined' ? API_BASE : (window.location.hostname === 'localhost' ? 'http://localhost:3003' : '');
  var baseUrl = apiBase || window.location.origin;
  var pdfUrl = baseUrl + '/api/maps-pdf?map=' + encodeURIComponent(map.id);
  var mapName = map.name || map.id;

  var MAP_TO_SAMMLUNG = {
    'Entwicklung der Phantasie': 'Entwicklung des Kindes - Phantasie.pdf',
    'Entwicklung der Urteilskraft': 'Entwicklung des Kindes - Urteilskraft.pdf',
    'Entwicklung des Gedächtnisses': 'Entwicklung des Kindes - Gedächtnisentwicklung.pdf',
    'Entwicklung des Nerven-Sinnessystems': 'Entwicklung des Kindes - Nerven-Sinnessystem.pdf',
    'Entwicklung des Rhythmischen_Systems': 'Entwicklung des Kindes - Rhyhtmisches System.pdf',
    'Entwicklung des Stoffwechsel-Gliedmaßensystems': 'Entwicklung des Kindes - Stoffwechsel-Gliedmaßensystem.pdf',
    'Gehen_Sprechen_Denken': 'Entwicklung des Kindes - Gehen, Sprechen, Denken.pdf',
    'Modellleib': 'Entwicklung des Kindes - Modellleib.pdf',
    'Modellleib_chronologisch': 'Entwicklung des Kindes - Modellleib.pdf',
    'Nachahmung': 'Entwicklung des Kindes - Nachahmung.pdf',
    'Nachahmung_-_Nachfolge_-_Freiheit': 'Entwicklung des Kindes - Nachahmung, Nachfolge, Freiheit.pdf',
    'Pubertät': 'Entwicklung des Kindes - Pubertät.pdf',
    'Reinkarnations-Metamorphose': 'Reinkarnation - Reinkarnationsmetamorphose Gliedmaßen - Kopf (thematisch).pdf',
    'Rubikon': 'Entwicklung des Kindes - Rubikon.pdf',
    'Seelische_Entwicklung_des_Kindes': 'Entwicklung des Kindes - Seelische Entwicklung.pdf',
    'Wirkungen_der_Erziehung_im_Lebenslauf': 'Entwicklung des Kindes - Wirkungen der Erziehung im Lebenslauf.pdf',
    'Zahnwechsel': 'Entwicklung des Kindes - Zahnwechsel.pdf'
  };

  var mapId = map.id || '';
  var sammlungFile = MAP_TO_SAMMLUNG[mapId];
  var sammlungUrl = sammlungFile ? baseUrl + '/api/sammlungen-pdf?file=' + encodeURIComponent(sammlungFile) : null;

  var modal = document.createElement('div');
  modal.id = 'mapsDownloadModal';
  modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);z-index:20000;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.2s ease;';
  modal.onclick = function(e) { if (e.target === modal) modal.remove(); };

  var content = document.createElement('div');
  content.style.cssText = 'background:var(--background-color,#FAF8F3);border-radius:8px;padding:1.5rem;max-width:400px;width:90%;box-shadow:0 8px 32px rgba(0,0,0,0.3);';

  var buttonsHtml = '<button id="mapsDownloadPdf" style="display:flex;align-items:center;gap:8px;padding:10px 14px;border:1px solid var(--border-color);background:transparent;color:var(--text-color);cursor:pointer;border-radius:6px;font-size:0.9em;text-align:left;transition:background 0.15s;"' +
    " onmouseover=\"this.style.background='var(--sidebar-bg)'\" onmouseout=\"this.style.background='transparent'\">" +
    '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>' +
    '<span><strong>Karten-PDF</strong><br><span style="font-size:0.8em;color:var(--secondary-text);">Graphische Übersicht als PDF</span></span>' +
  '</button>';

  if (sammlungUrl) {
    buttonsHtml += '<button id="mapsDownloadSammlung" style="display:flex;align-items:center;gap:8px;padding:10px 14px;border:1px solid var(--border-color);background:transparent;color:var(--text-color);cursor:pointer;border-radius:6px;font-size:0.9em;text-align:left;transition:background 0.15s;"' +
      " onmouseover=\"this.style.background='var(--sidebar-bg)'\" onmouseout=\"this.style.background='transparent'\">" +
      '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>' +
      '<span><strong>Thematische Zitatsammlung</strong><br><span style="font-size:0.8em;color:var(--secondary-text);">Alle Zitate als PDF</span></span>' +
    '</button>';
  }

  content.innerHTML = '<h3 style="margin:0 0 1rem 0;font-size:1.05rem;color:var(--text-color);">Download: ' + mapName + '</h3>' +
    '<div style="display:flex;flex-direction:column;gap:10px;">' + buttonsHtml + '</div>' +
    "<button onclick=\"document.getElementById('mapsDownloadModal').remove()\" style=\"margin-top:1rem;padding:6px 16px;border:1px solid var(--border-color);background:transparent;color:var(--secondary-text);cursor:pointer;border-radius:4px;font-size:0.85em;float:right;\">Abbrechen</button>";

  modal.appendChild(content);
  document.body.appendChild(modal);

  document.getElementById('mapsDownloadPdf').onclick = function() {
    modal.remove();
    var a = document.createElement('a');
    a.href = pdfUrl;
    a.download = mapName + '.pdf';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  var sammlBtn = document.getElementById('mapsDownloadSammlung');
  if (sammlBtn && sammlungUrl) {
    sammlBtn.onclick = function() {
      modal.remove();
      var a = document.createElement('a');
      a.href = sammlungUrl;
      a.download = sammlungFile;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    };
  }
}

// ===== Sammlungen Sub-Tab =====
async function loadSammlungenList() {
  var results = document.getElementById('results');
  if (!results) return;
  results.innerHTML = '<div style="padding:0.3rem 0.5rem;"><div style="color:var(--secondary-text);">Lade Liste…</div></div>';
  var apiBase = typeof API_BASE !== 'undefined' ? API_BASE : (window.location.hostname === 'localhost' ? 'http://localhost:3003' : '');

  var gesamtPdfs = [];
  var sammlungPdfs = [];

  try {
    var [gesamtRes, sammlRes] = await Promise.all([
      fetch(apiBase + '/api/gesamtdarstellungen-list'),
      fetch(apiBase + '/api/sammlungen-list')
    ]);
    var gesamtData = await gesamtRes.json();
    var sammlData = await sammlRes.json();
    gesamtPdfs = gesamtData.pdfs || [];
    sammlungPdfs = sammlData.pdfs || [];
  } catch(err) {
    results.innerHTML = '<div style="padding:1rem;color:var(--error-color);">Fehler beim Laden der Sammlungen.</div>';
    console.error('[SAMMLUNGEN]', err);
    return;
  }

  var html = '<div style="padding:0 0.5rem;">';

  // --- Gesamtdarstellungen (klappbar) ---
  html += '<h1 class="sammlungen-section-toggle" onclick="toggleSammlungenSection(\'gesamt\')" style="font-size:1.2em;margin:0 0 0.6rem 0;color:var(--heading-color);cursor:pointer;user-select:none;display:flex;align-items:center;gap:6px;">' +
    '<span id="gesamt-arrow" style="display:inline-block;transition:transform 0.2s;font-size:0.7em;">▶</span> Gesamtdarstellungen</h1>';
  html += '<ul id="gesamt-list" style="list-style:none;padding:0;margin:0 0 1rem 0;display:none;">';
  if (gesamtPdfs.length === 0) {
    html += '<li style="color:var(--secondary-text);font-size:0.9em;padding:4px 0;">Keine Gesamtdarstellungen verfügbar.</li>';
  } else {
    gesamtPdfs.forEach(function(p) {
      html += '<li style="margin-bottom:8px;"><a href="#" class="gesamtdarstellung-link" data-file="' + p.filename.replace(/"/g, '&quot;') + '" style="color:var(--link-color);text-decoration:none;font-size:0.95em;line-height:1.4;display:block;padding:4px 0;border-bottom:1px solid var(--border-color);">' + p.shortName + '</a></li>';
    });
  }
  html += '</ul>';

  // --- Zitat-Sammlungen (klappbar, standardmäßig offen) ---
  html += '<h1 class="sammlungen-section-toggle" onclick="toggleSammlungenSection(\'zitat\')" style="font-size:1.2em;margin:0 0 0.6rem 0;color:var(--heading-color);cursor:pointer;user-select:none;display:flex;align-items:center;gap:6px;">' +
    '<span id="zitat-arrow" style="display:inline-block;transition:transform 0.2s;transform:rotate(90deg);font-size:0.7em;">▶</span> Zitat-Sammlungen</h1>';
  html += '<ul id="zitat-list" style="list-style:none;padding:0;margin:0;">';
  if (sammlungPdfs.length === 0) {
    html += '<li style="color:var(--secondary-text);font-size:0.9em;padding:4px 0;">Keine Zitat-Sammlungen gefunden.</li>';
  } else {
    sammlungPdfs.forEach(function(p) {
      html += '<li style="margin-bottom:8px;"><a href="#" class="sammlungen-link" data-file="' + p.filename.replace(/"/g, '&quot;') + '" style="color:var(--link-color);text-decoration:none;font-size:0.95em;line-height:1.4;display:block;padding:4px 0;border-bottom:1px solid var(--border-color);">' + p.shortName + '</a></li>';
    });
  }
  html += '</ul>';

  html += '</div>';
  results.innerHTML = html;

  // Click-Handler: Gesamtdarstellungen
  results.querySelectorAll('.gesamtdarstellung-link').forEach(function(a) {
    a.addEventListener('click', function(e) {
      e.preventDefault();
      results.querySelectorAll('.sammlungen-link, .gesamtdarstellung-link').forEach(function(l) { l.style.fontWeight = ''; });
      this.style.fontWeight = '700';
      showGesamtdarstellungPdf(this.dataset.file);
    });
  });

  // Click-Handler: Zitat-Sammlungen
  results.querySelectorAll('.sammlungen-link').forEach(function(a) {
    a.addEventListener('click', function(e) {
      e.preventDefault();
      results.querySelectorAll('.sammlungen-link, .gesamtdarstellung-link').forEach(function(l) { l.style.fontWeight = ''; });
      this.style.fontWeight = '700';
      showSammlungPdf(this.dataset.file);
    });
  });

  // Erste Zitat-Sammlung automatisch laden
  if (sammlungPdfs.length > 0) {
    var firstLink = results.querySelector('.sammlungen-link');
    if (firstLink) {
      firstLink.style.fontWeight = '700';
      showSammlungPdf(sammlungPdfs[0].filename);
    }
  }
}

function toggleSammlungenSection(section) {
  var list = document.getElementById(section + '-list');
  var arrow = document.getElementById(section + '-arrow');
  if (!list || !arrow) return;
  var isVisible = list.style.display !== 'none';
  list.style.display = isVisible ? 'none' : 'block';
  arrow.style.transform = isVisible ? 'rotate(0deg)' : 'rotate(90deg)';
}

function showGesamtdarstellungPdf(filename) {
  window._currentSammlungFilename = filename;
  window._currentSammlungType = 'gesamtdarstellung';
  var viewer = document.getElementById('viewer');
  if (!viewer) return;
  var docTitle = document.getElementById('document-title');
  var shortName = filename.replace(/\.pdf$/i, '');
  if (docTitle) docTitle.textContent = shortName;

  var isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
  var iframeApiBase = isLocal ? 'http://localhost:3003' : window.location.origin;
  var pdfUrl = iframeApiBase + '/api/gesamtdarstellungen-pdf?file=' + encodeURIComponent(filename);
  viewer.innerHTML = '<iframe id="sammlungen-pdf-iframe" src="' + pdfUrl + '" style="width:100%;height:calc(100vh - 100px);border:none;"></iframe>';
}

async function showSammlungPdf(filename) {
  window._currentSammlungFilename = filename;
  window._currentSammlungType = 'sammlung';
  var viewer = document.getElementById('viewer');
  if (!viewer) return;
  var docTitle = document.getElementById('document-title');
  var shortName = filename.replace(/\.pdf$/i, '');
  if (docTitle) docTitle.textContent = shortName;

  var isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
  // Iframe muss online same-origin bleiben, sonst blockiert CSP frame-src.
  var iframeApiBase = isLocal ? 'http://localhost:3003' : window.location.origin;
  var pdfUrl = iframeApiBase + '/api/sammlungen-pdf?file=' + encodeURIComponent(filename);

  // Online wie lokal direkt vom eigenen API-Endpunkt laden (keine externe Viewer-Abhaengigkeit)
  viewer.innerHTML = '<iframe id="sammlungen-pdf-iframe" src="' + pdfUrl + '" style="width:100%;height:calc(100vh - 100px);border:none;"></iframe>';
}

window.downloadSammlungPdf = function() {
  var filename = window._currentSammlungFilename;
  if (!filename) return;
  var isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
  var downloadApiBase = isLocal ? 'http://localhost:3003' : window.location.origin;
  var endpoint = (window._currentSammlungType === 'gesamtdarstellung') ? '/api/gesamtdarstellungen-pdf' : '/api/sammlungen-pdf';
  var url = downloadApiBase + endpoint + '?file=' + encodeURIComponent(filename);
  var a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
};

