// Docs Tab - Scroll to Section Function (für Viewer)
function scrollToDocsSection(sectionId) {
  if (event) event.preventDefault();
  
  // Suche im Viewer (wo die Docs jetzt angezeigt werden)
  const viewer = document.getElementById('viewer');
  if (viewer) {
    const section = viewer.querySelector('#' + sectionId);
    if (section) {
      section.scrollIntoView({ behavior: 'auto', block: 'start' });
      return false;
    }
  }
  
  // Fallback: Suche im gesamten Dokument
  const section = document.getElementById(sectionId);
  if (section) {
    section.scrollIntoView({ behavior: 'auto', block: 'start' });
  }
  return false;
}

