// ============================================================================
// TIMELINE TAB FUNCTIONS
// ============================================================================

let timelineBatchRunning = false;
let timelineBatchCurrentIndex = 0;

// Load timeline statistics
async function loadTimelineStats() {
  try {
    // Show admin section if localhost
    if (API_BASE.includes('localhost')) {
      const adminSection = document.getElementById('timelineAdminSection');
      if (adminSection) {
        adminSection.style.display = 'block';
        // Load available GAs
        await loadAvailableGAs();
      }
    }
    
    // Statistiken berechnen
    let primaryKeywordsCount = 0;
    let consolidatedKeywordsCount = 0;
    let consolidationFactor = '-';
    
    const filesResponse = await fetch(`${API_BASE}/api/list-files`);
    const files = await filesResponse.json();
    
    // Suche das älteste Backup (= originale, unkonsolidierte Keywords)
    const backupFiles = files.filter(f => f.startsWith('keywords-database-backup-')).sort();
    
    if (backupFiles.length > 0) {
      // Lade das älteste Backup als Referenz für Primary Keywords
      const oldestBackup = backupFiles[0];
      const primaryResponse = await fetch(`${API_BASE}/api/file/${oldestBackup}`);
      const primaryData = await primaryResponse.json();
      
      const primaryKeywordsSet = new Set();
      Object.values(primaryData).forEach(lecture => {
        if (lecture.keywords && Array.isArray(lecture.keywords)) {
          lecture.keywords.forEach(kw => {
            if (kw.term) primaryKeywordsSet.add(kw.term);
          });
        }
      });
      primaryKeywordsCount = primaryKeywordsSet.size;
      
      // Aktuelle DB als konsolidiert
      const currentResponse = await fetch(`${API_BASE}/api/keywords-database`);
      const currentData = await currentResponse.json();
      
      const consolidatedKeywordsSet = new Set();
      Object.values(currentData).forEach(lecture => {
        if (lecture.keywords && Array.isArray(lecture.keywords)) {
          lecture.keywords.forEach(kw => {
            if (kw.term) consolidatedKeywordsSet.add(kw.term);
          });
        }
      });
      consolidatedKeywordsCount = consolidatedKeywordsSet.size;
      
      // Berechne Reduktionsfaktor
      if (primaryKeywordsCount > 0) {
        const reduction = ((primaryKeywordsCount - consolidatedKeywordsCount) / primaryKeywordsCount * 100).toFixed(1);
        consolidationFactor = `${reduction}%`;
      }
    } else {
      // Kein Backup vorhanden - zeige aktuelle Keywords als Primary
      const currentResponse = await fetch(`${API_BASE}/api/keywords-database`);
      const currentData = await currentResponse.json();
      
      const primaryKeywordsSet = new Set();
      Object.values(currentData).forEach(lecture => {
        if (lecture.keywords && Array.isArray(lecture.keywords)) {
          lecture.keywords.forEach(kw => {
            if (kw.term) primaryKeywordsSet.add(kw.term);
          });
        }
      });
      primaryKeywordsCount = primaryKeywordsSet.size;
    }
    
    // 3. Lade Themen aus thematic-clusters.json (neue Struktur)
    const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
    const themesData = await themesResponse.json();
    const themeCount = Object.keys(themesData).length;
    
    // Aktualisiere UI (mit Null-Checks)
    const statPrimary = document.getElementById('statPrimaryKeywords');
    const statConsolidated = document.getElementById('statConsolidatedKeywords');
    const statFactor = document.getElementById('statConsolidationFactor');
    const statThemes = document.getElementById('statThemeCount');
    
    if (statPrimary) statPrimary.textContent = primaryKeywordsCount.toLocaleString();
    if (statConsolidated) statConsolidated.textContent = consolidatedKeywordsCount > 0 ? consolidatedKeywordsCount.toLocaleString() : '-';
    if (statFactor) statFactor.textContent = consolidationFactor;
    if (statThemes) statThemes.textContent = themeCount > 0 ? themeCount.toLocaleString() : '-';
    
    // Load themes if available
    await loadTimelineThemes();
    
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden:', error);
  }
}

// Load available GA numbers for selection
async function loadAvailableGAs() {
  try {
    const response = await fetch(`${API_BASE}/api/available-ga`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    
    const data = await response.json();
    const gaList = (data.availableGA || data); // Backend gibt { availableGA: [...] } zurück
    const select = document.getElementById('timelineGASelect');
    
    // Clear existing options except first
    select.innerHTML = '<option value="">GA-Bände</option>';
    
    // Add GA options (sortiert: ohne Suffix vor mit Suffix)
    if (Array.isArray(gaList)) {
      gaList.sort(compareGANumbers).forEach(ga => {
        const option = document.createElement('option');
        option.value = ga;
        option.textContent = ga;
        select.appendChild(option);
      });
      } else {
      console.warn('[TIMELINE] Ungültiges Format:', data);
    }
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden der GAs:', error);
  }
}

// Lade Keywords-Datenbank
async function loadKeywordsDatabase() {
  try {
    const response = await fetch(`${API_BASE}/api/keywords-database`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return await response.json();
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden der Keywords-DB:', error);
    return {};
  }
}

// Load available themes (aus thematic-clusters.json)
async function loadTimelineThemes() {
  try {
    const response = await fetch(`${API_BASE}/api/themes-database`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    
    const themes = await response.json();
    const themeSelect = document.getElementById('timelineThemeFilterAdmin');
    
    // Element existiert nur wenn Timeline gerendert wurde
    if (!themeSelect) {
      return;
    }
    
    if (Object.keys(themes).length > 0) {
      // Clear and populate
      themeSelect.innerHTML = '<option value="">Themen</option>';
      Object.keys(themes).sort().forEach(theme => {
        const option = document.createElement('option');
        option.value = theme;
        option.textContent = theme;
        themeSelect.appendChild(option);
      });
      themeSelect.disabled = false;
      
    } else {
      themeSelect.innerHTML = '<option value="">Noch keine Themenbereiche generiert...</option>';
      themeSelect.disabled = true;
    }
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden der Themenbereiche:', error);
    const themeSelect = document.getElementById('timelineThemeFilterAdmin');
    if (themeSelect) {
      themeSelect.innerHTML = '<option value="">Fehler beim Laden</option>';
    }
  }
}

// Load keywords for selected theme
async function loadTimelineKeywords() {
  const themeSelect = document.getElementById('timelineThemeFilterAdmin');
  const keywordSelect = document.getElementById('timelineKeywordFilterAdmin');
  
  // Element existiert nur wenn Timeline gerendert wurde
  if (!themeSelect || !keywordSelect) {
    return;
  }
  
  const theme = themeSelect.value;
  
  if (!theme || theme === '') {
    keywordSelect.innerHTML = '<option value="">Schlagwörter</option>';
    keywordSelect.disabled = true;
    return;
  }
  
  try {
    const response = await fetch(`${API_BASE}/api/themes-database`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    
    const themes = await response.json();
    const themeData = themes[theme];
    
    if (themeData && themeData.keywords) {
      keywordSelect.innerHTML = '<option value="">Schlagwörter des Themas</option>';
      themeData.keywords.sort().forEach(kw => {
        const option = document.createElement('option');
        option.value = kw;
        option.textContent = kw;
        keywordSelect.appendChild(option);
      });
      keywordSelect.disabled = false;
    }
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden der Keywords:', error);
  }
}

// === ALTE TIMELINE-GENERIERUNGS-FUNKTIONEN ENTFERNT ===
// Die Keyword- und Themen-Generierung erfolgt jetzt über den Keywords-Tab

// Render timeline visualization
// Globale Variable für letztes ausgewähltes Thema/Keyword
// Cache-Variablen entfernt - nicht mehr nötig!
let timelineHeadingLevel = 'both'; // 'h3', 'h4', oder 'both'

// Update timeline statistics display
async function updateTimelineStats() {
  const statsDisplay = document.getElementById('timelineStatsDisplay');
  if (!statsDisplay) return;
  
  // Wenn Suchergebnisse angezeigt werden, Statistik NICHT überschreiben
  if (showingSearchResultsTimeline) {
    return;
  }
  
  // Hole aktuelle Auswahl
  const currentTheme = document.getElementById('timelineThemeFilterAdmin')?.value || '';
  const currentKeyword = document.getElementById('timelineKeywordFilterAdmin')?.value || '';
  
  try {
    const keywordsDB = await loadKeywordsDatabase();
    
    // === FALL 1: Spezifisches KEYWORD ausgewählt ===
    if (currentKeyword) {
      let hitCount = 0; // Anzahl der Fundstellen für dieses Keyword
      const lecturesWithKeyword = new Set();
      
      Object.entries(keywordsDB).forEach(([lectureId, lecture]) => {
        const isNewGeneration = lecture.generationMethod && 
          (lecture.generationMethod.includes('unified-batch') || 
           lecture.generationMethod.includes('unified') ||
           lecture.generationMethod.includes('manual-add') ||
           lecture.generationMethod.includes('manual') ||
           lecture.generationMethod.includes('synced-from-summary-db'));
        
        if (isNewGeneration && lecture.keywords && Array.isArray(lecture.keywords)) {
          lecture.keywords.forEach(kw => {
            if (kw.term && kw.term.toLowerCase() === currentKeyword.toLowerCase()) {
              hitCount++; // Jedes Vorkommen zählt als Fundstelle
              lecturesWithKeyword.add(lectureId);
            }
          });
        }
      });
      
      statsDisplay.innerHTML = `${hitCount} ${hitCount === 1 ? 'Fundstelle' : 'Fundstellen'} · ${lecturesWithKeyword.size} ${lecturesWithKeyword.size === 1 ? 'Text' : 'Texte'}`;
      return;
    }
    
    // === FALL 2: Nur THEMA ausgewählt (kein spezifisches Keyword) ===
    if (currentTheme) {
      const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
      if (themesResponse.ok) {
        const themes = await themesResponse.json();
        const themeData = themes[currentTheme];
        
        if (themeData && themeData.keywords) {
          let hitCount = 0; // Anzahl aller Fundstellen für alle Keywords in diesem Thema
          const lecturesWithThemeKeywords = new Set();
          
          Object.entries(keywordsDB).forEach(([lectureId, lecture]) => {
            const isNewGeneration = lecture.generationMethod && 
              (lecture.generationMethod.includes('unified-batch') || 
               lecture.generationMethod.includes('unified') ||
             lecture.generationMethod.includes('manual-add') ||
             lecture.generationMethod.includes('manual') ||
             lecture.generationMethod.includes('synced-from-summary-db'));
            
            if (isNewGeneration && lecture.keywords && Array.isArray(lecture.keywords)) {
              lecture.keywords.forEach(kw => {
                if (kw.term && themeData.keywords.some(tk => tk.toLowerCase() === kw.term.toLowerCase())) {
                  hitCount++; // Jedes Vorkommen zählt als Fundstelle
                  lecturesWithThemeKeywords.add(lectureId);
                }
              });
            }
          });
          
          statsDisplay.innerHTML = `${hitCount} ${hitCount === 1 ? 'Fundstelle' : 'Fundstellen'} · ${lecturesWithThemeKeywords.size} ${lecturesWithThemeKeywords.size === 1 ? 'Text' : 'Texte'}`;
          return;
        }
      }
    }
    
    // === FALL 3: DEFAULT - Keine Auswahl, zeige Gesamtstatistik ===
    const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
    let themesCount = 0;
    
    if (themesResponse.ok) {
      const themes = await themesResponse.json();
      themesCount = Object.keys(themes).length;
    }
    
    // Zähle eindeutige Keywords (aus ALLEN generierten Vorträgen)
    const uniqueKeywords = new Set();
    let newGenerationCount = 0;
    
    Object.values(keywordsDB).forEach(lecture => {
      const hasKeywords = lecture.generationMethod && 
        (lecture.generationMethod.includes('unified-batch') || 
         lecture.generationMethod.includes('unified') ||
         lecture.generationMethod.includes('manual-add') ||
         lecture.generationMethod.includes('manual') ||
         lecture.generationMethod.includes('synced-from-summary-db'));
      
      if (hasKeywords) {
        newGenerationCount++;
        if (lecture.keywords && Array.isArray(lecture.keywords)) {
          lecture.keywords.forEach(kw => {
            if (kw.term) uniqueKeywords.add(kw.term);
          });
        }
      }
    });
    
    statsDisplay.innerHTML = `${themesCount} Themen · ${uniqueKeywords.size} Schlagwörter · ${newGenerationCount} Texte`;
  } catch (error) {
    console.error('[TIMELINE-STATS] Fehler beim Laden der Statistiken:', error);
    statsDisplay.innerHTML = 'Fehler beim Laden der Statistiken';
  }
}

// Bei Eingabe im Timeline-Suchfeld: Dropdown zum passenden Schlagwort scrollen
function handleTimelineKeywordSearchInput(event) {
  const searchInput = event.target;
  const keywordDropdown = document.getElementById('timelineKeywordFilterAdmin');
  
  if (!keywordDropdown) return;
  
  const searchTerm = searchInput.value.trim().toLowerCase();
  
  // Wenn Suchfeld leer, zurück zu "Alle Schlagwörter"
  if (searchTerm.length === 0) {
    keywordDropdown.value = '';
    return;
  }
  
  if (searchTerm.length < 2) return;
  
  // Finde exaktes Schlagwort im Dropdown
  const options = keywordDropdown.options;
  for (let i = 0; i < options.length; i++) {
    const optionText = options[i].text.toLowerCase();
    if (optionText === searchTerm) {
      // Setze das Dropdown auf diesen Wert (scrollt automatisch)
      keywordDropdown.value = options[i].value;
      // Kurzes visuelles Feedback
      keywordDropdown.style.transition = 'background-color 0.3s';
      keywordDropdown.style.backgroundColor = 'rgba(70, 120, 134, 0.2)';
      setTimeout(() => {
        keywordDropdown.style.backgroundColor = '';
      }, 1000);
      break;
    }
  }
}

// Handle keyword search in timeline search field
async function handleTimelineKeywordSearch(event) {
  // Nur bei Enter-Taste ausführen
  if (event.key !== 'Enter') {
    return;
  }
  
  event.preventDefault();
  
  const searchInput = document.getElementById('timelineKeywordSearch');
  const keywordDropdown = document.getElementById('timelineKeywordFilterAdmin');
  
  if (!searchInput || !keywordDropdown) {
    console.error('[TIMELINE-SEARCH] Input oder Dropdown nicht gefunden');
    return;
  }
  
  const searchTerm = searchInput.value.trim();
  
  if (!searchTerm) {
    return; // Leeres Suchfeld ignorieren
  }
  
  // Prüfe, ob das Suchwort in der Dropdown-Liste vorhanden ist (case-insensitive)
  let foundOption = null;
  const options = keywordDropdown.options;
  
  for (let i = 0; i < options.length; i++) {
    const optionText = options[i].text.toLowerCase();
    const optionValue = options[i].value.toLowerCase();
    
    if (optionText === searchTerm.toLowerCase() || optionValue === searchTerm.toLowerCase()) {
      foundOption = options[i];
      break;
    }
  }
  
  // Leere das Suchfeld
  searchInput.value = '';
  
  if (foundOption) {
    // Schlagwort in der Liste gefunden: Dropdown setzen und normale Funktion aufrufen
    keywordDropdown.value = foundOption.value;
    await updateTimelineFilters('keyword');
  } else {
    // Schlagwort nicht in der Liste: GA-Suche durchführen
    await showKeywordSearchInTimeline(searchTerm);
  }
}

// Update timeline filters when changed
// changedBy: 'theme' = User hat Thema geändert, 'keyword' = User hat Keyword geändert
async function updateTimelineFilters(changedBy = 'keyword') {
  // Reset Flag - User wechselt zur normalen Timeline-Ansicht
  showingSearchResultsTimeline = false;
  
  const currentTheme = document.getElementById('timelineThemeFilterAdmin')?.value || '';
  const currentKeyword = document.getElementById('timelineKeywordFilterAdmin')?.value || '';
  
  // === FALL 1: Thema wurde geändert ? Zeige Keywords für dieses Thema ===
  if (changedBy === 'theme') {
    await loadKeywordsForTheme(currentTheme);
  }
  
  // === FALL 2: Keyword wurde geändert ? Zeige zugehöriges Thema ===
  if (changedBy === 'keyword' && currentKeyword !== '') {
    await setThemeForKeyword(currentKeyword);
  }
  
  // Timeline neu rendern
  // Prüfe: Wenn Keyword ausgewählt (mit oder ohne Thema), verwende IMMER GA-Suche
  if (currentKeyword) {
    showingSearchResultsTimeline = true;
    
    // Statistik-Anzeige leeren, bevor Timeline generiert wird
    const statsDisplay = document.getElementById('timelineStatsDisplay');
    if (statsDisplay) {
      statsDisplay.innerHTML = '';
    }
    
    await showKeywordSearchInTimeline(currentKeyword);
    return;
  }
  
  // Statistik aktualisieren (nur wenn kein Keyword ausgewählt)
  await updateTimelineStats();
  
  const timelineContainer = document.getElementById('timelineContainer');
  if (timelineContainer) {
    timelineContainer.innerHTML = '';
  }
  await renderTimelineContent();
}

// Hilfsfunktion: Lade Keywords für ein bestimmtes Thema
async function loadKeywordsForTheme(themeName) {
  const keywordSelect = document.getElementById('timelineKeywordFilterAdmin');
  if (!keywordSelect) return;
  
  let keywordsHTML = themeName 
    ? '<option value="">Schlagwörter zum Thema</option>' 
    : '<option value="">Schlagwörter</option>';
  
  if (themeName) {
    // Keywords für das gewählte Thema
    try {
      const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
      const keywordsDB = await loadKeywordsDatabase();
      
      if (themesResponse.ok) {
        const themes = await themesResponse.json();
        const themeData = themes[themeName];
        
        if (themeData && themeData.keywords) {
          // Sammle existierende Keywords aus Vorträgen
          const existingKeywords = new Set();
          Object.values(keywordsDB).forEach(lecture => {
            if (lecture.keywords && Array.isArray(lecture.keywords)) {
              lecture.keywords.forEach(kw => {
                if (kw.term) existingKeywords.add(kw.term.toLowerCase());
              });
            }
          });
          
          // Zeige ALLE Keywords des Themas (auch manuell hinzugefügte)
          themeData.keywords.sort().forEach(kw => {
            keywordsHTML += `<option value="${kw}">${kw}</option>`;
          });
        }
      }
    } catch (error) {
      console.error('[TIMELINE] Fehler beim Laden der Keywords:', error);
    }
  } else {
    // Alle Keywords
    try {
      const keywordsDB = await loadKeywordsDatabase();
      const allKeywords = new Set();
      
      Object.values(keywordsDB).forEach(lecture => {
        if (lecture.keywords && Array.isArray(lecture.keywords)) {
          lecture.keywords.forEach(kw => {
            if (kw.term) allKeywords.add(kw.term);
          });
        }
      });
      
      Array.from(allKeywords).sort().forEach(kw => {
        keywordsHTML += `<option value="${kw}">${kw}</option>`;
      });
    } catch (error) {
      console.error('[TIMELINE] Fehler beim Laden der Keywords:', error);
    }
  }
  
  keywordSelect.innerHTML = keywordsHTML;
}

// Hilfsfunktion: Finde und setze Thema für ein Keyword
async function setThemeForKeyword(keyword) {
  const themeSelect = document.getElementById('timelineThemeFilterAdmin');
  if (!themeSelect) {
    console.error('[TIMELINE] Theme-Dropdown nicht gefunden!');
    return;
  }
  
  try {
    const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
    if (themesResponse.ok) {
      const themes = await themesResponse.json();
      
      // Finde das Thema
      let foundTheme = null;
      for (const [themeName, themeData] of Object.entries(themes)) {
        if (themeData.keywords && Array.isArray(themeData.keywords)) {
          if (themeData.keywords.some(kw => kw.toLowerCase() === keyword.toLowerCase())) {
            foundTheme = themeName;
            break;
          }
        }
      }
      
      // Setze IMMER das Thema (oder leer, falls nicht gefunden)
      const newTheme = foundTheme || '';
      const oldTheme = themeSelect.value;
      
      themeSelect.value = newTheme;
      
      // Prüfe ob es funktioniert hat
      if (themeSelect.value !== newTheme) {
        console.error('[TIMELINE] FEHLER: Theme wurde nicht gesetzt!');
        console.error('[TIMELINE] Sollte sein:', newTheme);
        console.error('[TIMELINE] Ist aber:', themeSelect.value);
      } else {
        }
    }
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Finden des Themas:', error);
  }
}

async function renderTimeline() {
  // Wenn Suchergebnisse-Timeline angezeigt wird, nicht überschreiben
  if (showingSearchResultsTimeline) {
    return;
  }
  
  // Timeline wird in #results angezeigt (sidebar-content), wie alle anderen Tabs!
  const contentDiv = document.getElementById('results');
  if (!contentDiv) {
    console.error('[TIMELINE] results-Div nicht gefunden');
    return;
  }
  
  // WICHTIG: Beim Rendern KEINE alten Werte verwenden - Dropdowns sollen leer starten
  const currentTheme = '';
  const currentKeyword = '';
  
  // Lade Themen-Liste
  let themesHTML = '<option value="">Themen werden noch generiert...</option>';
  try {
    const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
    if (themesResponse.ok) {
      const themes = await themesResponse.json();
      if (Object.keys(themes).length > 0) {
        themesHTML = '<option value="">Bitte Thema wählen...</option>';
        Object.keys(themes).sort().forEach(theme => {
          const selected = theme === currentTheme ? 'selected' : '';
          themesHTML += `<option value="${theme} - ${selected} - ${theme}</option>`;
        });
      }
    }
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden der Themen:', error);
  }
  
  // Lade Keywords: Wenn Thema gewählt, nur dessen Keywords; sonst alle
  let keywordsHTML = currentTheme 
    ? '<option value="">Schlagwörter zum Thema</option>' 
    : '<option value="">Schlagwörter</option>';
  try {
    const keywordsDB = await loadKeywordsDatabase();
    
    if (currentTheme) {
      // Keywords NUR vom ausgewählten Thema (inkl. manuell hinzugefügte)
      const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
      if (themesResponse.ok) {
        const themes = await themesResponse.json();
        const themeData = themes[currentTheme];
        if (themeData && themeData.keywords) {
          // Sammle existierende Keywords (NUR aus neu generierten Vorträgen)
          const existingKeywords = new Set();
          Object.values(keywordsDB).forEach(lecture => {
            // Filtere: NUR Vorträge mit neuem unified generationMethod
            const isNewGeneration = lecture.generationMethod && 
              (lecture.generationMethod.includes('unified-batch') || 
               lecture.generationMethod.includes('unified') ||
             lecture.generationMethod.includes('manual-add') ||
             lecture.generationMethod.includes('manual') ||
             lecture.generationMethod.includes('synced-from-summary-db'));
            
            if (isNewGeneration && lecture.keywords && Array.isArray(lecture.keywords)) {
              lecture.keywords.forEach(kw => {
                if (kw.term) {
                  existingKeywords.add(kw.term.toLowerCase());
                }
              });
            }
          });
          
          // Zeige ALLE Keywords des Themas (auch manuell hinzugefügte)
          themeData.keywords.sort().forEach(kw => {
            const selected = kw === currentKeyword ? 'selected' : '';
            keywordsHTML += `<option value="${kw} - ${selected} - ${kw}</option>`;
          });
        }
      }
    } else {
      // Alle Keywords aus allen Vorträgen (NUR mit neuem unified System)
      const keywordsDB = await loadKeywordsDatabase();
      const allKeywords = new Set();
      
      Object.values(keywordsDB).forEach(lecture => {
        // Filtere: NUR Vorträge mit neuem unified generationMethod
        const isNewGeneration = lecture.generationMethod && 
          (lecture.generationMethod.includes('unified-batch') || 
           lecture.generationMethod.includes('unified') ||
           lecture.generationMethod.includes('manual-add') ||
           lecture.generationMethod.includes('manual') ||
           lecture.generationMethod.includes('synced-from-summary-db'));
        
        if (isNewGeneration && lecture.keywords && Array.isArray(lecture.keywords)) {
          lecture.keywords.forEach(kw => {
            if (kw.term) {
              allKeywords.add(kw.term);
            }
          });
        }
      });
      
      Array.from(allKeywords).sort().forEach(kw => {
        const selected = kw === currentKeyword ? 'selected' : '';
        keywordsHTML += `<option value="${kw} - ${selected} - ${kw}</option>`;
      });
    }
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Laden der Keywords:', error);
  }
  
  // Aktualisiere Filter-Dropdowns im Admin-Bereich (oben im Tab)
  const themeSelect = document.getElementById('timelineThemeFilterAdmin');
  const keywordSelect = document.getElementById('timelineKeywordFilterAdmin');
  
  if (themeSelect) {
    themeSelect.innerHTML = themesHTML;
    if (currentTheme) {
      themeSelect.value = currentTheme;
    }
  }
  
  if (keywordSelect) {
    keywordSelect.innerHTML = keywordsHTML;
    if (currentKeyword) {
      keywordSelect.value = currentKeyword;
    }
  }
  
  // Berechne und zeige Statistiken im Admin-Bereich
  await updateTimelineStats();
  
  const theme = currentTheme;
  const keyword = currentKeyword;
  
  // Prüfe ob bereits ein timelineContainer existiert (z.B. von Suchergebnissen)
  let timelineContainer = document.getElementById('timelineContainer');
  if (!timelineContainer) {
    // Nur wenn kein Container existiert, erstelle einen neuen
    let html = `<div id="timelineContainer"></div>`;
    contentDiv.innerHTML = html;
  }
  
  // Prüfe ob Thema oder Keyword ausgewählt
  if (!theme && !keyword) {
    const container = document.getElementById('timelineContainer');
    if (container && !showingSearchResultsTimeline) {
      // Nur Platzhalter anzeigen, wenn NICHT Suchergebnisse angezeigt werden
      container.innerHTML = '<div style="text-align: center; padding: 2rem; color: var(--secondary-text);"><em>Bitte Thema oder Schlagwort wählen oder Suchwort eingeben</em></div>';
    }
    return;
  }
  
  // Render Timeline Content (aber nur wenn keine Suchergebnisse angezeigt werden)
  if (!showingSearchResultsTimeline) {
    await renderTimelineContent();
  } else {
  }
}



async function renderTimelineContent() {
  const timelineContainer = document.getElementById('timelineContainer');
  if (!timelineContainer) return;
  
  const theme = document.getElementById('timelineThemeFilterAdmin')?.value || '';
  const keyword = document.getElementById('timelineKeywordFilterAdmin')?.value || '';
  
  if (!theme && !keyword) {
    timelineContainer.innerHTML = '<div style="text-align: center; padding: 2rem; color: var(--secondary-text);"><em>Bitte Thema oder Schlagwort wählen oder Suchwort eingeben</em></div>';
    return;
  }
  
  let html = '';
  
  try {
    // WICHTIG: Lade zuerst vollständige Vortragsdaten für korrekte Überschriften-Zuordnung
    await loadFullLecturesForTimeline();
    
    // Lade Keywords-Datenbank, Cluster und Summary-Database (für Überschriften)
    const keywordsDB = await loadKeywordsDatabase();
    const themesResponse = await fetch(`${API_BASE}/api/themes-database`);
    const clusters = themesResponse.ok ? await themesResponse.json() : {};
    const summaryDBResponse = await fetch(`${API_BASE}/summary-database.json`);
    const summaryDB = summaryDBResponse.ok ? await summaryDBResponse.json() : {};
    
    let keywordEntries = [];
    
    // Erstelle Mapping: Keyword -> Cluster
    const keywordToCluster = {};
    Object.entries(clusters).forEach(([clusterName, clusterData]) => {
      if (clusterData.keywords && Array.isArray(clusterData.keywords)) {
        clusterData.keywords.forEach(kw => {
          keywordToCluster[kw.toLowerCase()] = clusterName;
        });
      }
    });
    
    // FALL 1: Nur Thema (Cluster) ausgewählt
    if (theme && !keyword) {
      // Zeige alle Keywords die zu diesem Cluster gehören (NUR neue unified Generierungen)
      for (const lecture of Object.values(keywordsDB)) {
        // Filtere: NUR Vorträge mit neuem unified generationMethod
        const isNewGeneration = lecture.generationMethod && 
          (lecture.generationMethod.includes('unified-batch') || 
           lecture.generationMethod.includes('unified') ||
           lecture.generationMethod.includes('manual-add') ||
           lecture.generationMethod.includes('manual') ||
           lecture.generationMethod.includes('synced-from-summary-db'));
        
        if (isNewGeneration && lecture.keywords && Array.isArray(lecture.keywords)) {
          for (const kw of lecture.keywords) {
            const kwCluster = keywordToCluster[kw.term.toLowerCase()];
            if (kwCluster === theme) {
              // Finde beste Überschrift für diesen Absatz
              const bestHeading = await findBestHeadingForIndex(
                kw.index, 
                summaryDB[lecture.lectureId]?.headings || [],
                lecture.lectureId  // NEU: lectureId übergeben für korrekte Positionsermittlung
              );
              
              keywordEntries.push({
                lectureId: lecture.lectureId,
                date: lecture.date,
                year: lecture.year,
                keyword: {
                  ...kw,
                  heading: bestHeading || kw.heading || kw.term
                }
              });
            }
          }
        }
      }
      
      // Dedupliziere: Pro Vortrag sollte dieselbe Überschrift nur einmal erscheinen
      // (verschiedene Keywords können auf denselben Absatz zeigen)
      const uniqueEntries = new Map();
      keywordEntries.forEach(entry => {
        const key = `${entry.lectureId}|||${entry.keyword.heading}`;
        if (!uniqueEntries.has(key)) {
          uniqueEntries.set(key, entry);
        }
      });
      keywordEntries = Array.from(uniqueEntries.values());
      
    }
    
    // FALL 2: Cluster + Keyword ausgewählt
    // FALL 3: Nur Keyword ausgewählt (kein Cluster)
    // BEIDE FÄLLE: Verwende IMMER GA-Suche mit Keyword-Datenbank-Kombination
    if (keyword) {
      
      // Setze Flag, damit normale Timeline-Rendering übersprungen wird
      showingSearchResultsTimeline = true;
      
      // Rufe die neue Funktion auf, die Keyword-DB + GA-Suche kombiniert
      await showKeywordSearchInTimeline(keyword);
      return; // Wichtig: Beende hier, da showKeywordSearchInTimeline das Rendering übernimmt
    }
    
    if (keywordEntries.length === 0) {
      console.warn('[TIMELINE] Keine Keyword-Einträge gefunden!');
      console.warn('[TIMELINE] Theme:', theme, '| Keyword:', keyword);
      console.warn('[TIMELINE] Cluster-Keys:', Object.keys(clusters));
      timelineContainer.innerHTML = '<div style="text-align: center; padding: 2rem; color: var(--secondary-text);">Keine Keywords gefunden für diese Auswahl.</div>';
      return;
    }
    
    // Filtere Einträge ohne Jahr heraus (werden nicht angezeigt)
    const validEntries = keywordEntries.filter(e => e.year);
    const entriesWithoutYear = keywordEntries.length - validEntries.length;
    
    if (entriesWithoutYear > 0) {
      console.warn(`[TIMELINE] ${entriesWithoutYear} Einträge ohne Jahr-Feld werden nicht angezeigt`);
    }
    
    // Sammle alle Jahre aus validen Keywords
    const allYears = new Set();
    validEntries.forEach(e => { allYears.add(e.year); });
    const sortedYears = Array.from(allYears).sort((a, b) => a - b);
    
    // Gruppiere Keywords nach Jahr
    const keywordsByYear = {};
    
    validEntries.forEach(entry => {
      const year = entry.year;
      if (!keywordsByYear[year]) keywordsByYear[year] = [];
      keywordsByYear[year].push(entry);
    });
    
    // Sortiere Einträge nach Datum innerhalb jedes Jahres
    sortedYears.forEach(year => {
      if (keywordsByYear[year]) {
        keywordsByYear[year].sort((a, b) => (a.date || '').localeCompare(b.date || ''));
      }
    });
    
    // Render Timeline (ohne Header)
    html += `
      <div class="timeline-visualization">
        <!-- Mittlere Spalte: Timeline mit dynamisch positionierten Jahren -->
        <div class="timeline-center-column">
    `;
    
    // Render Jahreszahlen - Position wird via JS angepasst
    sortedYears.forEach(year => {
      html += `<div class="timeline-year-marker" data-year="${year}">${year}</div>`;
    });
    
    html += `
        </div>
        
        <!-- Keywords Spalte -->
        <div class="timeline-keywords-column">
    `;
    
    // Render Keyword-Einträge
    sortedYears.forEach(year => {
      const keywordsForYear = keywordsByYear[year] || [];
      
      keywordsForYear.forEach(entry => {
        const date = formatDate(entry.date);
        const lectureId = entry.lectureId || '';
        const keywordTerm = entry.keyword.term || '';
        
        // Robustes Parsing der LectureId (GA123/4 oder GA123/ oder GA/)
        const gaMatch = lectureId.match(/GA(\d*)\/(\d*)/);
        const gaNum = gaMatch && gaMatch[1] ? gaMatch[1] : '';
        const lecNum = gaMatch && gaMatch[2] ? gaMatch[2] : '';
        
        // Falls keine Nummern gefunden, zeige die komplette lectureId
        const rawLectureId = (gaNum || lecNum) ? `GA${gaNum} - ${lecNum}` : lectureId || 'GA/';
        const displayLectureId = formatLectureId(rawLectureId);
        
        let index = entry.keyword.index || '';
        // Entferne ^ vom Index falls vorhanden
        if (index.startsWith('^')) {
          index = index.substring(1);
        }
        
        // Zeige H3 UND H4 Überschriften für das ausgewählte Keyword
        const displayText = entry.keyword.heading || entry.keyword.term;
        const levelInfo = entry.keyword.level ? ` (${entry.keyword.level.toUpperCase()})` : '';
        
        // Escape Keyword für JavaScript String
        const escapedKeyword = keywordTerm.replace(/'/g, "\\'").replace(/"/g, '&quot;');
        
        html += `
          <div class="timeline-entry" data-year="${year}">
            <div><span class="timeline-entry-date">${date}</span><a href="#" onclick="showLecture('${lectureId}', '${index}', ['${escapedKeyword}']); return false;" class="ga-keyword-link">${displayLectureId}</a></div>
            <div class="timeline-entry-keywords">${displayText}</div>
          </div>
        `;
      });
    });
    
    html += `
        </div>
      </div>
    `;
    
    timelineContainer.innerHTML = html;
    
    // Positioniere Jahreszahlen dynamisch nach dem Rendern
    setTimeout(() => {
      positionYearMarkers();
    }, 50);
    
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Rendern:', error);
    timelineContainer.innerHTML = `<div style="text-align: center; padding: 2rem; color: #d9534f;">Fehler beim Laden der Timeline: ${error.message}</div>`;
  }
}

// Positioniere Jahreszahlen dynamisch auf Höhe des ersten Eintrags
function positionYearMarkers() {
  const yearMarkers = document.querySelectorAll('.timeline-year-marker');
  
  yearMarkers.forEach(marker => {
    const year = marker.getAttribute('data-year');
    
    // Finde alle Einträge dieses Jahres in beiden Spalten
    const leftEntries = document.querySelectorAll(`.timeline-themes-column .timeline-entry[data-year="${year}"]`);
    const rightEntries = document.querySelectorAll(`.timeline-keywords-column .timeline-entry[data-year="${year}"]`);
    
    // Bestimme ersten sichtbaren Eintrag (links oder rechts)
    let firstEntry = null;
    
    if (leftEntries.length > 0 && rightEntries.length > 0) {
      // Beide Spalten haben Einträge - nimm den höheren (kleinere offsetTop)
      const leftTop = leftEntries[0].offsetTop;
      const rightTop = rightEntries[0].offsetTop;
      firstEntry = leftTop <= rightTop ? leftEntries[0] : rightEntries[0];
    } else if (leftEntries.length > 0) {
      // Nur linke Spalte hat Einträge
      firstEntry = leftEntries[0];
    } else if (rightEntries.length > 0) {
      // Nur rechte Spalte hat Einträge
      firstEntry = rightEntries[0];
    }
    
    if (firstEntry) {
      // Positioniere Jahreszahl auf Höhe des ersten Eintrags
      const entryTop = firstEntry.offsetTop;
      const containerTop = marker.parentElement.offsetTop;
      const relativeTop = entryTop - containerTop;
      
      marker.style.position = 'absolute';
      marker.style.top = `${relativeTop}px`;
      marker.style.left = '50%';
      marker.style.transform = 'translateX(-50%)';
    }
  });
}

// Flag um zu verhindern, dass renderTimeline() die Suchergebnisse-Timeline überschreibt
let showingSearchResultsTimeline = false;
let searchResultsTimelineRunning = false; // Verhindert Doppelklicks

// Funktion für den Timeline-Button im Suche-Tab
function showSearchResultsInTimeline() {
  // Zeige Timeline direkt im Suche-Tab (nicht zum Timeline-Tab wechseln)
  // Die Ergebnisse werden im #results Element angezeigt
  showSearchResultsTimelineV2();
}

// Zeige Suchergebnisse im Timeline-Format (V2 - mit Links)
// Kann auch mit expliziten Ergebnissen aufgerufen werden
async function showSearchResultsTimelineV2(customResults = null, customKeywords = null) {
  // Verhindere Doppelklicks/mehrfache Ausführung
  if (searchResultsTimelineRunning) {
    return;
  }
  
  searchResultsTimelineRunning = true;
  
  // WICHTIG: Flag SOFORT setzen, bevor irgendwas anderes passiert
  showingSearchResultsTimeline = true;
  
  // Verwende #results (sidebar-content) wie alle anderen Tabs!
  const resultsDiv = document.getElementById('results');
  if (!resultsDiv) {
    console.error('[TIMELINE-V2] results-Div nicht gefunden');
    showingSearchResultsTimeline = false;
    searchResultsTimelineRunning = false;
    return;
  }
  
  // Statistik-Anzeige leeren, bevor Timeline generiert wird
  const statsDisplay = document.getElementById('timelineStatsDisplay');
  if (statsDisplay) {
    statsDisplay.innerHTML = '';
  }
  
  // Leere den Content-Bereich und erstelle neuen Container
  resultsDiv.innerHTML = '';
  
  // Erstelle neuen timelineContainer
  const timelineContainer = document.createElement('div');
  timelineContainer.id = 'timelineContainer';
  resultsDiv.appendChild(timelineContainer);
  
  // Zeige "GA-Suche läuft..." Nachricht
  timelineContainer.innerHTML = '<div style="text-align: center; padding: 2rem; color: var(--secondary-text); font-style: italic;">Führe GA-Suche durch, bitte einen Moment Geduld...</div>';
  
  // Verwende customResults falls übergeben, sonst searchResults (lokal) oder window._tempSearchResults
  // WICHTIG: searchResults enthält bereits die relevanz-gefilterten Treffer vom Backend
  // (Das Backend filtert nach Relevanz, bevor die Ergebnisse zurückgegeben werden)
  const resultsToUse = customResults || searchResults || window._tempSearchResults || [];
  
  // Log für Debugging: Zeige Anzahl der verwendeten Ergebnisse
  
  // Prüfe ob Suchergebnisse vorhanden sind
  if (!resultsToUse || resultsToUse.length === 0) {
    timelineContainer.innerHTML = '<div style="text-align: center; padding: 2rem; color: var(--secondary-text);">Keine Suchergebnisse vorhanden. Bitte führen Sie zuerst eine Suche durch.</div>';
    showingSearchResultsTimeline = false;
    searchResultsTimelineRunning = false;
    return;
  }
  
  try {
    // WICHTIG: Lade zuerst vollständige Vortragsdaten für korrekte Überschriften-Zuordnung
    await loadFullLecturesForTimeline();
    
    // Lade Summary-Database für Überschriften
    const summaryDBResponse = await fetch(`${API_BASE}/summary-database.json`);
    const summaryDB = summaryDBResponse.ok ? await summaryDBResponse.json() : {};
    
    // Sammle alle eindeutigen Buch-IDs aus den Ergebnissen
    const bookIds = new Set();
    resultsToUse.forEach(result => {
      if (result.isBook && result.ID) {
        bookIds.add(result.ID);
      }
    });
    
    // Lade Bücher-Daten für alle gefundenen Bücher
    if (bookIds.size > 0) {
      await Promise.all(Array.from(bookIds).map(bookId => loadBookForTimeline(bookId)));
    }
    
    // Konvertiere Suchergebnisse in Timeline-Einträge
    let timelineEntries = [];
    
    for (const result of resultsToUse) {
      // Extrahiere Jahr aus Datum (Format: "YYYY-MM-DD" oder aus fileName)
      let year = null;
      let dateString = result.date || '';
      
      // Für Bücher: Verwende yearRange falls vorhanden
      if (result.isBook && result.yearRange) {
        // Extrahiere Jahr aus yearRange (z.B. "1912-1913" -> nimm erstes Jahr)
        const yearMatch = result.yearRange.match(/^(\d{4})/);
        if (yearMatch) {
          year = parseInt(yearMatch[1]);
          dateString = result.yearRange;
        }
      }
      
      // Falls kein date-Feld, versuche aus fileName zu extrahieren
      if (!dateString && result.fileName) {
        dateString = extractDateFromFileName(result.fileName);
      }
      
      if (dateString) {
        // Extrahiere Jahr (Format: YYYY-MM-DD -> nimm erste 4 Zeichen)
        const yearMatch = dateString.match(/^(\d{4})/);
        if (yearMatch) {
          year = parseInt(yearMatch[1]);
        }
      }
      
      // Für Bücher ohne Jahr: Verwende Jahr aus GA-Nummer falls möglich
      if (!year && result.isBook && result.ID) {
        // Versuche Jahr aus GA-Nummer zu extrahieren (falls vorhanden)
        // Dies ist ein Fallback, da Bücher normalerweise ein Jahr haben sollten
      }
      
      // Hole die Überschriften für diesen Vortrag oder Buch
      const lectureHeadings = summaryDB[result.ID]?.headings || [];
      
      // Hole GA-Nummer und Titel
      const gaNumber = result.GA || (result.ID ? result.ID.match(/^GA(\d+)/)?.[1] : null);
      const title = result.title || result.fileName || result.ID;
      
      // Suchergebnisse haben index direkt im result-Objekt
      if (result.index) {
        // Finde beste Überschrift für diesen Index (funktioniert für Vorträge und Bücher)
        const bestHeading = await findBestHeadingForIndex(
          result.index, 
          lectureHeadings, 
          result.ID  // lectureId oder bookId übergeben für korrekte Positionsermittlung
        );
        
        timelineEntries.push({
          lectureId: result.ID,
          date: dateString,
          year: year,
          gaNumber: gaNumber,
          title: title,
          index: result.index,  // Direkt aus result, nicht aus snippet
          content: result.content || '',
          heading: bestHeading || title,
          isBook: result.isBook || false
        });
      } else {
        // Fallback: Wenn kein Index vorhanden
        timelineEntries.push({
          lectureId: result.ID,
          date: dateString,
          year: year,
          gaNumber: gaNumber,
          title: title,
          index: null,
          content: '',
          heading: title,
          isBook: result.isBook || false
        });
      }
    }
    
    // Entferne nur EXAKT identische Duplikate (gleiche lectureId, Datum UND heading)
    const uniqueEntries = [];
    const seenEntries = new Set();
    
    for (const entry of timelineEntries) {
      // Erstelle eindeutigen Schlüssel aus lectureId, Datum und heading
      const key = `${entry.lectureId} - ${entry.date} - ${entry.heading}`;
      
      if (!seenEntries.has(key)) {
        seenEntries.add(key);
        uniqueEntries.push(entry);
      }
    }
    
    timelineEntries = uniqueEntries;
    
    // Filtere Einträge ohne Jahr heraus
    const validEntries = timelineEntries.filter(e => e.year);
    const entriesWithoutYear = timelineEntries.length - validEntries.length;
    
    if (validEntries.length === 0) {
      let debugInfo = `<div style="text-align: left; padding: 1rem; background: #fff3cd; border-left: 4px solid #ffc107; font-size: 0.9em; margin-bottom: 1rem;">
        <strong>⚠️ Keine Suchergebnisse mit gültigen Datumswerten gefunden</strong><br><br>
        <strong>Debug-Informationen:</strong><br>
        | Gesamt-Suchergebnisse: ${resultsToUse.length}<br>
        | Timeline-Einträge erstellt: ${timelineEntries.length}<br>
        | Einträge mit gültigem Jahr: ${validEntries.length}<br>
        | Einträge ohne Jahr: ${entriesWithoutYear}<br>
      `;
      
      // Zeige Beispiel-Datum wenn vorhanden
      if (resultsToUse.length > 0 && resultsToUse[0].date) {
        debugInfo += `<br> |  Beispiel-Datum: "${resultsToUse[0].date}"<br>`;
      }
      
      debugInfo += `<br><em>Tipp: Bitte prüfen Sie die Browser-Konsole für weitere Details.</em></div>`;
      
      timelineContainer.innerHTML = debugInfo;
      showingSearchResultsTimeline = false;
      searchResultsTimelineRunning = false;
      return;
    }
    
    // Sammle alle Jahre
    const allYears = new Set();
    validEntries.forEach(e => { allYears.add(e.year); });
    const sortedYears = Array.from(allYears).sort((a, b) => a - b);
    
    // Gruppiere nach Jahr
    const entriesByYear = {};
    validEntries.forEach(entry => {
      const year = entry.year;
      if (!entriesByYear[year]) entriesByYear[year] = [];
      entriesByYear[year].push(entry);
    });
    
    // Sortiere Einträge nach Datum innerhalb jedes Jahres
    sortedYears.forEach(year => {
      if (entriesByYear[year]) {
        entriesByYear[year].sort((a, b) => (a.date || '').localeCompare(b.date || ''));
      }
    });
    
    // Berechne Anzahl einzigartiger Vorträge
    const uniqueLectures = new Set(validEntries.map(e => e.lectureId));
    const lectureCount = uniqueLectures.size;
    
    // Setze currentGANumber für Info-Button basierend auf dem ersten Ergebnis
    if (validEntries.length > 0 && validEntries[0].lectureId) {
      const firstLectureId = validEntries[0].lectureId;
      const gaMatch = firstLectureId.match(/^(GA\d{1,3}[a-z]?)/i);
      if (gaMatch) {
        currentGANumber = gaMatch[1];
        updateButtonStates(); // Aktualisiere Button-Status
      }
    }
    
    // Aktualisiere Statusanzeige im Admin-Bereich
    const statsDisplay = document.getElementById('timelineStatsDisplay');
    if (statsDisplay) {
      statsDisplay.innerHTML = `${validEntries.length} ${validEntries.length === 1 ? 'Fundstelle' : 'Fundstellen'} · ${lectureCount} ${lectureCount === 1 ? 'Text' : 'Texte'}`;
    }
    
    // Hole aktuelle Suchbegriffe für die Keyword-Links
    // Verwende customKeywords falls übergeben, sonst window._tempSearchKeywords oder aus Formular
    const searchKeywords = customKeywords || window._tempSearchKeywords || (() => {
      const currentWord1 = document.getElementById('word1')?.value.trim() || '';
      const currentWord2 = document.getElementById('word2')?.value.trim() || '';
      return [currentWord1, currentWord2].filter(w => w);
    })();
    
    // Erstelle Timeline HTML - EXAKT wie bei Schlagwort-Timeline! (OHNE Statuszeile)
    let html = `
      <div class="timeline-visualization">
        <!-- Mittlere Spalte: Timeline mit dynamisch positionierten Jahren -->
        <div class="timeline-center-column">
    `;
    
    // Render Jahreszahlen - Position wird via JS angepasst
    sortedYears.forEach(year => {
      html += `<div class="timeline-year-marker" data-year="${year}">${year}</div>`;
    });
    
    html += `
        </div>
        
        <!-- Keywords Spalte -->
        <div class="timeline-keywords-column">
    `;
    
    // Gruppiere Einträge nach Vortrag (lectureId) innerhalb jedes Jahres
    sortedYears.forEach(year => {
      const entries = entriesByYear[year];
      
      // Gruppiere nach Vortrag
      const groupedByLecture = {};
      entries.forEach(entry => {
        if (!groupedByLecture[entry.lectureId]) {
          groupedByLecture[entry.lectureId] = {
            lectureId: entry.lectureId,
            date: entry.date,
            year: entry.year,
            entries: []
          };
        }
        groupedByLecture[entry.lectureId].entries.push(entry);
      });
      
      // Render gruppierte Vorträge
      Object.values(groupedByLecture).forEach(lectureGroup => {
        const formattedDate = formatDate(lectureGroup.date);
        
        // Erstelle Links für Überschriften (ohne Markierung)
        const headingLinks = lectureGroup.entries.map(entry => {
          let cleanIndex = entry.index || '';
          if (cleanIndex && cleanIndex.startsWith('^')) {
            cleanIndex = cleanIndex.substring(1);
          }
          
          // HTML-Escape der Überschrift (ohne Markierung)
          const headingText = entry.heading || '';
          const escapedHeadingText = String(headingText)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
          
          // Erstelle Link zur Überschrift ohne Markierung
          const keywordsArray = searchKeywords.map(k => `'${k.replace(/'/g, "\\'")}'`).join(',');
          const escapedLectureId = entry.lectureId.replace(/'/g, "\\'");
          const linkHtml = `<a href="#" onclick="showLecture('${escapedLectureId}', '${cleanIndex}', [${keywordsArray}]); return false;" class="timeline-heading-link">${escapedHeadingText}</a>`;
          
          return linkHtml;
        });
        
        // Render Vortrag mit einmaligem Datum/GA-Nummer und mehreren Überschriften
        html += `
          <div class="timeline-entry" data-year="${year}">
            <div style="margin-bottom: 0.3rem;"><span class="timeline-entry-date">${formattedDate}</span>${formatLectureId(lectureGroup.lectureId)}</div>
              <div class="timeline-headings-list">
                ${headingLinks.join('')}
              </div>
          </div>
        `;
      });
    });
    
    html += `
        </div>
      </div>
    `;
    
    timelineContainer.innerHTML = html;
    
    // Positioniere Jahreszahlen dynamisch nach dem Rendern (wie bei Schlagwort-Timeline)
    setTimeout(() => {
      positionYearMarkers();
    }, 50);
    
    // Erfolgreich abgeschlossen - erlaube erneuten Aufruf
    searchResultsTimelineRunning = false;
    
  } catch (error) {
    console.error('[TIMELINE] Fehler beim Anzeigen der Suchergebnisse:', error);
    timelineContainer.innerHTML = `<div style="text-align: center; padding: 2rem; color: #d9534f;">Fehler beim Laden: ${error.message}</div>`;
    showingSearchResultsTimeline = false;
    searchResultsTimelineRunning = false;
  }
}

// Update switchTab function to load stats when timeline tab is opened
const originalSwitchTab = window.switchTab;
window.switchTab = function(tabName) {
  // WICHTIG: Entferne WZ-Sektion beim Tab-Wechsel
  const viewer = document.getElementById('viewer');
  if (viewer) {
    const chalkboardsSection = viewer.querySelector('.lecture-chalkboards-section');
    if (chalkboardsSection) {
      chalkboardsSection.remove();
      console.log('[CHALKBOARDS] WZ-Sektion beim Tab-Wechsel entfernt (Wrapper)');
    }
  }
  
  // WICHTIG: Reset WZ-Informationen beim Tab-Wechsel
  if (typeof openedFromChalkboard !== 'undefined') {
    openedFromChalkboard = null;
  }
  
  // WICHTIG: Wandtafeln-Buttons IMMER verstecken beim Tab-Wechsel (außer wenn zum GA-Tab gewechselt wird UND Wandtafeln aktiv sind)
  if (tabName !== 'ga' || !isChalkboardsViewActive) {
    // Buttons verstecken
    const chalkboardsInfoBtn = document.getElementById('chalkboardsInfoBtn');
    const chalkboardsSortBtn = document.getElementById('chalkboardsSortToggleBtn');
    if (chalkboardsInfoBtn) chalkboardsInfoBtn.style.display = 'none';
    if (chalkboardsSortBtn) chalkboardsSortBtn.style.display = 'none';
    
    // Bei Tab-Wechsel weg vom GA-Tab: Wandtafeln-Ansicht deaktivieren
    if (tabName !== 'ga' && typeof isChalkboardsViewActive !== 'undefined' && isChalkboardsViewActive) {
      isChalkboardsViewActive = false;
      selectedChalkboardsYearFilter = null;
      const chalkboardsBtn = document.getElementById('ga-chalkboards-btn');
      if (chalkboardsBtn) {
        chalkboardsBtn.style.background = 'transparent';
        chalkboardsBtn.style.color = 'var(--accent-color)';
        chalkboardsBtn.classList.remove('active');
      }
      if (typeof removeChalkboardsYearButtons === 'function') {
        removeChalkboardsYearButtons();
      }
      // Viewer leeren, damit Wandtafeln nicht im neuen Tab sichtbar bleiben
      if (tabName !== 'korrektur' && tabName !== 'thematic2') {
        const viewerEl = document.getElementById('viewer');
        if (viewerEl) {
          viewerEl.innerHTML = '';
        }
      }
    }
  }
  
  // Schließe Mitglieder-Panel beim Wechsel zu einem anderen Tab (Suche, GA, Themen, Timeline, Index)
  const isMembersPanelOpen = typeof isMembersPanelActive === 'function' && isMembersPanelActive();
  if (isMembersPanelOpen && typeof closeMembersPanel === 'function') {
    closeMembersPanel();
  }
  
  // Call original function
  if (originalSwitchTab) {
    originalSwitchTab(tabName);
  }
  
  // Load stats when timeline tab is opened
  if (tabName === 'timeline') {
    loadTimelineStats(); // Lädt Admin-Bereich
    
    // Nur renderTimeline() aufrufen wenn KEIN pending Keyword vorhanden
    // UND wenn keine Suchergebnisse-Timeline angezeigt wird
    if (!timelinePendingKeyword && !showingSearchResultsTimeline) {
      renderTimeline();
    }
  } else {
    // Bei Tab-Wechsel weg von Timeline: Reset Flag
    // Aber NICHT wenn eine Keyword-Navigation zum Themen-Tab gerade läuft
    if (!timelinePendingKeyword) {
      showingSearchResultsTimeline = false;
    }
  }
  
  // Load quotes when zitate tab is opened
  if (tabName === 'zitate') {
    loadQuotesForTab();
  }
  
  // Reset statistics when keyword/search tab is opened
  if (tabName === 'keyword') {
    // Lösche Suchergebnis-Statistik
    const resultInfo = document.getElementById('resultInfo');
    if (resultInfo) {
      resultInfo.textContent = '';
      resultInfo.innerHTML = '';
    }
    
    // Setze Dropdowns zurück
    if (typeof yearFilterDropdown !== 'undefined' && yearFilterDropdown) {
      yearFilterDropdown.clear();
    }
    if (typeof gaFilterDropdown !== 'undefined' && gaFilterDropdown) {
      gaFilterDropdown.clear();
    }
    
    // Setze serverInfo auf Default-Wert
    setTimeout(() => {
      if (typeof updateServerInfo === 'function') {
        updateServerInfo();
      }
    }, 50);
  }
};

