let availableGAVolumesForExport = [];

// Lade verfügbare GA-Bände für Export
async function loadGAVolumesForExport() {
  if (!isLocal) {
    alert('Diese Funktion ist nur lokal verfügbar.');
    return;
  }
  
  try {
    const response = await fetch(`${API_BASE}/api/keywords/available-ga-volumes`);
    if (!response.ok) throw new Error(`Fehler: ${response.status}`);
    
    const data = await response.json();
    availableGAVolumesForExport = data.volumes;
    
    const container = document.getElementById('gaVolumeExportCheckboxes');
    container.innerHTML = '';
    
    if (availableGAVolumesForExport.length === 0) {
      container.innerHTML = '<p style="text-align: center; color: var(--secondary-text); font-size: 0.85em;">Keine GA-Bände gefunden</p>';
      return;
    }
    
    availableGAVolumesForExport.forEach(vol => {
      const label = document.createElement('label');
      label.style.display = 'flex';
      label.style.alignItems = 'center';
      label.style.gap = '8px';
      label.style.padding = '4px';
      label.style.fontSize = '0.85em';
      label.style.color = 'var(--text-color)';
      label.style.cursor = 'pointer';
      
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = vol.volume.toLowerCase();
      checkbox.className = 'ga-volume-export-checkbox';
      checkbox.onchange = updateBatchExportButtonState;
      
      const textSpan = document.createElement('span');
      const suffix = vol.sourceOnly ? ' (noch nicht exportiert)' : '';
      textSpan.textContent = `${formatLectureId(vol.volume)} - ${vol.lectureCount} ${vol.lectureCount === 1 ? 'Vortrag' : 'Vorträge'}${suffix}`;
      
      label.appendChild(checkbox);
      label.appendChild(textSpan);
      container.appendChild(label);
    });
    
    updateBatchExportButtonState();
    
  } catch (error) {
    console.error('[GA-VOLUMES-EXPORT] Fehler:', error);
    alert('Fehler beim Laden der GA-Bände: ' + error.message);
  }
}

// Toggle alle GA-Bände auswählen/abwählen für Export
function toggleSelectAllGAForExport() {
  const checkboxes = document.querySelectorAll('.ga-volume-export-checkbox');
  const allChecked = Array.from(checkboxes).every(cb => cb.checked);
  
  checkboxes.forEach(cb => {
    cb.checked = !allChecked;
  });
  
  updateBatchExportButtonState();
}

// Update Export-Button Status
function updateBatchExportButtonState() {
  const checkboxes = document.querySelectorAll('.ga-volume-export-checkbox');
  const anyChecked = Array.from(checkboxes).some(cb => cb.checked);
  
  const btn = document.getElementById('batchExportGABtn');
  if (btn) {
    btn.disabled = !anyChecked;
  }
}

// Batch-Export für mehrere GA-Bände
async function batchExportGAVolumes() {
  if (!isLocal) {
    alert('Diese Funktion ist nur lokal verfügbar.');
    return;
  }
  
  const checkboxes = document.querySelectorAll('.ga-volume-export-checkbox:checked');
  const selectedVolumes = Array.from(checkboxes).map(cb => cb.value);
  
  if (selectedVolumes.length === 0) {
    alert('Bitte wählen Sie mindestens einen GA-Band aus!');
    return;
  }
  
  const confirmMsg = `${selectedVolumes.length} GA-Band${selectedVolumes.length > 1 ? 'e' : ''} exportieren?\n\n` +
    `Bände: ${selectedVolumes.map(v => formatLectureId(v)).join(', ')}\n\n` +
    `Dies wird:\n` +
    ` |  Die Markdown-Quellen aus Steiner_GA/ lesen\n` +
    ` |  Die JSON-Dateien neu generieren\n` +
    ` |  Bestehende Pagebreaks für diese Bände löschen\n\n` +
    `Der Export kann einige Minuten dauern.`;
  
  if (!confirm(confirmMsg)) {
    return;
  }
  
  const btn = document.getElementById('batchExportGABtn');
  const statusDiv = document.getElementById('batchExportStatus');
  const progressDiv = document.getElementById('batchExportProgress');
  const progressText = document.getElementById('batchExportProgressText');
  const progressPercent = document.getElementById('batchExportProgressPercent');
  const progressBar = document.getElementById('batchExportProgressBar');
  const resultsDiv = document.getElementById('batchExportResults');
  
  btn.disabled = true;
  btn.style.opacity = '0.5';
  checkboxes.forEach(cb => cb.disabled = true);
  statusDiv.style.display = 'inline';
  statusDiv.textContent = 'Exportiere...';
  progressDiv.style.display = 'block';
  resultsDiv.innerHTML = '';
  
  let successCount = 0;
  let errorCount = 0;
  const results = [];
  
  try {
    for (let i = 0; i < selectedVolumes.length; i++) {
      const gaVolume = selectedVolumes[i];
      const normalizedGA = gaVolume.toUpperCase();
      const progress = Math.round(((i + 1) / selectedVolumes.length) * 100);
      
      progressText.textContent = `Exportiere ${normalizedGA} - ${i + 1} - ${selectedVolumes.length})...`;
      progressPercent.textContent = `${progress}%`;
      progressBar.style.width = `${progress}%`;
      
      try {
        const resp = await fetch(`${API_BASE}/api/export/ga`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ gaNumber: normalizedGA })
        });
        
        const result = await resp.json();
        
        if (resp.ok && result.success) {
          successCount++;
          results.push({
            ga: normalizedGA,
            success: true,
            type: result.type,
            files: result.files?.length || 0,
            lectureCount: result.lectureCount || 0
          });
        } else {
          errorCount++;
          results.push({
            ga: normalizedGA,
            success: false,
            error: result.error || 'Unbekannter Fehler'
          });
        }
      } catch (error) {
        errorCount++;
        results.push({
          ga: normalizedGA,
          success: false,
          error: error.message
        });
      }
      
      // Kurze Pause zwischen Exports, um das System nicht zu überlasten
      if (i < selectedVolumes.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
    
    // Zeige Ergebnisse
    progressText.textContent = 'Export abgeschlossen!';
    progressPercent.textContent = '100%';
    progressBar.style.width = '100%';
    
    let resultsHTML = '<div style="display: grid; gap: 0.5rem;">';
    resultsHTML += `<div style="padding: 0.5rem; background: var(--sidebar-bg); border-radius: 4px; font-weight: bold;">
      Erfolgreich: ${successCount} | Fehler: ${errorCount}
    </div>`;
    
    results.forEach(r => {
      if (r.success) {
        resultsHTML += `
          <div style="padding: 0.5rem; background: #d4edda; border-radius: 4px; border: 1px solid #c3e6cb;">
            <strong style="color: #155724;">? ${r.ga}</strong>
            <div style="font-size: 0.8em; color: #155724; margin-top: 0.2rem;">
              Typ: ${r.type} | Dateien: ${r.files}${r.lectureCount ? ` | Vorträge: ${r.lectureCount}` : ''}
            </div>
          </div>
        `;
      } else {
        resultsHTML += `
          <div style="padding: 0.5rem; background: #f8d7da; border-radius: 4px; border: 1px solid #f5c6cb;">
            <strong style="color: #721c24;">? ${r.ga}</strong>
            <div style="font-size: 0.8em; color: #721c24; margin-top: 0.2rem;">
              ${r.error}
            </div>
          </div>
        `;
      }
    });
    
    resultsHTML += '</div>';
    resultsDiv.innerHTML = resultsHTML;
    
    statusDiv.textContent = successCount > 0 ? `? ${successCount} erfolgreich` : '? Fehler';
    statusDiv.style.color = successCount > 0 ? '#5cb85c' : '#d9534f';
    
  } catch (error) {
    console.error('[BATCH-EXPORT] Fehler:', error);
    statusDiv.textContent = '? Export fehlgeschlagen';
    statusDiv.style.color = '#d9534f';
    resultsDiv.innerHTML = `<div style="color: #d9534f;">Fehler: ${error.message}</div>`;
  } finally {
    btn.disabled = false;
    btn.style.opacity = '1';
    checkboxes.forEach(cb => cb.disabled = false);
  }
}

