async function generateThematicClusters() {
  const btn = document.getElementById('generateClustersBtn');
  const statusDiv = document.getElementById('clustersStatus');
  const resultsDiv = document.getElementById('clustersResults');
  
  if (!confirm('Thematische Cluster aus Seed-Keywords generieren?\n\nDies wird die Claude API verwenden und dauert ca. 1-2 Minuten.')) {
    return;
  }
  
  const originalText = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<em>In Bearbeitung...</em>';
  btn.style.opacity = '0.5';
  statusDiv.style.display = 'block';
  statusDiv.innerHTML = '<span style="color: var(--link-color);">? Generiere Themenbereiche...</span>';
  resultsDiv.style.display = 'none';
  
  try {
    const response = await fetch(`${API_BASE}/api/themes/generate-clusters-from-seeds`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      }
    });
    
    if (!response.ok) {
      throw new Error(`Server-Fehler: ${response.status}`);
    }
    
    const result = await response.json();
    
    if (result.success) {
      statusDiv.innerHTML = `<span style="color: #5cb85c;">? ${result.clustersCount} Themenbereiche generiert! Abdeckung: ${result.coverage}</span>`;
      
      // Zeige Ergebnisse
      displayClusters(result.clusters, result.totalSeedKeywords);
      
    } else {
      throw new Error(result.error || 'Unbekannter Fehler');
    }
    
  } catch (error) {
    console.error('[CLUSTERS] Fehler:', error);
    statusDiv.innerHTML = `<span style="color: #d9534f;">? Fehler: ${error.message}</span>`;
  } finally {
    btn.disabled = false;
    btn.innerHTML = originalText;
    btn.style.opacity = '1';
  }
}

async function loadExistingClusters() {
  const statusDiv = document.getElementById('clustersStatus');
  const resultsDiv = document.getElementById('clustersResults');
  
  statusDiv.style.display = 'block';
  statusDiv.innerHTML = '<span style="color: var(--link-color);">? Lade Cluster...</span>';
  
  try {
    const response = await fetch(`${API_BASE}/api/themes/clusters`);
    
    if (!response.ok) {
      throw new Error('Keine Cluster gefunden');
    }
    
    const data = await response.json();
    
    statusDiv.innerHTML = `<span style="color: #5cb85c;">? Cluster geladen (${data.clustersCount} Themenbereiche, Abdeckung: ${data.coverage})</span>`;
    displayClusters(data.clusters, data.seedKeywordsCount);
    
  } catch (error) {
    console.error('[CLUSTERS] Fehler:', error);
    statusDiv.innerHTML = `<span style="color: #d9534f;">? ${error.message}</span>`;
    resultsDiv.style.display = 'none';
  }
}

function displayClusters(clusters, totalKeywords) {
  const resultsDiv = document.getElementById('clustersResults');
  const contentDiv = document.getElementById('clustersResultsContent');
  
  let html = '<div style="display: grid; gap: 0.8rem;">';
  
  // Sortiere nach Anzahl Keywords
  const sortedClusters = Object.entries(clusters).sort((a, b) => 
    b[1].keywords.length - a[1].keywords.length
  );
  
  sortedClusters.forEach(([name, data]) => {
    const percentage = ((data.keywords.length / totalKeywords) * 100).toFixed(1);
    const keywordsPreview = data.keywords.slice(0, 15).join(', ');
    const moreCount = data.keywords.length > 15 ? ` ... (+${data.keywords.length - 15} weitere)` : '';
    const manualBadge = data.manual ? '<span style="margin-left: 0.5rem; padding: 2px 6px; background: #5cb85c; color: white; font-size: 0.7em; border-radius: 3px;">Manuell</span>' : '';
    
    html += `
      <div style="padding: 0.8rem; background: var(--background-color); border-radius: 4px; border: 1px solid var(--border-color);">
        <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 0.5rem;">
          <div>
            <strong style="color: var(--heading-color); font-size: 1em;">${name}</strong>${manualBadge}
          </div>
          <span style="color: var(--secondary-text); font-size: 0.85em;">${data.keywords.length} KWs (${percentage}%)</span>
        </div>
        <div style="color: var(--secondary-text); font-size: 0.85em; margin-bottom: 0.5rem;">
          ${data.description}
        </div>
        <div style="color: var(--text-color); font-size: 0.8em; font-style: italic;">
          ${keywordsPreview}${moreCount}
        </div>
      </div>
    `;
  });
  
  html += '</div>';
  
  contentDiv.innerHTML = html;
  resultsDiv.style.display = 'block';
}

// Manuellen Cluster hinzufügen
async function addManualCluster() {
  const nameInput = document.getElementById('manualClusterName');
  const descInput = document.getElementById('manualClusterDescription');
  const keywordsInput = document.getElementById('manualClusterKeywords');
  const btn = document.getElementById('addManualClusterBtn');
  const statusDiv = document.getElementById('manualClusterStatus');
  
  const name = nameInput.value.trim();
  const description = descInput.value.trim();
  const keywordsText = keywordsInput.value.trim();
  
  // Validierung
  if (!name) {
    alert('Bitte Cluster-Name eingeben!');
    return;
  }
  
  if (!keywordsText) {
    alert('Bitte mindestens ein Keyword eingeben!');
    return;
  }
  
  // Parse Keywords (ein Keyword pro Zeile)
  const keywords = keywordsText.split('\n')
    .map(kw => kw.trim())
    .filter(kw => kw.length > 0);
  
  if (keywords.length === 0) {
    alert('Bitte mindestens ein Keyword eingeben!');
    return;
  }
  
  btn.disabled = true;
  btn.textContent = 'Speichere...';
  statusDiv.style.display = 'none';
  
  try {
    const response = await fetch(`${API_BASE}/api/themes/add-cluster`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        name: name,
        description: description,
        keywords: keywords
      })
    });
    
    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Server-Fehler');
    }
    
    const result = await response.json();
    
    statusDiv.style.display = 'block';
    statusDiv.innerHTML = `<span style="color: #5cb85c;">? Cluster "${result.clusterName}" hinzugefügt mit ${result.keywordCount} Keywords! Gesamt: ${result.totalClusters} Cluster</span>`;
    
    // Formular zurücksetzen
    clearManualClusterForm();
    
    // Cluster neu laden
    await loadExistingClusters();
    
    // Timeline-Themes auch neu laden (falls Timeline geöffnet)
    await loadTimelineThemes();
    
  } catch (error) {
    console.error('[MANUAL-CLUSTER] Fehler:', error);
    statusDiv.style.display = 'block';
    statusDiv.innerHTML = `<span style="color: #d9534f;">? Fehler: ${error.message}</span>`;
  } finally {
    btn.disabled = false;
    btn.textContent = 'Cluster hinzufügen';
  }
}

function clearManualClusterForm() {
  document.getElementById('manualClusterName').value = '';
  document.getElementById('manualClusterDescription').value = '';
  document.getElementById('manualClusterKeywords').value = '';
  document.getElementById('manualClusterStatus').style.display = 'none';
}

// Cluster reorganisieren
async function reorganizeClusters() {
  const btn = document.getElementById('reorganizeClustersBtn');
  const statusDiv = document.getElementById('clustersStatus');
  
  if (!confirm('Cluster reorganisieren?\n\nAlle Keywords werden neu analysiert und optimal zugeordnet.\nDies kann einige Minuten dauern.')) {
    return;
  }
  
  const originalText = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<em>In Bearbeitung...</em>';
  statusDiv.style.display = 'block';
  statusDiv.innerHTML = '<span style="color: var(--link-color);">? Reorganisiere Cluster...</span>';
  
  try {
    const response = await fetch(`${API_BASE}/api/themes/reorganize-clusters`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      }
    });
    
    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Server-Fehler');
    }
    
    const result = await response.json();
    
    statusDiv.innerHTML = `<span style="color: #5cb85c;">? Reorganisation abgeschlossen!</span><br>` +
      `<span style="font-size: 0.85em;">Keywords verschoben: ${result.keywordsMoved || 0} | ` +
      `Neue Cluster: ${result.newClustersCreated || 0} | ` +
      `Total Cluster: ${result.totalClusters}</span>`;
    
    // Cluster neu laden
    await loadExistingClusters();
    await loadTimelineThemes();
    
  } catch (error) {
    console.error('[REORGANIZE] Fehler:', error);
    statusDiv.innerHTML = `<span style="color: #d9534f;">? Fehler: ${error.message}</span>`;
  } finally {
    btn.disabled = false;
    btn.innerHTML = originalText;
  }
}

