async function renameCluster() {
  const oldName = document.getElementById('clusterToEdit').value;
  const newName = document.getElementById('newClusterName').value.trim();
  const statusDiv = document.getElementById('clusterEditorStatus');
  
  if (!oldName) {
    alert('Bitte Cluster auswählen!');
    return;
  }
  
  if (!newName) {
    alert('Bitte neuen Namen eingeben!');
    return;
  }
  
  if (!confirm(`Cluster "${oldName}" zu "${newName}" umbenennen?`)) {
    return;
  }
  
  statusDiv.style.display = 'block';
  statusDiv.style.background = '#d9edf7';
  statusDiv.style.color = '#31708f';
  statusDiv.innerHTML = '? Verarbeite...';
  
  try {
    const response = await fetch(`${API_BASE}/api/themes/rename-cluster`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        oldName: oldName,
        newName: newName
      })
    });
    
    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Server-Fehler');
    }
    
    const result = await response.json();
    
    statusDiv.style.background = '#dff0d8';
    statusDiv.style.color = '#3c763d';
    statusDiv.innerHTML = `? Cluster umbenannt! ${result.totalClusters} Cluster gesamt`;
    
    // Neu laden
    await loadClustersForEdit();
    document.getElementById('newClusterName').value = '';
    
  } catch (error) {
    console.error('[RENAME-CLUSTER] Fehler:', error);
    statusDiv.style.background = '#f2dede';
    statusDiv.style.color = '#a94442';
    statusDiv.innerHTML = `? Fehler: ${error.message}`;
  }
}

async function mergeClusters() {
  const sourceCluster = document.getElementById('clusterToEdit').value;
  const targetCluster = document.getElementById('mergeTargetCluster').value;
  const statusDiv = document.getElementById('clusterEditorStatus');
  
  if (!sourceCluster || !targetCluster) {
    alert('Bitte beide Cluster auswählen!');
    return;
  }
  
  if (sourceCluster === targetCluster) {
    alert('Bitte unterschiedliche Cluster wählen!');
    return;
  }
  
  if (!confirm(`Cluster "${sourceCluster}" in "${targetCluster}" zusammenführen?\n\n"${sourceCluster}" wird gelöscht und alle Keywords werden zu "${targetCluster}" verschoben.`)) {
    return;
  }
  
  statusDiv.style.display = 'block';
  statusDiv.style.background = '#d9edf7';
  statusDiv.style.color = '#31708f';
  statusDiv.innerHTML = '? Führe zusammen...';
  
  try {
    const response = await fetch(`${API_BASE}/api/themes/merge-clusters`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        sourceCluster: sourceCluster,
        targetCluster: targetCluster
      })
    });
    
    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Server-Fehler');
    }
    
    const result = await response.json();
    
    statusDiv.style.background = '#dff0d8';
    statusDiv.style.color = '#3c763d';
    statusDiv.innerHTML = `? ${result.keywordsMerged} Keywords zusammengeführt! ${result.totalClusters} Cluster verbleibend`;
    
    // Neu laden
    await loadClustersForEdit();
    
  } catch (error) {
    console.error('[MERGE-CLUSTER] Fehler:', error);
    statusDiv.style.background = '#f2dede';
    statusDiv.style.color = '#a94442';
    statusDiv.innerHTML = `? Fehler: ${error.message}`;
  }
}

