function openBackupModal() {
  document.getElementById('backupModal').style.display = 'block';
  loadBackupList();
}

function closeBackupModal() {
  document.getElementById('backupModal').style.display = 'none';
}

async function loadBackupList() {
  const container = document.getElementById('backupListContainer');
  const type = document.getElementById('backupTypeSelect').value;
  
  container.innerHTML = '<div style="padding: 20px; text-align: center;"><div style="border: 2px solid var(--accent-color); border-top-color: transparent; border-radius: 50%; width: 30px; height: 30px; animation: spin 1s linear infinite; margin: 0 auto 10px;"></div>Lade Backups...</div>';
  
  try {
    const url = type === 'keywords' 
      ? 'http://localhost:3003/api/backups/list'
      : `http://localhost:3003/api/backups/list/${type}`;
      
    const response = await fetch(url);
    const data = await response.json();
    
    if (data.backups.length === 0) {
      container.innerHTML = '<div style="padding: 20px; text-align: center; color: #666;">Keine Backups gefunden</div>';
      return;
    }
    
    container.innerHTML = data.backups.map(backup => {
      const date = new Date(backup.modified);
      const sizeInfo = backup.isDirectory 
        ? '📁 Verzeichnis' 
        : `${(backup.size / 1024).toFixed(0)} KB`;
      const restoreDisabled = backup.isDirectory ? 'disabled title="Verzeichnis-Backups können nicht direkt wiederhergestellt werden"' : '';
      return `
        <div style="padding: 12px; border-bottom: 1px solid var(--border-color); display: flex; justify-content: space-between; align-items: center;">
          <div>
            <div style="font-weight: 500; font-size: 0.9rem;">${backup.name}</div>
            <div style="font-size: 0.75rem; color: var(--secondary-text); margin-top: 3px;">
              ${date.toLocaleString('de-DE')} - ${sizeInfo}
            </div>
          </div>
          <button class="depth-btn" onclick="restoreBackup('${backup.name}')" style="padding: 4px 12px; font-size: 0.8rem;" ${restoreDisabled} - ${backup.isDirectory ? 'Manuell' : 'Wiederherstellen'}
          </button>
        </div>
      `;
    }).join('');
  } catch (error) {
    console.error('Fehler beim Laden der Backups:', error);
    container.innerHTML = '<div style="padding: 20px; text-align: center; color: #dc3545;">Fehler beim Laden</div>';
  }
}

async function createManualBackup() {
  const type = document.getElementById('backupTypeSelect').value;
  
  try {
    const response = await fetch('http://localhost:3003/api/backups/create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type })
    });
    
    if (response.ok) {
      const data = await response.json();
      let msg;
      if (type === 'full') {
        msg = `${data.backupsCreated} Backups erstellt`;
      } else if (type === 'chalkboards') {
        msg = `Wandtafeln-Backup: ${data.count} Tafeln gesichert`;
      } else if (type === 'lectures') {
        msg = `Vortr\u00E4ge-Backup: ${data.count} Dateien gesichert`;
      } else if (type === 'books') {
        msg = `B\u00FCcher-Backup: ${data.count} Dateien gesichert`;
      } else if (type === 'code') {
        msg = `Code-Backup: ${data.count} Dateien gesichert`;
      } else if (type === 'html') {
        msg = `HTML-Backup: ${data.count} Dateien gesichert`;
      } else if (type === 'embeddings') {
        msg = `Embeddings-Backup erstellt`;
      } else if (data.message) {
        msg = data.message;
      } else {
        msg = `Backup erstellt: ${data.backup || data.backupFile}`;
      }
      showToast(msg, 'success');
      loadBackupList();
    } else {
      showToast('Fehler beim Erstellen des Backups', 'error');
    }
  } catch (error) {
    console.error('Fehler:', error);
    showToast('Fehler beim Erstellen des Backups', 'error');
  }
}

async function restoreBackup(backupName) {
  try {
    const response = await fetch('http://localhost:3003/api/backups/restore', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ backupName })
    });
    
    if (response.ok) {
      const data = await response.json();
      showToast(`Backup wiederhergestellt: ${data.entries} Eintr\u00E4ge`, 'success');
      closeBackupModal();
      setTimeout(() => location.reload(), 1500);
    } else {
      const errData = await response.json();
      showToast(`Fehler: ${errData.error}`, 'error');
    }
  } catch (error) {
    console.error('Fehler:', error);
    showToast('Fehler bei Wiederherstellung', 'error');
  }
}

