// ZITATE-SYSTEM
// ============================================================================

// Speichere neues Zitat aus dem Tab
// Hilfsfunktion: Extrahiert das Datum des Vortrags im ISO-Format (YYYY-MM-DD) oder null
function getLectureDateForQuote(lectureData) {
  if (!lectureData) return null;
  
  let date = lectureData.date || lectureData.dateString || '';
  
  if (!date) return null;
  
  // Wenn bereits im ISO-Format (YYYY-MM-DD), direkt zurückgeben
  if (date.match(/^\d{4}-\d{2}-\d{2}$/)) {
    return date;
  }
  
  // Versuche aus deutschem Format zu konvertieren (z.B. "21. Oktober 1908")
  const dateMatch = date.match(/(\d{1,2})\.\s*(Januar|Februar|März|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember)\s*(\d{4})/i);
  if (dateMatch) {
    const day = dateMatch[1].padStart(2, '0');
    const monthNames = {
      'januar': '01', 'februar': '02', 'märz': '03', 'april': '04',
      'mai': '05', 'juni': '06', 'juli': '07', 'august': '08',
      'september': '09', 'oktober': '10', 'november': '11', 'dezember': '12'
    };
    const month = monthNames[dateMatch[2].toLowerCase()];
    const year = dateMatch[3];
    if (month) {
      return `${year}-${month}-${day}`;
    }
  }
  
  // Fallback: Versuche aus location oder fileName zu extrahieren
  const locationDate = lectureData.location || lectureData.fileName || '';
  if (locationDate) {
    const locationMatch = locationDate.match(/(\d{1,2})\.\s*(Januar|Februar|März|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember)\s*(\d{4})/i);
    if (locationMatch) {
      const day = locationMatch[1].padStart(2, '0');
      const monthNames = {
        'januar': '01', 'februar': '02', 'märz': '03', 'april': '04',
        'mai': '05', 'juni': '06', 'juli': '07', 'august': '08',
        'september': '09', 'oktober': '10', 'november': '11', 'dezember': '12'
      };
      const month = monthNames[locationMatch[2].toLowerCase()];
      const year = locationMatch[3];
      if (month) {
        return `${year}-${month}-${day}`;
      }
    }
  }
  
  return null;
}


// Lade alle Zitate für den Verwaltungs-Tab
async function loadQuotesForTab() {
  try {
    const response = await fetch(`${API_BASE}/api/quotes`);
    if (!response.ok) throw new Error('Fehler beim Laden');
    
    const quotesDB = await response.json();
    const quotes = quotesDB.quotes || [];
    
    const countSpan = document.getElementById('quotesCount');
    const listDiv = document.getElementById('quotesList');
    
    if (countSpan) countSpan.textContent = quotes.length;
    
    if (!listDiv) return;
    
    if (quotes.length === 0) {
      listDiv.innerHTML = '<p style="color: #666; font-style: italic;">Keine Zitate vorhanden.</p>';
      return;
    }
    
    let html = '';
    quotes.forEach(quote => {
      const shortText = quote.text.length > 200 ? quote.text.substring(0, 200) + '...' : quote.text;
      // Konvertiere **text** zu <b>text</b> für Fettschrift
      const formattedText = shortText.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
      const activeClass = quote.isActive ? 'background: #e8f4f8; border-color: #467886;' : '';
      const usedDateStr = quote.usedSince ? new Date(quote.usedSince).toLocaleDateString('de-DE') : '';
      
      html += `
        <div style="padding: 0.75rem; border: 1px solid #ddd; border-radius: 4px; ${activeClass}">
          <div style="font-style: italic; margin-bottom: 0.3rem; line-height: 1.4;">"${formattedText}"</div>
          <div style="font-size: 0.7em; color: #999; margin-bottom: 0.3rem;">
            Hinzugefügt: ${new Date(quote.addedAt).toLocaleDateString('de-DE')}
          </div>
          <div style="display: flex; gap: 4px; flex-wrap: wrap; align-items: center;">
            <button onclick="showSingleQuotePopup('${quote.id}')" 
                    class="depth-btn" 
                    style="padding: 2px 8px; font-size: 0.75em; background: #5bc0de; color: white;">
              Popup
            </button>
            <button onclick="editQuote('${quote.id}')" 
                    class="depth-btn" 
                    style="padding: 2px 8px; font-size: 0.75em; background: #467886; color: white;">
              Bearbeiten
            </button>
            <button onclick="toggleQuoteActive('${quote.id}', ${quote.isActive})" 
                    class="depth-btn" 
                    style="padding: 2px 8px; font-size: 0.75em; background: ${quote.isActive ? '#5cb85c' : '#f0ad4e'}; color: white;">
              ${quote.isActive ? 'An' : 'Aus'}
            </button>
            ${quote.activeToggledAt ? `<span style="font-size: 0.65em; color: #888; margin-left: 2px;">${new Date(quote.activeToggledAt).toLocaleDateString('de-DE')}</span>` : ''}
            <button onclick="toggleQuoteUsed('${quote.id}', ${quote.isUsed || false})" 
                    class="depth-btn" 
                    style="padding: 2px 8px; font-size: 0.75em; background: ${quote.isUsed ? '#9b59b6' : '#95a5a6'}; color: white;">
              ${quote.isUsed ? 'Verwendet' : 'Unverwendet'}
            </button>
            ${usedDateStr ? `<span style="font-size: 0.7em; color: #666; margin-left: 4px;">${usedDateStr}</span>` : ''}
            <button onclick="deleteQuote('${quote.id}')" 
                    class="depth-btn" 
                    style="padding: 2px 8px; font-size: 0.75em; background: #d9534f; color: white;">
              Löschen
            </button>
          </div>
        </div>
      `;
    });
    
    listDiv.innerHTML = html;
    
    // Speichere die erste aktive Quote-ID in localStorage für index.html
    const activeQuotes = quotes.filter(q => q.isActive);
    if (activeQuotes.length > 0) {
      const currentActiveId = localStorage.getItem('activeQuoteId');
      // Nur aktualisieren, wenn keine gespeicherte ID existiert oder die gespeicherte nicht mehr aktiv ist
      if (!currentActiveId || !activeQuotes.find(q => q.id === currentActiveId)) {
        localStorage.setItem('activeQuoteId', activeQuotes[0].id);
      }
    } else {
      // Keine aktiven Zitate mehr
      localStorage.removeItem('activeQuoteId');
    }
    
  } catch (error) {
    console.error('[QUOTES] Fehler beim Laden:', error);
  }
}

// Toggle Zitat aktiv/inaktiv
async function toggleQuoteActive(quoteId, currentIsActive) {
  // Umkehren: wenn aktuell aktiv, dann deaktivieren und umgekehrt
  const newIsActive = !currentIsActive;
  
  try {
    const response = await fetch(`${API_BASE}/api/quotes/toggle-active`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ quoteId, isActive: newIsActive })
    });
    
    if (!response.ok) throw new Error('Server-Fehler');
    
    // Speichere aktive Quote-ID in localStorage für index.html
    if (newIsActive) {
      localStorage.setItem('activeQuoteId', quoteId);
      // Trigger storage event für andere Tabs/Fenster
      window.dispatchEvent(new Event('storage'));
    } else {
      // Wenn dieses Zitat deaktiviert wird, prüfe ob es das aktive war
      const currentActiveId = localStorage.getItem('activeQuoteId');
      if (currentActiveId === quoteId) {
        // Lade alle Zitate und finde das nächste aktive
        const quotesResponse = await fetch(`${API_BASE}/api/quotes`);
        if (quotesResponse.ok) {
          const quotesDB = await quotesResponse.json();
          const activeQuotes = (quotesDB.quotes || []).filter(q => q.isActive);
          if (activeQuotes.length > 0) {
            localStorage.setItem('activeQuoteId', activeQuotes[0].id);
          } else {
            localStorage.removeItem('activeQuoteId');
          }
          window.dispatchEvent(new Event('storage'));
        }
      }
    }
    
    await loadQuotesForTab();
    
  } catch (error) {
    console.error('[QUOTES] Fehler beim Toggle:', error);
    alert('Fehler: ' + error.message);
  }
}

// Toggle Zitat verwendet/unverwendet
async function toggleQuoteUsed(quoteId, currentIsUsed) {
  const newIsUsed = !currentIsUsed;
  
  try {
    const response = await fetch(`${API_BASE}/api/quotes/toggle-used`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ quoteId, isUsed: newIsUsed })
    });
    
    if (!response.ok) throw new Error('Server-Fehler');
    
    await loadQuotesForTab();
    
  } catch (error) {
    console.error('[QUOTES] Fehler beim Toggle Used:', error);
    alert('Fehler: ' + error.message);
  }
}

