// Zeige einzelnes Zitat im Popup
async function showSingleQuotePopup(quoteId) {
  try {
    const response = await fetch(`${API_BASE}/api/quotes`);
    if (!response.ok) return;
    
    const quotesDB = await response.json();
    const quote = (quotesDB.quotes || []).find(q => q.id === quoteId);
    
    if (!quote) {
      alert('Zitat nicht gefunden');
      return;
    }
    
    // Subtitle im Header leeren
    const subtitleElement = document.getElementById('quotesPopupSubtitle');
    if (subtitleElement) {
      subtitleElement.innerHTML = '';
    }
    
    const container = document.getElementById('quotesPopupContent');
    if (container) {
      // NUR lokales Feld verwenden: text
      let quoteText = quote.text || '';
      
      // Entferne Quellenangabe am Ende des Textes (z.B. "(08.03.1904, GA052/15)" oder "(GA267, 1905)")
      quoteText = quoteText.replace(/\s*\(\d{2}\.\d{2}\.\d{4},\s*GA\d+[a-z]?\/?\d*\)\s*$/i, '');
      quoteText = quoteText.replace(/\s*\(GA\d+[a-z]?\/?\d*,\s*\d{4}\)\s*$/i, '');
      quoteText = quoteText.replace(/\s*\(GA\d+[a-z]?\/?\d*\)\s*$/i, '');
      
      // Text mit Absätzen und Gedichtzeilen formatieren
      // Konvertiere **text** zu <b>text</b> für Fettschrift
      // Doppelte Zeilenumbrüche = neue Strophe (mit Abstand)
      // Einfache Zeilenumbrüche = Gedichtzeile (ohne Abstand, nur <br>)
      const stanzas = quoteText.split(/\n\s*\n/); // Teile bei Leerzeilen (Strophen)
      const formattedHtml = stanzas.map(stanza => {
        const lines = stanza.split('\n').map(line => line.trim()).filter(line => line.length > 0);
        const stanzaHtml = lines.map(line => line.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')).join('<br>');
        return `<p style="margin: 0.5rem 0;">${stanzaHtml}</p>`;
      }).join('');
      
      // GA-Nummer und Datum für Quellenangabe unter dem Zitat
      let sourceParts = [];
      if (quote.lectureId && quote.lectureId !== 'manual') {
        const displayId = formatLectureId(quote.lectureId);
        const paragraphIndex = quote.paragraphIndex || '';
        sourceParts.push(`<a href="#" onclick="navigateToLectureInTexteTab('${quote.lectureId}'); closeQuotesPopup(); return false;" style="color: var(--link-color, #467886); text-decoration: none; font-weight: bold;">${displayId}</a>`);
      }
      if (quote.date) {
        try {
          const dateObj = new Date(quote.date);
          const dateStr = dateObj.toLocaleDateString('de-DE', { day: 'numeric', month: 'long', year: 'numeric' });
          sourceParts.push(`<span style="font-weight: bold;">${dateStr}</span>`);
        } catch (e) {}
      }
      const sourceHtml = sourceParts.length > 0 ? `<div style="text-align: right; margin-top: 1rem; font-size: 0.9rem; font-style: normal;">${sourceParts.join(', ')}</div>` : '';
      
      container.innerHTML = `
        <div style="font-style: italic; line-height: 1.4; font-size: 1.0rem;">${formattedHtml}</div>
        ${sourceHtml}
      `;
    }
    
    // Position zurücksetzen
    if (typeof resetQuotesPopupPosition === 'function') {
      resetQuotesPopupPosition();
    }
    
    document.getElementById('quotesPopup').style.display = 'flex';
  } catch (error) {
    console.error('[QUOTES-POPUP] Fehler beim Anzeigen:', error);
  }
}

// Öffne Zitate-Popup
async function openQuotesPopup() {
  try {
    // Prüfe erst, ob aktive Zitate vorhanden sind
    const response = await fetch(`${API_BASE}/api/quotes`);
    if (!response.ok) return;
    
    const quotesDB = await response.json();
    const activeQuotes = (quotesDB.quotes || []).filter(q => q.isActive);
    
    // Nur öffnen, wenn aktive Zitate existieren
    if (activeQuotes.length === 0) {
      return;
    }
    
    // Öffne das erste aktive Zitat mit showSingleQuotePopup
    const firstActiveQuote = activeQuotes[0];
    if (firstActiveQuote && firstActiveQuote.id) {
      showSingleQuotePopup(firstActiveQuote.id);
    }
  } catch (error) {
    console.error('[QUOTES-POPUP] Fehler beim Prüfen:', error);
  }
}


// Schließe Zitate-Popup
function closeQuotesPopup() {
  document.getElementById('quotesPopup').style.display = 'none';
}

// Lade aktive Zitate ins Popup
async function loadQuotesIntoPopup() {
  try {
    const response = await fetch(`${API_BASE}/api/quotes`);
    if (!response.ok) throw new Error('Fehler beim Laden');
    
    const quotesDB = await response.json();
    const activeQuotes = (quotesDB.quotes || []).filter(q => q.isActive);
    
    const container = document.getElementById('quotesPopupContent');
    if (!container) return;
    
    if (activeQuotes.length === 0) {
      container.innerHTML = '<p style="color: #666; font-style: italic; text-align: center;">Keine aktiven Zitate vorhanden.</p>';
      return;
    }
    
    // Zeige zufälliges Zitat
    const randomQuote = activeQuotes[Math.floor(Math.random() * activeQuotes.length)];
    
    // GA-Nummer und Datum im Subtitle (NUR lokale Zitate!)
    const subtitleElement = document.getElementById('quotesPopupSubtitle');
    if (subtitleElement) {
      let htmlParts = [];
      
      // GA-Nummer als fetter, klickbarer Link
      if (randomQuote.lectureId && randomQuote.lectureId !== 'manual') {
        const displayId = formatLectureId(randomQuote.lectureId);
        const paragraphIndex = randomQuote.paragraphIndex || '';
        htmlParts.push(`<a href="#" onclick="navigateToLectureInTexteTab('${randomQuote.lectureId}'); closeQuotesPopup(); return false;" style="color: var(--link-color, #467886); text-decoration: none; font-weight: bold;">${displayId}</a>`);
      }
      
      // Datum im Format "8. März 1904" (nicht klickbar, fett)
      if (randomQuote.date) {
        try {
          const dateObj = new Date(randomQuote.date);
          const dateStr = dateObj.toLocaleDateString('de-DE', { day: 'numeric', month: 'long', year: 'numeric' });
          htmlParts.push(`<span style="font-weight: bold;">${dateStr}</span>`);
        } catch (e) {
          // Ignoriere Fehler beim Datum
        }
      }
      
      subtitleElement.innerHTML = htmlParts.join(', ');
    }
    
    // NUR lokales Feld verwenden: text
    let quoteText = randomQuote.text || '';
    
    // Entferne Quellenangabe am Ende des Textes (z.B. "(08.03.1904, GA052/15)" oder "(GA267, 1905)")
    quoteText = quoteText.replace(/\s*\(\d{2}\.\d{2}\.\d{4},\s*GA\d+[a-z]?\/?\d*\)\s*$/i, '');
    quoteText = quoteText.replace(/\s*\(GA\d+[a-z]?\/?\d*,\s*\d{4}\)\s*$/i, '');
    quoteText = quoteText.replace(/\s*\(GA\d+[a-z]?\/?\d*\)\s*$/i, '');
    
    // Text mit mehr Abstand zwischen Absätzen
    const formattedText = quoteText.split('\n').map(para => para.trim()).filter(para => para.length > 0).join('\n\n');
    
    container.innerHTML = `
      <div style="font-style: italic; white-space: pre-wrap; line-height: 1.6;">
        ${formattedText}
      </div>
    `;
    
  } catch (error) {
    console.error('[QUOTES-POPUP] Fehler:', error);
  }
}

