let saveQuoteData = null;

// Öffne Dialog zum Speichern eines Zitats aus einem Absatz oder markiertem Text
function openSaveQuoteDialog(paragraphIndex, element) {
  if (!currentLectureData) {
    console.warn('[SAVE-QUOTE] Kein Vortrag geladen');
    return;
  }
  
  // Prüfe zuerst, ob Text markiert ist
  const selection = window.getSelection();
  const selectedText = selection.toString().trim();
  
  let quoteText = '';
  
  if (selectedText && selectedText.length > 0) {
    // Verwende den markierten Text (kann auch über mehrere Absätze gehen)
    quoteText = selectedText;
  } else {
    // Fallback: Extrahiere gesamten Absatztext (entferne HTML-Tags)
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = element.innerHTML;
    quoteText = tempDiv.textContent.trim();
  }
  
  // Extrahiere Datum des Vortrags, falls vorhanden
  const lectureDate = getLectureDateForQuote(currentLectureData);
  
  // Speichere Daten für später
  saveQuoteData = {
    lectureId: currentLectureData.ID,
    paragraphIndex: paragraphIndex,
    date: lectureDate || null, // null statt leerem String wenn kein Datum vorhanden
    text: quoteText
  };
  
  // Fülle Modal-Felder
  document.getElementById('saveQuoteLectureId').textContent = saveQuoteData.lectureId;
  document.getElementById('saveQuoteParagraphIndex').textContent = paragraphIndex;
  document.getElementById('saveQuoteText').value = quoteText;
  document.getElementById('saveQuoteActive').checked = true;
  
  // Zeige Modal
  document.getElementById('saveQuoteModal').style.display = 'block';
  document.getElementById('saveQuoteOverlay').style.display = 'block';
  
  // Fokus auf Textarea
  setTimeout(() => {
    document.getElementById('saveQuoteText').focus();
  }, 100);
  
  }

// Globaler Event-Listener für Strg+Shift+Mouseup mit markiertem Text (Zitat speichern)
document.addEventListener('mouseup', function(event) {
  // Nur bei Strg+Shift-Taste
  if (!event.ctrlKey || !event.shiftKey) return;
  
  // Prüfe ob Text markiert ist
  const selection = window.getSelection();
  const selectedText = selection.toString().trim();
  
  if (selectedText && selectedText.length > 0) {
    event.preventDefault();
    
    // Finde den Absatz, in dem die Selektion startet
    let paragraphIndex = '';
    let anchorNode = selection.anchorNode;
    let paragraphElement = null;
    
    // Suche nach dem übergeordneten .paragraph Element oder para- ID
    while (anchorNode && anchorNode !== document) {
      if (anchorNode.nodeType === 1) { // Element node
        // Prüfe auf para- ID
        if (anchorNode.id && anchorNode.id.startsWith('para-')) {
          paragraphIndex = anchorNode.id.replace('para-', '');
          paragraphElement = anchorNode;
          break;
        }
        // Prüfe auf data-index Attribut
        if (anchorNode.dataset && anchorNode.dataset.index) {
          paragraphIndex = anchorNode.dataset.index;
          paragraphElement = anchorNode;
          break;
        }
        // Prüfe auf .paragraph Klasse mit onclick
        if (anchorNode.classList && anchorNode.classList.contains('paragraph')) {
          const onclick = anchorNode.getAttribute('onclick');
          if (onclick) {
            const match = onclick.match(/selectParagraphForKeyword\('([^']+)'/);
            if (match) {
              paragraphIndex = match[1];
            }
          }
          paragraphElement = anchorNode;
          break;
        }
      }
      anchorNode = anchorNode.parentNode;
    }
    
    // Strg+Shift+Klick: Immer das normale Zitate-System verwenden (Tab Zitate)
    // NICHT das Members-System (für Members gibt es das Context-Menu)
    if (currentLectureData) {
      openSaveQuoteDialogWithSelection(selectedText, paragraphIndex);
    }
  }
});

