// Bestätige und speichere Zitat
async function confirmSaveQuote() {
  if (!saveQuoteData) {
    console.warn('[SAVE-QUOTE] Keine Daten vorhanden');
    return;
  }
  
  const statusDiv = document.getElementById('saveQuoteStatus');
  const quoteText = document.getElementById('saveQuoteText').value.trim();
  const isActive = document.getElementById('saveQuoteActive').checked;
  
  if (!quoteText) {
    statusDiv.style.display = 'block';
    statusDiv.style.background = '#f8d7da';
    statusDiv.style.color = '#721c24';
    statusDiv.textContent = 'Bitte geben Sie einen Zitat-Text ein.';
    return;
  }
  
  try {
    statusDiv.style.display = 'block';
    statusDiv.style.background = '#d1ecf1';
    statusDiv.style.color = '#0c5460';
    statusDiv.textContent = 'Speichere Zitat...';
    
    const quoteData = {
      text: quoteText,
      lectureId: saveQuoteData.lectureId,
      paragraphIndex: saveQuoteData.paragraphIndex,
      isActive: isActive
    };
    
    // Füge Datum nur hinzu, wenn es vorhanden ist
    if (saveQuoteData.date) {
      quoteData.date = saveQuoteData.date;
    }
    
    const response = await fetch(`${API_BASE}/api/quotes/add`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(quoteData)
    });
    
    if (!response.ok) {
      throw new Error('Server-Fehler');
    }
    
    statusDiv.style.background = '#d4edda';
    statusDiv.style.color = '#155724';
    statusDiv.textContent = '? Zitat erfolgreich gespeichert!';
    
    // Aktualisiere Zitate-Liste im Tab
    await loadQuotesForTab();
    
    // MB aktualisieren falls offen (unabhängig vom aktiven Tab)
    if (typeof invalidateMembersCache === 'function') {
      invalidateMembersCache('quotes');
    }
    if (typeof updateMembersPanelIfOpen === 'function') {
      await updateMembersPanelIfOpen('quotes');
    }
    
    // Schließe Dialog nach kurzer Verzögerung
    setTimeout(() => {
      closeSaveQuoteDialog();
    }, 1500);
    
    } catch (error) {
    console.error('[SAVE-QUOTE] Fehler:', error);
    statusDiv.style.background = '#f8d7da';
    statusDiv.style.color = '#721c24';
    statusDiv.textContent = 'Fehler: ' + error.message;
  }
}

