async function openAddKeywordModal(lectureId) {
  if (!isLocal) return;
  
  addKeywordTargetLectureId = lectureId;
  document.getElementById('addKeywordLectureId').textContent = lectureId;
  document.getElementById('addKeywordNameInput').value = '';
  document.getElementById('addKeywordStatus').style.display = 'none';
  
  // Zeige ausgewählten Absatz an (falls vorhanden)
  const paragraphInfo = document.getElementById('addKeywordParagraphInfo');
  if (selectedParagraphIndex) {
    paragraphInfo.style.display = 'block';
    paragraphInfo.innerHTML = `<span style="color: #5cb85c;">? Absatz ausgewählt: ${selectedParagraphIndex}</span>`;
  } else {
    paragraphInfo.style.display = 'block';
    paragraphInfo.innerHTML = `<span style="color: #666;">? Kein Absatz ausgewählt (verwendet ersten Absatz)</span>`;
  }
  
  // Lade bereits verknüpfte Keywords für den ausgewählten Absatz
  if (selectedParagraphIndex) {
    await loadExistingKeywordsForParagraph(lectureId, selectedParagraphIndex);
  } else {
    // Verstecke Sektion wenn kein Absatz ausgewählt
    document.getElementById('existingKeywordsSection').style.display = 'none';
  }
  
  // Lade Cluster-Liste
  try {
    const response = await fetch(`${API_BASE}/api/themes-database`);
    if (response.ok) {
      const themes = await response.json();
      const select = document.getElementById('addKeywordClusterSelect');
      select.innerHTML = '<option value="">Kein Cluster</option>';
      
      Object.keys(themes).sort().forEach(themeName => {
        const option = document.createElement('option');
        option.value = themeName;
        option.textContent = themeName;
        select.appendChild(option);
      });
    }
  } catch (error) {
    console.error('[ADD-KW] Fehler beim Laden der Cluster:', error);
  }
  
  document.getElementById('addKeywordModal').style.display = 'block';
  document.getElementById('addKeywordOverlay').style.display = 'block';
  document.getElementById('addKeywordNameInput').focus();
}

// Lade bereits verknüpfte Keywords für einen Absatz
async function loadExistingKeywordsForParagraph(lectureId, paragraphIndex) {
  try {
    const response = await fetch(`${API_BASE}/api/get-paragraph-keywords`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ lectureId, paragraphIndex })
    });
    
    if (!response.ok) {
      console.error('[LOAD-EXISTING-KW] Fehler beim Laden:', response.status);
      document.getElementById('existingKeywordsSection').style.display = 'none';
      return;
    }
    
    const data = await response.json();
    const keywords = data.keywords || [];
    
    const section = document.getElementById('existingKeywordsSection');
    const list = document.getElementById('existingKeywordsList');
    const count = document.getElementById('existingKeywordsCount');
    
    if (keywords.length === 0) {
      section.style.display = 'none';
      return;
    }
    
    // Zeige die Sektion
    section.style.display = 'block';
    count.textContent = keywords.length;
    
    // Rendere Keywords als Pills mit Löschen-Button
    list.innerHTML = keywords.map(kw => `
      <div style="display: flex; align-items: center; gap: 5px; background: var(--background-color); padding: 5px 8px; border-radius: 4px; border: 1px solid #ccc; font-size: 0.85em;">
        <span style="color: var(--text-color);">${kw.term}</span>
        <button onclick="removeKeywordFromParagraph('${kw.term.replace(/'/g, "\\'")}', event)" 
          style="background: #dc3545; color: white; border: none; border-radius: 3px; padding: 2px 6px; cursor: pointer; font-size: 0.75em; line-height: 1;" 
          title="Keyword entfernen">×</button>
      </div>
    `).join('');
    
  } catch (error) {
    console.error('[LOAD-EXISTING-KW] Fehler:', error);
    document.getElementById('existingKeywordsSection').style.display = 'none';
  }
}

// Entferne ein Keyword von einem Absatz
async function removeKeywordFromParagraph(keywordTerm, event) {
  event.stopPropagation();
  
  try {
    const response = await fetch(`${API_BASE}/api/remove-keyword-from-paragraph`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        lectureId: addKeywordTargetLectureId, 
        paragraphIndex: selectedParagraphIndex, 
        keywordTerm 
      })
    });
    
    if (!response.ok) {
      const error = await response.json();
      const statusDiv = document.getElementById('addKeywordStatus');
      statusDiv.style.display = 'block';
      statusDiv.style.background = '#f8d7da';
      statusDiv.style.color = '#721c24';
      statusDiv.textContent = `Fehler beim Entfernen: ${error.error || 'Unbekannter Fehler'}`;
      setTimeout(() => { statusDiv.style.display = 'none'; }, 3000);
      return;
    }
    
    const data = await response.json();
    // Entferne das Keyword aus der aktuellen Summary
    if (currentLectureSummary && currentLectureSummary.lectureKeywords) {
      currentLectureSummary.lectureKeywords = currentLectureSummary.lectureKeywords.filter(
        kw => !(kw.term === keywordTerm && kw.index === selectedParagraphIndex)
      );
      // Aktualisiere die Keywords-Anzeige unter der Summary
      updateKeywordsDisplay();
      }
    
    // Aktualisiere die Anzeige der verknüpften Keywords im Modal
    await loadExistingKeywordsForParagraph(addKeywordTargetLectureId, selectedParagraphIndex);
    
    // Zeige Erfolg-Nachricht
    const statusDiv = document.getElementById('addKeywordStatus');
    statusDiv.style.display = 'block';
    statusDiv.style.background = '#d4edda';
    statusDiv.style.color = '#155724';
    statusDiv.textContent = `? Keyword "${keywordTerm}" entfernt`;
    
    setTimeout(() => {
      statusDiv.style.display = 'none';
    }, 2000);
    
  } catch (error) {
    console.error('[REMOVE-KW] Fehler:', error);
    const statusDiv = document.getElementById('addKeywordStatus');
    statusDiv.style.display = 'block';
    statusDiv.style.background = '#f8d7da';
    statusDiv.style.color = '#721c24';
    statusDiv.textContent = 'Fehler beim Entfernen des Keywords';
    setTimeout(() => { statusDiv.style.display = 'none'; }, 3000);
  }
}

function closeAddKeywordModal() {
  document.getElementById('addKeywordModal').style.display = 'none';
  document.getElementById('addKeywordOverlay').style.display = 'none';
  addKeywordTargetLectureId = null;
  
  // Leere Eingabefelder
  document.getElementById('addKeywordNameInput').value = '';
  document.getElementById('addKeywordDescInput').value = '';
  document.getElementById('addKeywordClusterSelect').value = '';
  
  // Entferne Absatz-Markierung
  document.querySelectorAll('.paragraph.selected-for-keyword').forEach(el => {
    el.classList.remove('selected-for-keyword');
  });
  selectedParagraphIndex = null;
}

async function addKeywordToLecture() {
  const keywordName = document.getElementById('addKeywordNameInput').value.trim();
  const keywordDesc = document.getElementById('addKeywordDescInput').value.trim();
  const cluster = document.getElementById('addKeywordClusterSelect').value;
  const statusDiv = document.getElementById('addKeywordStatus');
  
  if (!keywordName) {
    statusDiv.style.display = 'block';
    statusDiv.style.background = '#f8d7da';
    statusDiv.style.color = '#721c24';
    statusDiv.textContent = 'Bitte geben Sie einen Keyword-Namen ein';
    return;
  }
  
  if (!addKeywordTargetLectureId) {
    statusDiv.style.display = 'block';
    statusDiv.style.background = '#f8d7da';
    statusDiv.style.color = '#721c24';
    statusDiv.textContent = 'Fehler: Keine Vortrag-ID';
    return;
  }
  
  statusDiv.style.display = 'block';
  statusDiv.style.background = '#d1ecf1';
  statusDiv.style.color = '#0c5460';
  statusDiv.textContent = 'Füge Keyword hinzu...';
  
  try {
    // Erstelle Keyword-Objekt (mit ausgewähltem Absatz-Index)
    const keywordIndex = selectedParagraphIndex || "^manual";
    
    const newKeyword = {
      term: keywordName,
      index: keywordIndex,
      heading: keywordDesc || "Manuell hinzugefügt",  // Verwende eigenen Text oder Platzhalter
      customDescription: !!keywordDesc,  // Flag: true wenn eigener Text
      source: "manual",
      matchType: "manual",
      matchedExisting: null,
      summaryMentioned: false,
      confidence: 1.0,
      level: "h3"
    };
    
    // Rufe Backend-Endpoint auf (aktualisiert BEIDE Datenbanken)
    const response = await fetch(`${API_BASE}/api/add-keyword-to-lecture`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        lectureId: addKeywordTargetLectureId,
        keyword: newKeyword
      })
    });
    
    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || 'Server-Fehler');
    }
    
    const result = await response.json();
    
    // Füge zu Cluster hinzu (wenn gewählt)
    if (cluster) {
      await fetch(`${API_BASE}/keywords/move-to-cluster`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ keyword: keywordName, targetCluster: cluster })
      });
    }
    
    // Erfolg!
    statusDiv.style.background = '#d4edda';
    statusDiv.style.color = '#155724';
    statusDiv.textContent = `? Keyword "${keywordName}" hinzugefügt${cluster ? ' zu Cluster "' + cluster + '"' : ''} (in beiden DBs)`;
    
    // Aktualisiere die Liste der verknüpften Keywords, falls ein Absatz ausgewählt ist
    if (selectedParagraphIndex) {
      await loadExistingKeywordsForParagraph(addKeywordTargetLectureId, selectedParagraphIndex);
    }
    
    // Füge das neue Keyword zur aktuellen Summary hinzu und aktualisiere die Anzeige
    if (currentLectureSummary) {
      if (!currentLectureSummary.lectureKeywords) {
        currentLectureSummary.lectureKeywords = [];
      }
      currentLectureSummary.lectureKeywords.push(newKeyword);
      
      // Aktualisiere nur den Keywords-Bereich unter der Summary
      updateKeywordsDisplay();
      }
    
    // Leere Eingabefeld für weiteres Hinzufügen
    document.getElementById('addKeywordNameInput').value = '';
    document.getElementById('addKeywordDescInput').value = '';
    document.getElementById('addKeywordClusterSelect').value = '';
    
    // Optional: Modal nach 2 Sekunden schließen (oder manuell)
    setTimeout(() => {
      statusDiv.style.display = 'none';
    }, 3000);
    
    // Entferne automatisches Schließen, damit Nutzer weitere Keywords hinzufügen kann
    // Modal bleibt offen für weitere Keyword-Eingaben
    
  } catch (error) {
    console.error('[ADD-KW] Fehler:', error);
    statusDiv.style.background = '#f8d7da';
    statusDiv.style.color = '#721c24';
    statusDiv.textContent = 'Fehler: ' + error.message;
  }
}

// ---- extracted script block ----
// Zitate-Popup verschiebbar machen (nur Drag, kein Resize)
(function() {
  let isDragging = false;
  let currentX, currentY, initialX, initialY;
  let xOffset = 0, yOffset = 0;
  
  const popup = document.getElementById('quotesPopup');
  const popupInner = document.getElementById('quotesPopupInner');
  const header = document.getElementById('quotesPopupHeader');
  
  if (!popup || !popupInner || !header) return;
  
  // Drag-Funktionalität
  header.addEventListener('mousedown', dragStart);
  document.addEventListener('mousemove', handleMouseMove);
  document.addEventListener('mouseup', handleMouseUp);
  
  function dragStart(e) {
    if (e.target.tagName === 'BUTTON' || e.target.closest('button')) return;
    
    // Hole aktuelle Position des Popups
    const rect = popup.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    
    // Berechne Offset vom Mausklick zum Popup-Zentrum
    initialX = e.clientX - centerX;
    initialY = e.clientY - centerY;
    
    isDragging = true;
    popup.style.cursor = 'move';
  }
  
  function handleMouseMove(e) {
    if (isDragging) {
      e.preventDefault();
      
      // Berechne neue Position basierend auf Mausposition minus initialem Offset
      currentX = e.clientX - initialX;
      currentY = e.clientY - initialY;
      
      // Setze Position relativ zum Popup-Zentrum
      popup.style.left = currentX + 'px';
      popup.style.top = currentY + 'px';
      popup.style.transform = 'translate(-50%, -50%)';
    }
  }
  
  function handleMouseUp() {
    if (isDragging) {
      // Speichere die aktuelle Position für den nächsten Drag
      const rect = popup.getBoundingClientRect();
      xOffset = rect.left + rect.width / 2 - window.innerWidth / 2;
      yOffset = rect.top + rect.height / 2 - window.innerHeight / 2;
    }
    isDragging = false;
    popup.style.cursor = '';
  }
  
  // Reset position when popup is opened
  window.resetQuotesPopupPosition = function() {
    xOffset = 0;
    yOffset = 0;
    popup.style.left = '50%';
    popup.style.top = '45%';
    popup.style.transform = 'translate(-50%, -50%)';
  };
})();

