// Initialisiere Chat-Badge sofort beim Laden, wenn Benutzer eingeloggt ist
  function initializeChatBadgeOnLoad() {
    // Warte bis members-panel.js und members-api.js geladen sind
    if (typeof initSupabase === 'function' && typeof getCurrentUser === 'function') {
      initSupabase().then(() => {
        return getCurrentUser();
      }).then(user => {
        if (user) {
          // Setze currentUser global für members-panel.js
          if (typeof window !== 'undefined') {
            window.currentUser = user;
            // Setze auch in members-panel.js falls vorhanden
            if (typeof window.setCurrentUser === 'function') {
              window.setCurrentUser(user);
            }
          }
          
          // Initialisiere Chat-Realtime-Listener für Badge-Updates
          if (typeof initializeChatRealtimeListener === 'function') {
            initializeChatRealtimeListener();
          }
          
          // Aktualisiere Badge sofort - auch wenn Panel geschlossen ist
          if (typeof updateChatBadge === 'function') {
            // Verwende setTimeout um sicherzustellen, dass currentUser gesetzt ist
            setTimeout(() => {
              updateChatBadge();
            }, 200);
          }
        }
      }).catch(() => {
        // Benutzer nicht eingeloggt, kein Badge nötig
      });
    } else {
      // Scripts noch nicht geladen, versuche es später nochmal
      setTimeout(initializeChatBadgeOnLoad, 500);
    }
  }
  
  // Initialisiere beim DOMContentLoaded
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeChatBadgeOnLoad);
  } else {
    // DOM bereits geladen
    initializeChatBadgeOnLoad();
  }
  
  // Initialisiere auch nach kurzer Verzögerung (falls Scripts noch nicht geladen sind)
  setTimeout(initializeChatBadgeOnLoad, 1000);
  setTimeout(initializeChatBadgeOnLoad, 2000);

