(function() {
  // Prüfe ob Popup dauerhaft deaktiviert wurde
  const HINT_POPUP_DISABLED_KEY = 'ga_suche_hint_popup_disabled';
  
  if (localStorage.getItem(HINT_POPUP_DISABLED_KEY) === 'true') {
    // Popup wurde dauerhaft deaktiviert - nicht mehr anzeigen
    return;
  }
  
  function showHintPopup() {
    // Erstelle das Popup-Element
    const popup = document.createElement('div');
    popup.className = 'hint-popup';
    popup.innerHTML = `
      <div class="hint-popup-content">
        <strong>Willkommen</strong> im Rudolf-Steiner-online Portal. Aktuell befindet sich das Portal noch in der Testphase und kann deshalb Fehler enthalten. Wir bitten dies zu entschuldigen und sind dankbar, wenn Sie uns über den Button <strong>„Fehler melden"</strong> oben links auf eventuelle Probleme aufmerksam machen.<br><br>
        Klicken Sie <strong>Strg+Klick</strong>, um Informationen über die einzelnen Bereiche und Funktionen zu erhalten.<br><br>
        Weitere Tastenkombinationen über den <strong>Info-Button</strong> oben links.
      </div>
      <div class="hint-popup-footer">
        <label class="hint-popup-dismiss-label">
          <input type="checkbox" class="hint-popup-dismiss-checkbox">
          <span>Nicht mehr anzeigen</span>
        </label>
      </div>
      <button class="hint-popup-close" title="Schließen">
        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <line x1="18" y1="6" x2="6" y2="18"></line>
          <line x1="6" y1="6" x2="18" y2="18"></line>
        </svg>
      </button>
    `;
    
    document.body.appendChild(popup);
    
    // Schließen-Funktion - prüft Checkbox
    function closePopup() {
      // Prüfe ob Checkbox aktiviert ist
      const checkbox = popup.querySelector('.hint-popup-dismiss-checkbox');
      if (checkbox && checkbox.checked) {
        localStorage.setItem(HINT_POPUP_DISABLED_KEY, 'true');
      }
      
      popup.classList.add('hiding');
      setTimeout(() => {
        if (popup.parentNode) {
          popup.parentNode.removeChild(popup);
        }
      }, 300);
    }
    
    // Event-Listener für Schließen-Button (X)
    popup.querySelector('.hint-popup-close').addEventListener('click', closePopup);
    
    // Automatisch nach 30 Sekunden ausblenden
    setTimeout(closePopup, 30000);
  }
  
  // Zeige Popup nach kurzer Verzögerung bei jedem Besuch
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      setTimeout(showHintPopup, 1500);
    });
  } else {
    setTimeout(showHintPopup, 1500);
  }
})();

